# Confluence: rsi_4h + rsi_1h + bb_pct_b_4h. Pure function — never raises.
def _parabolic_state(ind: dict, cfg) -> tuple:
    if not bool(getattr(cfg, 'PARABOLIC_PROTECTION_ENABLED', True)):
        return (False, False, False, False)
    try:
        r4 = float((ind or {}).get('rsi_4h', 50) or 50)
        r1 = float((ind or {}).get('rsi_1h', 50) or 50)
        rd = float((ind or {}).get('rsi_D', 50) or 50)
        bb4 = float((ind or {}).get('bb_pct_b_4h', 0.5) or 0.5)
        pp_up = (r4 >= float(getattr(cfg, 'PARABOLIC_RSI_4H_MIN', 70.0))
                 and r1 >= float(getattr(cfg, 'PARABOLIC_RSI_1H_MIN', 65.0))
                 and bb4 >= float(getattr(cfg, 'PARABOLIC_BB_PCT_B_4H_MIN', 0.90)))
        pp_dn = (r4 <= float(getattr(cfg, 'PARABOLIC_RSI_4H_MAX', 30.0))
                 and r1 <= float(getattr(cfg, 'PARABOLIC_RSI_1H_MAX', 35.0))
                 and bb4 <= float(getattr(cfg, 'PARABOLIC_BB_PCT_B_4H_MAX', 0.10)))
        eo_on = bool(getattr(cfg, 'EXTREME_OB_OS_OVERRIDE_ENABLED', True))
        eob = (eo_on
               and r4 >= float(getattr(cfg, 'EXTREME_OB_RSI_4H_MIN', 80.0))
               and rd >= float(getattr(cfg, 'EXTREME_OB_RSI_D_MIN', 75.0))
               and bb4 >= float(getattr(cfg, 'EXTREME_OB_BB_PCT_B_4H_MIN', 1.0)))
        eos = (eo_on
               and r4 <= float(getattr(cfg, 'EXTREME_OS_RSI_4H_MAX', 20.0))
               and rd <= float(getattr(cfg, 'EXTREME_OS_RSI_D_MAX', 25.0))
               and bb4 <= float(getattr(cfg, 'EXTREME_OS_BB_PCT_B_4H_MAX', 0.0)))
        return (pp_up, pp_dn, eob, eos)
    except Exception:
        return (False, False, False, False)


def _rz_standalone_exit_gate(indicators: dict, is_long: bool, signal, config) -> tuple:
    """Allow RZ exits only after HTF zone and LTF breakdown confirmation."""
    action = getattr(signal, "zone_action", "")
    expected_action = "EXIT_LONG" if is_long else "EXIT_SHORT"
    if action != expected_action:
        return False, f"action={action or 'NONE'}"

    ind = indicators or {}
    top_threshold = float(getattr(config, "RZ_TOP_BB_THRESHOLD", 0.85))
    bottom_threshold = float(getattr(config, "RZ_BOT_BB_THRESHOLD", 0.15))
    min_htf = max(1, int(getattr(config, "RZ_EXIT_MIN_HTF", 2)))
    htf_tfs = ("1h", "4h", "D")

    def value(key, default=None):
        raw = ind.get(key, default)
        try:
            return float(raw) if raw is not None else None
        except (TypeError, ValueError):
            return default

    def in_red_zone(tf):
        bb = value(f"bb_pct_b_{tf}")
        dc = value(f"dc_position_{tf}")
        if is_long:
            return (bb is not None and bb >= top_threshold) or (dc is not None and dc >= top_threshold)
        return (bb is not None and bb <= bottom_threshold) or (dc is not None and dc <= bottom_threshold)

    htf_flags = {tf: in_red_zone(tf) for tf in htf_tfs}
    htf_count = sum(htf_flags.values())

    ltf_tf = str(getattr(config, "RZ_LTF_MICRO", "5m"))
    wt1_ltf = value(f"wt1_{ltf_tf}")
    wt2_ltf = value(f"wt2_{ltf_tf}")
    wt1_15m = value("wt1_15m")
    wt2_15m = value("wt2_15m")
    if None in (wt1_ltf, wt2_ltf, wt1_15m, wt2_15m):
        return False, f"htf={htf_count}/{len(htf_tfs)} missing_ltf_wt"

    ltf_break = wt1_ltf < wt2_ltf if is_long else wt1_ltf > wt2_ltf
    mid_break = wt1_15m < wt2_15m if is_long else wt1_15m > wt2_15m
    close_ltf = value(f"close_{ltf_tf}", value("current_price"))
    prev_low = value(f"low_{ltf_tf}_prev")
    prev_high = value(f"high_{ltf_tf}_prev")
    low_ltf = value(f"low_{ltf_tf}")
    high_ltf = value(f"high_{ltf_tf}")
    if is_long:
        structure_break = ((close_ltf is not None and prev_low is not None and close_ltf < prev_low)
                           or (low_ltf is not None and prev_low is not None and low_ltf < prev_low))
    else:
        structure_break = ((close_ltf is not None and prev_high is not None and close_ltf > prev_high)
                           or (high_ltf is not None and prev_high is not None and high_ltf > prev_high))

    passed = htf_count >= min_htf and ltf_break and mid_break and structure_break
    reason = (f"action={action} htf={htf_count}/{len(htf_tfs)} "
              f"ltf_wt={ltf_break} 15m_wt={mid_break} structure={structure_break} "
              f"zones={','.join(tf for tf, ok in htf_flags.items() if ok) or 'none'}")
    return passed, reason


def _ee_reentry_boost(symbol, indicators, is_long, cfg):
    """Pure-additive engine evaluator for REENTRY paths. Engines NEVER block reentries.
    Returns (size_mult, tag_str). size_mult==1.0 + empty tag = pass-through (default).
    With LIVE_ENTRY_ENGINE_REENTRY_SIZE_MULT=1.0 (default), size_mult is always 1.0 — pure observability.
    Wrapped to never raise — engine bug must NEVER block a reentry."""
    try:
        if cfg is None or not getattr(cfg, 'LIVE_ENTRY_ENGINE_ENABLED', False):
            return 1.0, ''
        _side = 'LONG' if is_long else 'SHORT'
        _score_max = 0.0
        _reasons = []
        for _name, _fn, _flag in (
            ('wt', _ee_should_fire_wt_entry, 'LIVE_ENTRY_ENGINE_WT_ENABLED'),
            ('stoch', _ee_should_fire_stoch_entry, 'LIVE_ENTRY_ENGINE_STOCH_ENABLED'),
            ('dc', _ee_should_fire_dc_entry, 'LIVE_ENTRY_ENGINE_DC_ENABLED'),
            ('htf', _ee_should_fire_htf_entry, 'LIVE_ENTRY_ENGINE_HTF_ENABLED'),
            ('stdev_macro', _ee_should_fire_stdev_macro_entry, 'LIVE_ENTRY_ENGINE_STDEV_MACRO_ENABLED'),
        ):
            if not getattr(cfg, _flag, False): continue
            if _fn is None: continue
            try:
                _fire, _why, _sc = _fn(symbol, indicators, _side)
                if _fire and _sc >= float(getattr(cfg, 'LIVE_ENTRY_ENGINE_MIN_SCORE', 0.6)):
                    _score_max = max(_score_max, _sc)
                    _reasons.append(f"{_name}={_sc:.2f}")
            except Exception:
                pass
        if _score_max <= 0.0 or not _reasons:
            return 1.0, ''
        _mult_cap = float(getattr(cfg, 'LIVE_ENTRY_ENGINE_REENTRY_SIZE_MULT', 1.0))
        _mult = 1.0 + (_mult_cap - 1.0) * _score_max
        return _mult, f" +ENGINES({','.join(_reasons)})"
    except Exception:
        return 1.0, ''

