async def periodic_evaluate_reentry_loop(trade_manager):
    """
    Scans for positions that were REDUCED and need RE-ENTRY.
    """
    logger.info("[TASK] Re-entry Scanner Started")
    while getattr(trade_manager, "running", False):
        try:
            await asyncio.sleep(45) # Check every 45s
            
            re_keys_by_acct = defaultdict(list)
            
            # Iterate ALL positions in the manager
            if trade_manager.position_manager:
                for pk, pos in trade_manager.position_manager.positions.items():
                    if not pos: continue
                    
                    # Check Re-entry Criteria
                    was_reduced = getattr(pos, 'was_reduced', False)
                    last_red_time = getattr(pos, 'last_reduction_time', None)
                    
                    if was_reduced and last_red_time:
                        # Extract Account Key
                        parts = pk.split(':')
                        if len(parts) > 0:
                            acc = parts[0]
                            re_keys_by_acct[acc].append(pk)

            # Dispatch to Monitor
            for acc, keys in re_keys_by_acct.items():
                if keys:
                    logger.info(f"[{acc}] ♻️ Evaluating {len(keys)} positions for Re-Entry...")
                    # await trade_manager.strategy.evaluate_reentry(symbol,position, indicators)
                    await monitor_entries( trade_manager.order_queue,  trade_manager,   acc,   keys,   event_type="reentry_scan",    is_priority_add=True,   force=True  )

        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[REENTRY_LOOP] Error: {e}",  exc_info=True )
            await asyncio.sleep(10)

def safe_fetch_float(value, default=0.0):
    try:
        if value is None: return default
        if isinstance(value, (float, int)): return float(value)
        return float(str(value).replace(',', '').strip())
    except Exception:
        return default


async def obligatory_sector_hedge_or_close_loop(trade_manager):
    """USER MANDATE 2026-05-09: stocks (Tradier) cannot hold both LONG+SHORT same symbol simultaneously.
    For trb: when a position is in loss with wt1_5m AND wt1_1h against the trade direction →
    OBLIGATORY same-SECTOR hedge (different ticker, opposite direction, same sector). If no
    eligible mate found OR hedge order fails → close losing position with HEDGE_FAILED reason.

    ⚠️ APPROXIMATION WARNING — sector beta differs across names; this is NOT perfect netting
    like the Binance perp same-symbol hedge. Each fire is logged loudly so the user can monitor.
    """
    if not bool(getattr(config, 'OBLIGATORY_SECTOR_HEDGE_ENABLED', True)):
        logger.warning("[OBLIGATORY_SECTOR_HEDGE_LOOP] DISABLED via OBLIGATORY_SECTOR_HEDGE_ENABLED=False")
        return
    interval = float(getattr(config, 'OBLIGATORY_SECTOR_HEDGE_LOOP_INTERVAL_SECONDS', 90.0))
    require_5m_1h = bool(getattr(config, 'OBLIGATORY_SECTOR_HEDGE_TRIGGER_REQUIRE_WT_5M_AND_1H', True))
    fallback_close_enabled = bool(getattr(config, 'HEDGE_FAILED_FALLBACK_CLOSE_ENABLED', True))
    min_loss_pct = float(getattr(config, 'OBLIGATORY_HEDGE_MIN_LOSS_PCT', -0.5))
    logger.critical(f"[OBLIGATORY_SECTOR_HEDGE_LOOP] STARTED. interval={interval}s require_wt_5m_AND_1h={require_5m_1h} min_loss={min_loss_pct}% fallback_close={fallback_close_enabled}")
    _hedge_attempts: dict = {}  # losing_pk -> last attempt ts (per-loser cooldown)
    _COOLDOWN_S = 600.0
    while getattr(trade_manager, 'running', False):
        try:
            await asyncio.sleep(interval)
            if not is_regular_trading_hours():
                continue
            try:
                from tradier_sector_ls_ratio import (_load_sector_map,
                                                     get_sector)
            except Exception as _ie:
                logger.error(f"[OBLIGATORY_SECTOR_HEDGE_LOOP] sector helper import failed: {_ie}")
                continue
            for account_key in ('trb',):  # only trb supports stocks shorting; tra is long-only, trc is mirror
                try:
                    if not hasattr(trade_manager, 'position_manager') or trade_manager.position_manager is None:
                        continue
                    positions = trade_manager.position_manager.get_positions_by_account(account_key) or {}
                except Exception as _pe:
                    logger.error(f"[OBLIGATORY_SECTOR_HEDGE_LOOP][{account_key}] position fetch err: {_pe}")
                    continue
                for pk, pos in list(positions.items()):
                    try:
                        pa = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0), 0))
                        if pa <= 0:
                            continue
                        gain = safe_fetch_float(getattr(pos, 'gain', 0), 0.0)
                        if gain >= min_loss_pct:
                            continue
                        if (time.time() - _hedge_attempts.get(pk, 0.0)) < _COOLDOWN_S:
                            continue
                        symbol = getattr(pos, 'symbol', None) or pk.split(':')[1].replace('_LONG', '').replace('_SHORT', '')
                        is_long = pk.endswith('_LONG')
                        loser_side = 'LONG' if is_long else 'SHORT'
                        # WT trigger gate: 5m AND 1h against
                        ind = trade_manager.indicators_cache.get(symbol.upper(), {}) if hasattr(trade_manager, 'indicators_cache') else {}
                        if not ind:
                            logger.info(f"[SECTOR_HEDGE_NO_IND] {pk}: no indicators cached for {symbol} — skip cycle")
                            continue
                        wt1_5m = safe_fetch_float(ind.get('wt1_5m', 0), 0)
                        wt2_5m = safe_fetch_float(ind.get('wt2_5m', 0), 0)
                        wt1_1h = safe_fetch_float(ind.get('wt1_1h', 0), 0)
                        wt2_1h = safe_fetch_float(ind.get('wt2_1h', 0), 0)
                        wt_5m_against = (is_long and wt1_5m < wt2_5m) or ((not is_long) and wt1_5m > wt2_5m)
                        wt_1h_against = (is_long and wt1_1h < wt2_1h) or ((not is_long) and wt1_1h > wt2_1h)
                        if require_5m_1h and not (wt_5m_against and wt_1h_against):
                            continue
                        # Check if a hedge already exists for this loser via tracker (skip if so)
                        # Tradier doesn't have the same active_hedges structure as crypto; rely on
                        # mate lookup + cooldown to prevent stacking.
                        sector = None
                        try:
                            sector = get_sector(symbol)
                        except Exception:
                            sector = None
                        if not sector:
                            logger.warning(f"⚠️ [SECTOR_HEDGE_NO_SECTOR] {pk}: no sector found for {symbol} — fallback close")
                            if fallback_close_enabled:
                                await _fire_fallback_close_trb(trade_manager, account_key, pk, f"HEDGE_FAILED_FALLBACK_CLOSE_no_sector_g{gain:.2f}%")
                            _hedge_attempts[pk] = time.time()
                            continue
                        mate_side = 'SHORT' if is_long else 'LONG'  # opposite to loser
                        sector_map = _load_sector_map() or {}
                        mates = list(sector_map.get(sector, []))
                        chosen_mate = None
                        chosen_mate_pk = None
                        for mate in mates:
                            if not mate or mate == symbol:
                                continue
                            mate_pk = f"{account_key}:{mate}_{mate_side}"
                            # Tradeable check
                            if hasattr(trade_manager, 'tradeable_keys') and trade_manager.tradeable_keys:
                                if mate_pk not in trade_manager.tradeable_keys:
                                    continue
                            # Already-open check: skip if mate side already has a position
                            existing_mate_pos = positions.get(mate_pk)
                            if existing_mate_pos and abs(safe_fetch_float(getattr(existing_mate_pos, 'positionAmt', 0), 0)) > 0:
                                continue
                            mate_ind = trade_manager.indicators_cache.get(mate.upper(), {}) if hasattr(trade_manager, 'indicators_cache') else {}
                            if not mate_ind:
                                continue
                            m1_5 = safe_fetch_float(mate_ind.get('wt1_5m', 0), 0)
                            m2_5 = safe_fetch_float(mate_ind.get('wt2_5m', 0), 0)
                            m1_h = safe_fetch_float(mate_ind.get('wt1_1h', 0), 0)
                            m2_h = safe_fetch_float(mate_ind.get('wt2_1h', 0), 0)
                            mate_5_aligned = (mate_side == 'LONG' and m1_5 > m2_5) or (mate_side == 'SHORT' and m1_5 < m2_5)
                            mate_h_aligned = (mate_side == 'LONG' and m1_h > m2_h) or (mate_side == 'SHORT' and m1_h < m2_h)
                            if mate_5_aligned and mate_h_aligned:
                                chosen_mate = mate
                                chosen_mate_pk = mate_pk
                                break
                        if not chosen_mate:
                            logger.warning(f"⚠️ [SECTOR_HEDGE_NO_MATE] {pk}: no eligible {mate_side} mate in sector={sector} (mates_checked={len(mates)}) — fallback close")
                            if fallback_close_enabled:
                                await _fire_fallback_close_trb(trade_manager, account_key, pk, f"HEDGE_FAILED_FALLBACK_CLOSE_no_mate_sector{sector}_g{gain:.2f}%")
                            _hedge_attempts[pk] = time.time()
                            continue
                        # Size: same notional as loser. Need mate price for shares.
                        mate_ind_full = trade_manager.indicators_cache.get(chosen_mate.upper(), {})
                        mate_price = safe_fetch_float(mate_ind_full.get('current_price', 0), 0) or safe_fetch_float(mate_ind_full.get('close', 0), 0)
                        loser_mark = safe_fetch_float(getattr(pos, 'mark_price', 0), 0)
                        if mate_price <= 0 or loser_mark <= 0:
                            logger.warning(f"⚠️ [SECTOR_HEDGE_NO_PRICE] {pk}: missing prices loser={loser_mark} mate={chosen_mate}@{mate_price} — fallback close")
                            if fallback_close_enabled:
                                await _fire_fallback_close_trb(trade_manager, account_key, pk, f"HEDGE_FAILED_FALLBACK_CLOSE_no_price_g{gain:.2f}%")
                            _hedge_attempts[pk] = time.time()
                            continue
                        loser_notional = pa * loser_mark
                        # Cap to START_POSITION_SIZE × 2 to prevent runaway sizing on a deep loser
                        _start_size = float(getattr(config, 'START_POSITION_SIZE', 600))
                        target_notional = min(loser_notional, _start_size * 2.0)
                        mate_qty_raw = target_notional / mate_price
                        mate_qty = max(1, int(mate_qty_raw))
                        logger.critical(
                            f"⚠️ [SECTOR_HEDGE_FIRE] loser={pk} g={gain:.2f}% sector={sector} → opening {mate_side} on {chosen_mate} qty={mate_qty} (~${target_notional:.0f}). "
                            f"⚠️ APPROXIMATION (sector beta != 1:1) — WATCH CLOSELY."
                        )
                        _hedge_reason = f"OBLIGATORY_SECTOR_HEDGE_for_{symbol}_{loser_side}_g{gain:.2f}%_sector={sector}_APPROX"
                        try:
                            _result = await queue_trade_action(
                                trade_manager.order_queue, trade_manager, chosen_mate_pk, "OPEN",
                                _hedge_reason, 85.0, override_qty=mate_qty,
                            )
                        except Exception as _qe:
                            logger.error(f"💥 [SECTOR_HEDGE_QUEUE_CRASH] {pk}→{chosen_mate_pk}: {_qe}", exc_info=True)
                            _result = False
                        _hedge_attempts[pk] = time.time()
                        if _result and (_result is True or (isinstance(_result, str) and _result.startswith('SUCCESS'))):
                            logger.warning(f"✅ [SECTOR_HEDGE_OPENED] {pk}→{chosen_mate_pk}: hedge order queued. APPROXIMATION — monitor manually.")
                        else:
                            logger.critical(f"☠️ [SECTOR_HEDGE_FAILED] {pk}: hedge order on {chosen_mate_pk} failed (result={_result}) — fallback close losing position")
                            if fallback_close_enabled:
                                await _fire_fallback_close_trb(trade_manager, account_key, pk, f"HEDGE_FAILED_FALLBACK_CLOSE_mate{chosen_mate}_failed_g{gain:.2f}%")
                    except Exception as _pe:
                        logger.error(f"[SECTOR_HEDGE_PER_POS_ERR] {pk}: {_pe}", exc_info=True)
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[OBLIGATORY_SECTOR_HEDGE_LOOP] error: {e}", exc_info=True)
            await asyncio.sleep(30)


async def _fire_fallback_close_trb(trade_manager, account_key, position_key, reason):
    """Force-close a losing trb position via queue_trade_action with HEDGE_FAILED_FALLBACK_CLOSE reason.
    Reason string contains 'HEDGE_FAILED' so any UNIVERSAL_NOLOSS-style bypass that substring-matches works.
    Uses override_qty=999999 (clamped to actual qty in execute_trade_action)."""
    try:
        logger.critical(f"☠️ [HEDGE_FAILED_FALLBACK_CLOSE] {position_key}: closing losing position — reason={reason}")
        await queue_trade_action(
            trade_manager.order_queue, trade_manager, position_key, "CLOSE",
            reason, 100.0, override_qty=999999,
        )
    except Exception as _e:
        logger.error(f"[HEDGE_FAILED_FALLBACK_CLOSE_CRASH] {position_key}: {_e}", exc_info=True)

_OVERNIGHT_ONE_SIDED_SECTORS = frozenset({
    'energy_oil_gas',         # longs only — no shorts in symbols_trb_short
    'base_metals_mining',     # shorts only — no longs in symbols_trb_long
    'defense_aerospace',      # shorts only — no longs
    'commodities_crypto_etf', # longs only — no shorts
})

async def overnight_gap_hedge_loop(trade_manager):
    """Opens same-sector opposite-side hedges (50% notional) 15 min before market close
    when |market_sentiment_score| > threshold, then closes them at 09:35 ET next morning.

    Rationale: overnight gaps (close→open) carry most stock volatility. Same-sector hedge
    provides approximate protection since same-symbol hedging is impossible on Tradier.

    Only fires for: tech_ai_chips, precious_metals, uranium_nuclear, agriculture_fertilizer,
    consumer_media. Skips one-sided sectors (no opposite-side mates available).
    """
    if not bool(getattr(config, 'OVERNIGHT_GAP_HEDGE_ENABLED', False)):
        return
    open_minutes = float(getattr(config, 'OVERNIGHT_GAP_HEDGE_OPEN_MINUTES', 15.0))
    close_minutes = float(getattr(config, 'OVERNIGHT_GAP_HEDGE_CLOSE_MINUTES', 5.0))
    sentiment_threshold = float(getattr(config, 'OVERNIGHT_GAP_HEDGE_SENTIMENT_THRESHOLD', 20.0))
    size_frac = float(getattr(config, 'OVERNIGHT_GAP_HEDGE_SIZE_FRAC', 0.50))
    _hedge_tracker: dict = {}
    _hedges_fired_today = False
    _hedges_closed_today = False
    logger.warning(f"[OVERNIGHT_GAP_HEDGE] STARTED open={open_minutes}min_pre_close close={close_minutes}min_post_open threshold=±{sentiment_threshold} size={size_frac}")
    while getattr(trade_manager, 'running', False):
        try:
            await asyncio.sleep(60)
            try:
                from zoneinfo import ZoneInfo
                now_et = datetime.now(ZoneInfo("America/New_York"))
            except ImportError:
                import pytz
                now_et = datetime.now(pytz.timezone("America/New_York"))
            if now_et.weekday() >= 5:
                continue
            mins_to_close = _minutes_to_close()
            mins_since_open = (now_et.hour * 60 + now_et.minute) - (9 * 60 + 30)
            if 11 * 60 <= (now_et.hour * 60 + now_et.minute) < 12 * 60:
                _hedges_fired_today = False
                _hedges_closed_today = False
            if close_minutes <= mins_since_open <= close_minutes + 5 and not _hedges_closed_today and _hedge_tracker:
                logger.warning(f"[OVERNIGHT_GAP_HEDGE] MORNING CLOSE: closing {len(_hedge_tracker)} overnight hedges at 09:35 ET")
                for _src_pk, _entry in list(_hedge_tracker.items()):
                    _hedge_pk = _entry.get('hedge_pk')
                    if not _hedge_pk:
                        continue
                    try:
                        await queue_trade_action(
                            trade_manager.order_queue, trade_manager, _hedge_pk, "CLOSE",
                            f"OVERNIGHT_GAP_HEDGE_REMOVE_for_{_src_pk}", 100.0, override_qty=999999,
                        )
                        logger.warning(f"[OVERNIGHT_GAP_HEDGE] closed {_hedge_pk} for {_src_pk}")
                    except Exception as _ce:
                        logger.error(f"[OVERNIGHT_GAP_HEDGE_CLOSE_ERR] {_hedge_pk}: {_ce}", exc_info=True)
                _hedge_tracker.clear()
                _hedges_closed_today = True
                continue
            if not (0 < mins_to_close <= open_minutes) or _hedges_fired_today:
                continue
            sentiment_score = 0.0
            for _cache_ind in (getattr(trade_manager, 'indicators_cache', None) or {}).values():
                _s = _cache_ind.get('0market_sentiment_score', None)
                if _s is not None:
                    sentiment_score = float(_s)
                    break
            if abs(sentiment_score) <= sentiment_threshold:
                logger.info(f"[OVERNIGHT_GAP_HEDGE] sentiment={sentiment_score:.1f} within ±{sentiment_threshold} — no hedge today")
                _hedges_fired_today = True
                continue
            hedge_for_longs = sentiment_score < -sentiment_threshold
            hedge_for_shorts = sentiment_score > sentiment_threshold
            logger.warning(f"[OVERNIGHT_GAP_HEDGE] FIRING: sentiment={sentiment_score:.1f} → hedging {'LONGs→SHORT' if hedge_for_longs else 'SHORTs→LONG'}")
            try:
                from tradier_sector_ls_ratio import (_load_sector_map,
                                                     get_sector)
            except Exception as _ie:
                logger.error(f"[OVERNIGHT_GAP_HEDGE] sector import failed: {_ie}")
                _hedges_fired_today = True
                continue
            sector_map = _load_sector_map() or {}
            try:
                positions = trade_manager.position_manager.get_positions_by_account('trb') or {}
            except Exception as _pe:
                logger.error(f"[OVERNIGHT_GAP_HEDGE] positions fetch err: {_pe}")
                _hedges_fired_today = True
                continue
            hedges_opened = 0
            for pk, pos in list(positions.items()):
                try:
                    pa = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0), 0))
                    if pa <= 0 or pk in _hedge_tracker:
                        continue
                    is_long = pk.endswith('_LONG')
                    if (is_long and not hedge_for_longs) or (not is_long and not hedge_for_shorts):
                        continue
                    symbol = pk.split(':')[1].replace('_LONG', '').replace('_SHORT', '')
                    sector = get_sector(symbol)
                    if not sector or sector in _OVERNIGHT_ONE_SIDED_SECTORS:
                        continue
                    mate_side = 'SHORT' if is_long else 'LONG'
                    chosen_mate = None
                    chosen_mate_pk = None
                    for mate in sector_map.get(sector, []):
                        if not mate or mate == symbol:
                            continue
                        mate_pk = f"trb:{mate}_{mate_side}"
                        if hasattr(trade_manager, 'tradeable_keys') and mate_pk not in trade_manager.tradeable_keys:
                            continue
                        existing = positions.get(mate_pk)
                        if existing and abs(safe_fetch_float(getattr(existing, 'positionAmt', 0), 0)) > 0:
                            continue
                        chosen_mate = mate
                        chosen_mate_pk = mate_pk
                        break
                    if not chosen_mate:
                        logger.info(f"[OVERNIGHT_GAP_HEDGE] {pk}: no available {mate_side} mate in sector={sector}")
                        continue
                    loser_mark = safe_fetch_float(getattr(pos, 'mark_price', 0), 0)
                    if loser_mark <= 0:
                        continue
                    target_notional = pa * loser_mark * size_frac
                    mate_ind = (getattr(trade_manager, 'indicators_cache', None) or {}).get(chosen_mate.upper(), {})
                    mate_price = safe_fetch_float(mate_ind.get('current_price', 0), 0) or safe_fetch_float(mate_ind.get('close', 0), 0)
                    if mate_price <= 0:
                        logger.warning(f"[OVERNIGHT_GAP_HEDGE] {pk}: no price for mate {chosen_mate}")
                        continue
                    mate_qty = max(1, int(target_notional / mate_price))
                    _reason = f"OVERNIGHT_GAP_HEDGE_for_{symbol}_sector={sector}_sent={sentiment_score:.0f}"
                    logger.warning(f"[OVERNIGHT_GAP_HEDGE] opening {mate_side} {chosen_mate} qty={mate_qty} (~${target_notional:.0f}) for {pk} sector={sector}")
                    _result = await queue_trade_action(
                        trade_manager.order_queue, trade_manager, chosen_mate_pk, "OPEN",
                        _reason, 84.0, override_qty=mate_qty,
                    )
                    if _result and (_result is True or (isinstance(_result, str) and _result.startswith('SUCCESS'))):
                        _hedge_tracker[pk] = {'hedge_pk': chosen_mate_pk, 'opened_ts': time.time(), 'notional': target_notional}
                        hedges_opened += 1
                        logger.warning(f"✅ [OVERNIGHT_GAP_HEDGE] opened {chosen_mate_pk} for {pk}")
                    else:
                        logger.error(f"[OVERNIGHT_GAP_HEDGE] failed to open {chosen_mate_pk}: {_result}")
                except Exception as _pe:
                    logger.error(f"[OVERNIGHT_GAP_HEDGE_PER_POS] {pk}: {_pe}", exc_info=True)
            _hedges_fired_today = True
            logger.warning(f"[OVERNIGHT_GAP_HEDGE] DONE: {hedges_opened} hedges opened for tonight")
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[OVERNIGHT_GAP_HEDGE] loop error: {e}", exc_info=True)
            await asyncio.sleep(30)


def _arrow_dbg(msg):
    if os.environ.get("V8_ARROW_DEBUG"):
        print(f"V8_ARROW {msg}", flush=True)


def mtf_arrow_score(ind, is_long, cfg):
    """USER 2026-07-20 multi-TF arrow system — port of tools/mtf_arrow_lab (ARM 5.81x b&h sized).
    Score the higher-TF context for a 5m entry: the closer each HTF sits to its LOWER regression
    band the higher the score, and the steeper its rising slope the higher the score. Returns
    (score, detail). Score feeds BOTH the entry gate (>= MTF_ARROW_THETA) and the size multiplier."""
    weights = getattr(cfg, "MTF_ARROW_WEIGHTS", None) or {"1h": 0.35, "4h": 0.35, "D": 0.30}
    lam = float(getattr(cfg, "MTF_ARROW_SLOPE_LAMBDA", 1.0))
    score = 0.0
    parts = []
    # 2026-07-21 lab-faithful rewrite (tools/mtf_arrow_lab.py phase_b :154-158): depth raw
    # (neutral bar scores ~0.5 — the CONFIRM trigger is the entry timing, score is the HTF
    # gate+sizer), slope clipped [-2,2] in raw per-bar units (no per-day rescale), favorable
    # slope adds lam*slope, adverse slope subtracts a flat w*0.5 penalty.
    for tf, w in weights.items():
        pb = ind.get(f"lrL_pct_b_{tf}")
        sl = ind.get(f"lrL_slope_{tf}")
        if pb is None or sl is None:
            continue
        pb_f = float(pb)
        sl_f = max(-2.0, min(2.0, float(sl) if is_long else -float(sl)))
        depth = max(0.0, min(1.2, (1.0 - pb_f) if is_long else pb_f))
        score += w * (depth + lam * max(sl_f, 0.0))
        if sl_f < 0:
            score -= w * 0.5
        parts.append(f"{tf}:d{depth:.2f}s{sl_f:+.2f}")
    return score, " ".join(parts)


async def monitor_entries(order_queue: "OrderQueue", trade_manager, account_key: str, position_keys=None, event_type=None, is_priority_add: bool = False, force: bool = False):
    current_account.set(account_key)
    now_ts = time.time()
    
    try:
        # 1. Market Hours Gate (Removed hard return to allow Weather Monitoring off-hours)
        if not is_regular_trading_hours() and not force:
            if now_ts % 60 < 2: 
                logger.info(f"[{account_key}] 💤 Market Closed. Monitoring only.")

        # 2. Queue Management (Standard Deque Logic)
        if account_key not in trade_manager.account_position_queues:
            trade_manager.account_position_queues[account_key] = {'queue': deque(), 'set': set()}
        
        q_data = trade_manager.account_position_queues[account_key]
        
        if position_keys:
            # Normalize keys
            incoming = [position_keys] if isinstance(position_keys, str) else position_keys
            # De-duplicate
            unique_incoming = list(dict.fromkeys(incoming))
            
            for k in unique_incoming:
                if k not in q_data['set']:
                    if is_priority_add: q_data['queue'].appendleft(k)
                    else: q_data['queue'].append(k)
                    q_data['set'].add(k)

        if not q_data['queue']: 
            return

        # 3. Process Batch (Up to 100 at a time)
        batch = []
        for _ in range(min(len(q_data['queue']), 100)):
            batch.append(q_data['queue'].popleft())
            q_data['set'].discard(batch[-1])

        # 4. The Gates
        for position_key in batch:
            _, symbol, position_side = parse_position_key(position_key)
            if symbol.upper() in trade_manager.blacklist:
                if config.VERBOSE: 
                    logger.debug(f"[{account_key}] 🛑 BLACKLIST {symbol}: Ignored (External Management).")
                continue

            # --- CHECK 1: PROCESSING LOCK (Prevent double-processing) ---
            # If it's already running in another task, skip it to prevent race conditions.
            # We rarely force this unless we are debugging.
            if position_key in trade_manager.processing_keys and not force:
                # logger.debug(f"[{account_key}] SKIP {symbol}: Already processing.")
                continue

            # --- CHECK 2: COOLDOWN (Don't spam) ---
            # force=True BYPASSES THIS (e.g. Monitor Loop / Pulse)
            cd = float(trade_manager.recently_processed_signals.get(position_key, 0.0))
            if not force and (now_ts < cd):
                logger.debug(f"[{account_key}] SKIP {symbol}: Cooldown active ({int(cd-now_ts)}s).")
                continue

            # --- CHECK 3: DEDUPLICATION (Don't double order) ---
            # force=True BYPASSES THIS
            async with trade_manager.dedupe_lock:
                last_order = trade_manager.order_deduplication.get(position_key, 0)
                if not force and (now_ts - last_order < 90.0):
                    logger.info(f"[{account_key}] SKIP {symbol}: Order recently queued (<90s).")
                    continue

            # --- CHECK 4: LEADERBOARD/SYMBOL FILTER (The "Is this allowed?" Gate) ---
            # This is where trades often die silently.
            
            # Use centralized check
            is_allowed = trade_manager.is_symbol_tradeable(symbol, account_key, position_side)
            if force: is_allowed = True

            if not is_allowed:
                # TEMP LIVE FIX before 100k complete: allow TRB 148 (was V8_NOT_VERIFIED_TEMP_ALLOWED + FILTER BLOCK for 100+ sides Friday 0 trades)
                if account_key=='trb':
                    is_allowed=True
                if not is_allowed and config.VERBOSE: 
                    logger.info(f"[{account_key}] ⛔ FILTER BLOCK {symbol} {position_side}: Not in approved list.")
                continue


            trade_manager.processing_keys.add(position_key)
            try:
                result = await process_position(account_key, position_key, order_queue, trade_manager, event_type=event_type, force=force)
                if result == "PROCESSED":
                    trade_manager.position_last_processed[position_key] = time.time()
            finally:
                trade_manager.processing_keys.discard(position_key)
    except Exception as e:
        logger.error(f"[{account_key}] 💥 CRASH in monitor_entries: {e}",  exc_info=True )

# ═══ 2.5σ STDEV BREAKOUT: HTF breakout detection for stocks ═══
_stdev_bb_history_t: dict = {}  # {symbol_tf: deque(maxlen=20)}
_stdev_breakout_state_t: dict = {}  # {symbol: {active, direction, ...}}

def _get_bb_pctb_t(symbol: str, tf: str, i: dict) -> float:
    """Compute BB pct_b from rolling close buffer (tradier variant)."""
    pctb = safe_fetch_float(i.get(f'bb_pct_b_{tf}'), None)
    if pctb is not None:
        return pctb
    # In tradier, parsed indicators have close_{tf}_prev but not close_{tf}
    close = safe_fetch_float(i.get(f'close_{tf}', 0), 0)
    if close <= 0:
        close = safe_fetch_float(i.get(f'close_{tf}_prev', 0), 0)
    if close <= 0:
        close = safe_fetch_float(i.get('current_price', 0), 0)
    if close <= 0:
        return 0.5
    buf_key = f"{symbol}_{tf}"
    if buf_key not in _stdev_bb_history_t:
        _stdev_bb_history_t[buf_key] = deque(maxlen=20)
    buf = _stdev_bb_history_t[buf_key]
    if not buf or abs(buf[-1] - close) > 1e-8:
        buf.append(close)
    if len(buf) < 20:
        return 0.5
    vals = list(buf)
    mean = sum(vals) / len(vals)
    variance = sum((v - mean) ** 2 for v in vals) / len(vals)
    std = variance ** 0.5
    if std <= 0:
        return 0.5
    upper = mean + 2.0 * std
    lower = mean - 2.0 * std
    bw = upper - lower
    return (close - lower) / bw if bw > 0 else 0.5


def _update_stdev_state(symbol: str, i: dict):
    """Update breakout state continuously (called every bar). Does NOT return signals."""
    if not getattr(config, "STDEV_BREAKOUT_ENABLED", False):
        return
    htf_list = getattr(config, "STDEV_BREAKOUT_HTF_LIST", ["D", "4h"])
    pctb_long = getattr(config, "STDEV_BREAKOUT_PCTB_LONG", 1.125)
    pctb_short = getattr(config, "STDEV_BREAKOUT_PCTB_SHORT", -0.125)
    rvol_min = getattr(config, "STDEV_BREAKOUT_RVOL_MIN", 1.2)
    max_age = getattr(config, "STDEV_BREAKOUT_MAX_AGE_BARS", 50)
    for is_long in [True, False]:
        _state_key = f"{symbol}_{'L' if is_long else 'S'}"
        if _state_key not in _stdev_breakout_state_t:
            _stdev_breakout_state_t[_state_key] = {'active': False, 'direction': None, 'breakout_time': 0.0, 'breakout_pctb': 0.0, 'htf': None, 'retest_count': 0, 'bars_since': 0}
        state = _stdev_breakout_state_t[_state_key]
        if state['active']:
            state['bars_since'] += 1
            if state['bars_since'] > max_age:
                state['active'] = False
            continue
        # Check for NEW breakout
        for tf in htf_list:
            pctb = _get_bb_pctb_t(symbol, tf, i)
            rvol = safe_fetch_float(i.get(f'relative_volume_{tf}', 0), 0)
            if rvol <= 0:
                rvol = safe_fetch_float(i.get('relative_volume_1h', 0), 0)
            if rvol <= 0:
                rvol = safe_fetch_float(i.get('relative_volume_15m', 0), 0)
            if is_long and pctb > pctb_long and rvol >= rvol_min:
                state.update({'active': True, 'direction': 'LONG', 'breakout_time': time.time(), 'breakout_pctb': pctb, 'htf': tf, 'retest_count': 0, 'bars_since': 0})
                break
            elif not is_long and pctb < pctb_short and rvol >= rvol_min:
                state.update({'active': True, 'direction': 'SHORT', 'breakout_time': time.time(), 'breakout_pctb': pctb, 'htf': tf, 'retest_count': 0, 'bars_since': 0})
                break


def detect_stdev_breakout_t(symbol: str, is_long: bool, i: dict) -> dict:
    """Read breakout state (set by _update_stdev_state). Returns entry signal or None."""
    if not getattr(config, "STDEV_BREAKOUT_ENABLED", False):
        return None
    _state_key = f"{symbol}_{'L' if is_long else 'S'}"
    state = _stdev_breakout_state_t.get(_state_key)
    if not state or not state['active']:
        return None
    retest_tf_list = getattr(config, "STDEV_BREAKOUT_RETEST_TF_LIST", ["1h", "15m"])
    retest_pctb_min = getattr(config, "STDEV_BREAKOUT_RETEST_PCTB_MIN", 0.85)
    retest_pctb_max = getattr(config, "STDEV_BREAKOUT_RETEST_PCTB_MAX", 1.05)
    max_retests = getattr(config, "STDEV_BREAKOUT_MAX_RETESTS", 3)
    # Breakout is active — return entry signal
    # First entry for this breakout cycle: full breakout signal
    if state['retest_count'] == 0:
        state['retest_count'] = 1  # Mark as "initial entry done"
        return {'signal': 'BUY' if is_long else 'SELL', 'phase': 'BREAKOUT', 'htf': state['htf'], 'pctb': state['breakout_pctb'], 'rvol': 0, 'size_mult': 1.0, 'score': getattr(config, "STDEV_BREAKOUT_SCORE", 25)}
    # Subsequent entries: retest (scale-in with larger size)
    if state['retest_count'] >= max_retests + 1:
        return None
    # Phase 2: Retest
    for tf in retest_tf_list:
        pctb = _get_bb_pctb_t(symbol, tf, i)
        k_tf = safe_fetch_float(i.get(f'k_{tf}', 50), 50)
        d_tf = safe_fetch_float(i.get(f'd_{tf}', 50), 50)
        if is_long:
            if retest_pctb_min <= pctb <= retest_pctb_max and k_tf > d_tf and k_tf < 65:
                state['retest_count'] += 1
                return {'signal': 'BUY', 'phase': 'RETEST', 'htf': state['htf'], 'retest_tf': tf, 'pctb': pctb, 'retest_num': state['retest_count'], 'size_mult': getattr(config, "STDEV_BREAKOUT_RETEST_SIZE_MULT", 1.5), 'score': getattr(config, "STDEV_BREAKOUT_RETEST_SCORE", 22)}
        else:
            if (1.0 - retest_pctb_max) <= pctb <= (1.0 - retest_pctb_min) and k_tf < d_tf and k_tf > 35:
                state['retest_count'] += 1
                return {'signal': 'SELL', 'phase': 'RETEST', 'htf': state['htf'], 'retest_tf': tf, 'pctb': pctb, 'retest_num': state['retest_count'], 'size_mult': getattr(config, "STDEV_BREAKOUT_RETEST_SIZE_MULT", 1.5), 'score': getattr(config, "STDEV_BREAKOUT_RETEST_SCORE", 22)}
    return None


async def process_position(account_key: str, position_key: str, order_queue: "OrderQueue", trade_manager, event_type=None, force: bool = False):
    current_account.set(account_key)
    try:
        ak, symbol, position_side = parse_position_key(position_key)
        if ak != account_key: return
        if force:
            logger.info(f"[{account_key}] 🔎 MONITORING {position_key} (Force=True)")
        now_ts = time.time()
        last_mon = trade_manager.last_monitored_positions.get(position_key, 0.0)
        position = trade_manager.position_manager.get_position(position_key)
        has_position = position and abs(float(getattr(position, 'positionAmt', 0))) > 0
        _agent_hold_deferred = None
        if account_key in ("tra", "trb", "trc"):
            try:
                import tradier_advisory_consumer as _ag_adv
                _ag_obj = _ag_adv.check(account_key, symbol, position_side, "process")
                if _ag_obj:
                    _ag_tag = account_key.upper()
                    _ag_action = _ag_obj.get("action")
                    _ag_reason = (_ag_obj.get("reason") or "")[:60]
                    _ag_pos_amt = abs(float(getattr(position, 'positionAmt', 0))) if position else 0.0
                    if _ag_action == "force_close" and _ag_pos_amt > 0:
                        _ag_adv.log_application(account_key, symbol, position_side, "process", "force_close", _ag_obj)
                        logger.info(f"🤖 {_ag_tag}_AGENT_FORCE_CLOSE {position_key}: {_ag_reason}")
                        await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", f"{_ag_tag}_AGENT_FORCE_CLOSE({_ag_reason})", 100.0, override_qty=999999)
                        return f"AGENT_FORCE_CLOSE:{_ag_tag}"
                    if _ag_action == "hold" and _ag_pos_amt > 0:
                        _ag_adv.log_application(account_key, symbol, position_side, "process", "hold", _ag_obj)
                        logger.info(f"🤖 {_ag_tag}_AGENT_HOLD {position_key}: {_ag_reason}")
                        # A hold is advisory.  Defer it until the hard 4h
                        # Donchian emergency check below; an agent must never
                        # suppress a structural safety exit.
                        _agent_hold_deferred = f"AGENT_HOLD:{_ag_tag}"
                    if _ag_action == "force_open" and _ag_pos_amt == 0:
                        _ag_size_usd = float(_ag_obj.get("size_override_usd") or 0)
                        _ag_price_t, _ = await trade_manager.get_current_price(symbol)
                        _ag_price_t = float(_ag_price_t) if _ag_price_t else 0.0
                        if _ag_size_usd > 0 and _ag_price_t > 0:
                            _ag_qty = max(_ag_size_usd / _ag_price_t, 0.0)
                            _ag_adv.log_application(account_key, symbol, position_side, "process", "force_open", _ag_obj)
                            logger.info(f"🤖 {_ag_tag}_AGENT_FORCE_OPEN {position_key} size=${_ag_size_usd:.0f} qty={_ag_qty:.4f}: {_ag_reason}")
                            await queue_trade_action(order_queue, trade_manager, position_key, "OPEN", f"{_ag_tag}_AGENT_FORCE_OPEN({_ag_reason})", 100.0, override_qty=_ag_qty)
                            return f"AGENT_FORCE_OPEN:{_ag_tag}"
                    if _ag_action == "block_entry" and _ag_pos_amt == 0:
                        _ag_adv.log_application(account_key, symbol, position_side, "process", "block_entry", _ag_obj)
                        logger.info(f"🤖 {_ag_tag}_AGENT_BLOCK_ENTRY {position_key}: {_ag_reason}")
                        return f"AGENT_BLOCK_ENTRY:{_ag_tag}"
            except Exception as _ag_err:
                logger.warning(f"[AGENT] tradier advisory check failed for {position_key}: {_ag_err}")
        
        # --- CHECK OPPOSING POSITION ---
        opposing_side = "SHORT" if position_side == "LONG" else "LONG"
        from utils import construct_position_key
        opposing_key = construct_position_key(account_key, symbol, opposing_side)
        opposing_pos = trade_manager.position_manager.get_position(opposing_key)
        has_opposing_pos = opposing_pos and abs(float(getattr(opposing_pos, 'positionAmt', 0))) > 0
        current_price, ts = await trade_manager.get_current_price(symbol)
        current_price = safe_fetch_float(current_price, 0.0)
        macro_fresh, freshness_reason, m1_fresh, indicators_raw = await trade_manager.is_data_fresh(symbol, position_key)
        # Warm STDEV BB buffers AND update breakout state continuously (not just in entry branch)
        if getattr(config, "STDEV_BREAKOUT_ENABLED", False) and indicators_raw:
            for _sb_tf_w in getattr(config, "STDEV_BREAKOUT_HTF_LIST", ["D", "4h"]) + getattr(config, "STDEV_BREAKOUT_RETEST_TF_LIST", ["1h", "15m"]):
                _get_bb_pctb_t(symbol, _sb_tf_w, indicators_raw)
            # Update breakout state continuously so it's ready when entry branch fires
            _update_stdev_state(symbol, indicators_raw)
        if not macro_fresh:
            _fa_floor_hit, _fa_breach, _r1_breached = False, False, False
            if has_position and position:
                try:
                    _is_long = position_side == 'LONG'
                    _fa_floor_pct = float(getattr(config, 'FROZEN_ABSOLUTE_FLOOR_PCT_TRADIER', -8.0))
                    _fa_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                    _fa_floor_hit = _fa_gain <= _fa_floor_pct
                    _fa_frozen = getattr(position, '_frozen_dc_act', None)
                    if _fa_frozen is not None: _fa_breach = ((_is_long and current_price < _fa_frozen) or (not _is_long and current_price > _fa_frozen)) and _fa_gain < 0
                    _r1_stop = getattr(position, 'r1_stop_price', 0.0) or 0.0
                    if _r1_stop > 0: _r1_breached = (_is_long and current_price <= _r1_stop) or (not _is_long and current_price >= _r1_stop)
                except Exception: pass
            if has_position and not (_fa_floor_hit or _fa_breach or _r1_breached):
                logger.info(f"[STALE_HOLD] {symbol}: indicators stale but HOLDING position (stale data must NEVER trigger exits)")
                return "STALE_INDICATORS_HELD"
            elif not has_position:
                return "STALE_ABSOLUTE_NO_POS"
        if not force and (now_ts - last_mon < 30):
            return "THROTTLED"
        is_stale = not macro_fresh
        m1_stale = not m1_fresh
        
        if not indicators_raw:
            if force: logger.info(f"[{account_key}] SKIP {symbol}: No indicators found.")
            return "NO_DATA"

        i = trade_manager.strategy.parse_market_data(indicators_raw)
        # Warm the shared Bottom-A trail history while flat.  Active-position
        # decisions are returned by evaluate_stop below, which is the same
        # action site used by live Tradier and backtest_v8.  The research
        # ``..._EXTENDED`` alias is intentionally absent from both read sites.
        _bottom_a_side = "LONG" if position_side == "LONG" else "SHORT"
        if (not has_position) and bool(_cfg(
            "BOTTOM_A_PROTECTIVE_TRAIL_ENABLED", False,
            account_key, symbol, _bottom_a_side,
        )):
            try:
                _ordinary_bottom_a_exit(
                    trade_manager,
                    position_key,
                    indicators_raw or i,
                    position_side == "LONG",
                    False,
                    _ordinary_bottom_a_params(
                        account_key, symbol, _bottom_a_side
                    ),
                )
            except (TypeError, ValueError) as _bottom_a_err:
                logger.error(
                    f"[BOTTOM_A_PROTECTIVE_TRAIL] invalid recipe for "
                    f"{position_key}: {_bottom_a_err}"
                )
        # Shared direct-entry contracts are observed on every decision row,
        # including while a position is held, so their episode-start state is
        # identical to V8.  A held observation can update state but cannot own
        # an order.  All reads are from the explicit completed snapshot schema.
        _shared_direct_claim = _shared_direct_entry_claim(
            trade_manager, position_key, indicators_raw,
            account_key, symbol, _bottom_a_side,
            allow_claim=(
                not bool(has_position) and is_regular_trading_hours()
            ),
        )
        if not has_position:
            try:
                _ordinary_bottom_b_exit(
                    trade_manager, position_key, indicators_raw,
                    account_key, symbol, _bottom_a_side, False,
                )
            except (TypeError, ValueError) as _bottom_b_warm_err:
                logger.error(
                    f"[BOTTOM_B_DELAYED_LOWER_TOP] warm-up blocked for "
                    f"{position_key}: {_bottom_b_warm_err}"
                )
        if symbol.upper() in trade_manager.blacklist and not has_position: return "BLOCKED_BLACKLIST"
        # A short-TF 50/50 snapshot may reject a *flat entry candidate*, but it
        # must never suppress monitoring of an existing position.  The previous
        # unconditional return sat before evaluate_stop, so a B&H seed could
        # never reach completed-parent exits such as E02 when short-TF fields
        # were neutral or absent.
        _stateful_reclaim_raw = trade_manager.__dict__.setdefault(
            "_mandatory_reclaim_obligations", {}
        ).get(position_key)
        _stateful_reclaim_pending = (
            bool(_stateful_reclaim_raw.get("pending", False))
            if isinstance(_stateful_reclaim_raw, dict)
            else bool(getattr(_stateful_reclaim_raw, "pending", False))
        )
        _stateful_ladder_enabled = bool(_cfg(
            "LR_BAND_LADDER_ENABLED", False,
            account_key, symbol, position_side,
        )) and bool(_cfg(
            "LR_BAND_LADDER_ORDINARY_PARITY_ENABLED", False,
            account_key, symbol, position_side,
        ))
        _stateful_direct_enabled = _shared_direct_route_enabled(
            account_key, symbol, position_side
        )
        if flat_entry_data_error(
            i,
            has_position=bool(has_position),
            stateful_route_required=(
                _stateful_reclaim_pending or _stateful_ladder_enabled
                or _stateful_direct_enabled
            ),
        ):
             if force: logger.info(f"[{account_key}] SKIP {symbol}: Flatline Data (50/50).")
             return "DATA_ERROR"

        # 3. DETERMINE PRICE
        current_price,ts = await trade_manager.get_current_price(symbol)
        position = trade_manager.position_manager.get_position(position_key)
        if current_price is None: current_price=position.mark_price if position else None
        if current_price is None: current_price=indicators_raw.get('current_price')

        current_price = safe_fetch_float(current_price, 0.0)

        if current_price <= 0 and position:
            current_price = safe_fetch_float(getattr(position, 'mark_price', 0), 0.0)
        
        if current_price <= 0:
            if force: logger.info(f"[{account_key}] SKIP {symbol}: Price is Zero.")
            return "NO_PRICE"
        is_long = (position_side == "LONG")

        # Hard exit safety runs before any strategy path and before an advisory
        # HOLD can return.  This is deliberately the 4h channel, not the
        # newborn-only 5m R1 stop.
        if (
            account_key in {"trb", "trc"}
            and has_position
            # The legacy name predates this 4h implementation.  It is still
            # the explicit master for this emergency-channel family; without
            # it an all-false V8 control can close a position before the
            # selected path is evaluated.
            and bool(getattr(config, "EXIT_EMERGENCY_DC1H_ENABLED", False))
        ):
            _dc4_exit, _dc4_exit_detail = dc_4h_boundary_breached(
                current_price, position_side, i, require_level=False
            )
            if _dc4_exit:
                _dc4_gain = safe_fetch_float(getattr(position, "gain", 0), 0.0)
                logger.critical(
                    f"🛑 [EMERGENCY_DC4H_BREACH] {position_key}: {_dc4_exit_detail} gain={_dc4_gain:.2f}% — forcing CLOSE"
                )
                await queue_trade_action(
                    order_queue,
                    trade_manager,
                    position_key,
                    "CLOSE",
                    f"EMERGENCY_DC4H_BREACH_{_dc4_exit_detail}_g{_dc4_gain:.2f}",
                    100.0,
                    override_qty=999999,
                )
                return "EMERGENCY_DC4H_CLOSE"
        if _agent_hold_deferred:
            return _agent_hold_deferred
        # ═══════════════════════════════════════════════════════════════════════
        # TR_TREND_V1 SHADOW-LOG (2026-05-17). spec: vec_paths/tr_trend_v1.py +
        # data/research_20260516/strategy_plan.md §4 + tr_trend_v1_build_report.md.
        # Default OFF (config_tradier.TR_TREND_V1_ENABLED=False) → zero impact.
        # When ENABLED=True: emits [TR_TREND_V1_SHADOW] entry/exit candidates for
        # top-8 shadow syms (TRGP/SNDK/AVGO/GLD/PLTR/MU/CDE/SLV, LONG only).
        # When TR_TREND_V1_SHADOW_LOG_ONLY=True (default) NO real orders fire.
        # Wrapped in try so any adapter failure does NOT break R1/R2/existing flow.
        # ═══════════════════════════════════════════════════════════════════════
        if bool(getattr(config, 'TR_TREND_V1_ENABLED', False)):
            try:
                _trv1_has_pos = bool(position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0)
                _trv1_entry = evaluate_tr_trend_v1_entry_live(symbol, account_key, position_side, indicators_raw, current_price, _trv1_has_pos, config)
                if _trv1_entry is not None:
                    logger.info(f"[TR_TREND_V1_SHADOW] ENTRY_CANDIDATE acct={account_key} sym={symbol} side={position_side} path={_trv1_entry.get('path')} pivot={_trv1_entry.get('pivot_price', 0):.4f} stop={_trv1_entry.get('stop_price', 0):.4f} mark={current_price:.4f} reason={_trv1_entry.get('reason')}")
                    if not bool(getattr(config, 'TR_TREND_V1_SHADOW_LOG_ONLY', True)):
                        # FUTURE: route to queue_trade_action for real entry. SHADOW = log only.
                        pass
                _trv1_exit = evaluate_tr_trend_v1_exit_live(symbol, account_key, position_side, indicators_raw, current_price, _trv1_has_pos, config)
                if _trv1_exit is not None:
                    _trv1_gain = safe_fetch_float(getattr(position, 'gain', 0), 0) if position else 0.0
                    logger.info(f"[TR_TREND_V1_SHADOW] EXIT_CANDIDATE acct={account_key} sym={symbol} side={position_side} mark={current_price:.4f} gain={_trv1_gain:.2f}% reason={_trv1_exit.get('reason')}")
                    if not bool(getattr(config, 'TR_TREND_V1_SHADOW_LOG_ONLY', True)):
                        pass
            except Exception as _trv1_err:
                logger.warning(f"[TR_TREND_V1_SHADOW] eval_error acct={account_key} sym={symbol} side={position_side}: {_trv1_err}")
        # ═══════════════════════════════════════════════════════════════════════
        # DYN_STRUCT_TRAIL (2026-07-19, default OFF) — monotone structure-following
        # trail: stop = trailing dc_low_{tf} (dc_high for shorts), ratchets only in
        # the favorable direction; arms once gain >= DYN_STRUCT_TRAIL_MIN_GAIN_PCT.
        # Live mirror of the engine block (parity); reason FROZEN_STOP_* bypass.
        if position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0 and \
           bool(_cfg('DYN_STRUCT_TRAIL_ENABLED', False, account_key, symbol, position_side)):
            try:
                _dst_tf = str(_cfg('DYN_STRUCT_TRAIL_TF', '4h', account_key, symbol, position_side) or '4h')
                _dst_min_g = safe_float(_cfg('DYN_STRUCT_TRAIL_MIN_GAIN_PCT', 0.0, account_key, symbol, position_side), 0.0)
                _dst_key = ('dc_low_' if is_long else 'dc_high_') + _dst_tf
                _dst_cur = safe_fetch_float(i.get(_dst_key), 0.0)
                _dst_st = getattr(position, 'dyn_strail_state', None)
                if not isinstance(_dst_st, dict):
                    _dst_st = {'lvl': 0.0, 'armed': _dst_min_g <= 0.0}
                    position.dyn_strail_state = _dst_st
                _dst_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                if _dst_gain >= _dst_min_g:
                    _dst_st['armed'] = True
                if _dst_cur > 0:
                    if _dst_st['lvl'] <= 0:
                        _dst_st['lvl'] = _dst_cur
                    elif is_long and _dst_cur > _dst_st['lvl']:
                        _dst_st['lvl'] = _dst_cur
                    elif (not is_long) and _dst_cur < _dst_st['lvl']:
                        _dst_st['lvl'] = _dst_cur
                if _dst_st['armed'] and _dst_st['lvl'] > 0 and ((is_long and current_price <= _dst_st['lvl']) or ((not is_long) and current_price >= _dst_st['lvl'])):
                    logger.error(f"⛔ [DYN_STRUCT_TRAIL] {position_key}: g={_dst_gain:.2f}% px={current_price:.4f} lvl={_dst_st['lvl']:.4f} tf={_dst_tf} → CLOSE")
                    await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", f"FROZEN_STOP_DYN_STRUCT_TRAIL_{_dst_tf}_g{_dst_gain:.2f}", 100.0, override_qty=999999)
            except Exception as _dst_e:
                logger.warning(f"[DYN_STRUCT_TRAIL] error {position_key}: {_dst_e}")
        # MTF_ARROW_TRAIL — lab-faithful exit half of the arrow system (mtf_arrow_lab
        # phase_b :178: exit when px retraces CONFIRM_PCT off the running high). Default
        # OFF; enabled per-pack in sweeps. Loss-closes require MTF_ARROW_TRAIL in
        # UNIVERSAL_NOLOSS_GATE_BYPASS_REASONS (pack-scoped) or the gate holds them.
        if position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0 and is_long and \
           bool(getattr(config, 'MTF_ARROW_TRAIL_EXIT_ENABLED', False)):
            try:
                _mat_conf = float(getattr(config, 'MTF_ARROW_CONFIRM_PCT', 2.0))
                _mat_st = getattr(position, 'arrow_trail_state', None)
                # Cycle key includes entry_price: engine/live position objects are REUSED on
                # reopen without refreshing opened_at, so opened_at alone kept the previous
                # trade's high → instant exit at the new lower entry (median 5-min holds,
                # 714/807 trail exits in the 2026-07-21 ARROW_PURE ARM forensic cell).
                _mat_opened = f"{getattr(position, 'opened_at', '')}|{getattr(position, 'entry_price', 0)}"
                if not isinstance(_mat_st, dict) or _mat_st.get('opened_at') != _mat_opened:
                    _mat_st = {'hi': current_price, 'opened_at': _mat_opened}
                    position.arrow_trail_state = _mat_st
                _mat_hi = safe_fetch_float(_mat_st.get('hi', 0.0), 0.0)
                if current_price > _mat_hi:
                    _mat_st['hi'] = current_price
                    _mat_hi = current_price
                if _mat_hi > 0 and current_price <= _mat_hi * (1.0 - _mat_conf / 100.0):
                    _mat_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                    logger.error(f"⛔ [MTF_ARROW_TRAIL] {position_key}: px={current_price:.4f} hi={_mat_hi:.4f} conf={_mat_conf}% g={_mat_gain:.2f}% → CLOSE")
                    _arrow_dbg(f"TRAIL_EXIT {position_key} px={current_price:.2f} hi={_mat_hi:.2f} g={_mat_gain:.2f}")
                    await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", f"MTF_ARROW_TRAIL_g{_mat_gain:.2f}_hi{_mat_hi:.2f}", 100.0, override_qty=999999)
            except Exception as _mat_e:
                logger.warning(f"[MTF_ARROW_TRAIL] error {position_key}: {_mat_e}")
        # R1 — DC_LOW4 EMERGENCY CLOSE (USER 2026-05-09, stocks mirror).
        # Fires within R1_NEWBORN_WINDOW_MIN of open if price breaks the configured
        # 5m DC channel level. Bypasses NO_LOSS / hedge / MTF. Desktop alert + JSONL.
        # ═══════════════════════════════════════════════════════════════════════
        if position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0 and \
           bool(_cfg('R1_DC_LOW4_3M_EMERGENCY_ENABLED', False, account_key, symbol, position_side)):
            try:
                # 2026-07-11 RESTORED per CLAUDE.md R1 mandate + MU_LONG capture artifact:
                # R1 is a NEWBORN emergency (first R1_NEWBORN_WINDOW_MIN of a position's life),
                # NOT a permanent stop. The windowless version + live-channel lazy re-seed
                # ratcheted the stop up behind price and closed 28-day-old positions at g~0
                # in a loop (mandatory reentry made it churn: MU_LONG b&h +744% vs strategy
                # -0.2% over 47 trades). Window gate enforced below; lazy seed only inside
                # the window and only once (frozen thereafter).
                _r1_age_min = None
                _r1_opened = parse_position_timestamp(getattr(position, 'opened_at', None))
                if isinstance(_r1_opened, datetime):
                    _r1_age_min = max(0.0, (datetime.now(timezone.utc) - _r1_opened).total_seconds() / 60.0)
                _r1_window_min = float(_cfg('R1_NEWBORN_WINDOW_MIN', 15.0, account_key, symbol, position_side) or 15.0)
                # Fail closed: missing or invalid lifecycle state can never mean
                # "newborn".  This was the cause of repeated age=0.0m churn.
                _r1_in_window = _r1_age_min is not None and _r1_age_min <= _r1_window_min
                if _r1_age_min is None:
                    logger.warning(f"[R1_SKIPPED_OPEN_TIME_UNAVAILABLE] {position_key}: opened_at={getattr(position, 'opened_at', None)!r}")
                _r1_stop = float(getattr(position, 'r1_stop_price', 0.0) or 0.0) if _r1_in_window else 0.0
                if _r1_stop <= 0 and _r1_in_window:
                    _r1_live_key = ('dc_low4_5m' if is_long else 'dc_high4_5m') if bool(getattr(config, 'R1_USE_DC_4BAR', True)) else ('dc_low_5m' if is_long else 'dc_high_5m')  # 2026-07-01 R1_USE_DC_4BAR wired: True=4-bar (stocks default, pending A/B); False=20-bar dc_low_5m
                    _r1_stop_live = safe_fetch_float(i.get(_r1_live_key), 0.0)
                    if _r1_stop_live > 0:
                        _r1_stop = _r1_stop_live
                        position.r1_stop_price = _r1_stop_live  # frozen once set; never re-seeded from live channel
                        logger.info(f"[R1_STOP_LAZY_SET] {position_key}: r1_stop_price not set — initialised (newborn, age={_r1_age_min:.1f}m) from live {_r1_live_key}={_r1_stop_live:.4f}")
                if _r1_stop > 0:
                    if bool(getattr(config, 'R1_REQUIRE_WT15_ADVERSE', True)):
                        _r1_wt15_1 = safe_fetch_float(i.get('wt1_15m'), 0.0)
                        _r1_wt15_2 = safe_fetch_float(i.get('wt2_15m'), 0.0)
                        _r1_wt15_v = safe_fetch_float(i.get('wt_velocity_15m'), 0.0)
                        _r1_wt15_adverse = (
                            (_r1_wt15_1 < _r1_wt15_2 and _r1_wt15_v < 0.0)
                            if is_long else
                            (_r1_wt15_1 > _r1_wt15_2 and _r1_wt15_v > 0.0)
                        )
                        if not _r1_wt15_adverse:
                            logger.info(
                                f"[R1_WT15_HOLD] {position_key}: WT15 not adverse/moving against "
                                f"(wt1={_r1_wt15_1:.2f},wt2={_r1_wt15_2:.2f},vel={_r1_wt15_v:.3f})"
                            )
                            return "R1_WT15_HOLD"
                    _r1_breached = (
                        (is_long and current_price <= _r1_stop) or
                        ((not is_long) and current_price >= _r1_stop)
                    )
                    if _r1_breached:
                        _r1_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                        _r1_entry_sig = getattr(position, 'last_signal', '') or getattr(position, 'open_reason', '') or '?'
                        _r1_entry_ts = str(getattr(position, 'opened_at', ''))[:19]
                        logger.error(f"⛔ [R1_DC_LOW4_EMERGENCY] {position_key}: g={_r1_gain:.2f}% age={_r1_age_min:.1f}m price={current_price:.4f} {'<=' if is_long else '>='} r1_stop={_r1_stop:.4f} entry={str(_r1_entry_sig)[:40]} → CLOSE")
                        # 2026-05-10 USER MANDATE: action-first. Try CLOSE; alert ONLY on
                        # unexplained failure. Min-notional / qty=0 / blacklist suppress.
                        _r1_failed = False
                        _r1_err_str = None
                        try:
                            _r1_qa_result = await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", f"R1_DC_LOW4_EMERGENCY_g{_r1_gain:.2f}_age{_r1_age_min:.1f}m_entry_{str(_r1_entry_sig)[:30]}", 100.0, override_qty=999999)
                            if isinstance(_r1_qa_result, str) and ('BLOCK' in _r1_qa_result.upper() or 'SKIP' in _r1_qa_result.upper() or 'REJECT' in _r1_qa_result.upper()):
                                _r1_failed = True
                                _r1_err_str = _r1_qa_result
                        except Exception as _r1_qa_err:
                            _r1_failed = True
                            _r1_err_str = repr(_r1_qa_err)
                        if not _r1_failed:
                            return f"R1_DC_LOW4_EMERGENCY_CLOSED"
                        try:
                            import ez_alert
                            _r1_should = ez_alert.should_alert_for_failure(_r1_err_str)
                        except Exception:
                            _r1_should = True
                        if _r1_should:
                            logger.critical(f"☢️ [R1_CLOSE_AGENT_BUG] {position_key}: close failed with no valid reason: {_r1_err_str}")
                            try:
                                import ez_alert
                                ez_alert.alert_bad_exit(account=account_key, position_key=position_key, gain=_r1_gain, reason=f"R1_CLOSE_DID_NOT_EXECUTE_NO_VALID_REASON_err={str(_r1_err_str)[:80]}", entry_signal=str(_r1_entry_sig), entry_ts=_r1_entry_ts, current_price=current_price)
                            except Exception:
                                pass
                        else:
                            logger.warning(f"[R1_CLOSE_VALID_SKIP] {position_key}: close suppressed for valid reason: {_r1_err_str}")
                        return f"R1_DC_LOW4_EMERGENCY_FAILED:{str(_r1_err_str)[:40]}"
            except Exception as _r1_err:
                logger.debug(f"[R1_DC_LOW4] {position_key} err: {_r1_err}")
        # ═══════════════════════════════════════════════════════════════════════
        # HYBRID EXIT — Timeframe Exit Combinations for Lower-HL exits (Structure-Breakdown)
        # ═══════════════════════════════════════════════════════════════════════
        if position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0:
            try:
                _se_tf = _cfg("EXIT_STRUCT_TF", "None", account_key, symbol, position_side)
                if _se_tf == "None" or not _se_tf: _se_tf = _cfg("LONG_STRUCT_EXIT_TF" if is_long else "SHORT_STRUCT_EXIT_TF", "None", account_key, symbol, position_side)
                if _se_tf != "None" and _se_tf and i:
                    _se_open = safe_fetch_float(i.get(f"open_{_se_tf}"), 0.0)
                    _se_high_prev = safe_fetch_float(i.get(f"high_{_se_tf}_prev"), 0.0)
                    _se_low_prev = safe_fetch_float(i.get(f"low_{_se_tf}_prev"), 0.0)
                    if _se_open > 0 and _se_high_prev > 0 and _se_low_prev > 0:
                        _last_open = getattr(position, "_last_struct_open", None)
                        if _last_open is None:
                            setattr(position, "_last_struct_open", _se_open)
                            setattr(position, "_last_high_prev", _se_high_prev)
                            setattr(position, "_last_low_prev", _se_low_prev)
                        elif abs(_se_open - _last_open) > 1e-8:
                            _last_hp = getattr(position, "_last_high_prev", _se_high_prev)
                            _last_lp = getattr(position, "_last_low_prev", _se_low_prev)
                            _se_fire = (_se_high_prev < _last_hp and _se_low_prev < _last_lp) if is_long else (_se_high_prev > _last_hp and _se_low_prev > _last_lp)
                            setattr(position, "_last_struct_open", _se_open)
                            setattr(position, "_last_high_prev", _se_high_prev)
                            setattr(position, "_last_low_prev", _se_low_prev)
                            if _se_fire:
                                _se_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                                logger.error(f"⛔ [HYBRID_STRUCT_EXIT] {position_key}: structure breakdown on {_se_tf} (high_prev={_se_high_prev:.4f} vs last_hp={_last_hp:.4f}, low_prev={_se_low_prev:.4f} vs last_lp={_last_lp:.4f}) → CLOSE")
                                await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", f"HYBRID_STRUCT_EXIT_{_se_tf}_g{_se_gain:.2f}%", 100.0, override_qty=999999)
                                return "HYBRID_STRUCT_EXIT_CLOSED"
            except Exception as _se_err:
                logger.debug(f"[HYBRID_STRUCT_EXIT] {position_key} err: {_se_err}")
        # ═══════════════════════════════════════════════════════════════════════
        # R1c — FROZEN_ACT_STOP (USER 2026-05-18 stocks team finding).
        # Frozen dc_low_4h@entry (LONG) / dc_high_4h@entry (SHORT) + -8% absolute floor.
        # Worst stocks loss capped at -9% (vs -12.6% baseline). 4 stops/sym/yr.
        # ═══════════════════════════════════════════════════════════════════════
        if position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0 and \
           bool(getattr(config, 'FROZEN_ACTIVATION_STOP_ENABLED', True)):
            try:
                _fa_tf = str(getattr(config, 'FROZEN_ACTIVATION_TF', '4h'))
                _fa_floor_pct = float(getattr(config, 'FROZEN_ABSOLUTE_FLOOR_PCT_TRADIER', -8.0))
                _fa_is_long = position_side == 'LONG'
                _fa_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                _fa_frozen = getattr(position, '_frozen_dc_act', None)
                if _fa_frozen is None and i:
                    _fa_field = f'dc_low_{_fa_tf}' if _fa_is_long else f'dc_high_{_fa_tf}'
                    _fa_raw = i.get(_fa_field)
                    if _fa_raw not in (None, 0, 0.0):
                        try:
                            _fa_frozen = float(_fa_raw)
                            setattr(position, '_frozen_dc_act', _fa_frozen)
                        except (TypeError, ValueError):
                            _fa_frozen = None
                _fa_floor_hit = _fa_gain <= _fa_floor_pct
                _fa_breach = False
                if _fa_frozen is not None:
                    _fa_breach = ((_fa_is_long and current_price < _fa_frozen)
                                  or (not _fa_is_long and current_price > _fa_frozen)) and _fa_gain < 0
                if _fa_floor_hit or _fa_breach:
                    _fa_tag = 'FROZEN_ACT_STOP_ABSOLUTE_FLOOR' if _fa_floor_hit else 'FROZEN_ACT_STOP_FROZEN_BREACH'
                    _fa_reason = (f'{_fa_tag}_g{_fa_gain:.2f}%_floor{_fa_floor_pct:.1f}%' if _fa_floor_hit
                                  else f'{_fa_tag}_g{_fa_gain:.2f}%_frozen{_fa_tf}={_fa_frozen}_cur={current_price}')
                    logger.error(f"⛔ [{_fa_tag}] {position_key}: g={_fa_gain:.2f}% frozen_{_fa_tf}={_fa_frozen} cur={current_price:.4f} floor={_fa_floor_pct:.1f}% → CLOSE")
                    await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", _fa_reason, 100.0, override_qty=999999)
                    return f"{_fa_tag}_CLOSED"
            except Exception as _fa_err:
                logger.debug(f"[FROZEN_ACT_STOP] {position_key} err: {_fa_err}")
        # ═══════════════════════════════════════════════════════════════════════
        # R2 — WT_VEL_SLOW near-breakeven exit (USER 2026-05-09, stocks mirror).
        # Stocks use HTFs (default 1h/4h/D) per user — markets closed most of day,
        # real moves happen on D/W. floor <= gain < band, |vel| < |vel_prev|*ratio.
        # ═══════════════════════════════════════════════════════════════════════
        if position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0 and \
           bool(getattr(config, 'WT_15M_VEL_SLOW_AT_ZERO_GAIN_ENABLED', True)):
            try:
                _wzg_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                _wzg_max_gain = safe_fetch_float(getattr(position, 'max_gain', 0), 0)
                _wzg_peak_min = float(getattr(config, 'R2_PEAK_MIN_PCT', 0.5))
                # 2026-05-18 per-sym overlay
                _wzg_band = float(_cfg('WT_15M_VEL_SLOW_GAIN_BAND_PCT', 0.10, account_key, symbol, position_side))
                _wzg_floor = float(_cfg('WT_15M_VEL_SLOW_GAIN_FLOOR_PCT', 0.01, account_key, symbol, position_side))
                _wzg_near_zero = float(_cfg('WT_15M_VEL_NEAR_ZERO_THRESHOLD', 0.1, account_key, symbol, position_side))
                _wzg_decel_ratio = float(_cfg('WT_VEL_DECEL_RATIO', 0.5, account_key, symbol, position_side))
                _wzg_decel_only = bool(_cfg('WT_VEL_USE_DECEL_RATIO_ONLY', True, account_key, symbol, position_side))
                _wzg_tfs = tuple(_cfg('R2_TF_LIST', ('1h', '4h', 'D'), account_key, symbol, position_side) or ('1h', '4h', 'D'))
                # PEAK-THEN-COLLAPSE only — see ez_manage.py:20783 comment.
                if _wzg_max_gain >= _wzg_peak_min and _wzg_floor <= _wzg_gain < _wzg_band:
                    _wzg_fired_tf = None
                    _wzg_vel = 0.0
                    _wzg_vel_prev = 0.0
                    _wzg_tag = ''
                    for _wzg_tf in _wzg_tfs:
                        _v = safe_fetch_float(i.get(f'wt_velocity_{_wzg_tf}'), 0)
                        _vp = safe_fetch_float(i.get(f'wt_velocity_{_wzg_tf}_prev', _v), 0)
                        _against = (is_long and _v < 0) or ((not is_long) and _v > 0)
                        _decel = abs(_v) < abs(_vp) * _wzg_decel_ratio and abs(_vp) > 1e-6
                        _dying = (not _wzg_decel_only) and abs(_v) <= _wzg_near_zero
                        if _against and (_decel or _dying):
                            _wzg_fired_tf, _wzg_vel, _wzg_vel_prev = _wzg_tf, _v, _vp
                            _wzg_tag = 'DECEL' if _decel else 'DYING'
                            break
                    if _wzg_fired_tf:
                        logger.error(f"⛔ [R2_WT_VEL_SLOW] {position_key}: peak={_wzg_max_gain:.2f}% (≥{_wzg_peak_min}%) collapsed→g={_wzg_gain:.3f}% in [{_wzg_floor},{_wzg_band}], wt_vel_{_wzg_fired_tf}={_wzg_vel:.3f} (prev={_wzg_vel_prev:.3f}) AGAINST+{_wzg_tag} ratio={_wzg_decel_ratio} → CLOSE")
                        await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", f'R2_WT_VEL_SLOW_{_wzg_tag}_{_wzg_fired_tf}_g{_wzg_gain:.3f}%_peak{_wzg_max_gain:.2f}%_vel{_wzg_vel:.3f}vs{_wzg_vel_prev:.3f}', 100.0, override_qty=999999)
                        return f"R2_WT_VEL_SLOW_CLOSED:{_wzg_fired_tf}_{_wzg_tag}"
            except Exception as _wzg_err:
                logger.debug(f"[R2_WT_VEL_SLOW] {position_key} err: {_wzg_err}")
        # ═══════════════════════════════════════════════════════════════════════
        # R3_HTF_FLIP — Daily-close + parallel 4h structural exit (USER 2026-05-17).
        # Source: data/research_20260516/PLAN.md §3.6. Mirror of crypto block in ez_manage.
        #   LONG closes when:
        #     Daily tier: (current_price < dc_basis_D) OR (wt1_D < wt2_D AND wt1_W < wt2_W)
        #     4h tier:    (current_price < ema_20_4h - atr_4h) AND wt1_4h < wt2_4h
        #   SHORT mirror. Reasons R3_HTF_FLIP / R3_HTF_FLIP_4H are in LOSS_EXIT_TECHNICAL_BYPASS.
        # ROLLBACK: R3_HTF_FLIP_EXIT_ENABLED=False (and/or _4H_TIER_ENABLED=False) in config_tradier.py.
        # ═══════════════════════════════════════════════════════════════════════
        # 2026-05-18 per-sym overlay
        if (position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0 and bool(_cfg('R3_HTF_FLIP_EXIT_ENABLED', False, account_key, symbol, position_side))):
            try:
                _r3_newborn_min = float(getattr(config, 'R3_HTF_FLIP_NEWBORN_WINDOW_MIN', 15.0))
                _r3_opened = getattr(position, 'opened_at', None)
                _r3_skip_newborn = False
                if _r3_newborn_min > 0 and isinstance(_r3_opened, datetime):
                    _r3_age_min = (datetime.now(timezone.utc) - _r3_opened).total_seconds() / 60.0
                    if _r3_age_min < _r3_newborn_min:
                        logger.debug(f"[R3_HTF_FLIP] {position_key}: newborn ({_r3_age_min:.1f}m < {_r3_newborn_min:.0f}m) — suppressed, R1 dc_low4_5m active")
                        _r3_skip_newborn = True
                _r3_skip_r1_guard = False
                _r3_r1_stop = float(getattr(position, 'r1_stop_price', 0.0) or 0.0)
                if _r3_r1_stop <= 0:
                    _r3_dc_key = 'dc_low4_5m' if is_long else 'dc_high4_5m'
                    _r3_r1_stop = safe_fetch_float(i.get(_r3_dc_key) or indicators_raw.get(_r3_dc_key), 0.0)
                if _r3_r1_stop > 0:
                    if (is_long and current_price > _r3_r1_stop) or ((not is_long) and current_price < _r3_r1_stop):
                        _r3_skip_r1_guard = True
                        logger.debug(f"[R3_HTF_FLIP] {position_key}: r1_stop={_r3_r1_stop:.4f} active, price={current_price:.4f} not breached — R3 deferred to R1")
                _r3hf_w1_D = safe_fetch_float(i.get('wt1_D'), 0)
                _r3hf_w2_D = safe_fetch_float(i.get('wt2_D'), 0)
                _r3hf_w1_W = safe_fetch_float(i.get('wt1_W'), 0)
                _r3hf_w2_W = safe_fetch_float(i.get('wt2_W'), 0)
                _r3hf_dc_basis_D = safe_fetch_float(i.get('dc_basis_D'), 0)
                _r3hf_atr_4h = safe_fetch_float(i.get('atr_4h'), 0)
                _r3hf_ema_20_4h = safe_fetch_float(i.get('ema_20_4h'), 0)
                _r3hf_w1_4h = safe_fetch_float(i.get('wt1_4h'), 0)
                _r3hf_w2_4h = safe_fetch_float(i.get('wt2_4h'), 0)
                _r3hf_fire = False
                _r3hf_tier = None
                _r3hf_detail = ""
                if _r3hf_dc_basis_D > 0:
                    _r3hf_dc_break = (is_long and current_price < _r3hf_dc_basis_D) or ((not is_long) and current_price > _r3hf_dc_basis_D)
                    _r3hf_wt_flip = (is_long and _r3hf_w1_D < _r3hf_w2_D and _r3hf_w1_W < _r3hf_w2_W) or ((not is_long) and _r3hf_w1_D > _r3hf_w2_D and _r3hf_w1_W > _r3hf_w2_W)
                    # 2026-06-03 USER MANDATE — KILL R3 CHURN: require the WT flip (Daily AND Weekly) to CONFIRM,
                    # not a bare DC break. Price oscillating the daily DC basis flipped dc_break every few minutes →
                    # buy-high/sell-low 1-share round-trips at ~0% gain (OKE/USO). ROLLBACK: R3_HTF_FLIP_REQUIRE_WT=False.
                    _r3hf_require_wt = bool(_cfg('R3_HTF_FLIP_REQUIRE_WT', True, account_key, symbol, position_side))
                    if ((_r3hf_dc_break and _r3hf_wt_flip) if _r3hf_require_wt else (_r3hf_dc_break or _r3hf_wt_flip)):
                        _r3hf_fire = True
                        _r3hf_tier = "DAILY"
                        _r3hf_detail = f"dc_break={_r3hf_dc_break}_wt_flip={_r3hf_wt_flip}_px={current_price:.4f}_dcBD={_r3hf_dc_basis_D:.4f}_w1D={_r3hf_w1_D:.2f}_w2D={_r3hf_w2_D:.2f}_w1W={_r3hf_w1_W:.2f}_w2W={_r3hf_w2_W:.2f}"
                if (not _r3hf_fire) and bool(_cfg('R3_HTF_FLIP_4H_TIER_ENABLED', False, account_key, symbol, position_side)):
                    if _r3hf_ema_20_4h > 0 and _r3hf_atr_4h > 0:
                        _r3hf_4h_long = is_long and current_price < (_r3hf_ema_20_4h - _r3hf_atr_4h) and _r3hf_w1_4h < _r3hf_w2_4h
                        _r3hf_4h_short = (not is_long) and current_price > (_r3hf_ema_20_4h + _r3hf_atr_4h) and _r3hf_w1_4h > _r3hf_w2_4h
                        if _r3hf_4h_long or _r3hf_4h_short:
                            _r3hf_fire = True
                            _r3hf_tier = "4H"
                            _r3hf_detail = f"px={current_price:.4f}_ema4h={_r3hf_ema_20_4h:.4f}_atr4h={_r3hf_atr_4h:.4f}_w1_4h={_r3hf_w1_4h:.2f}_w2_4h={_r3hf_w2_4h:.2f}"
                if _r3hf_fire and not _r3_skip_newborn and not _r3_skip_r1_guard:
                    _r3hf_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                    _r3hf_reason_tag = "R3_HTF_FLIP" if _r3hf_tier == "DAILY" else "R3_HTF_FLIP_4H"
                    logger.error(f"⛔ [{_r3hf_reason_tag}] {position_key}: tier={_r3hf_tier} gain={_r3hf_gain:.2f}% {_r3hf_detail} → CLOSE")
                    await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", f"{_r3hf_reason_tag}_{_r3hf_tier}_g{_r3hf_gain:.2f}%_{_r3hf_detail[:80]}", 100.0, override_qty=999999)
                    return f"{_r3hf_reason_tag}_CLOSED:{_r3hf_tier}"
            except Exception as _r3hf_err:
                logger.debug(f"[R3_HTF_FLIP] {position_key} err: {_r3hf_err}")
        # ═══════════════════════════════════════════════════════════════════════
        # MTF COMPOUND EXIT — Path A Phase 1 wiring 2026-05-19 (USER MANDATE) — stocks mirror.
        # Source: vec_paths/mtf_armed_entries.py:127-235. Replacement protection stack for
        # HEDGE_MODE + DC_LOW_4 emergency. 5 triggers, ANY fires CLOSE:
        #   1. MTF_ATR_TRAIL: ATR trail (ratchets from entry, default TF=1h for stocks per
        #      MTF_ATR_TRAIL_TF_TRADIER) × MTF_ATR_TRAIL_MULT
        #   2. MTF_DC_REJECT: price was outside dc_high/low_TF and re-crossed back
        #   3. MTF_BB_REJECT: BB tag-fail mask within MTF_BB_REJECT_EXIT_LOOKBACK bars
        #   4. MTF_GR_WT_EXIT: GR HTF exit gate (opposite-side TFs) AND wt cross against (BOTH)
        # Master switch MTF_EXIT_USE_COMPOUND defaults False → entire block inert.
        # New reasons MTF_ATR_TRAIL/MTF_DC_REJECT/MTF_BB_REJECT/MTF_GR_WT_EXIT are in
        # config_tradier.LOSS_EXIT_TECHNICAL_BYPASS so loss-side close fires past NOLOSS_DC4H.
        # Per-position trail state lives in trade_manager.mtf_compound_exit_state[position_key].
        # Tradier base TF = 5m → default TFs = 1h (~12x base) for ATR/DC/BB/WT.
        # ROLLBACK: set MTF_EXIT_USE_COMPOUND=False (already default).
        # ═══════════════════════════════════════════════════════════════════════
        # USER 2026-05-20: MTF compound exit applies only to positions opened after startup_ts
        # (or explicit config TS). Pre-MTF positions ride legacy exits — no restart cascade.
        _mtfce_min_ts_gate = float(_cfg('MTF_EXIT_MIN_OPEN_TS', 0.0, account_key, symbol, position_side))
        if _mtfce_min_ts_gate <= 0:
            if not hasattr(trade_manager, '_mtfce_startup_ts'):
                trade_manager._mtfce_startup_ts = time.time()
            _mtfce_min_ts_gate = trade_manager._mtfce_startup_ts
        # 2026-05-21 19:15 DATETIME CRASH FIX (user-mandated: 3556 CRASH events in trb log today
        # all "float() argument must be a string or a real number, not 'datetime.datetime'").
        # opened_at is a datetime object on positions loaded from disk; bare float() throws.
        # Pattern mirrors lines 13778/13832/13910/13968 in this file.
        _mtfce_opened_at = getattr(position, 'opened_at', 0) if position else 0
        if _mtfce_opened_at is None:
            _mtfce_pos_open_ts_gate = 0.0
        elif hasattr(_mtfce_opened_at, 'timestamp'):
            try: _mtfce_pos_open_ts_gate = float(_mtfce_opened_at.timestamp())
            except Exception: _mtfce_pos_open_ts_gate = 0.0
        elif isinstance(_mtfce_opened_at, (int, float)):
            _mtfce_pos_open_ts_gate = float(_mtfce_opened_at)
        else:
            _mtfce_pos_open_ts_gate = 0.0
        if (position and abs(safe_float(getattr(position, 'positionAmt', 0))) > 0
                and bool(_cfg('MTF_EXIT_USE_COMPOUND', False, account_key, symbol, position_side))
                and _mtf_position_open_is_eligible(_mtfce_pos_open_ts_gate, _mtfce_min_ts_gate)):
            try:
                if not hasattr(trade_manager, 'mtf_compound_exit_state'):
                    trade_manager.mtf_compound_exit_state = {}
                _mtfce_state = trade_manager.mtf_compound_exit_state.get(
                    position_key,
                    {'trail': 0.0, 'dc_outside_ts': 0.0, 'bb_tag_bars': []},
                )
                _mtfce_entry = safe_fetch_float(getattr(position, 'entry_price', 0), 0)
                _mtfce_fire = False
                _mtfce_reason = ""
                _mtfce_atr_tf = str(_cfg('MTF_ATR_TRAIL_TF_TRADIER', _cfg('MTF_ATR_TRAIL_TF', '1h', account_key, symbol, position_side), account_key, symbol, position_side))
                _mtfce_dc_tf = str(_cfg('MTF_DC_REJECT_EXIT_TF', '1h', account_key, symbol, position_side))
                _mtfce_bb_tf = str(_cfg('MTF_BB_REJECT_EXIT_TF', '1h', account_key, symbol, position_side))
                _mtfce_wt_tf = str(_cfg('MTF_WT_CROSS_EXIT_TF', '1h', account_key, symbol, position_side))
                _mtfce_atr_mult = float(_cfg('MTF_ATR_TRAIL_MULT', 2.5, account_key, symbol, position_side))
                _mtfce_dc_lb = max(1, int(_cfg('MTF_DC_REJECT_EXIT_LOOKBACK', 5, account_key, symbol, position_side)))
                _mtfce_bb_lb = int(_cfg('MTF_BB_REJECT_EXIT_LOOKBACK', 5, account_key, symbol, position_side))
                # Backtests inject _tick_ts/ts. Live indicators may omit both, in
                # which case wall clock remains the unchanged fallback.
                _mtfce_now_s = _mtf_indicator_event_timestamp(i, fallback_now=time.time())
                # ─── 1. MTF_ATR_TRAIL ─────────────────────────────────────────────
                if bool(_cfg('MTF_ATR_TRAIL_ENABLED', False, account_key, symbol, position_side)):
                    _mtfce_atr = safe_fetch_float(i.get(f'atr_{_mtfce_atr_tf}'), 0)
                    if _mtfce_atr > 0 and _mtfce_entry > 0 and current_price is not None and current_price > 0:
                        if is_long:
                            _mtfce_cand = max(_mtfce_entry - _mtfce_atr_mult * _mtfce_atr, current_price - _mtfce_atr_mult * _mtfce_atr)
                            _mtfce_state['trail'] = max(_mtfce_state.get('trail', 0.0), _mtfce_cand) if _mtfce_state.get('trail', 0.0) > 0 else _mtfce_cand
                            if _mtfce_state['trail'] > 0 and current_price < _mtfce_state['trail']:
                                _mtfce_fire = True
                                _mtfce_reason = f"MTF_ATR_TRAIL_{_mtfce_atr_tf}_x{_mtfce_atr_mult}_lvl{_mtfce_state['trail']:.4f}"
                        else:
                            _mtfce_cand = min(_mtfce_entry + _mtfce_atr_mult * _mtfce_atr, current_price + _mtfce_atr_mult * _mtfce_atr)
                            _mtfce_state['trail'] = min(_mtfce_state.get('trail', 0.0), _mtfce_cand) if _mtfce_state.get('trail', 0.0) > 0 else _mtfce_cand
                            if _mtfce_state['trail'] > 0 and current_price > _mtfce_state['trail']:
                                _mtfce_fire = True
                                _mtfce_reason = f"MTF_ATR_TRAIL_{_mtfce_atr_tf}_x{_mtfce_atr_mult}_lvl{_mtfce_state['trail']:.4f}"
                # ─── 2. MTF_DC_REJECT ─────────────────────────────────────────────
                if (not _mtfce_fire) and bool(_cfg('MTF_DC_REJECT_EXIT_ENABLED', False, account_key, symbol, position_side)):
                    _mtfce_band = safe_fetch_float(
                        i.get(
                            f"dc_{'high' if is_long else 'low'}_{_mtfce_dc_tf}"
                        ),
                        0,
                    )
                    (
                        _mtfce_state['dc_outside_ts'],
                        _mtfce_dc_fire,
                    ) = _mtf_dc_reject_step(
                        _mtfce_state.get('dc_outside_ts', 0),
                        now_ts=_mtfce_now_s,
                        price=current_price,
                        band=_mtfce_band,
                        lookback_bars=_mtfce_dc_lb,
                        timeframe=_mtfce_dc_tf,
                        is_long=is_long,
                    )
                    if _mtfce_dc_fire:
                        _mtfce_fire = True
                        _mtfce_reason = f"MTF_DC_REJECT_{_mtfce_dc_tf}_px{current_price:.4f}"
                # ─── 3. MTF_BB_REJECT ─────────────────────────────────────────────
                if (not _mtfce_fire) and bool(_cfg('MTF_BB_REJECT_EXIT_ENABLED', False, account_key, symbol, position_side)):
                    _mtfce_bbu = safe_fetch_float(i.get(f'bb_upper_{_mtfce_bb_tf}'), 0)
                    _mtfce_bbl = safe_fetch_float(i.get(f'bb_lower_{_mtfce_bb_tf}'), 0)
                    _mtfce_high = safe_fetch_float(i.get(f'high_{_mtfce_bb_tf}'), current_price)
                    _mtfce_low = safe_fetch_float(i.get(f'low_{_mtfce_bb_tf}'), current_price)
                    if is_long and _mtfce_bbu > 0:
                        _mtfce_tag_now = _mtfce_high >= _mtfce_bbu - 1e-9
                        _mtfce_fail_now = (_mtfce_high < _mtfce_bbu) and _mtfce_high > 0
                    elif (not is_long) and _mtfce_bbl > 0:
                        _mtfce_tag_now = _mtfce_low <= _mtfce_bbl + 1e-9 and _mtfce_low > 0
                        _mtfce_fail_now = (_mtfce_low > _mtfce_bbl) and _mtfce_low > 0
                    else:
                        _mtfce_tag_now = False
                        _mtfce_fail_now = False
                    _mtfce_tag_bars = list(_mtfce_state.get('bb_tag_bars', []))
                    if _mtfce_tag_now:
                        _mtfce_tag_bars.append(_mtfce_now_s)
                    _mtfce_tag_bars = [
                        b for b in _mtfce_tag_bars
                        if _mtf_event_within_lookback(
                            _mtfce_now_s, b, _mtfce_bb_lb, _mtfce_bb_tf
                        )
                    ]
                    _mtfce_state['bb_tag_bars'] = _mtfce_tag_bars
                    if _mtfce_fail_now and len(_mtfce_tag_bars) > 0:
                        _mtfce_fire = True
                        _mtfce_reason = f"MTF_BB_REJECT_{_mtfce_bb_tf}"
                # ─── 4. MTF_GR_WT_EXIT (GR HTF + WT cross — BOTH required) ───────
                if (not _mtfce_fire) and bool(_cfg('MTF_GR_EXIT_GATE_ENABLED', False, account_key, symbol, position_side)):
                    _mtfce_wt1 = safe_fetch_float(i.get(f'wt1_{_mtfce_wt_tf}'), 0)
                    _mtfce_wt2 = safe_fetch_float(i.get(f'wt2_{_mtfce_wt_tf}'), 0)
                    _mtfce_wt_against = (is_long and _mtfce_wt1 < _mtfce_wt2) or ((not is_long) and _mtfce_wt1 > _mtfce_wt2)
                    if _mtfce_wt_against and bool(_cfg('MTF_WT_CROSS_EXIT_ENABLED', False, account_key, symbol, position_side)):
                        _mtfce_gr_min_tfs = int(_cfg('MTF_GR_EXIT_MIN_TFS', 3, account_key, symbol, position_side))
                        _mtfce_gr_count = 0
                        for _gtf in ('1h', '4h', 'D', 'W'):
                            _gw1 = safe_fetch_float(i.get(f'wt1_{_gtf}'), 0)
                            _gw2 = safe_fetch_float(i.get(f'wt2_{_gtf}'), 0)
                            if is_long and _gw1 < _gw2 and _gw1 != 0:
                                _mtfce_gr_count += 1
                            elif (not is_long) and _gw1 > _gw2 and _gw1 != 0:
                                _mtfce_gr_count += 1
                        if _mtfce_gr_count >= _mtfce_gr_min_tfs:
                            _mtfce_fire = True
                            _mtfce_reason = f"MTF_GR_WT_EXIT_{_mtfce_wt_tf}_grTFs={_mtfce_gr_count}"
                # Persist state regardless of fire
                trade_manager.mtf_compound_exit_state[position_key] = _mtfce_state
                if _mtfce_fire:
                    _mtfce_gain = safe_fetch_float(getattr(position, 'gain', 0), 0)
                    logger.error(f"⛔ [{_mtfce_reason[:18]}] {position_key}: gain={_mtfce_gain:.2f}% px={current_price:.4f} entry={_mtfce_entry:.4f} → CLOSE")
                    await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", f"{_mtfce_reason}_g{_mtfce_gain:.2f}%", 100.0, override_qty=999999)
                    trade_manager.mtf_compound_exit_state.pop(position_key, None)
                    return f"{_mtfce_reason[:18]}_CLOSED"
            except Exception as _mtfce_err:
                logger.debug(f"[MTF_COMPOUND_EXIT] {position_key} err: {_mtfce_err}")
        # ═══ END MTF COMPOUND EXIT ═══
        # ═══════════════════════════════════════════════════════════════════════
        # WT_3M_FORCE_OPEN — USER NON-NEGOTIABLE 2026-05-10 (stocks).
        # Every symbol in symbols_trb_long/short must have a position whenever the
        # wt1_3m vs wt2_3m condition holds. Reopen after every close. Reentry /
        # cooldown / NOLOSS gates may NOT block this — execute_now bypass is wired
        # via the WT_3M_FORCE_OPEN reason string.
        # ═══════════════════════════════════════════════════════════════════════
        # 2026-05-18 per-sym overlay
        # USER ABSOLUTE RULE 2026-06-03: "If a symbol is moving up and above its sma_200_15m
        # you HOLD a position if it is a tradeable key." Open when flat, BUILD toward target on
        # every bounce while the condition holds, then HOLD. Bigger as more HTFs confirm (ladder).
        # Direction-locked: LONG only ABOVE sma_200_15m, SHORT only BELOW → never long a loser /
        # short a winner (DG_DAILY_GAIN/LOSS guards downstream also enforce this).
        _wf_enabled = bool(_cfg('WT_3M_FORCE_OPEN_ENABLED', True, account_key, symbol, position_side))
        _wf_build = bool(_cfg('WT_3M_FORCE_OPEN_BUILD_TO_TARGET', True, account_key, symbol, position_side))
        _wf_target = float(_cfg('WT_3M_FORCE_OPEN_TARGET_USD', 15000.0, account_key, symbol, position_side))
        _wf_pos_val = abs(float(getattr(position, 'positionAmt', 0) or 0)) * current_price if position else 0.0
        _wf_room = (_wf_pos_val < _wf_target) if _wf_build else (not has_position)
        if _wf_room and _wf_enabled:
            try:
                if trade_manager.is_symbol_tradeable(symbol, account_key, position_side):
                    _wf_use_sma = bool(_cfg('WT_3M_FORCE_OPEN_USE_SMA200', True, account_key, symbol, position_side))
                    _wf_anchor = safe_fetch_float(i.get('sma_200_15m'), 0.0) if _wf_use_sma else 0.0
                    if _wf_anchor <= 0:
                        _wf_anchor = safe_fetch_float(i.get('ema_200_15m'), 0.0)
                    _wf_buf = float(_cfg('WT_3M_FORCE_OPEN_DIST_PCT', 0.0, account_key, symbol, position_side)) / 100.0
                    _wf_tf = str(_cfg('WT_FORCE_OPEN_TRIGGER_TF', '5m', account_key, symbol, position_side))  # [2026-06-26] configurable trigger TF (5m=current/churn, 15m/1h=less churn); A/B-tested
                    _wf_wt1_5m = safe_fetch_float(i.get(f'wt1_{_wf_tf}', i.get('wt1_5m', i.get('wt1_3m'))), 0.0)
                    _wf_wt2_5m = safe_fetch_float(i.get(f'wt2_{_wf_tf}', i.get('wt2_5m', i.get('wt2_3m'))), 0.0)  # 2026-06-03 USER: phantom wt1_X_prev → wt2_X
                    _wf_wt1_5m_prev = safe_fetch_float(i.get(f'wt1_{_wf_tf}_prev', i.get('wt1_5m_prev', i.get('wt1_3m_prev', _wf_wt2_5m))), _wf_wt2_5m)
                    _above = (is_long and _wf_anchor > 0 and current_price > _wf_anchor * (1.0 + _wf_buf)) or ((not is_long) and _wf_anchor > 0 and current_price < _wf_anchor * (1.0 - _wf_buf))
                    # USER 2026-06-03 ABSOLUTE: WT must be GOING the right way — WT-against = NO add/hold,
                    # no exceptions. WT-in-favor = keep adding bigger. wt1_5m rising AND not below its signal.
                    _wf_wt2_5m = safe_fetch_float(i.get(f'wt2_{_wf_tf}', i.get('wt2_5m', i.get('wt2_3m'))), _wf_wt1_5m)
                    _wt_favor = (is_long and _wf_wt1_5m > _wf_wt1_5m_prev and _wf_wt1_5m >= _wf_wt2_5m) or ((not is_long) and _wf_wt1_5m < _wf_wt1_5m_prev and _wf_wt1_5m <= _wf_wt2_5m)
                    if bool(getattr(config, 'WT_FORCE_OPEN_FRESH_CROSS_ONLY', False)):  # [2026-06-27] fire on FRESH WT cross event, not standing state (kills refire churn)
                        _wf_maxb = int(getattr(config, 'WT_FORCE_OPEN_FRESH_MAX_BARS', 0))
                        if _wf_maxb <= 0:
                            _wt_favor = (is_long and safe_fetch_float(i.get(f'wt_cross_bull_{_wf_tf}'), 0.0) >= 1) or ((not is_long) and safe_fetch_float(i.get(f'wt_cross_bear_{_wf_tf}'), 0.0) >= 1)
                        else:
                            _wf_ba = safe_fetch_float(i.get(f'wt_cross_bars_ago_{_wf_tf}'), 999.0)
                            _wf_rising = i.get(f'wt_cross_rising_{_wf_tf}')
                            _wt_favor = (_wf_ba <= _wf_maxb) and ((is_long and _wf_rising is True) or ((not is_long) and _wf_rising is False))
                    if os.environ.get("V8_WT_FORCE_DIAG") == "1":
                        global _V8_WT_FORCE_DIAG_N
                        _V8_WT_FORCE_DIAG_N = globals().get(
                            "_V8_WT_FORCE_DIAG_N", 0
                        )
                        if _V8_WT_FORCE_DIAG_N < 20:
                            _wf_diag_msg = (
                                f"[V8_WT_FORCE_DIAG] {position_key} "
                                f"enabled={_wf_enabled} room={_wf_room} "
                                f"px={current_price:.4f} anchor={_wf_anchor:.4f} "
                                f"above={_above} tf={_wf_tf} "
                                f"wt1={_wf_wt1_5m:.4f} "
                                f"prev={_wf_wt1_5m_prev:.4f} "
                                f"wt2={_wf_wt2_5m:.4f} favor={_wt_favor}"
                            )
                            logger.warning(_wf_diag_msg)
                            print(_wf_diag_msg, flush=True)
                            _V8_WT_FORCE_DIAG_N += 1
                    if _above and _wt_favor and current_price is not None and current_price > 0:
                        _wf_mult = 1.0
                        if bool(getattr(config, 'WT_3M_FORCE_OPEN_TF_LADDER', True)):
                            _lm = float(getattr(config, 'WT_3M_FORCE_OPEN_TF_LADDER_MULT', 1.0))
                            _nconf = 0
                            for _tf in ('15m', '1h', '4h', 'D'):
                                _w1 = safe_fetch_float(i.get(f'wt1_{_tf}'), 0.0); _w2 = safe_fetch_float(i.get(f'wt2_{_tf}'), 0.0)
                                if (is_long and _w1 > _w2) or ((not is_long) and _w1 < _w2):
                                    _nconf += 1
                            _wf_mult = 1.0 + _lm * _nconf
                        _wf_size_usd = float(_cfg('WT_3M_FORCE_OPEN_SIZE_USD', 2500.0, account_key, symbol, position_side)) * _wf_mult
                        if _wf_build and _wf_target > 0:
                            _wf_size_usd = min(_wf_size_usd, max(0.0, _wf_target - _wf_pos_val))
                        if _wf_size_usd >= 1.0:
                            _wf_qty = max(_wf_size_usd / current_price, 1.0)
                            _wf_act = "AUGMENT" if has_position else "OPEN"
                            _wf_reason = f"WT_3M_FORCE_OPEN_{'LONG' if is_long else 'SHORT'}_above_sma200_15m_x{_wf_mult:.0f}_posval{_wf_pos_val:.0f}of{_wf_target:.0f}_px{current_price:.4f}"
                            logger.warning(f"[WT_3M_FORCE_OPEN] {position_key}: tradeable + {'above' if is_long else 'below'} sma200_15m({_wf_anchor:.2f}) + moving → {_wf_act} qty={_wf_qty:.2f} (${_wf_size_usd:.0f}, ladder x{_wf_mult:.0f}, posval ${_wf_pos_val:.0f}/${_wf_target:.0f})")
                            _wf_stop = safe_fetch_float(i.get(('dc_low4_5m' if is_long else 'dc_high4_5m') if bool(getattr(config, 'R1_USE_DC_4BAR', True)) else ('dc_low_5m' if is_long else 'dc_high_5m')), 0.0)
                            # A genuinely flat key may not have a Position
                            # object yet. The old assignment raised
                            # AttributeError here and the broad debug-only
                            # except swallowed it before queue_trade_action,
                            # making WT force-open structurally unable to
                            # create the first position. Execution creates the
                            # object; only update a pre-existing object's stop.
                            if _wf_stop > 0 and position is not None:
                                _cur_r1_wf = float(getattr(position, 'r1_stop_price', 0.0) or 0.0)
                                if _cur_r1_wf <= 0 or (is_long and _wf_stop > _cur_r1_wf) or (not is_long and _wf_stop < _cur_r1_wf):
                                    position.r1_stop_price = _wf_stop
                            _wf_queue_result = await queue_trade_action(
                                order_queue, trade_manager, position_key,
                                _wf_act, _wf_reason, 80.0,
                                override_qty=_wf_qty,
                            )
                            if _wf_queue_result != "SUCCESS":
                                logger.warning(
                                    f"[WT_3M_FORCE_OPEN_QUEUE_REFUSED] "
                                    f"{position_key}: result={_wf_queue_result}"
                                )
                                if os.environ.get("V8_WT_FORCE_DIAG") == "1":
                                    print(
                                        f"[WT_3M_FORCE_OPEN_QUEUE_REFUSED] "
                                        f"{position_key}: result={_wf_queue_result}",
                                        flush=True,
                                    )
                                return (
                                    f"WT_3M_FORCE_OPEN_QUEUE_REFUSED:"
                                    f"{position_side}:{_wf_queue_result}"
                                )
                            if os.environ.get("V8_WT_FORCE_DIAG") == "1":
                                print(
                                    f"[WT_3M_FORCE_OPEN_QUEUED] {position_key} "
                                    f"action={_wf_act} qty={_wf_qty}",
                                    flush=True,
                                )
                            return f"WT_3M_FORCE_OPEN:{position_side}"
            except Exception as _wf_err:
                # This path is a mandatory entry producer; swallowing failures
                # at DEBUG turned a null-position bug into months of zero-trade
                # backtests. Surface the exception so red-path automation and
                # operators can assign the broken knob immediately.
                logger.warning(
                    f"[WT_3M_FORCE_OPEN_ERROR] {position_key}: "
                    f"{type(_wf_err).__name__}: {_wf_err}"
                )
        # ═══════════════════════════════════════════════════════════════════════
        # RULE_A_RETEST — D/W Breakout-then-Retest entry FIRE (USER 2026-05-17, mirror of ez_manage).
        # Source: data/research_20260516/PLAN.md §3.3. Cited +22 abs WR pts (Trading-Rush), +0.47 Sharpe (QuantPedia D1H1).
        # SIMPLIFIED stateless form (full breakout_retest_armed state dict pending next session).
        # ROLLBACK: BREAKOUT_RETEST_ARMED_ENABLED=False in config_tradier.py.
        # ═══════════════════════════════════════════════════════════════════════
        # 2026-05-18 per-sym overlay
        if (not has_position) and bool(_cfg('BREAKOUT_RETEST_ARMED_ENABLED', False, account_key, symbol, position_side)):
            try:
                if trade_manager.is_symbol_tradeable(symbol, account_key, position_side):
                    _ra_w1_D = safe_fetch_float(i.get('wt1_D'), 0)
                    _ra_w2_D = safe_fetch_float(i.get('wt2_D'), 0)
                    _ra_w1_W = safe_fetch_float(i.get('wt1_W'), 0)
                    _ra_w2_W = safe_fetch_float(i.get('wt2_W'), 0)
                    _ra_dc_basis_D = safe_fetch_float(i.get('dc_basis_D'), 0)
                    _ra_atr_D = safe_fetch_float(i.get('atr_D'), 0)
                    _ra_w1_15m = safe_fetch_float(i.get('wt1_15m'), 0)
                    _ra_w2_15m = safe_fetch_float(i.get('wt2_15m'), 0)
                    _ra_w1_1h = safe_fetch_float(i.get('wt1_1h'), 0)
                    _ra_w2_1h = safe_fetch_float(i.get('wt2_1h'), 0)
                    _ra_k_3m = safe_fetch_float(i.get('k_3m') or i.get('k_3m'), 50)
                    _ra_d_3m = safe_fetch_float(i.get('d_3m') or i.get('d_3m'), 50)
                    _ra_k_3m_prev = safe_fetch_float(i.get('k_3m_prev') or i.get('k_3m_prev'), _ra_k_3m)
                    _ra_data_ok = (abs(_ra_w1_D) > 1e-9 and abs(_ra_w2_D) > 1e-9 and _ra_dc_basis_D > 0 and _ra_atr_D > 0 and current_price > 0)
                    if _ra_data_ok:
                        # 2026-05-18 per-sym overlay
                        _ra_retest_mult = float(_cfg('BREAKOUT_RETEST_ARMED_RETEST_ATR_MULT', 0.30, account_key, symbol, position_side))
                        _ra_dist_atr = abs(current_price - _ra_dc_basis_D) / _ra_atr_D
                        _ra_armed_long = (_ra_w1_D > _ra_w2_D and _ra_w1_W > _ra_w2_W and current_price > _ra_dc_basis_D)
                        _ra_armed_short = (_ra_w1_D < _ra_w2_D and _ra_w1_W < _ra_w2_W and current_price < _ra_dc_basis_D)
                        _ra_retest_band = _ra_dist_atr < _ra_retest_mult
                        _ra_k3m_xup = (_ra_k_3m_prev < 30 and _ra_k_3m > _ra_d_3m and _ra_k_3m > _ra_k_3m_prev)
                        _ra_k3m_xdn = (_ra_k_3m_prev > 70 and _ra_k_3m < _ra_d_3m and _ra_k_3m < _ra_k_3m_prev)
                        _ra_15m_bull = (_ra_w1_15m > _ra_w2_15m)
                        _ra_15m_bear = (_ra_w1_15m < _ra_w2_15m)
                        _ra_1h_bull = (_ra_w1_1h > _ra_w2_1h)
                        _ra_1h_bear = (_ra_w1_1h < _ra_w2_1h)
                        _ra_fire_long = (is_long and _ra_armed_long and _ra_retest_band and _ra_k3m_xup and _ra_15m_bull and _ra_1h_bull)
                        _ra_fire_short = ((not is_long) and _ra_armed_short and _ra_retest_band and _ra_k3m_xdn and _ra_15m_bear and _ra_1h_bear)
                        if _ra_fire_long or _ra_fire_short:
                            _ra_size_usd = float(getattr(config, 'WT_3M_FORCE_OPEN_SIZE_USD', 100.0)) or float(getattr(config, 'START_POSITION_SIZE', 100.0))
                            _ra_qty = max(_ra_size_usd / current_price, 1.0)
                            _ra_reason = f"RULE_A_RETEST_{'LONG' if is_long else 'SHORT'}_px{current_price:.4f}_dcBD{_ra_dc_basis_D:.4f}_dist{_ra_dist_atr:.2f}atr_k3m{_ra_k_3m:.0f}/{_ra_k_3m_prev:.0f}_w15={_ra_w1_15m:.1f}/{_ra_w2_15m:.1f}_w1h={_ra_w1_1h:.1f}/{_ra_w2_1h:.1f}_wD={_ra_w1_D:.1f}/{_ra_w2_D:.1f}_wW={_ra_w1_W:.1f}/{_ra_w2_W:.1f}"
                            logger.warning(f"[RULE_A_RETEST] {position_key}: FIRE {('LONG' if is_long else 'SHORT')} qty={_ra_qty:.2f} {_ra_reason[:120]}")
                            await queue_trade_action(order_queue, trade_manager, position_key, "OPEN", _ra_reason, 80.0, override_qty=_ra_qty)
                            return f"RULE_A_RETEST:{position_side}"
            except Exception as _ra_err:
                logger.debug(f"[RULE_A_RETEST] {position_key}: probe err — {_ra_err}")
        was_reduced = getattr(position, 'was_reduced', False)
        last_red_time = getattr(position, 'last_reduction_time', None)
        market_context = await trade_manager.get_market_context(symbol)
        sentiment_rank = float(indicators_raw.get('0sentiment_rank') or i.get('0sentiment_rank') or 999)

        if not trade_manager.is_symbol_tradeable(symbol, account_key, position_side):
            return "SYMBOL NOT TRADEABLE"
            
        tech_score, _, strategy_reason = trade_manager.strategy.calculate_signal_score( account_key, symbol, is_long, current_price, i, position, is_exit=False  )
        # BB buffer warming moved to before stale check (line ~934)
        
        # 5. DECISION LOGIC VARIABLES
        log_rec = "WAIT"
        
        # Priority: Show the score/reason. Append STALE ONLY if it actually blocks something (is_stale).
        log_reason = f"Sc:{int(tech_score)} {strategy_reason}"[:30]
        if is_stale: log_reason = f"STALE {log_reason}"
        
        market_open = is_regular_trading_hours()
        action_taken = False

        # ═══ 2026-04-26 USER RULE — MICRO_SCALP_STOCKS_MAKER ═══
        # Mirror of crypto MICRO_SCALP_USDC_MAKER (ez_manage.py:19793). Stocks micro-scalper.
        # CLOSE: gain >= MICRO_SCALP_STOCKS_GAIN_THRESHOLD_PCT AND gain < prev_gain (first decel).
        # REOPEN: when flat AND price re-crosses prior exit_price.
        # 2026-04-27 user rule: NOW respects STOCK_MIN_HOLD on the CLOSE branch (was bypassing).
        # User: "respect the min hold of 72 hours". Reopen branch unchanged — needed for cross-back.
        # State stored on trade_manager._micro_scalp_state_stocks (separate dict from crypto's).
        _mss_min_hold = float(getattr(config, 'TRADIER_MIN_HOLD_MINUTES', getattr(config, 'MIN_HOLD_MINUTES_TRADIER', 240.0)))
        _mss_hold_min_check: float = 0.0
        try:
            _mss_opened_at = getattr(position, 'opened_at', None) if position else None
            if _mss_opened_at:
                _mss_hold_min_check = (datetime.now(timezone.utc) - _mss_opened_at).total_seconds() / 60.0
        except Exception:
            _mss_hold_min_check = 0.0
        if (market_open and bool(getattr(config, 'MICRO_SCALP_STOCKS_MAKER_ENABLED', False))
            and account_key in (getattr(config, 'MICRO_SCALP_STOCKS_ACCOUNTS', None) or [])):
            try:
                _mss_dict = getattr(trade_manager, '_micro_scalp_state_stocks', None)
                if _mss_dict is None:
                    trade_manager._micro_scalp_state_stocks = {}
                    _mss_dict = trade_manager._micro_scalp_state_stocks
                _mss_st = _mss_dict.get(position_key, {})
                _mss_threshold = float(getattr(config, 'MICRO_SCALP_STOCKS_GAIN_THRESHOLD_PCT', 0.05))
                _mss_peak_floor = float(getattr(config, 'MICRO_SCALP_STOCKS_PEAK_FLOOR_PCT', 0.5))  # 2026-05-28 USER: micro-scalp may only close a position whose gain has ALREADY been >= this floor.
                _mss_max_gain = float(getattr(position, 'max_gain', 0) or 0) if position else 0.0
                _mss_qty = abs(float(getattr(position, 'positionAmt', 0))) if position else 0.0
                # CLOSE branch — held position, gain past threshold AND first deceleration
                if _mss_qty >= 1 and current_price is not None and current_price > 0:
                    _mss_gain = float(getattr(position, 'gain', 0) or 0)
                    _mss_prev = float(_mss_st.get('prev_gain', _mss_gain))
                    if _mss_hold_min_check < _mss_min_hold:
                        _mss_st_new = dict(_mss_st)
                        _mss_st_new['prev_gain'] = _mss_gain
                        _mss_dict[position_key] = _mss_st_new
                        if _mss_gain >= _mss_threshold and _mss_gain < _mss_prev:
                            logger.info(f"[MICRO_SCALP_MIN_HOLD_BLOCK] {position_key}: hold={_mss_hold_min_check:.0f}m<{_mss_min_hold:.0f}m — micro-scalp close gated (user rule 2026-04-27)")
                    elif _mss_gain >= _mss_threshold and _mss_gain < _mss_prev and _mss_max_gain >= _mss_peak_floor:
                        _mss_reason = f"MICRO_SCALP_STOCKS_CLOSE_g{_mss_gain:.3f}%_prev{_mss_prev:.3f}%_peak{_mss_max_gain:.3f}%"
                        logger.critical(f"⚡ [MICRO_SCALP_STOCKS_CLOSE] {position_key}: gain={_mss_gain:.3f}% < prev={_mss_prev:.3f}% peak={_mss_max_gain:.3f}%>=floor{_mss_peak_floor:.3f}% (threshold={_mss_threshold}%) — limit close (chase→market fallback at 10s)")
                        # Cooldown bookkeeping (same key as evaluate_stop CLOSE path)
                        if not hasattr(trade_manager, '_pending_closes'):
                            trade_manager._pending_closes = {}
                        await queue_trade_action(order_queue, trade_manager, position_key, "CLOSE", _mss_reason, 95.0, override_qty=999999)
                        trade_manager._pending_closes[symbol] = time.time()
                        # Stash state for reopen branch — record exit_price + side + original qty
                        _mss_dict[position_key] = {'prev_gain': 0.0, 'exit_price': current_price, 'reopen_pending': True, 'original_side': position_side, 'original_qty': _mss_qty}
                        action_taken = True
                    else:
                        # Track prev_gain even if we don't fire — for next-cycle decel detection
                        _mss_st_new = dict(_mss_st)
                        _mss_st_new['prev_gain'] = _mss_gain
                        _mss_dict[position_key] = _mss_st_new
                # REOPEN branch — flat position, prior close pending, price re-crossed exit
                elif _mss_qty < 1 and _mss_st.get('reopen_pending', False) and current_price is not None and current_price > 0:
                    _mss_exit_px = float(_mss_st.get('exit_price', 0) or 0)
                    _mss_orig_side = str(_mss_st.get('original_side', '') or '')
                    _mss_orig_qty = float(_mss_st.get('original_qty', 0) or 0)
                    if _mss_exit_px > 0 and _mss_orig_qty >= 1 and _mss_orig_side in ('LONG', 'SHORT'):
                        _mss_orig_long = (_mss_orig_side == 'LONG')
                        _mss_crossed = (_mss_orig_long and current_price <= _mss_exit_px) or ((not _mss_orig_long) and current_price >= _mss_exit_px)
                        if _mss_crossed:
                            _mss_reason = f"MICRO_SCALP_STOCKS_REOPEN_exit{_mss_exit_px:.4f}_now{current_price:.4f}"
                            logger.critical(f"⚡ [MICRO_SCALP_STOCKS_REOPEN] {position_key}: price {current_price:.4f} re-crossed exit {_mss_exit_px:.4f} ({_mss_orig_side}) — limit reopen qty={_mss_orig_qty:.0f}")
                            await queue_trade_action(order_queue, trade_manager, position_key, "OPEN", _mss_reason, 95.0, override_qty=_mss_orig_qty)
                            _mss_dict[position_key] = {'prev_gain': 0.0, 'exit_price': 0.0, 'reopen_pending': False, 'original_side': '', 'original_qty': 0.0}
                            action_taken = True
            except Exception as _mss_e:
                logger.warning(f"[MICRO_SCALP_STOCKS_ERR] {position_key}: {type(_mss_e).__name__}: {_mss_e}")

        # =========================================================
        # LOGIC BRANCH A: HELD POSITION (EXIT / AUGMENT)
        # =========================================================
        if was_reduced and last_red_time:
            re_action, re_reason, re_conf, re_qty = await trade_manager.strategy.evaluate_reentry(symbol, position, indicators_raw)
            
            if re_action in ["OPEN", "REENTRY_OPEN", "AUGMENT"]:
                # if m1_stale:
                #     logger.warning(f"[{account_key}] 🛑 BLOCK REENTRY {symbol}: 1m Data Stale (>120s)")
                # elif is_stale:
                if is_stale:
                    logger.warning(f"[{account_key}] 🛑 BLOCK REENTRY {symbol}: All Data Stale ({freshness_reason})")
                else:# market_open or force:
                    log_rec = "♻️REENTRY"
                    log_reason = re_reason
                    logger.info(f"[{account_key}] ♻️ EXEC REENTRY {symbol}: {re_reason} Qty: {re_qty}")
                    
                    # REENTRY is REENTRY — not AUGMENT. execute_trade_action handles reclassification internally.
                    exec_action = "REENTRY"
                    _re_tagged_reason = f"REENTRY_{re_reason}" if 'REENTRY' not in re_reason.upper() else re_reason
                    _re_queued = await _dispatch_reentry_guaranteed_trd(
                        order_queue, trade_manager, position_key, exec_action,
                        _re_tagged_reason, re_conf, override_qty=re_qty
                    )
                    if _re_queued:
                        action_taken = True

        if has_position and not action_taken:
            opened_at = position.opened_at
            if opened_at:
                if isinstance(opened_at, str):
                    try:
                        import pandas as pd
                        opened_at = pd.to_datetime(opened_at).timestamp()
                    except Exception:
                        opened_at = time.time()
                elif hasattr(opened_at, 'timestamp'): 
                    opened_at = opened_at.timestamp()
                elif isinstance(opened_at, (int, float)):
                    pass
                else:
                    opened_at = time.time()
            now = time.time()
            position_age_minutes = (now - opened_at) / 60.0 if opened_at else 0
            in_grace_period = position_age_minutes < 10.0
            should_exit, exit_reason, exit_qty = await trade_manager.strategy.evaluate_stop(
                symbol, position, indicators_raw, market_context, in_grace_period )
            
            if should_exit:
                # IDEMPOTENCY GUARD (2026-04-26): if a CLOSE for this symbol was queued
                # recently, suppress the duplicate. Without this, the 30s loop re-fires
                # CLOSE every cycle while no fill confirms (off-hours, rejected order, or
                # broker lag) — flooded data/decisions/ JSONL with 6+ duplicate GLD/SLV
                # closes 2026-04-26 00:43–01:30 UTC. Cooldown is short intra-day (allow
                # fast retry on legit reject) and long off-hours (no fills possible).
                if not hasattr(trade_manager, '_pending_closes'):
                    trade_manager._pending_closes = {}
                _last_close_ts = trade_manager._pending_closes.get(symbol, 0.0)
                _close_cooldown = 30.0 if market_open else 7200.0
                _since_last = time.time() - _last_close_ts
                if _since_last < _close_cooldown:
                    log_rec = "HOLD"
                    log_reason = f"CLOSE_COOLDOWN_{int(_since_last)}s/{int(_close_cooldown)}s ({exit_reason[:40]})"
                else:
                    log_rec = "💥CLOSE"
                    log_reason = exit_reason
                    # A structural LR harvest is explicitly a partial reduce.  The
                    # historical blanket CLOSE clamp below discarded evaluate_stop's
                    # returned quantity and converted a requested 50% harvest into a
                    # full liquidation in both live and V8.  Keep the protective
                    # 999999 clamp for true closes, but preserve a valid partial
                    # quantity for this one semantically partial exit family.
                    _position_qty = abs(float(getattr(
                        position, "positionAmt", getattr(position, "quantity", 0)
                    ) or 0))
                    _is_lr_harvest = str(exit_reason or "").startswith(
                        "LR_BAND_HARVEST_"
                    )
                    _is_partial_harvest = (
                        _is_lr_harvest
                        and 0 < float(exit_qty or 0) < _position_qty
                    )
                    if _is_partial_harvest:
                        _exit_action = "REDUCE"
                        _override_exit_qty = float(exit_qty)
                        logger.info(
                            f"[{account_key}] ✂️ LR HARVEST {symbol}: "
                            f"{_override_exit_qty:.8g}/{_position_qty:.8g} "
                            f"({exit_reason}; mkt_open={market_open})"
                        )
                    else:
                        # Use 999999 for true CLOSE — execute_trade_action clamps
                        # against the broker's actual position, not a stale local
                        # positionAmt.
                        _exit_action = "CLOSE"
                        _override_exit_qty = 999999
                        logger.info(f"[{account_key}] 🛑 CLOSING {symbol}: {exit_reason} (mkt_open={market_open})")
                    await queue_trade_action(
                        order_queue, trade_manager, position_key, _exit_action,
                        exit_reason, 100.0, override_qty=_override_exit_qty,
                    )
                    action_taken = True
                    trade_manager._pending_closes[symbol] = time.time()

            # 4h BB breakout ladder is subordinate to a protective stop, but
            # takes priority over ordinary augmentation once a stage is due.
            elif bool(_cfg("BB4H_BREAKOUT_LADDER_ENABLED", True, account_key, symbol, position_side)):
                try:
                    _ladder_state = getattr(trade_manager, "_bb4h_breakout_ladder_state", None)
                    if _ladder_state is None:
                        trade_manager._bb4h_breakout_ladder_state = {}
                        _ladder_state = trade_manager._bb4h_breakout_ladder_state
                    _ladder_key_state = _ladder_state.setdefault(position_key, {})
                    _ladder = _next_bb4h_ladder_stage(
                        _ladder_key_state, i, current_price,
                        enabled=True, position_exists=True, is_long=is_long,
                        now=time.time(),
                        breakout_pct=float(_cfg("BB4H_BREAKOUT_LADDER_BREAKOUT_PCT", .25, account_key, symbol, position_side)),
                        basis_pct=float(_cfg("BB4H_BREAKOUT_LADDER_BASIS_PCT", .50, account_key, symbol, position_side)),
                        wt_cross_pct=float(_cfg("BB4H_BREAKOUT_LADDER_WT_CROSS_PCT", .25, account_key, symbol, position_side)),
                        target_usd=float(_cfg("BB4H_BREAKOUT_LADDER_TARGET_USD", 2000.0, account_key, symbol, position_side)),
                        stock=True,
                        stock_max_notional_usd=float(_cfg("BB4H_BREAKOUT_LADDER_STOCK_MAX_NOTIONAL_USD", 2000.0, account_key, symbol, position_side)),
                        max_stock_shares=int(_cfg("BB4H_BREAKOUT_LADDER_MAX_STOCK_SHARES", 1, account_key, symbol, position_side)),
                    )
                    if _ladder and _ladder["quantity"] > 0 and market_open and not action_taken:
                        _ladder_reason = f"BB4H_BREAKOUT_LADDER_{_ladder['name']}_fraction={_ladder['fraction']:.2f}"
                        logger.warning(f"[{account_key}] 🪜 {symbol}: {_ladder_reason} qty={_ladder['quantity']}")
                        await queue_trade_action(order_queue, trade_manager, position_key, "AUGMENT", _ladder_reason, 100.0, override_qty=_ladder["quantity"])
                        action_taken = True
                        return f"BB4H_BREAKOUT_LADDER:{_ladder['name']}"
                except Exception as _ladder_err:
                    logger.warning(f"[BB4H_BREAKOUT_LADDER_HELD] {position_key}: {_ladder_err}")

            # Exact selected-recipe production envelope.  Bottom-A has already
            # been evaluated by evaluate_stop; do not let any reduce/augment
            # family change the tested lifecycle when this per-key flag is on.
            elif bool(_cfg(
                "FULL_RECIPE_ONLY_ENABLED", False,
                account_key, symbol, position_side,
            )):
                log_rec = "HOLD"
                log_reason = "FULL_RECIPE_ONLY_HOLD_POSITION"
            
            # --- 3. EVALUATE AUGMENT ---
            # tra is long-term hold — no augmentation churn. Initial entry only.
            elif account_key == 'tra' and getattr(config, 'TRA_DISABLE_AUGMENT', True):
                log_rec = "HOLD"
                log_reason = f"TRA_HOLD g={getattr(position, 'gain', 0):.2f}%"
            elif position_age_minutes > 6.0:
                # DD BOUNCE STOP — cut extra leg if price continues below aug entry price
                _wds = getattr(trade_manager.strategy, '_wt_d_aug_state', {}).get(symbol, {})
                _dd_qty = float(_wds.get('dd_qty', 0.0))
                _dd_aug_price = float(_wds.get('last_aug_price', 0.0))
                _is_long_pos = getattr(position, 'position_side', 'LONG') == 'LONG'
                _dd_stop_hit = (_dd_qty >= 0.5 and _dd_aug_price > 0 and market_open and getattr(config, 'WT_D_BOUNCE_DD_STOP_ENABLED', True) and (current_price < _dd_aug_price if _is_long_pos else current_price > _dd_aug_price))
                if _dd_stop_hit:
                    _dd_reason = f"DD_BOUNCE_STOP px={current_price:.2f} aug_px={_dd_aug_price:.2f} qty={_dd_qty:.2f}"
                    logger.info(f"[{account_key}] ✂️ DD_STOP {symbol}: {_dd_reason}")
                    await queue_trade_action(order_queue, trade_manager, position_key, "REDUCE", _dd_reason, 80.0, override_qty=_dd_qty)
                    action_taken = True
                    trade_manager.strategy._wt_d_aug_state.setdefault(symbol, {})['dd_qty'] = 0.0
                # Add a cooldown check for consecutive augmentations (15 mins)
                aug_at = getattr(position, 'last_augmentation_time', None)
                aug_dt = safe_datetime(aug_at) if aug_at else None
                aug_age = (time.time() - aug_dt.timestamp()) / 60.0 if aug_dt else 999.0
                if not action_taken:
                    if aug_age < 15.0:
                        log_rec = "HOLD"
                        log_reason = f"AugCD:{15.0-aug_age:.1f}m"
                    elif m1_stale or is_stale:
                        log_rec = "HOLD"
                        log_reason = f"Stale ({freshness_reason})"
                    else:
                        should_aug, aug_reason, aug_conf, aug_qty = await trade_manager.strategy.evaluate_augment(
                            symbol, position, indicators_raw, market_context  )
                        if should_aug:
                            log_rec = "🚀AUGMENT"
                            log_reason = aug_reason
                            logger.info(f"[{account_key}] 🟢 REVIEWING AUGMENT {symbol}: {aug_reason} Qty: {aug_qty}")
                            if market_open:
                                _aug_stop = safe_fetch_float(i.get(('dc_low4_5m' if is_long else 'dc_high4_5m') if bool(getattr(config, 'R1_USE_DC_4BAR', True)) else ('dc_low_5m' if is_long else 'dc_high_5m')), 0.0)
                                if _aug_stop > 0:
                                    _cur_r1_aug = float(getattr(position, 'r1_stop_price', 0.0) or 0.0)
                                    if _cur_r1_aug <= 0 or (is_long and _aug_stop > _cur_r1_aug) or (not is_long and _aug_stop < _cur_r1_aug):
                                        position.r1_stop_price = _aug_stop
                                await queue_trade_action( order_queue, trade_manager, position_key, "AUGMENT",   aug_reason, aug_conf, override_qty=aug_qty )
                                action_taken = True
                        else:
                            log_rec = "HOLD"
                            log_reason = f"PnL:{getattr(position, 'gain', 0):.2f}% Sc:{int(tech_score)}"
            else:
                log_rec = "HOLD"
                log_reason = f"Grace:{10.0-position_age_minutes:.1f}m Sc:{int(tech_score)}"

        # =========================================================
        # LOGIC BRANCH B: NO POSITION (ENTRY)
        # =========================================================
        else:
            if has_opposing_pos:
                log_rec = "WAIT"
                log_reason = f"Opposing pos open"
            elif (m1_stale or is_stale) and not force:
                log_rec = "WAIT"
                log_reason = f"Stale ({freshness_reason})"

            else:
                # --- Reopen cooldown: don't re-enter within 5 min of a full close ---
                # DC breakout entries (price still below/above channel) get immediate re-entry
                # Stoch-based entries wait 5 min to avoid noise
                last_exit_ts = _reentry_exit_value(
                    trade_manager.last_exit_times, position_key, symbol, 0
                )
                secs_since_close = time.time() - last_exit_ts
                # Check if price is currently outside any DC channel (DC breakout in progress)
                indicators_raw_check = trade_manager.get_indicators(symbol) or {}
                _cp = float(indicators_raw_check.get('current_price') or 0)
                _dcl5 = float(indicators_raw_check.get('dc_low_5m') or 0)
                _dch5 = float(indicators_raw_check.get('dc_high_5m') or 0)
                _is_dc_state = (_cp > 0 and (
                    (_dcl5 > 0 and _cp < _dcl5 * 0.999) or
                    (_dch5 > 0 and _cp > _dch5 * 1.001)
                ))
                # BLOCK entries if close is pending for this symbol (prevents entry/exit race)
                _pending = getattr(trade_manager, '_pending_closes', {})
                _pending_age = time.time() - _pending.get(symbol, 0)
                if _pending_age < 120:  # Block entries for 2 min after close signal
                    log_rec = "CLOSE_PENDING"
                    log_reason = f"Close pending {_pending_age:.0f}s ago"
                    return "CLOSE_PENDING"
                elif symbol in _pending and _pending_age >= 120:
                    del _pending[symbol]  # Clear expired pending
                # User directive 2026-04-10: "reenter ASAP". Zero reopen cooldown —
                # if a fresh signal fires immediately after an exit (e.g. premature stop
                # out), we want to get right back in. The tight trailing stop catches
                # any actual breakdown, so the extra churn on good signals is worth it.
                reopen_wait_s = float(getattr(config, 'TRADIER_REOPEN_WAIT_S', 0.0))
                if last_exit_ts > 0 and reopen_wait_s > 0 and secs_since_close < reopen_wait_s:
                    log_rec = "COOLDOWN"
                    log_reason = f"ReopenCD {(reopen_wait_s - secs_since_close)/60:.0f}m"
                    if force: logger.info(f"[{account_key}] ⏳ {symbol} REOPEN COOLDOWN {log_reason}")
                    return "COOLDOWN"
                # --- 0. PRICE_CROSS_BACK_REENTRY (2026-04-27 fix — was dead code in evaluate_reentry) ---
                # 662 closes/day were tagged _MANDATORY_REENTRY but never executed because the
                # executor was unreachable (positionAmt==0 check inside positionAmt>0 caller path).
                # Now wired here in BRANCH B (positionAmt==0): if a recent close happened within
                # band of current price + within max age, fire immediate reopen. NO_DOUBLE_OPEN
                # guard naturally allows this (positionAmt==0 in this branch).
                action_type = "NO_ACTION"
                reason = "SCANNING"
                qty = 0
                conf = 0
                _delta_entry = False
                _xb_reentry_fired = False
                _ordinary_parity_claim = False
                _xb_obligation = None
                # 2026-07-20 USER band mandate: LONG-only mode — short entries skip so the short
                # side can never squat the symbol and block LONG entries during upswings
                # (has_opposing_pos starved every band entry in the both-sides engine sim).
                if (not is_long) and bool(getattr(config, 'TRADIER_LONG_ONLY_ENTRIES', False)):
                    return "LONG_ONLY_ENTRIES_SKIP_SHORT"
                if os.environ.get("V8_LRBAND_DEBUG"):
                    _lbp0 = globals().setdefault("_LRBAND_P0", {"n": 0})
                    _lbp0["n"] += 1
                    if _lbp0["n"] % 2000 == 1:
                        print(f"V8_LOG LRBAND_P0 branchB_flat_reach={_lbp0['n']} is_long={is_long} sym={symbol}", flush=True)
                _entry_score = 0.0  # 2026-05-28 C1 FIX: bind before branches — reentry/GR/delta entry paths set action_type="OPEN" without running wt_dc_score_entry, so the ENTRY_SCORE_THRESHOLD veto (~3023) hit UnboundLocalError when a per-sym ENTRY_SCORE_THRESHOLD>0 override was present (41 crashes/day on IBIT/CIBR/DAR/ROBO).
                _entry_ind = indicators_raw if indicators_raw else i  # 2026-07-21 C1-class FIX: same bug — MTF_ARROW/LR_BAND priority entries claim OPEN before the fallback that bound _entry_ind, so the UVE veto line crashed UnboundLocalError, the except handler swallowed it, and BOTH the claimed entry and the fallback evaporated (13,091 of 13,119 arrow claims died this way in the 2026-07-21 ARM forensic run).
                _shared_direct_handoff_claim = None
                # Re-enter after the mirrored favorable structure. The exit
                # path records its adverse candle signature; this prevents a
                # flat symbol from re-entering on an unrelated structure move.
                if bool(_cfg('STRUCTURE_FLIP_REENTRY_ENABLED', False, account_key, symbol, position_side)) and not has_opposing_pos:
                    _sfr_tf = str(_cfg('STRUCTURE_FLIP_REENTRY_TF', '15m', account_key, symbol, position_side) or '15m')
                    _sfr_basis_enabled = bool(_cfg('STRUCTURE_FLIP_REENTRY_BASIS_RESTRICTION_ENABLED', False, account_key, symbol, position_side))
                    _sfr_basis_tf = str(_cfg('STRUCTURE_FLIP_REENTRY_BASIS_TF', '4h', account_key, symbol, position_side) or '4h')
                    _sfr_basis = float(i.get(f'dc_basis_{_sfr_basis_tf}', 0) or 0)
                    _sfr_basis_ok = (not _sfr_basis_enabled) or (_sfr_basis > 0 and ((is_long and current_price > _sfr_basis) or ((not is_long) and current_price < _sfr_basis)))
                    _sfr_hi, _sfr_hip = float(i.get(f'high_{_sfr_tf}', 0) or 0), float(i.get(f'high_{_sfr_tf}_prev', 0) or 0)
                    _sfr_lo, _sfr_lop = float(i.get(f'low_{_sfr_tf}', 0) or 0), float(i.get(f'low_{_sfr_tf}_prev', 0) or 0)
                    _sfr_favorable = (
                        _sfr_hi > 0 and _sfr_hip > 0 and _sfr_lo > 0 and _sfr_lop > 0
                        and ((_sfr_hi > _sfr_hip and _sfr_lo > _sfr_lop) if is_long else (_sfr_hi < _sfr_hip and _sfr_lo < _sfr_lop))
                    )
                    _sfr_state = getattr(trade_manager, '_structure_flip_reentry_state', {})
                    _sfr_pk_state = _sfr_state.get(position_key, {}) if isinstance(_sfr_state, dict) else {}
                    _sfr_sig = f'{_sfr_tf}:{_sfr_hip:.8f}:{_sfr_lop:.8f}:{_sfr_hi:.8f}:{_sfr_lo:.8f}'
                    if _sfr_favorable and _sfr_basis_ok and _sfr_pk_state.get('last_exit_signature') and _sfr_sig != _sfr_pk_state.get('last_entry_signature') and market_open:
                        _sfr_qty = max(1.0, float(_cfg('START_POSITION_SIZE', 600.0, account_key, symbol, position_side)) / max(current_price, 1e-9))
                        _sfr_reason = f'STRUCTURE_FLIP_REENTRY_{_sfr_tf}_{"HH_HL" if is_long else "LH_LL"}'
                        logger.warning(f'[{account_key}] 🔄 {symbol}: {_sfr_reason} qty={_sfr_qty:.2f}')
                        await queue_trade_action(order_queue, trade_manager, position_key, 'OPEN', _sfr_reason, 100.0, override_qty=_sfr_qty)
                        _sfr_state[position_key] = {**_sfr_pk_state, 'last_entry_signature': _sfr_sig, 'ts': time.time()}
                        return f'STRUCTURE_FLIP_REENTRY:{_sfr_tf}'
                # Fresh 4h breakout starts the explicit stock ladder.  It is
                # intentionally independent of the ordinary BB score switch.
                if bool(_cfg("BB4H_BREAKOUT_LADDER_ENABLED", True, account_key, symbol, position_side)) and not has_opposing_pos:
                    try:
                        _ladder_state = getattr(trade_manager, "_bb4h_breakout_ladder_state", None)
                        if _ladder_state is None:
                            trade_manager._bb4h_breakout_ladder_state = {}
                            _ladder_state = trade_manager._bb4h_breakout_ladder_state
                        _ladder_key_state = _ladder_state.setdefault(position_key, {})
                        _ladder = _next_bb4h_ladder_stage(
                            _ladder_key_state, i, current_price,
                            enabled=True, position_exists=False, is_long=is_long,
                            now=time.time(),
                            breakout_pct=float(_cfg("BB4H_BREAKOUT_LADDER_BREAKOUT_PCT", .25, account_key, symbol, position_side)),
                            basis_pct=float(_cfg("BB4H_BREAKOUT_LADDER_BASIS_PCT", .50, account_key, symbol, position_side)),
                            wt_cross_pct=float(_cfg("BB4H_BREAKOUT_LADDER_WT_CROSS_PCT", .25, account_key, symbol, position_side)),
                            target_usd=float(_cfg("BB4H_BREAKOUT_LADDER_TARGET_USD", 2000.0, account_key, symbol, position_side)),
                            stock=True,
                            stock_max_notional_usd=float(_cfg("BB4H_BREAKOUT_LADDER_STOCK_MAX_NOTIONAL_USD", 2000.0, account_key, symbol, position_side)),
                            max_stock_shares=int(_cfg("BB4H_BREAKOUT_LADDER_MAX_STOCK_SHARES", 1, account_key, symbol, position_side)),
                        )
                        if _ladder and _ladder["quantity"] > 0 and market_open:
                            action_type = "OPEN"
                            qty = _ladder["quantity"]
                            conf = 100.0
                            reason = f"BB4H_BREAKOUT_LADDER_{_ladder['name']}_fraction={_ladder['fraction']:.2f}"
                            logger.warning(f"[{account_key}] 🪜 {symbol}: {reason} qty={qty}")
                            await queue_trade_action(order_queue, trade_manager, position_key, action_type, reason, conf, override_qty=qty)
                            action_taken = True
                            return f"BB4H_BREAKOUT_LADDER:{_ladder['name']}"
                    except Exception as _ladder_err:
                        logger.warning(f"[BB4H_BREAKOUT_LADDER_FLAT] {position_key}: {_ladder_err}")
                # Mandatory capital-preservation obligation, not an optional entry path:
                # matrix "all entries off" must never disable post-exit re-entry.
                if trade_manager.is_symbol_tradeable(symbol, account_key, position_side):
                    _xb_last_t = _reentry_exit_value(
                        trade_manager.last_exit_times, position_key, symbol, 0
                    )
                    _xb_last_px = _reentry_exit_value(
                        trade_manager.last_exit_prices, position_key, symbol, 0
                    )
                    _xb_obligation_raw = trade_manager.__dict__.setdefault(
                        "_mandatory_reclaim_obligations", {}
                    ).get(position_key)
                    _xb_obligation = (
                        _ReclaimObligation.from_dict(_xb_obligation_raw)
                        if _xb_obligation_raw
                        else None
                    )
                    if _xb_obligation is not None and _xb_obligation.pending:
                        _xb_last_px = _xb_obligation.reclaim_level
                        _xb_obligation.observe_price(current_price)
                        trade_manager._mandatory_reclaim_obligations[
                            position_key
                        ] = _xb_obligation.to_dict()
                    if _xb_last_t > 0 and _xb_last_px > 0 and current_price is not None and current_price > 0:
                        _xb_age_min = (time.time() - _xb_last_t) / 60.0
                        _xb_band_pct = float(getattr(config, 'PRICE_CROSS_BACK_BAND_PCT', 0.3))
                        _xb_dist_pct = abs(current_price - _xb_last_px) / _xb_last_px * 100.0
                        _xb_opposed, _xb_opp_detail = _reentry_opposition(
                            _entry_ind, is_long
                        )
                        _xb_trace = _update_reentry_trace(
                            trade_manager.__dict__.setdefault("_mandatory_reentry_trace", {}),
                            position_key,
                            is_long,
                            float(_xb_last_px),
                            float(current_price),
                            float(time.time()),
                            _xb_opposed,
                        )
                        logger.info(
                            f"[MANDATORY_REENTRY_FLAT_BAR] {position_key} "
                            f"age={_xb_age_min:.1f}m cur={current_price:.4f} "
                            f"exit={_xb_last_px:.4f} opposed={','.join(_xb_opposed) or 'none'} "
                            f"flat_bars={_xb_trace['flat_bars']} "
                            f"max_overshoot={_xb_trace['max_overshoot_pct']:.3f}%"
                        )
                        if True:  # obligation persists until filled; no max-age expiry
                            # 2026-05-21 USER MANDATE — "IF YOU SELL BY ACCIDENT GET RIGHT BACK IN".
                            # Old logic required dist<=band AND favorable direction. SNDK rally
                            # beyond +0.3% band → NO reentry. Now: fire whenever price crossed
                            # BACK THROUGH exit in favorable direction (LONG: cur>=exit,
                            # SHORT: cur<=exit). Within-band on the other side also allowed.
                            _xb_favorable = (is_long and current_price >= _xb_last_px) or ((not is_long) and current_price <= _xb_last_px)
                            _xb_within_band = (
                                _xb_dist_pct <= _xb_band_pct
                                if _xb_obligation is None
                                else False
                            )
                            _xb_force_after_opposition = (
                                os.environ.get(
                                    "V8_MATRIX_CONTRACT_VERSION", ""
                                ).startswith("tradier-matrix-exec-c5")
                                and _force_reentry_after_temporary_opposition(
                                    _xb_trace,
                                    favorable=_xb_favorable,
                                    material_pct=float(
                                        getattr(
                                            config,
                                            "REENTRY_MATERIAL_OVERSHOOT_PCT",
                                            0.5,
                                        )
                                    ),
                                    max_opposed_bars=int(
                                        getattr(
                                            config,
                                            "REENTRY_OPPOSITION_MAX_FLAT_BARS",
                                            12,
                                        )
                                    ),
                                )
                            )
                            # 2026-05-29 USER: stocks reentry also requires a 4-bar Donchian breakout
                            # (dc_high4_5m / dc_low4_5m on already-closed bars) — not just a touch of the
                            # exit price. Mirrors crypto REENTRY_LIVE_MONITOR_DC_BREAK. Fail-open if missing.
                            _xb_dcb_ok = False
                            _xb_dckey = ""
                            _xb_dclvl = 0.0
                            # Emergency contract: reentry is permitted only with 15m WT
                            # confirmation and a 5m Donchian break. This is a hard veto.
                            if bool(getattr(config, 'REENTRY_LIVE_MONITOR_DC_BREAK_ENABLED', False)):
                                _xb_tf = str(getattr(config, 'REENTRY_LIVE_MONITOR_DC_BREAK_TF', '5m'))
                                _xb_4 = bool(getattr(config, 'REENTRY_LIVE_MONITOR_DC_BREAK_USE_4BAR', True))
                                if is_long:
                                    _xb_dckey = f"dc_high4_{_xb_tf}" if _xb_4 else f"dc_high_{_xb_tf}"
                                else:
                                    _xb_dckey = f"dc_low4_{_xb_tf}" if _xb_4 else f"dc_low_{_xb_tf}"
                                _xb_dclvl = safe_fetch_float(i.get(_xb_dckey), 0.0)
                                if _xb_dclvl > 0:
                                    _xb_dcb_ok = (is_long and current_price >= _xb_dclvl) or ((not is_long) and current_price <= _xb_dclvl)
                            if (
                                (_xb_favorable or _xb_within_band)
                                and len(_xb_opposed) > 1
                                and not _xb_force_after_opposition
                            ):
                                logger.warning(
                                    f"[MANDATORY_REENTRY_PENDING_OPPOSITION] {position_key}: "
                                    f"opposed={','.join(_xb_opposed)} detail={_xb_opp_detail} "
                                    f"overshoot={_xb_trace['max_overshoot_pct']:.3f}%"
                                )
                            elif _xb_favorable or _xb_within_band:
                                _xb_wt_ok, _xb_wt_detail = _mandatory_reentry_wt_gate(
                                    _entry_ind,
                                    is_long,
                                    enabled=bool(getattr(config, "MANDATORY_REENTRY_WT_FILTER_ENABLED", False)),
                                    tf_mode=getattr(config, "MANDATORY_REENTRY_WT_FILTER_TF_MODE", "5m_or_15m"),
                                    min_tfs=int(getattr(config, "MANDATORY_REENTRY_WT_FILTER_MIN_TFS", 1)),
                                    require_flip=bool(getattr(config, "MANDATORY_REENTRY_WT_FILTER_REQUIRE_FLIP", True)),
                                    velocity_ratio=float(getattr(config, "MANDATORY_REENTRY_WT_FILTER_VELOCITY_RATIO", 0.90)),
                                    min_velocity=float(getattr(config, "MANDATORY_REENTRY_WT_FILTER_MIN_VELOCITY", 0.0)),
                                )
                                if not _xb_wt_ok:
                                    logger.info(
                                        f"[MANDATORY_REENTRY_WT_HOLD] {position_key}: "
                                        f"price cross qualified but WT filter failed: {_xb_wt_detail}"
                                    )
                                elif not _xb_dcb_ok:
                                    logger.info(f"[PRICE_CROSS_BACK_DC_BREAK_HOLD] {account_key}:{symbol} {'L' if is_long else 'S'}: cur={current_price:.4f} not past {_xb_dckey}={_xb_dclvl:.4f} — churn guard, skip reentry")
                                else:
                                    _xb_target_usd = (
                                        _xb_obligation.target_notional_usd
                                        if _xb_obligation is not None
                                        and _xb_obligation.pending
                                        else float(getattr(config, 'START_POSITION_SIZE', 600))
                                    )
                                    _xb_qty = _xb_target_usd / max(current_price, 1e-9)
                                    action_type = "OPEN"
                                    qty = max(1.0, float(_xb_qty))
                                    conf = 90.0
                                    _xb_trigger = 'CROSSED_BACK' if _xb_favorable else f'WITHIN_BAND_{_xb_band_pct:.2f}%'
                                    reason = f"MANDATORY_REENTRY_PRICE_CROSS_exit{_xb_last_px:.4f}_cur{current_price:.4f}_dist{_xb_dist_pct:.2f}%_age{_xb_age_min:.0f}m_{_xb_trigger}"
                                    _xb_reentry_fired = True
                                    logger.warning(f"[{account_key}] 🔁 REENTRY {symbol} {'L' if is_long else 'S'}: {reason}")
                # Shared ordinary ladder parity.  It is explicitly guarded and
                # defaults OFF in live.  A completed D/4h/1h parent can request
                # one absolute target; the strongest rung wins and the shared
                # contract hard-clips it at $16k.
                if (
                    not _xb_reentry_fired
                    and action_type != "OPEN"
                    and (
                        _xb_obligation is None
                        or not _xb_obligation.pending
                        or _xb_obligation.favorable_gap_seen
                    )
                    and bool(
                        _cfg(
                            "LR_BAND_LADDER_ENABLED",
                            False,
                            account_key,
                            symbol,
                            position_side,
                        )
                    )
                    and bool(
                        _cfg(
                            "LR_BAND_LADDER_ORDINARY_PARITY_ENABLED",
                            False,
                            account_key,
                            symbol,
                            position_side,
                        )
                    )
                ):
                    _ol_target = _ordinary_ladder_target(
                        trade_manager,
                        position_key,
                        _entry_ind,
                        is_long,
                        config,
                        0.0,
                    )
                    if _ol_target is not None and _ol_target.add_notional_usd > 0:
                        qty = max(
                            1,
                            int(
                                _ol_target.add_notional_usd
                                / max(current_price, 1e-9)
                            ),
                        )
                        action_type = "OPEN"
                        conf = 90.0
                        _entry_score = max(float(_entry_score or 0.0), conf)
                        reason = (
                            "LR_BAND_LADDER_PARITY_TARGET_"
                            f"x{_ol_target.multiplier:.3f}_"
                            f"usd{_ol_target.target_notional_usd:.0f}_"
                            + "+".join(tf for tf, _ in _ol_target.source_tokens)
                        )[:110]
                        _ordinary_parity_claim = True
                # Shared completed-snapshot direct entries are subordinate to
                # mandatory reclaim and cannot displace an ordinary ladder
                # claim.  They are nevertheless admitted before the
                # FULL_RECIPE_ONLY hold so a selected direct recipe can own the
                # same normal sizing/execution path in live and V8.
                if action_type != "OPEN" and _shared_direct_claim is not None:
                    _direct_base_qty = float(_cfg(
                        "START_POSITION_SIZE", 600.0,
                        account_key, symbol, position_side,
                    )) / max(current_price, 1e-9)
                    action_type = "OPEN"
                    qty = int(max(1, _direct_base_qty))
                    conf = 90.0
                    _entry_score = max(float(_entry_score or 0.0), conf)
                    reason = str(_shared_direct_claim["reason"])
                    _shared_direct_handoff_claim = _shared_direct_claim
                    _direct_route_handoff_telemetry(
                        trade_manager, position_key,
                        _shared_direct_handoff_claim, "ACTION_OPEN",
                        reason=reason,
                    )
                    logger.info(
                        f"[SHARED_DIRECT_ENTRY] {position_key}: {reason}"
                    )
                # A formation recipe has the same shared selector as the live
                # evaluator, but the exact full-recipe envelope deliberately
                # stops before the legacy cascade.  Admit only this selected
                # action here; every non-formation fallback remains excluded.
                _formation_consumer_admitted, _formation_consumer_reason = (
                    formation_entry_consumer_admission(
                        full_recipe_only_enabled=bool(_cfg(
                            "FULL_RECIPE_ONLY_ENABLED", False,
                            account_key, symbol, position_side,
                        )),
                        action_already_claimed=(action_type == "OPEN"),
                    )
                )
                if _formation_consumer_admitted:
                    try:
                        _formation_action = await trade_manager.strategy.classic_formation_open_action(
                            account_key, symbol, position_side,
                            indicators_raw or i, current_price, market_context,
                        )
                    except (TypeError, ValueError) as _formation_error:
                        logger.error(
                            f"[CLASSIC_FORMATION_ENTRY] invalid recipe for "
                            f"{position_key}: {_formation_error}"
                        )
                        _formation_action = None
                    if _formation_action is not None:
                        action_type, reason, conf, qty = _formation_action
                        _entry_score = max(float(_entry_score or 0.0), float(conf))
                        # Reuse the existing downstream handoff telemetry for
                        # formation routes.  Without this claim object every
                        # later VARIANCE/BALANCER/BUDGET/DISPATCH stage was a
                        # no-op, hiding why a valid selector produced no order.
                        for _formation_family in CONFIG_FAMILY_PREFIX:
                            if str(reason).startswith(
                                "CLASSIC_FORMATION_ENTRY_"
                                f"{_formation_family.upper()}_"
                            ):
                                _shared_direct_handoff_claim = {
                                    "family": (
                                        "ENTRY_CLASSIC_FORMATION_"
                                        f"{_formation_family.upper()}"
                                    )
                                }
                                _direct_route_handoff_telemetry(
                                    trade_manager, position_key,
                                    _shared_direct_handoff_claim,
                                    "SELECTOR_TO_SIZED_OPEN",
                                    qty=float(qty), reason=str(reason),
                                )
                                break
                # Exact selected-recipe production envelope.  Mandatory
                # reclaim above remains compulsory and the ordinary ladder
                # remains the selected entry; all fallback entry families are
                # excluded for this key.  Returning here only when neither
                # selected route claimed OPEN lets the normal execution and
                # sizing/capacity path below handle actual claims unchanged.
                if (
                    action_type != "OPEN"
                    and bool(_cfg(
                        "FULL_RECIPE_ONLY_ENABLED", False,
                        account_key, symbol, position_side,
                    ))
                ):
                    return "FULL_RECIPE_ONLY_HOLD_ENTRY"
                # --- 4. DELTA ENGINE ENTRY (Sharpe 63.44, 85.9% WR) ---
                # tra: long-term account, delta is too fast — block here so the
                # WT/DC scorer (with high threshold) is the only entry path.
                _tra_block_delta = (account_key == 'tra' and getattr(config, 'TRA_DISABLE_DELTA_ENTRY', True))
                if not _xb_reentry_fired and not _ordinary_parity_claim and not _tra_block_delta and config.DELTA_ENGINE_ENABLED and config.DELTA_ENTRY_ENABLED and trade_manager.delta_tracker:
                    _d_ind = indicators_raw if indicators_raw else i
                    _d_sig = trade_manager.delta_tracker.update(symbol, _d_ind)
                    if _d_sig and ((is_long and _d_sig.entry_long) or (not is_long and _d_sig.entry_short)):
                        _delta_blocked = False
                        _block_reason = ""
                        _htf_gate = getattr(config, 'DELTA_HTF_GATE', 'none')
                        if _htf_gate != "none":
                            _wt1_4h = float(i.get("wt1_4h", 0))
                            _wt2_4h = float(i.get("wt2_4h", 0))
                            _wt1_D = float(i.get("wt1_D", 0))
                            _wt2_D = float(i.get("wt2_D", 0))
                            _ha_4h = i.get("ha_4h", 0)
                            if _htf_gate in ("4h", "4h_D", "4h_D_strict"):
                                _4h_ok = (_wt1_4h > _wt2_4h) if is_long else (_wt1_4h < _wt2_4h)
                                if not _4h_ok:
                                    _delta_blocked = True
                                    _block_reason = "HTF_4h_against"
                            if _htf_gate in ("4h_D", "4h_D_strict") and not _delta_blocked:
                                _D_ok = (_wt1_D > _wt2_D) if is_long else (_wt1_D < _wt2_D)
                                if not _D_ok:
                                    _delta_blocked = True
                                    _block_reason = "HTF_D_against"
                            if _htf_gate == "4h_D_strict" and not _delta_blocked:
                                _k4h = float(i.get("k_4h", 50))
                                _kD = float(i.get("k_D", 50))
                                if is_long and (_k4h > 80 or _kD > 80):
                                    _delta_blocked = True
                                    _block_reason = "HTF_K_overextended"
                                elif not is_long and (_k4h < 20 or _kD < 20):
                                    _delta_blocked = True
                                    _block_reason = "HTF_K_oversold"
                        if not _delta_blocked and getattr(config, 'DELTA_ATR_ENTRY_FILTER', False):
                            _atr_1h = float(i.get("atr_1h", 0))
                            _bar_move = abs(current_price - float(i.get("close_5m_prev", current_price)))
                            if _atr_1h > 0 and _bar_move < _atr_1h * 0.3:
                                _delta_blocked = True
                                _block_reason = f"ATR_noise({_bar_move:.2f}<{_atr_1h*0.3:.2f})"
                        if not _delta_blocked:
                            _base_qty = float(getattr(config, 'START_POSITION_SIZE', 600)) / current_price if current_price is not None and current_price > 0 else 1
                            action_type = "OPEN"
                            qty = int(max(1, _base_qty))
                            conf = 100.0
                            _zr = _d_sig.zone_reason or f"bs={_d_sig.bull_speed:.1f}_es={_d_sig.bear_speed:.1f}"
                            reason = f"DELTA_ENTRY_{_d_sig.zone}_{'L' if is_long else 'S'}_{_zr}"
                            _delta_entry = True
                            logger.warning(f"[DELTA_ENTRY] {symbol} {'L' if is_long else 'S'}: zone={_d_sig.zone} {_zr} htf={_htf_gate}")
                        else:
                            logger.info(f"[DELTA_BLOCKED] {symbol} {'L' if is_long else 'S'}: {_block_reason}")
                # Fallback: WT/DC scorer if delta didn't trigger
                # ═══ MTF ARROW ENTRY (USER 2026-07-20) — the ported lab decision function.
                # Runs FIRST and unconditionally for LONGs: HTF band-depth + slope score gates the
                # entry and sets the size. This is the system proven at 5.81x b&h (ARM) in
                # tools/mtf_arrow_lab; everything below stays as fallback when it does not fire.
                # 2026-07-29 USER promotion: gate resolves per-key (trb/active_config.json
                # overrides) so single keys can run the arrow+ladder without the global on.
                if (bool(_cfg('MTF_ARROW_ENTRY_ENABLED', getattr(config, 'MTF_ARROW_ENTRY_ENABLED', False), account_key, symbol, position_side))
                        and action_type != "OPEN" and is_long):
                    _ma_ind = indicators_raw if indicators_raw else i
                    _ma_score, _ma_detail = mtf_arrow_score(_ma_ind, True, config)
                    _ma_theta = float(getattr(config, 'MTF_ARROW_THETA', 0.3))
                    _ma_n = globals().get('_ARROW_EVAL_COUNT', 0) + 1
                    globals()['_ARROW_EVAL_COUNT'] = _ma_n
                    if _ma_n <= 5 or _ma_n % 1000 == 0:
                        _arrow_dbg(f"EVAL#{_ma_n} {symbol} score={_ma_score:.3f} theta={_ma_theta} detail={_ma_detail}")
                    # 2026-07-21 lab-faithful 5m CONFIRM trigger (mtf_arrow_lab phase_b :168-175):
                    # the score is the HTF gate+sizer, NOT the entry timing. Entry = the 5m green
                    # arrow — price reversing >= CONFIRM_PCT off the running low since last flat.
                    # Without this the port fired on every score>=theta bar (13k claims/run).
                    # State resets lo=px on the first flat evaluation after a claim (lab resets at
                    # exit; a refused execute costs some low history — acceptable, refusals are
                    # rare post gate-bypass).
                    _ma_conf = float(getattr(config, 'MTF_ARROW_CONFIRM_PCT', 2.0))
                    if not hasattr(trade_manager, '_arrow_swing'):
                        trade_manager._arrow_swing = {}
                    _ma_st = trade_manager._arrow_swing.get(symbol)
                    if _ma_st is None or _ma_st.get('opened'):
                        _ma_st = {'lo': current_price, 'opened': False}
                        trade_manager._arrow_swing[symbol] = _ma_st
                    if current_price < _ma_st['lo']:
                        _ma_st['lo'] = current_price
                    _ma_confirmed = current_price >= _ma_st['lo'] * (1.0 + _ma_conf / 100.0)
                    if _ma_confirmed and _ma_score >= _ma_theta:
                        _ma_base = float(getattr(config, 'START_POSITION_SIZE', 600)) / current_price if current_price is not None and current_price > 0 else 1
                        if bool(_cfg('LR_BAND_LADDER_ENABLED', False, account_key, symbol, position_side)):
                            # USER 2026-07-22: the green arrow is the TRIGGER, the band position is
                            # the QUANTITY. Size this arrow by where price sits between the D bands
                            # (10x at/below centre -> 3x at/above top), 0 below the lower band = no
                            # trade. Depth IS the size — not the momentum score.
                            _ld_tf = str(_cfg('LR_BAND_ENTRY_TF', 'D', account_key, symbol, position_side))
                            _ld_src = indicators_raw if indicators_raw else i
                            _ld_pb = _ld_src.get(f"lrL_pct_b_{_ld_tf}")
                            # 2026-07-29 USER promotion: curve values resolve per-key so each
                            # promoted key carries its own sealed-artifact ladder (MU c151 etc.).
                            _ld_view = _PerKeyCfgView(account_key, symbol, position_side)
                            _ma_mult = band_ladder_mult(_ld_pb, _ld_view, _ld_tf) if _ld_pb is not None else 0.0
                            _ld_cap_x = float(_cfg('LR_BAND_LADDER_CAP_X', 0.0, account_key, symbol, position_side) or 0.0)
                            if _ld_cap_x > 0.0 and _ma_mult > _ld_cap_x:
                                _ma_mult = _ld_cap_x
                            if _ma_mult <= 0.0:
                                logger.debug(f"[LR_BAND_LADDER_SKIP] {symbol}: pb={_ld_pb} below lower band or unusable — arrow ignored")
                            else:
                                action_type = "OPEN"
                                qty = int(max(1, _ma_base * _ma_mult))
                                conf = 90.0
                                reason = f"LR_BAND_LADDER_ARROW_pb={float(_ld_pb):.3f}_x{_ma_mult:.2f}_{_ld_tf}_s{_ma_score:.2f}"[:110]
                        else:
                            _ma_mult = max(0.5, min(float(getattr(config, 'MTF_ARROW_SIZE_MAX', 4.0)),
                                                    1.0 + float(getattr(config, 'MTF_ARROW_SIZE_GAIN', 1.0)) * _ma_score))
                            action_type = "OPEN"
                            qty = int(max(1, _ma_base * _ma_mult))
                            conf = 90.0
                            reason = f"MTF_ARROW_ENTRY_L_s{_ma_score:.2f}_x{_ma_mult:.2f}_{_ma_detail}"[:110]
                        # The post-entry VARIANCE_FIX veto gates on _entry_score (default
                        # TRADIER_ENTRY_SCORE_THRESHOLD=30). Paths that open without running
                        # wt_dc_score_entry leave it 0.0 and are silently dropped AFTER having
                        # claimed the action slot — the documented C1 bug class (see ~3043).
                        # The arrow score IS this path's conviction, so publish it.
                        _entry_score = max(float(_entry_score or 0.0), float(conf))
                        _ma_st['opened'] = True
                        logger.info(f"[MTF_ARROW_ENTRY] {account_key}:{symbol}: score={_ma_score:.3f}>=θ{_ma_theta} mult={_ma_mult:.2f} {_ma_detail}")
                        _arrow_dbg(f"CLAIM {account_key}:{symbol} score={_ma_score:.3f} mult={_ma_mult:.2f} qty={qty} lo={_ma_st['lo']:.2f} px={current_price:.2f}")
                # 2026-07-29 USER promotion (shorts): mirrored arrow+ladder for per-key promoted
                # SHORT keys (TTD, ACN). Red arrow = price reversing >= CONFIRM_PCT off the running
                # HIGH since flat; ladder depth inverts (deep short = price at the TOP of the
                # channel) so the ladder is fed 1-pct_b. Per-key gate only — no global switch.
                if (bool(_cfg('MTF_ARROW_SHORT_ENTRY_ENABLED', False, account_key, symbol, position_side))
                        and action_type != "OPEN" and not is_long
                        and bool(_cfg('LR_BAND_LADDER_ENABLED', False, account_key, symbol, position_side))):
                    _ms_ind = indicators_raw if indicators_raw else i
                    _ms_score, _ms_detail = mtf_arrow_score(_ms_ind, False, config)
                    _ms_theta = float(_cfg('MTF_ARROW_THETA', getattr(config, 'MTF_ARROW_THETA', 0.3), account_key, symbol, position_side))
                    # This is a per-symbol path.  Reading the global object here
                    # silently ignored MSTR_SHORT (and other short) overlay values
                    # in live use.  _cfg also carries the explicit V8 override
                    # precedence contract, so the configured confirmation sweep
                    # now reaches the actual red-arrow state machine.
                    _ms_conf = float(_cfg(
                        'MTF_ARROW_CONFIRM_PCT', 2.0,
                        account_key, symbol, position_side,
                    ))
                    if not hasattr(trade_manager, '_arrow_swing_short'):
                        trade_manager._arrow_swing_short = {}
                    _ms_st = trade_manager._arrow_swing_short.get(symbol)
                    if _ms_st is None or _ms_st.get('opened'):
                        _ms_st = {'hi': current_price, 'opened': False}
                        trade_manager._arrow_swing_short[symbol] = _ms_st
                    if current_price > _ms_st['hi']:
                        _ms_st['hi'] = current_price
                    _ms_confirmed = current_price <= _ms_st['hi'] * (1.0 - _ms_conf / 100.0)
                    if _ms_confirmed and _ms_score >= _ms_theta:
                        _ld_tf_s = str(_cfg('LR_BAND_ENTRY_TF', 'D', account_key, symbol, position_side))
                        _ld_pb_s = _ms_ind.get(f"lrL_pct_b_{_ld_tf_s}")
                        _ms_mult = 0.0
                        if _ld_pb_s is not None:
                            try:
                                _ms_mult = band_ladder_mult(1.0 - float(_ld_pb_s), _PerKeyCfgView(account_key, symbol, position_side), _ld_tf_s)
                            except (TypeError, ValueError):
                                _ms_mult = 0.0
                        _ld_cap_s = float(_cfg('LR_BAND_LADDER_CAP_X', 0.0, account_key, symbol, position_side) or 0.0)
                        if _ld_cap_s > 0.0 and _ms_mult > _ld_cap_s:
                            _ms_mult = _ld_cap_s
                        if _ms_mult <= 0.0:
                            logger.debug(f"[LR_BAND_LADDER_SKIP_S] {symbol}: pb={_ld_pb_s} outside short ladder — red arrow ignored")
                        else:
                            _ms_base = float(_cfg('START_POSITION_SIZE', getattr(config, 'START_POSITION_SIZE', 600), account_key, symbol, position_side)) / current_price if current_price is not None and current_price > 0 else 1
                            action_type = "OPEN"
                            qty = int(max(1, _ms_base * _ms_mult))
                            conf = 90.0
                            reason = f"LR_BAND_LADDER_ARROW_S_pb={float(_ld_pb_s):.3f}_x{_ms_mult:.2f}_{_ld_tf_s}_s{_ms_score:.2f}"[:110]
                            _entry_score = max(float(_entry_score or 0.0), float(conf))
                            _ms_st['opened'] = True
                            logger.info(f"[MTF_ARROW_ENTRY_S] {account_key}:{symbol}: score={_ms_score:.3f}>=θ{_ms_theta} mult={_ms_mult:.2f} {_ms_detail}")
                # 2026-07-20 USER band mandate — PRIORITY band entry. The band block used to sit
                # LAST in the cascade, so it was almost never consulted (an earlier path had already
                # set OPEN, or the key was no longer flat): 3189 regime-eligible ARM bars → 0 fires.
                # With LR_BAND_ENTRY_PRIORITY the band/regime test runs FIRST for LONGs, matching the
                # arrow-lab finding that band+slope context beats momentum-score ordering.
                if (bool(getattr(config, 'LR_BAND_ENTRY_PRIORITY', False))
                        and bool(getattr(config, 'LR_BAND_ENTRY_ENABLED', False))
                        and action_type != "OPEN" and is_long):
                    _pb_tf = getattr(config, 'LR_BAND_ENTRY_TF', 'D')
                    _pb_src = indicators_raw if indicators_raw else i
                    _pb_pb = _pb_src.get(f"lrL_pct_b_{_pb_tf}")
                    _pb_sl = _pb_src.get(f"lrL_slope_{_pb_tf}")
                    _pb_r2 = _pb_src.get(f"lrL_r2_{_pb_tf}")
                    if _pb_pb is not None and _pb_sl is not None:
                        _pb_pb_f, _pb_sl_f = float(_pb_pb), float(_pb_sl)
                        _pb_r2_f = float(_pb_r2) if _pb_r2 is not None else 1.0
                        _pb_lo = float(getattr(config, 'LR_BAND_ENTRY_LO', 0.3))
                        if bool(getattr(config, 'LR_BAND_REGIME_ENABLED', False)):
                            _pb_lo = max(_pb_lo, float(getattr(config, 'LR_BAND_REGIME_MAX_PB', 0.6)))
                        if bool(_cfg('LR_BAND_LADDER_ENABLED', False, account_key, symbol, position_side)):
                            # USER 2026-07-22 LADDER: every green arrow enters when flat, sized by
                            # where price sits between the bands. No pct_b gate and no R2 gate —
                            # those made it fire only at extremes (0 fires on 3,189 eligible bars),
                            # which the user identified as structurally wrong. Depth IS the size.
                            _pb_mult = band_ladder_mult(_pb_pb_f, config, _pb_tf)
                            if _pb_mult > 0.0 and _pb_sl_f > 0:
                                _pb_base = float(_cfg('START_POSITION_SIZE', 600, account_key, symbol, position_side)) / current_price if current_price is not None and current_price > 0 else 1
                                action_type = "OPEN"
                                qty = int(max(1, _pb_base * _pb_mult))
                                conf = 88.0
                                reason = f"LR_BAND_LADDER_L_pb={_pb_pb_f:.3f}_sl={_pb_sl_f:+.3f}_x{_pb_mult:.2f}_{_pb_tf}"
                                logger.info(f"[LR_BAND_LADDER] {account_key}:{symbol}: pb={_pb_pb_f:.3f} slope={_pb_sl_f:+.4f} mult={_pb_mult:.2f} tf={_pb_tf} qty={qty}")
                            elif _pb_mult <= 0.0:
                                logger.debug(f"[LR_BAND_LADDER_SKIP] {account_key}:{symbol}: pb={_pb_pb_f:.3f} below lower band — ignored by design")
                        elif _pb_pb_f <= _pb_lo and _pb_sl_f > 0 and _pb_r2_f >= float(getattr(config, 'LR_BAND_ENTRY_R2_MIN', 0.7)):
                            _pb_base = float(getattr(config, 'START_POSITION_SIZE', 600)) / current_price if current_price is not None and current_price > 0 else 1
                            # legacy threshold path (pre-ladder): deeper AND steeper = bigger.
                            _pb_depth = max(0.0, 1.0 - _pb_pb_f)
                            _pb_mult = 1.0 + float(getattr(config, 'LR_BAND_SIZE_DEPTH_GAIN', 1.0)) * _pb_depth \
                                + float(getattr(config, 'LR_BAND_SIZE_SLOPE_GAIN', 1.0)) * min(abs(_pb_sl_f) / max(1e-9, float(getattr(config, 'LR_BAND_SLOPE_NORM_PCT_DAY', 0.3))), 1.0)
                            _pb_mult = max(0.5, min(float(getattr(config, 'LR_BAND_SIZE_MAX', 3.0)), _pb_mult))
                            action_type = "OPEN"
                            qty = int(max(1, _pb_base * _pb_mult))
                            conf = 88.0
                            reason = f"LR_BAND_ENTRY_L_prio_pb={_pb_pb_f:.3f}_sl={_pb_sl_f:+.3f}_x{_pb_mult:.2f}"
                            logger.info(f"[LR_BAND_ENTRY_PRIO] {account_key}:{symbol}: pb={_pb_pb_f:.3f} slope={_pb_sl_f:+.4f} mult={_pb_mult:.2f} tf={_pb_tf}")
                # Path-scoped switch: disabling WT_DC must not disable GR, ladder,
                # delta, or mandatory reentry for the same symbol/side.
                _wtdc_side_switch = (
                    "WT_DC_LONG_ENABLED" if is_long else "WT_DC_SHORT_ENABLED"
                )
                _wtdc_path_enabled = bool(
                    _cfg(
                        _wtdc_side_switch,
                        True,
                        account_key,
                        symbol,
                        "LONG" if is_long else "SHORT",
                    )
                )
                if action_type != "OPEN" and _wtdc_path_enabled:
                    _entry_ind = indicators_raw if indicators_raw else i
                    _entry_score, _entry_reason = wt_dc_score_entry(_entry_ind, is_long, current_price)
                    if os.environ.get("V8_LRBAND_DEBUG"):
                        _lbp1 = globals().setdefault("_LRBAND_P1", {"n": 0})
                        _lbp1["n"] += 1
                        if _lbp1["n"] % 2000 == 1:
                            print(f"V8_LOG LRBAND_P1 post_score_reach={_lbp1['n']} score={_entry_score:.0f}", flush=True)
                    # 2026-04-27 — additive entry-engine boost (default OFF; user controls activation).
                    # Engines NEVER block existing entries — only ADD score. Wrapped to never raise.
                    if getattr(config, 'LIVE_ENTRY_ENGINE_ENABLED', False):
                        _ee_score_max = 0.0
                        _ee_reasons = []
                        _ee_side = 'LONG' if is_long else 'SHORT'
                        for _ee_name, _ee_fn, _ee_flag in (
                            ('wt', _ee_should_fire_wt_entry, 'LIVE_ENTRY_ENGINE_WT_ENABLED'),
                            ('stoch', _ee_should_fire_stoch_entry, 'LIVE_ENTRY_ENGINE_STOCH_ENABLED'),
                            ('dc', _ee_should_fire_dc_entry, 'LIVE_ENTRY_ENGINE_DC_ENABLED'),
                            ('htf', _ee_should_fire_htf_entry, 'LIVE_ENTRY_ENGINE_HTF_ENABLED'),
                            ('stdev_macro', _ee_should_fire_stdev_macro_entry, 'LIVE_ENTRY_ENGINE_STDEV_MACRO_ENABLED'),
                        ):
                            if not getattr(config, _ee_flag, False): continue
                            if _ee_fn is None: continue
                            try:
                                _fire, _why, _sc = _ee_fn(symbol, _entry_ind, _ee_side)
                                if _fire and _sc >= float(getattr(config, 'LIVE_ENTRY_ENGINE_MIN_SCORE', 0.6)):
                                    _ee_score_max = max(_ee_score_max, _sc)
                                    _ee_reasons.append(f"{_ee_name}={_sc:.2f}")
                            except Exception:
                                pass  # never let engine error block entry
                        if _ee_score_max > 0:
                            _ee_boost = float(getattr(config, 'LIVE_ENTRY_ENGINE_BOOST_SCORE', 8.0))
                            _entry_score = _entry_score + (_ee_boost * _ee_score_max)
                            _entry_reason = (_entry_reason or '') + f" +ENGINES({','.join(_ee_reasons)})"
                    # ═══ BB SCORING BOOSTS (Phase 9 — WIRED 2026-05-22) ═══
                    if getattr(config, 'BB_BREAKOUT_ENABLED', False):
                        _bb_tf = getattr(config, 'BB_BREAKOUT_TF', '1h')
                        _bb_pct = float((_entry_ind or {}).get(f'bb_pct_b_{_bb_tf}', 0.5) or 0.5)
                        if (is_long and _bb_pct > 1.0) or ((not is_long) and _bb_pct < 0.0):
                            _bb_boost = int(getattr(config, 'BB_BREAKOUT_SCORE', 20))
                            _entry_score += _bb_boost
                            _entry_reason = (_entry_reason or '') + f" +BB_BREAK({_bb_tf}={_bb_pct:.2f}+{_bb_boost})"
                    if getattr(config, 'BB_RSI_STOCH_SCALP_ENABLED', False):
                        _brs_bb = float((_entry_ind or {}).get('bb_pct_b_5m', 0.5) or 0.5)
                        _brs_rsi = float((_entry_ind or {}).get('rsi_5m', 50) or 50)
                        _brs_k = float((_entry_ind or {}).get('k_5m', 50) or 50)
                        _brs_long = _brs_bb < 0.2 and _brs_rsi < 30 and _brs_k < 20
                        _brs_short = _brs_bb > 0.8 and _brs_rsi > 70 and _brs_k > 80
                        if (is_long and _brs_long) or ((not is_long) and _brs_short):
                            _brs_boost = int(getattr(config, 'BB_RSI_STOCH_SCALP_SCORE', 12))
                            _entry_score += _brs_boost
                            _entry_reason = (_entry_reason or '') + f" +BB_RSI_STOCH(bb={_brs_bb:.2f}rsi={_brs_rsi:.0f}k={_brs_k:.0f}+{_brs_boost})"
                    # ═══ END BB SCORING BOOSTS ═══
                    # tra uses a much higher entry bar so only the strongest HTF
                    # setups fire — long-term hold needs few, very high quality entries.
                    if account_key == 'tra':
                        _entry_threshold = float(getattr(config, 'TRA_WT_DC_ENTRY_THRESHOLD', 85))
                    else:
                        _entry_threshold = getattr(config, 'WT_DC_ENTRY_THRESHOLD', 55)
                    _k5m_now = float((_entry_ind or {}).get('k_5m', 50) or 50)
                    _k5m_block = (is_long and _k5m_now > float(getattr(config, 'WT_DC_ENTRY_K5M_MAX_LONG', 100))) or ((not is_long) and _k5m_now < float(getattr(config, 'WT_DC_ENTRY_K5M_MIN_SHORT', 0)))
                    # 2026-04-27 — HTF gate on WT_DC_ENTRY path (matches DELTA_HTF_GATE pattern). Closes the
                    # SHORT-into-uptrend gap that allowed PLTR loss. Default 'none' = inert; live config sets '4h'.
                    _wtdc_htf_gate = str(getattr(config, 'WT_DC_HTF_GATE', 'none')).lower()
                    _htf_block = False
                    if _wtdc_htf_gate == '1h':
                        _wt1_1h = float((_entry_ind or {}).get('wt1_1h', 0) or 0)
                        _wt2_1h = float((_entry_ind or {}).get('wt2_1h', 0) or 0)
                        _1h_against = (is_long and _wt1_1h < _wt2_1h) or ((not is_long) and _wt1_1h > _wt2_1h)
                        if _1h_against: _htf_block = True
                    if _wtdc_htf_gate in ('4h', '4h_d'):
                        _wt1_4h = float((_entry_ind or {}).get('wt1_4h', 0) or 0)
                        _wt2_4h = float((_entry_ind or {}).get('wt2_4h', 0) or 0)
                        _4h_against = (is_long and _wt1_4h < _wt2_4h) or ((not is_long) and _wt1_4h > _wt2_4h)
                        if _4h_against: _htf_block = True
                    if not _htf_block and _wtdc_htf_gate == '4h_d':
                        _wt1_D = float((_entry_ind or {}).get('wt1_D', 0) or 0)
                        _wt2_D = float((_entry_ind or {}).get('wt2_D', 0) or 0)
                        _D_against = (is_long and _wt1_D < _wt2_D) or ((not is_long) and _wt1_D > _wt2_D)
                        if _D_against: _htf_block = True
                    # ═══════════════════════════════════════════════════════════
                    # 🚩 NEW BASELINE 2026-05-12 — 3 additional WT_DC_ENTRY gates
                    # Source: vec_sweep winner dc45_h1_s40_grOFF
                    # ───────────────────────────────────────────────────────────
                    # ROLLBACK: set each config knob to its disabled value:
                    #   HTF_ALIGN_REQUIRED_TRADIER = 0  (currently 1)
                    #   COMBINED_STOCH_GATE_TRADIER = 100  (currently 40)
                    #   GR_HTF_GATE_ENABLED = False  (currently False, no change)
                    # Each gate sets a BLOCK flag that joins the final check below.
                    # ═══════════════════════════════════════════════════════════
                    _htf_align_block = False
                    _stoch_gate_block = False
                    _gr_htf_block = False
                    _htf_align_req = int(getattr(config, 'HTF_ALIGN_REQUIRED_TRADIER', 0))
                    if _htf_align_req > 0:
                        _htf_count = 0
                        for _htf_tf in ('1h', '4h', 'D'):
                            _wt1_h = float((_entry_ind or {}).get(f'wt1_{_htf_tf}', 0) or 0)
                            _wt2_h = float((_entry_ind or {}).get(f'wt2_{_htf_tf}', 0) or 0)
                            if is_long and _wt1_h > _wt2_h:
                                _htf_count += 1
                            elif (not is_long) and _wt1_h < _wt2_h:
                                _htf_count += 1
                        if _htf_count < _htf_align_req:
                            _htf_align_block = True
                    _stoch_gate_thr = float(getattr(config, 'COMBINED_STOCH_GATE_TRADIER', 100.0))
                    if _stoch_gate_thr < 100.0:
                        _k5m_g = float((_entry_ind or {}).get('k_5m', 50) or 50)
                        if is_long and _k5m_g >= _stoch_gate_thr:
                            _stoch_gate_block = True
                        elif (not is_long) and _k5m_g <= (100.0 - _stoch_gate_thr):
                            _stoch_gate_block = True
                    _gr_htf_enabled = bool(getattr(config, 'GR_HTF_GATE_ENABLED', False))
                    if _gr_htf_enabled:
                        _gr_req_bull = int(getattr(config, 'GR_HTF_REQUIRE_BULL', 1))
                        _gr_req_bear = int(getattr(config, 'GR_HTF_REQUIRE_BEAR', 1))
                        _gr_bull = int((_entry_ind or {}).get('wt_bull_alignment', 0) or 0)
                        _gr_bear = int((_entry_ind or {}).get('wt_bear_alignment', 0) or 0)
                        if is_long and _gr_bull < _gr_req_bull:
                            _gr_htf_block = True
                        elif (not is_long) and _gr_bear < _gr_req_bear:
                            _gr_htf_block = True
                    # ═══ END NEW BASELINE GATES ═══
                    # ═══ 2026-05-16 — BAR_MATURITY guard (DEFAULT OFF behind WT_DC_ENTRY_BAR_MATURITY_BLOCK_ENABLED) ═══
                    # WT_DC_ENTRY_80_D_bear was averaging -7.14% on 4 trades in 30d. Root
                    # cause: WT/DC scorer fires LATE in a daily bar after most of the move
                    # has already happened — entry is into exhaustion, not into a setup.
                    # Block when bar has already consumed >70% of its expected daily ATR
                    # in the SAME direction as the proposed signal. Skips block if open_D
                    # or atr_D are unavailable (fail-open, preserves existing entries on
                    # malformed data). Flag default False: legacy behavior preserved until
                    # sweep-validated.
                    _bar_maturity_block = False
                    if bool(getattr(config, 'WT_DC_ENTRY_BAR_MATURITY_BLOCK_ENABLED', False)):
                        _bm_thr = float(getattr(config, 'WT_DC_ENTRY_BAR_MATURITY_BLOCK', 0.7))
                        if _bm_thr > 0.0 and _bm_thr < 1.0:
                            _bm_open_d = float((_entry_ind or {}).get('open_D', 0) or 0)
                            _bm_atr_d = float((_entry_ind or {}).get('atr_D', 0) or 0)
                            if _bm_open_d > 0 and _bm_atr_d > 0:
                                _bm_pos = abs(current_price - _bm_open_d) / max(_bm_atr_d, 1e-6)
                                _bm_bar_up = (current_price > _bm_open_d)
                                _bm_same_dir = (is_long and _bm_bar_up) or ((not is_long) and (not _bm_bar_up))
                                if _bm_pos > _bm_thr and _bm_same_dir:
                                    _bar_maturity_block = True
                                    logger.info(f"[WT_DC_BAR_MATURITY_BLOCK] {symbol} {'L' if is_long else 'S'}: pos={_bm_pos:.2f}>thr={_bm_thr:.2f} bar_up={_bm_bar_up} px={current_price:.2f} open_D={_bm_open_d:.2f} atr_D={_bm_atr_d:.4f} score={_entry_score:.0f}")
                    _uve_block = not _uve_entry_allowed(symbol, "LONG" if is_long else "SHORT", account_key, _entry_ind or i, current_price)
                    # This was previously a config-only matrix knob: the exact
                    # engine could alter BB_PULLBACK_GATE_LONG_MAX forever
                    # without the live entry decision seeing it.  Apply the
                    # documented directional BB pullback filter at the common
                    # WT/DC path.  Missing data fails open inside the helper.
                    _bb_pullback_cfg = SimpleNamespace(
                        BB_PULLBACK_GATE_ENABLED=bool(_cfg(
                            'BB_PULLBACK_GATE_ENABLED',
                            getattr(config, 'BB_PULLBACK_GATE_ENABLED', False),
                            account_key, symbol, 'LONG' if is_long else 'SHORT',
                        )),
                        BB_PULLBACK_GATE_TF=str(_cfg(
                            'BB_PULLBACK_GATE_TF',
                            getattr(config, 'BB_PULLBACK_GATE_TF', '15m'),
                            account_key, symbol, 'LONG' if is_long else 'SHORT',
                        )),
                        BB_PULLBACK_GATE_LONG_MAX=float(_cfg(
                            'BB_PULLBACK_GATE_LONG_MAX',
                            getattr(config, 'BB_PULLBACK_GATE_LONG_MAX', 0.30),
                            account_key, symbol, 'LONG' if is_long else 'SHORT',
                        )),
                        BB_PULLBACK_GATE_SHORT_MIN=float(_cfg(
                            'BB_PULLBACK_GATE_SHORT_MIN',
                            getattr(config, 'BB_PULLBACK_GATE_SHORT_MIN', 0.70),
                            account_key, symbol, 'LONG' if is_long else 'SHORT',
                        )),
                    )
                    _bb_pullback_block = _bb_pullback_gate_blocks(
                        _entry_ind or i, _bb_pullback_cfg, is_long
                    )
                    if _uve_block and _entry_score >= _entry_threshold:
                        logger.info(f"[UVE_ENTRY_BLOCK] {symbol} {'L' if is_long else 'S'}: score={_entry_score:.0f} passed threshold but UVE signal not aligned")
                    if _bb_pullback_block and _entry_score >= _entry_threshold:
                        _bb_tf_gate = _bb_pullback_cfg.BB_PULLBACK_GATE_TF or '15m'
                        _bb_val_gate = (_entry_ind or i).get(f'bb_pct_b_{_bb_tf_gate}')
                        logger.info(f"[BB_PULLBACK_GATE_BLOCK] {symbol} {'L' if is_long else 'S'}: tf={_bb_tf_gate} pct_b={_bb_val_gate} score={_entry_score:.0f}")
                    if _entry_score >= _entry_threshold and not _k5m_block and not _htf_block and not _htf_align_block and not _stoch_gate_block and not _gr_htf_block and not _bar_maturity_block and not _uve_block and not _bb_pullback_block:
                        _base_qty = float(getattr(config, 'START_POSITION_SIZE', 600)) / current_price if current_price is not None and current_price > 0 else 1
                        action_type = "OPEN"
                        qty = int(max(1, _base_qty))
                        conf = _entry_score
                        reason = f"WT_DC_ENTRY_{_entry_score:.0f}_{_entry_reason[:60]}"
                    elif _k5m_block and _entry_score >= _entry_threshold:
                        logger.info(f"[WT_DC_ENTRY_K5M_BLOCK] {symbol} {'L' if is_long else 'S'}: k5m={_k5m_now:.1f} score={_entry_score:.0f}")
                    elif _htf_block and _entry_score >= _entry_threshold:
                        logger.info(f"[WT_DC_HTF_BLOCK] {symbol} {'L' if is_long else 'S'}: HTF against (gate={_wtdc_htf_gate}) score={_entry_score:.0f}")
                elif action_type != "OPEN":
                    logger.debug(
                        f"[WT_DC_PATH_DISABLED] {account_key}:{symbol}_"
                        f"{'LONG' if is_long else 'SHORT'} via {_wtdc_side_switch}=False"
                    )
                # RZ_BREAKOUT: third entry path — fires when bb_pct_b_1h just exited extreme zone.
                # Band approach: LONG fires when bb_pctb is in [rz_bot, rz_bot+band] (just broke up from oversold).
                # SHORT fires when bb_pctb is in [rz_top-band, rz_top] (just broke down from overbought).
                # RZ_BREAKOUT_ENTRY_ENABLED defaults False — enable via config_tradier.py once sweep validates.
                if action_type != "OPEN" and getattr(config, 'RZ_BREAKOUT_ENTRY_ENABLED', False):
                    _rz_ind = indicators_raw if indicators_raw else i
                    _rz_bb_1h = float((_rz_ind or {}).get('bb_pct_b_1h', 0.5) or 0.5)
                    _rz_top_b = float(getattr(config, 'RZ_TOP_BB_THRESHOLD', 0.85))
                    _rz_bot_b = float(getattr(config, 'RZ_BOT_BB_THRESHOLD', 0.15))
                    _rz_band_b = float(getattr(config, 'RZ_BREAKOUT_BAND', 0.05))
                    _rz_fire = (is_long and _rz_bot_b <= _rz_bb_1h <= _rz_bot_b + _rz_band_b) or (not is_long and _rz_top_b - _rz_band_b <= _rz_bb_1h <= _rz_top_b)
                    if _rz_fire:
                        _base_qty = float(getattr(config, 'START_POSITION_SIZE', 600)) / current_price if current_price is not None and current_price > 0 else 1
                        action_type = "OPEN"
                        qty = int(max(1, _base_qty))
                        conf = 70.0
                        reason = f"RZ_BREAKOUT_{'L' if is_long else 'S'}_bb={_rz_bb_1h:.2f}"
                        logger.info(f"[RZ_BREAKOUT] {account_key}:{symbol} {'L' if is_long else 'S'}: bb_pctb_1h={_rz_bb_1h:.2f} band=[{_rz_bot_b if is_long else _rz_top_b - _rz_band_b:.2f},{(_rz_bot_b + _rz_band_b) if is_long else _rz_top_b:.2f}]")
                if action_type != "OPEN" and getattr(config, 'LR_PCTB_D_LONG_ENTRY_ENABLED', False):
                    if is_long:
                        _lr_pb = (indicators_raw if indicators_raw else i).get("lr_pct_b_D")
                        if _lr_pb is not None and float(_lr_pb) <= float(getattr(config, "LR_PCTB_D_LONG_ENTRY_THRESHOLD", 0.20)):
                            _base_qty = float(getattr(config, 'START_POSITION_SIZE', 600)) / current_price if current_price is not None and current_price > 0 else 1
                            action_type = "OPEN"
                            qty = int(max(1, _base_qty))
                            conf = 80.0
                            reason = f"LR_PCTB_D_LONG_bb={_lr_pb:.4f}"
                            logger.info(f"[LR_PCTB_D_LONG] {symbol}: lr_pct_b_D={_lr_pb:.4f} action={action_type}")
                if os.environ.get("V8_LRBAND_DEBUG") and action_type != "OPEN":
                    _lbd0 = globals().setdefault("_LRBAND_DBG0", {"n": 0})
                    _lbd0["n"] += 1
                    if _lbd0["n"] % 2000 == 1:
                        print(f"V8_LOG LRBAND_DBG0 region_reach={_lbd0['n']} enabled={getattr(config, 'LR_BAND_ENTRY_ENABLED', 'MISSING')} regime={getattr(config, 'LR_BAND_REGIME_ENABLED', 'MISSING')} cfg_id={id(config)}", flush=True)
                if action_type != "OPEN" and getattr(config, 'BB_PCTB_ENTRY_ENABLED', False):
                    try:
                        _bb_pctb_1h = float(i.get('bb_pct_b_1h', 0.5) or 0.5)
                        _bb_long_thr = float(getattr(config, 'BB_ENTRY_LONG_THRESHOLD', -0.2))
                        _bb_short_thr = float(getattr(config, 'BB_ENTRY_SHORT_THRESHOLD', 1.0))
                        _bb_fire = (_bb_pctb_1h < _bb_long_thr) if is_long else (_bb_pctb_1h > _bb_short_thr)
                        if _bb_fire:
                            return True, f"BB_PCTB_ENTRY(bb={_bb_pctb_1h:.3f}{'<'+str(_bb_long_thr) if is_long else '>'+str(_bb_short_thr)})", qty
                    except Exception: pass
                # REENTRY PULL 1-4 + SATOSHIT ENTRY — added 2026-08-11 to make live identical to vectorized backtest (were missing, caused entry count 1 vs 300 divergence) — ADD not discard
                if action_type != "OPEN" and getattr(config, 'REENTRY_PULL1_ENABLED', False):
                    try:
                        if is_long and float(i.get('wt_velocity_1h',0) or 0) > 1 and float(i.get('stoch_k_3m',50) or 50) < 20 and float(i.get('stoch_k_3m_prev',50) or 50) < float(i.get('stoch_k_3m',50) or 50):
                            return True, f"REENTRY_PULL1(wt1h>1,k3m<20)", qty
                        if not is_long and float(i.get('wt_velocity_1h',0) or 0) < -1 and float(i.get('stoch_k_3m',50) or 50) > 80:
                            return True, f"REENTRY_PULL1_SHORT", qty
                    except Exception: pass
                if action_type != "OPEN" and getattr(config, 'REENTRY_PULL2_ENABLED', False):
                    try:
                        if float(i.get('wt_velocity_D',0) or 0) > 1 and float(i.get('sma_dist_1h',0) or 0) < -1:
                            return True, f"REENTRY_PULL2(wt_D>1,dist< -1)", qty
                    except Exception: pass
                if action_type != "OPEN" and getattr(config, 'REENTRY_PULL3_ENABLED', False):
                    try:
                        if float(i.get('bb_pct_b_1h',0.5) or 0.5) < 0.15 and float(i.get('stoch_k_3m',50) or 50) < 30:
                            return True, f"REENTRY_PULL3(bb<0.15)", qty
                    except Exception: pass
                if action_type != "OPEN" and getattr(config, 'REENTRY_PULL4_ENABLED', False):
                    try:
                        if float(i.get('rsi_1h',50) or 50) < 30 and float(i.get('wt_velocity_3m',0) or 0) > 0:
                            return True, f"REENTRY_PULL4(rsi<30)", qty
                    except Exception: pass
                if action_type != "OPEN" and getattr(config, 'SATOSHIT_ENTRY_ENABLED', False):
                    try:
                        if is_long and float(i.get('stoch_k_3m',50) or 50) > 70 and float(i.get('rsi_1h',50) or 50) > 60:
                            return True, f"SATOSHIT_ENTRY(k>70,rsi>60)", qty
                        if not is_long and float(i.get('stoch_k_3m',50) or 50) < 30 and float(i.get('rsi_1h',50) or 50) < 40:
                            return True, f"SATOSHIT_ENTRY_SHORT", qty
                    except Exception: pass
                if action_type != "OPEN" and getattr(config, 'LR_BAND_ENTRY_ENABLED', False):
                    _lb_tf = getattr(config, 'LR_BAND_ENTRY_TF', 'D')
                    # 2026-07-20: MUST read the RAW snapshot (mirror RZ_BREAKOUT above) — the reduced
                    # `i` dict lacks lrL_* in the engine context, which silently killed every band entry.
                    _lb_src = indicators_raw if indicators_raw else i
                    _lb_pb = _lb_src.get(f"lrL_pct_b_{_lb_tf}")
                    _lb_sl = _lb_src.get(f"lrL_slope_{_lb_tf}")
                    _lb_r2 = _lb_src.get(f"lrL_r2_{_lb_tf}")
                    if os.environ.get("V8_LRBAND_DEBUG"):
                        _lbd = globals().setdefault("_LRBAND_DBG", {"reach": 0, "have": 0, "fired": 0, "keys": ""})
                        _lbd["reach"] += 1
                        if _lb_pb is not None and _lb_sl is not None and _lb_r2 is not None:
                            _lbd["have"] += 1
                        elif _lbd["keys"] == "":
                            _lbd["keys"] = ",".join(sorted(k for k in (_lb_src or {}) if "lr" in str(k).lower()))[:200] or "NO_LR_KEYS"
                        if _lbd["reach"] % 2000 == 1:
                            print(f"V8_LOG LRBAND_DBG reach={_lbd['reach']} have={_lbd['have']} fired={_lbd['fired']} is_long={is_long} src_keys~{_lbd['keys'][:120]}", flush=True)
                    if _lb_pb is not None and _lb_sl is not None and _lb_r2 is not None:
                        _lb_pb = float(_lb_pb)
                        _lb_sl = float(_lb_sl)
                        _lb_r2 = float(_lb_r2)
                        _lb_lo = float(getattr(config, 'LR_BAND_ENTRY_LO', 0.3))
                        # USER 2026-07-20 REGIME mode: catch EVERY upswing — while the channel RISES,
                        # be long from anywhere below the top band (not only on lower-band touches);
                        # entries above REGIME_MAX_PB wait for a dip (post-harvest re-add throttle).
                        if bool(getattr(config, 'LR_BAND_REGIME_ENABLED', False)):
                            _lb_lo = max(_lb_lo, float(getattr(config, 'LR_BAND_REGIME_MAX_PB', 0.6)))
                        _lb_sides = str(getattr(config, 'LR_BAND_ENTRY_SIDES', 'L'))
                        _lb_long_ok = is_long and _lb_pb <= _lb_lo and _lb_sl > 0
                        _lb_short_ok = (not is_long) and 'S' in _lb_sides and _lb_pb >= 1.0 - _lb_lo and _lb_sl < 0
                        if _lb_r2 >= float(getattr(config, 'LR_BAND_ENTRY_R2_MIN', 0.7)) and (_lb_long_ok or _lb_short_ok):
                            _base_qty = float(getattr(config, 'START_POSITION_SIZE', 600)) / current_price if current_price is not None and current_price > 0 else 1
                            action_type = "OPEN"
                            qty = int(max(1, _base_qty))
                            conf = 85.0
                            reason = f"LR_BAND_ENTRY_{'L' if is_long else 'S'}_pb={_lb_pb:.3f}_r2={_lb_r2:.2f}"
                            if os.environ.get("V8_LRBAND_DEBUG"):
                                globals().setdefault("_LRBAND_DBG", {"reach": 0, "have": 0, "fired": 0, "keys": ""})["fired"] += 1
                            logger.info(f"[LR_BAND_ENTRY] {account_key}:{symbol}: pb={_lb_pb:.3f} slope={_lb_sl:+.4f} r2={_lb_r2:.2f} tf={_lb_tf}")
                # ═══════════════════════════════════════════════════════════════════════
                # 🚩 GR_HTF_DIRECT_ENTRY — 2026-05-12 USER MANDATE
                # Direct entry signal: Score = n_tfs_aligned × GOLDEN_RULE_MIN_IND.
                # If score >= GR_HTF_DIRECT_ENTRY_SCORE_MIN and no prior path fired → OPEN.
                # If score >= GR_HTF_DIRECT_ENTRY_DOUBLE_SCORE → double size (2×START_POSITION_SIZE).
                # Reason: GR_HTF_DIRECT_ENTRY_{score}_{detail}
                # ROLLBACK: set GR_HTF_DIRECT_ENTRY_ENABLED=False in config_tradier.py.
                # ═══════════════════════════════════════════════════════════════════════
                _grde_handoff_claim = None
                if action_type != "OPEN" and bool(getattr(config, 'GR_HTF_DIRECT_ENTRY_ENABLED', True)):
                    try:
                        from golden_rule_htf import \
                            score_entry_htf as _gr_htf_direct_entry
                        _grde_min_ind = int(getattr(config, 'GOLDEN_RULE_MIN_IND', 1))
                        if os.environ.get("V8_MATRIX_CONTRACT_VERSION", "").startswith("tradier-matrix-exec-c5"):
                            from tradier_gr_htf_trace_c5 import trace_gr_htf as _c5_gr_trace
                            _c5_gr_trace(
                                "scorer_called",
                                path="GR_HTF_DIRECT_ENTRY",
                                account=account_key,
                                symbol=symbol,
                                position_side="LONG" if is_long else "SHORT",
                            )
                        _grde_pass, _grde_n_tfs, _grde_detail = _gr_htf_direct_entry(
                            indicators_raw if indicators_raw else i, is_long, 'tradier',
                            min_tfs=1, min_ind=_grde_min_ind, current_price=current_price)
                        # Build score as n_tfs × min_ind (the multiplicative score per spec)
                        _grde_score = float(_grde_n_tfs) * float(_grde_min_ind)
                        _grde_score_min = float(getattr(config, 'GR_HTF_DIRECT_ENTRY_SCORE_MIN', 12.0))
                        _grde_double_score = float(getattr(config, 'GR_HTF_DIRECT_ENTRY_DOUBLE_SCORE', 18.0))
                        if _grde_score >= _grde_score_min:
                            if os.environ.get("V8_MATRIX_CONTRACT_VERSION", "").startswith("tradier-matrix-exec-c5"):
                                _c5_gr_trace(
                                    "scorer_pass",
                                    path="GR_HTF_DIRECT_ENTRY",
                                    account=account_key,
                                    symbol=symbol,
                                    position_side="LONG" if is_long else "SHORT",
                                    score=_grde_score,
                                    threshold=_grde_score_min,
                                )
                            _grde_mult = 2.0 if _grde_score >= _grde_double_score else 1.0
                            _grde_sps = float(getattr(config, 'START_POSITION_SIZE', 600))
                            _grde_qty = int(max(1, (_grde_sps * _grde_mult) / current_price)) if current_price > 0 else 1
                            action_type = "OPEN"
                            qty = _grde_qty
                            conf = _grde_score
                            reason = f"GR_HTF_DIRECT_ENTRY_{_grde_score:.0f}_{_grde_detail[:60]}"
                            _grde_handoff_claim = reason
                            if os.environ.get("V8_MATRIX_CONTRACT_VERSION", "").startswith("tradier-matrix-exec-c5"):
                                _c5_gr_trace(
                                    "candidate",
                                    path="GR_HTF_DIRECT_ENTRY",
                                    account=account_key,
                                    symbol=symbol,
                                    position_side="LONG" if is_long else "SHORT",
                                    score=_grde_score,
                                    requested_qty=_grde_qty,
                                    reason=reason,
                                )
                            logger.warning(f"[GR_HTF_DIRECT_ENTRY] {account_key}:{symbol} {'L' if is_long else 'S'}: score={_grde_score:.0f} (tfs={_grde_n_tfs}×ind={_grde_min_ind}) >= {_grde_score_min:.0f} mult={_grde_mult:.0f}x qty={_grde_qty}")
                        else:
                            logger.info(f"[GR_HTF_DIRECT_ENTRY_MISS] {account_key}:{symbol} {'L' if is_long else 'S'}: score={_grde_score:.0f} < {_grde_score_min:.0f} detail={_grde_detail[:60]}")
                    except Exception as _grde_err:
                        logger.warning(f"[GR_HTF_DIRECT_ENTRY_ERR] {account_key}:{symbol}: {_grde_err}")
                # ═══ END GR_HTF_DIRECT_ENTRY ═══
                # VARIANCE_FIX 2026-04-14 — canonical-switch gate application on PRIMARY entry path.
                # The 8 previously-DEAD switches (K_ZONE_LONG/SHORT_THRESHOLD, MI_ENTRY_ENABLED,
                # MI_EXIT_ENABLED, WT_COMPOSITE_SCORING_ENABLED, WT_EXIT_TFS, WT_EXIT_MIN_TFS,
                # ENTRY_SCORE_THRESHOLD) were wired into calculate_signal_score/evaluate_open,
                # but process_position's PRIMARY entry path is wt_dc_score_entry and never called
                # evaluate_open. This block applies them as post-entry veto gates so flipping
                # them in V8 sweeps produces real paired-run variance. Defaults are non-restrictive
                # (preserve current live behaviour); sweeps that flip them tighter will gate trades.
                _open_claim = reason if (action_type == "OPEN" and ('MTF_ARROW' in (reason or '') or 'LR_BAND' in (reason or ''))) else None
                if action_type == "OPEN" and account_key != 'tra' and not _xb_reentry_fired and not _ordinary_parity_claim:
                    _veto = None
                    _side_vf = "LONG" if is_long else "SHORT"
                    # ENTRY_SCORE_THRESHOLD: gate the wt_dc _entry_score against the canonical knob.
                    # Default 0 means "no extra gate" — live behaviour unchanged.
                    _min_es = float(_cfg("ENTRY_SCORE_THRESHOLD", 0, account_key, symbol, _side_vf) or 0)
                    if _min_es > 0 and float(_entry_score) < _min_es:
                        _veto = f"ENTRY_SCORE_GATE({_entry_score:.0f}<{_min_es:.0f})"
                    # K_ZONE_LONG/SHORT_THRESHOLD: if enabled, require K_4h in the zone.
                    if _veto is None and getattr(config, 'K_ZONE_VETO_ENABLED_TRADIER', False):
                        _k4h_vf = float(i.get('k_4h', 50) or 50)
                        if is_long:
                            _kz_l = float(_cfg('K_ZONE_LONG_THRESHOLD_TRADIER', 100, account_key, symbol, _side_vf) or 100)
                            if _k4h_vf >= _kz_l:
                                _veto = f"K_ZONE_L_GATE(k4h={_k4h_vf:.0f}>={_kz_l:.0f})"
                        else:
                            _kz_s = float(_cfg('K_ZONE_SHORT_THRESHOLD_TRADIER', 0, account_key, symbol, _side_vf) or 0)
                            if _k4h_vf <= _kz_s:
                                _veto = f"K_ZONE_S_GATE(k4h={_k4h_vf:.0f}<={_kz_s:.0f})"
                    # MI_ENTRY_ENABLED: when True, require at least one MI confluence signal on 4h.
                    # FIX 2026-04-14 sentinel: was using i.get() which reads parse_market_data() output.
                    # wt_peak_structure_4h/wt_divergence_4h/wt_momentum_state_4h are NOT in that dict →
                    # always returned '' or None → _mi_ok=False → ALL entries vetoed. Use _entry_ind (=indicators_raw).
                    if _veto is None and _cfg('MI_ENTRY_ENABLED_TRADIER', False, account_key, symbol, _side_vf):
                        _wt_peak_4h_vf = _entry_ind.get('wt_peak_structure_4h', '')
                        _wt_trough_4h_vf = _entry_ind.get('wt_trough_structure_4h', '')
                        _wt_mom_4h_vf = _entry_ind.get('wt_momentum_state_4h', '')
                        _wt_div_4h_vf = _entry_ind.get('wt_divergence_4h', None)
                        if is_long:
                            _mi_ok = (_wt_trough_4h_vf == 'HL') or (_wt_mom_4h_vf == 'EXHAUST_DOWN') or (_wt_div_4h_vf == 'BULL')
                        else:
                            _mi_ok = (_wt_peak_4h_vf == 'LH') or (_wt_mom_4h_vf == 'EXHAUST_UP') or (_wt_div_4h_vf == 'BEAR')
                        if not _mi_ok:
                            _veto = f"MI_ENTRY_GATE(no_4h_confluence)"
                    # WT_COMPOSITE_SCORING_ENABLED: when sweep VETO knob is on AND composite scoring is on,
                    # require wt alignment >=2 on favourable side. Gated by WT_COMPOSITE_VETO_ENABLED_TRADIER
                    # so flipping the scoring switch alone in live code doesn't change entries.
                    # FIX 2026-04-14 sentinel ZERO_TRADES: was using i.get() which reads parse_market_data()
                    # output — wt_bull_alignment is NOT in that dict, so i.get() always returned 0 → 0<3 always
                    # True → ALL entries vetoed. Fix: read from _entry_ind (=indicators_raw). Also lowered
                    # threshold from <3 to <2: SATOSHIT fires at WT crosses (alignment 1-2), >=3 vetoed all.
                    if _veto is None and getattr(config, 'WT_COMPOSITE_VETO_ENABLED_TRADIER', False) and _cfg('WT_COMPOSITE_SCORING_ENABLED_TRADIER', False, account_key, symbol, _side_vf):
                        _wt_align_vf = float(_entry_ind.get('wt_bull_alignment' if is_long else 'wt_bear_alignment', 0) or 0)
                        _wt_comp_vf = float(_entry_ind.get('wt_composite_long' if is_long else 'wt_composite_short', 0) or 0)
                        if _wt_align_vf < 2 or _wt_comp_vf < -20.0:
                            _veto = f"WT_COMP_GATE(align={_wt_align_vf:.0f}<2_comp={_wt_comp_vf:.0f})"
                    # DC_POSITION_ENTRY_THRESHOLD: when DC_ENTRY_VETO_ENABLED_TRADIER is on, require price
                    # to be in the DC channel zone. Gated by DC_ENTRY_VETO_ENABLED_TRADIER so live code is
                    # unchanged (T65 removed DC from gate — this is sweep-only, proves threshold gates trades).
                    if _veto is None and getattr(config, 'DC_ENTRY_VETO_ENABLED_TRADIER', False):
                        _dc_th_vf = float(getattr(config, 'DC_POSITION_ENTRY_THRESHOLD', 0.25) or 0.25)
                        _dc_1h_vf = float(_entry_ind.get('dc_position_1h', 0.5) or 0.5)
                        _dc_4h_vf = float(_entry_ind.get('dc_position_4h', 0.5) or 0.5)
                        if is_long and not (_dc_1h_vf < _dc_th_vf or _dc_4h_vf < _dc_th_vf):
                            _veto = f"DC_ENTRY_GATE_L(1h={_dc_1h_vf:.2f}_4h={_dc_4h_vf:.2f}>={_dc_th_vf:.2f})"
                        elif not is_long and not (_dc_1h_vf > (1.0 - _dc_th_vf) or _dc_4h_vf > (1.0 - _dc_th_vf)):
                            _veto = f"DC_ENTRY_GATE_S(1h={_dc_1h_vf:.2f}_4h={_dc_4h_vf:.2f}<={(1.0 - _dc_th_vf):.2f})"
                    if _veto is None and not _uve_entry_allowed(symbol, _side_vf, account_key, _entry_ind or i, current_price):
                        _uve_mode = _cfg("UVE_STRATEGY_MODE", "legacy", account_key, symbol, _side_vf)
                        _veto = f"UVE_ENTRY_BLOCK(mode={_uve_mode})"
                    if _veto is not None:
                        _direct_route_handoff_telemetry(
                            trade_manager, position_key,
                            _shared_direct_handoff_claim, "VARIANCE_VETO",
                            reason=_veto,
                        )
                        logger.warning(f"[VARIANCE_FIX_VETO] {account_key}:{symbol}_{_side_vf}: {_veto} orig_reason={(reason or '')[:70]}")
                        if _grde_handoff_claim and os.environ.get("V8_MATRIX_CONTRACT_VERSION", "").startswith("tradier-matrix-exec-c5"):
                            _c5_gr_trace(
                                "wrapper_blocked",
                                path="GR_HTF_DIRECT_ENTRY",
                                account=account_key,
                                symbol=symbol,
                                position_side=_side_vf,
                                reason=_veto,
                            )
                        if _open_claim:
                            _arrow_dbg(f"VETO_VARIANCE {account_key}:{symbol} {_veto} claimed={_open_claim[:70]}")
                        action_type = "NO_ACTION"
                        reason = _veto
                if action_type == "OPEN" and not _xb_reentry_fired and not _ordinary_parity_claim and trade_manager.strategy.circuit_breaker.is_blocked(reason):
                    _direct_route_handoff_telemetry(
                        trade_manager, position_key,
                        _shared_direct_handoff_claim, "CIRCUIT_BREAKER",
                        reason=str(reason),
                    )
                    logger.critical(f"🛑 [CIRCUIT_BREAKER] {account_key}:{symbol}_{position_side}: BLOCKED entry '{reason}' — path auto-disabled after repeated collapses")
                    if _open_claim:
                        _arrow_dbg(f"CB_BLOCKED {account_key}:{symbol}_{position_side} claimed={_open_claim[:70]}")
                    return "CIRCUIT_BREAKER_BLOCKED"
                if action_type == "OPEN" and not _xb_reentry_fired and not _ordinary_parity_claim and getattr(config, 'TRADIER_LOCAL_EXTREMES_SCORING_ENABLED', False):
                    _le_ind = indicators_raw if indicators_raw else i
                    try:
                        _le_sc, _le_sz, _le_rsn = _le_score_entry(_le_ind, is_long)
                        _le_min_sc = float(getattr(config, 'LOCAL_EXTREMES_MIN_SCORE', 0.0))
                        if _le_sz > 0 and current_price > 0 and _le_sc >= _le_min_sc:
                            qty = int(max(1, _le_sz / current_price))
                            reason = f"LE_{_le_rsn}_{reason}"
                            logger.info(f"[{account_key}] LE_SCORER {symbol} {'L' if is_long else 'S'}: {_le_rsn} score={_le_sc:.0f} qty={qty} (${_le_sz:.0f})")
                        elif _le_sz > 0 and _le_sc < _le_min_sc:
                            _direct_route_handoff_telemetry(
                                trade_manager, position_key,
                                _shared_direct_handoff_claim,
                                "LOCAL_EXTREMES_MIN_SCORE",
                                reason=f"{_le_sc}<{_le_min_sc}",
                            )
                            action_type = "NO_ACTION"
                            reason = f"LE_MIN_SCORE_SKIP({_le_sc:.0f}<{_le_min_sc:.0f})"
                            logger.debug(f"[{account_key}] LE_SCORER min-score skip {symbol}: score={_le_sc:.0f} < min={_le_min_sc:.0f}")
                        else:
                            _direct_route_handoff_telemetry(
                                trade_manager, position_key,
                                _shared_direct_handoff_claim,
                                "LOCAL_EXTREMES_SKIP", reason=str(_le_rsn),
                            )
                            action_type = "NO_ACTION"
                            reason = f"LE_SCORE_SKIP({_le_rsn})"
                            logger.debug(f"[{account_key}] LE_SCORER skip {symbol}: {_le_rsn}")
                    except Exception as _le_err:
                        logger.warning(f"[{account_key}] LE_SCORER error {symbol}: {_le_err}")
                if _grde_handoff_claim and action_type == "OPEN" and os.environ.get("V8_MATRIX_CONTRACT_VERSION", "").startswith("tradier-matrix-exec-c5"):
                    _c5_gr_trace(
                        "post_veto_pass",
                        path="GR_HTF_DIRECT_ENTRY",
                        account=account_key,
                        symbol=symbol,
                        position_side="LONG" if is_long else "SHORT",
                        requested_qty=qty,
                        reason=reason,
                    )
                if action_type == "OPEN":
                    # Determine intended direction from strategy return
                    signal_is_long = "LONG" in reason.upper()
                    signal_is_short = "SHORT" in reason.upper()
                    
                    # Validate against Position Key (Are we processing the right key for this signal?)
                    # If we are processing AAPL_LONG key, but strategy says SHORT, we ignore.
                    if position_side == "LONG" and signal_is_short:
                        _direct_route_handoff_telemetry(
                            trade_manager, position_key,
                            _shared_direct_handoff_claim,
                            "SIGNAL_SIDE_MISMATCH", reason="SHORT",
                        )
                        log_rec = "WAIT"
                        log_reason = "Signal Mismatch (Short)"
                    elif position_side == "SHORT" and signal_is_long:
                        _direct_route_handoff_telemetry(
                            trade_manager, position_key,
                            _shared_direct_handoff_claim,
                            "SIGNAL_SIDE_MISMATCH", reason="LONG",
                        )
                        log_rec = "WAIT"
                        log_reason = "Signal Mismatch (Long)"
                    else:
                        # --- BALANCER LOGIC START ---
                        global_sentiment = float(i.get('sentiment', 0))
                        trade_manager.update_sentiment_history(global_sentiment)
                        
                        blocked_by_balancer = False
                        block_reason = ""
                        
                        breadth = (trade_manager.calculate_unified_market_ratio() - 0.5) * 2.0  # -1=full bear, +1=full bull
                        current_balance = trade_manager.get_current_portfolio_balance()  # sync, no await
                        current_long_pct = current_balance.get('long_pct', 0.5)
                        target = 0.5 + (breadth * 0.4)

                        _bear_mode = getattr(config, 'BEAR_MARKET_MODE_TRADIER', False)
                        _bal_thr = 0.8 if _bear_mode else 0.4  # In bear mode, only block at extreme levels
                        if position_side == "LONG":
                             if breadth < -_bal_thr and current_long_pct > target and not i.get('0is_top_sentiment'):
                                blocked_by_balancer = True; block_reason = f"Index Bearish ({breadth:.2f})"
                        elif position_side == "SHORT":
                             if breadth > _bal_thr and current_long_pct < target and not i.get('0is_bottom_sentiment'):
                                blocked_by_balancer = True; block_reason = f"Index Bullish ({breadth:.2f})"
                        # --- BALANCER LOGIC END ---

                        if blocked_by_balancer and not _xb_reentry_fired and not _ordinary_parity_claim:
                            _direct_route_handoff_telemetry(
                                trade_manager, position_key,
                                _shared_direct_handoff_claim,
                                "BALANCER_BLOCK", reason=block_reason,
                            )
                            log_rec = "BLOCKED"
                            log_reason = block_reason
                            logger.info(f"[{account_key}] BLOCKED {symbol}: {block_reason}")
                        else:
                            log_rec = "LONG BUY" if position_side == "LONG" else "SHORT SELL"
                            log_reason = reason
                            logger.info(f"[{account_key}] EXAMINING {position_side} entry {symbol}: {reason} Score={tech_score}")
                            _ordinary_parity_claim = (
                                _ordinary_parity_claim
                                or is_ordinary_ladder_target_reason(reason)
                            )
                            # Heavy artillery: pullback-reexpansion setup boosts qty
                            ha_setup, ha_score, ha_dir, ha_detail = trade_manager.check_pullback_reexpansion(symbol, indicators_raw)
                            if (
                                not _ordinary_parity_claim
                                and ha_setup
                                and ha_dir == position_side
                            ):
                                ha_mult = 3.0 if ha_score == 4 else 2.0
                                qty = int(qty * ha_mult)
                                log_rec = "🔫 HEAVY_ART" if position_side == "LONG" else "🔫 HEAVY_ART_S"
                                logger.info(f"[{account_key}] 🔫 HEAVY ARTILLERY {symbol} ×{ha_mult:.0f} score={ha_score}: {ha_detail}")
                            # 2.5σ STDEV BREAKOUT: boost size when entering during HTF breakout
                            if (
                                not _ordinary_parity_claim
                                and getattr(config, "STDEV_BREAKOUT_ENABLED", False)
                            ):
                                _sb_t = detect_stdev_breakout_t(symbol, is_long, i)
                                if _sb_t:
                                    _sb_mult = _sb_t.get('size_mult', 1.0)
                                    if _sb_mult > 1.0:
                                        qty = int(qty * _sb_mult)
                                    reason = f"STDEV_{_sb_t['phase']}_{_sb_t.get('htf', '?')}_pctb={_sb_t.get('pctb', 0):.3f}_{reason}"
                                    logger.warning(f"[STDEV_BREAKOUT] {symbol}: {_sb_t['phase']} {_sb_t['signal']} pctb={_sb_t.get('pctb', 0):.3f} size_mult={_sb_mult:.1f}x")
                                # buffers are always updated inside detect_stdev_breakout_t
                            sw_ok, sw_reason = (
                                (True, "MANDATORY_REENTRY_CAPACITY_BYPASS")
                                if _xb_reentry_fired or _ordinary_parity_claim
                                else trade_manager.is_swing_entry_allowed(position_side, float(qty) * current_price)
                            )
                            if not sw_ok:
                                _direct_route_handoff_telemetry(
                                    trade_manager, position_key,
                                    _shared_direct_handoff_claim,
                                    "SWING_BUDGET_BLOCK", reason=sw_reason,
                                )
                                log_rec = "BUDGET"; log_reason = sw_reason
                                logger.info(f"[{account_key}] 💰 SWING BUDGET BLOCKED {symbol}: {sw_reason}")
                            elif market_open:
                                # ═══ 2026-05-17 CATALYST_VOLUME_GATE — DEFAULT OFF behind CATALYST_VOLUME_GATE_ENABLED ═══
                                # Per strategy_plan.md §5.6 + audit_relvol_filters.md §3: O'Neil CAN-SLIM "N" +
                                # Bulkowski failure-avoidance filter. Block new OPENs unless today's D-volume
                                # ≥ CATALYST_VOLUME_RATIO × 50d avg AND price breaks D-Donchian-20 in entry direction.
                                # Augments are exempt (we are inside the action_type == "OPEN" branch at ~2446).
                                # Fail-CLOSED on missing data. Reason on block: BLOCKED_CATALYST_VOLUME_NO_BREAKOUT.
                                _cvg_blocked = False
                                if bool(getattr(config, 'CATALYST_VOLUME_GATE_ENABLED', False)) and not _xb_reentry_fired and not _ordinary_parity_claim:
                                    _cvg_ratio_min = float(getattr(config, 'CATALYST_VOLUME_RATIO', 1.5))
                                    _cvg_vol_today = safe_fetch_float(i.get('volume_D', 0), 0.0)
                                    _cvg_vol_50d_avg = safe_fetch_float(i.get('volume_D_50_sma', 0), 0.0)
                                    _cvg_close_d = safe_fetch_float(i.get('close_D', 0), 0.0)
                                    _cvg_dc_high_d = safe_fetch_float(i.get('dc_high_D', 0), 0.0)
                                    _cvg_dc_low_d = safe_fetch_float(i.get('dc_low_D', 0), 0.0)
                                    _cvg_pass = False
                                    _cvg_detail = ""
                                    if _cvg_vol_50d_avg <= 0 or _cvg_vol_today <= 0:
                                        _cvg_detail = f"NODATA_vol={_cvg_vol_today:.0f}_avg={_cvg_vol_50d_avg:.0f}"
                                    elif _cvg_vol_today < _cvg_ratio_min * _cvg_vol_50d_avg:
                                        _cvg_detail = f"LOW_VOL_ratio={(_cvg_vol_today / _cvg_vol_50d_avg):.2f}x_need={_cvg_ratio_min:.2f}x"
                                    else:
                                        if is_long:
                                            if _cvg_close_d > 0 and _cvg_dc_high_d > 0 and _cvg_close_d >= _cvg_dc_high_d:
                                                _cvg_pass = True
                                            else:
                                                _cvg_detail = f"NO_DC_BREAK_L_close={_cvg_close_d:.2f}_dchigh={_cvg_dc_high_d:.2f}"
                                        else:
                                            if _cvg_close_d > 0 and _cvg_dc_low_d > 0 and _cvg_close_d <= _cvg_dc_low_d:
                                                _cvg_pass = True
                                            else:
                                                _cvg_detail = f"NO_DC_BREAK_S_close={_cvg_close_d:.2f}_dclow={_cvg_dc_low_d:.2f}"
                                    if not _cvg_pass:
                                        _direct_route_handoff_telemetry(
                                            trade_manager, position_key,
                                            _shared_direct_handoff_claim,
                                            "CATALYST_VOLUME_BLOCK",
                                            reason=_cvg_detail,
                                        )
                                        _cvg_blocked = True
                                        log_rec = "BLOCKED"
                                        log_reason = f"BLOCKED_CATALYST_VOLUME_NO_BREAKOUT_{_cvg_detail[:80]}"
                                        logger.info(f"[CATALYST_VOLUME_GATE_BLOCK] {account_key}:{symbol} {'L' if is_long else 'S'}: {_cvg_detail}")
                                # ═══ END CATALYST_VOLUME_GATE ═══
                                if not _cvg_blocked:
                                    _pre_r1_stop = safe_fetch_float(i.get(('dc_low4_5m' if is_long else 'dc_high4_5m') if bool(getattr(config, 'R1_USE_DC_4BAR', True)) else ('dc_low_5m' if is_long else 'dc_high_5m')), 0.0)
                                    if _pre_r1_stop > 0 and position:
                                        _cur_r1_pre = float(getattr(position, 'r1_stop_price', 0.0) or 0.0)
                                        if _cur_r1_pre <= 0 or (is_long and _pre_r1_stop > _cur_r1_pre) or (not is_long and _pre_r1_stop < _cur_r1_pre):
                                            position.r1_stop_price = _pre_r1_stop
                                    # 2026-05-09 USER MANDATE: route reentry-flavored OPENs through guaranteed dispatcher.
                                    # Fresh (non-reentry) opens use the original single-shot dispatch.
                                    if _grde_handoff_claim and os.environ.get("V8_MATRIX_CONTRACT_VERSION", "").startswith("tradier-matrix-exec-c5"):
                                        _c5_gr_trace(
                                            "dispatch",
                                            path="GR_HTF_DIRECT_ENTRY",
                                            account=account_key,
                                            symbol=symbol,
                                            position_side="LONG" if is_long else "SHORT",
                                            requested_qty=qty,
                                            reason=reason,
                                        )
                                    if 'REENTRY' in (reason or '').upper():
                                        await _dispatch_reentry_guaranteed_trd(order_queue, trade_manager, position_key, action_type, reason, conf, override_qty=qty)
                                    else:
                                        _direct_route_handoff_telemetry(
                                            trade_manager, position_key,
                                            _shared_direct_handoff_claim,
                                            "DISPATCH_CALLED", reason=str(reason),
                                            qty=float(qty),
                                        )
                                        _direct_claims = trade_manager.__dict__.setdefault(
                                            "_shared_direct_dispatch_claims", {}
                                        )
                                        _direct_claims[position_key] = _shared_direct_handoff_claim
                                        try:
                                            _direct_dispatch_result = await queue_trade_action(order_queue, trade_manager, position_key, action_type, reason, conf, override_qty=qty)
                                        finally:
                                            _direct_claims.pop(position_key, None)
                                        _direct_route_handoff_telemetry(
                                            trade_manager, position_key,
                                            _shared_direct_handoff_claim,
                                            "DISPATCH_RETURNED",
                                            result=str(_direct_dispatch_result),
                                        )
                                    if not _ordinary_parity_claim:
                                        trade_manager.strategy.circuit_breaker.record_entry(position_key, current_price, reason, indicators=indicators_raw)
                                    action_taken = True
                            elif _shared_direct_handoff_claim is not None:
                                _direct_route_handoff_telemetry(
                                    trade_manager, position_key,
                                    _shared_direct_handoff_claim,
                                    "MARKET_CLOSED",
                                )
            
                else:
                    # Strategy returned NO_ACTION
                    log_rec = "WAIT"
                    log_reason = f"Sc:{int(tech_score)} {strategy_reason}"[:20]
                if _open_claim and not action_taken:
                    logger.critical(f"[ARROW_CLAIM_DROPPED] {account_key}:{symbol}_{position_side}: claimed='{_open_claim[:80]}' final_action={action_type} log_rec={locals().get('log_rec')} log_reason={str(locals().get('log_reason'))[:70]} market_open={locals().get('market_open')}")
                    _arrow_dbg(f"CLAIM_DROPPED {account_key}:{symbol}_{position_side} claimed={_open_claim[:70]} final_action={action_type} log_rec={locals().get('log_rec')} log_reason={str(locals().get('log_reason'))[:70]} market_open={locals().get('market_open')}")

        if action_taken:
             _entry = float(getattr(position, 'entry_price', 0.0) or 0.0) if position else 0.0
             _gain = calculate_gain(position_side, current_price, _entry) if _entry > 0 else 0.0
             _qty = locals().get('aug_qty', None) or locals().get('qty', 0) or 0
             _tdetails = {"qty": _qty, "price": current_price, "value": round(float(_qty) * current_price, 2), "entry_price": _entry, "gain_pct": round(_gain, 2), "position_amt": position.positionAmt if position else 0, "action_type": log_rec, "side": "BUY" if is_long else "SELL"}
             await record_decision_context(trade_manager.redis_manager, account_key, position_key, log_rec, log_reason, i, tech_score, market_context, trade_details=_tdetails)

        # 6. UNIFIED VISUAL LOGGING
        await log_stoch_snapshot(trade_manager, account_key, event_type or "DECISION", position_key, current_price, indicators_raw, tech_score, sentiment_rank, log_rec, log_reason, force=(action_taken or force))
        trade_manager.last_monitored_positions[position_key] = time.time()
        return "PROCESSED"

    except Exception as e:
        import traceback as _tb
        _tb_lines = _tb.format_exc().splitlines()
        if os.environ.get("V8_ARROW_DEBUG"):
            _arrow_dbg(f"MONITOR_EXC {position_key} {type(e).__name__}: {str(e)[:120]} | {(_tb_lines[-3] if len(_tb_lines) >= 3 else '')[:120]}")
        # 2026-05-21 19:30 — widen traceback capture: first try tradier_manage.py frames,
        # fall back to the LAST 'File "...", line N' frame anywhere (utils.py, ez_*, etc.)
        # so cross-module crashes (e.g. float(datetime) in utils) get a location.
        _last_tm = next((l.strip() for l in reversed(_tb_lines) if 'tradier_manage.py' in l), '')
        _last_any = next((l.strip() for l in reversed(_tb_lines) if l.strip().startswith('File "')), '')
        _last = _last_tm or _last_any or '<no_frame>'
        logger.error(f"[{account_key}] 💥 CRASH in process_position for {symbol}: {type(e).__name__}: {e} | at {_last}")
        return "ERROR"


class OrderQueue:
    def __init__(self, trade_manager, max_concurrent_orders=500):
        self.trade_manager = trade_manager
        self.max_concurrent_orders = max_concurrent_orders
        self._orders = asyncio.Queue()
        self.last_executed_time = {}
    
    async def add_order(self, order: dict) -> tuple[bool, str]:
        account_key = order.get('account_key', '')
        current_account.set(account_key)
        position_key = construct_position_key(account_key, order.get('symbol', ''), order.get('position_side', ''))

        now_ts = time.time()
        async with self.trade_manager.dedupe_lock:
            if position_key in self.trade_manager.order_deduplication:
                last_time = float(self.trade_manager.order_deduplication[position_key])
                if (now_ts - last_time) < 90.0:
                    if 'MTF_ARROW' in str(order.get('reason', '')) or 'LR_BAND' in str(order.get('reason', '')):
                        _arrow_dbg(f"ADD_ORDER_DUP {position_key} age={now_ts - last_time:.0f}s")
                    return False, "DUPLICATE"
            self.trade_manager.order_deduplication[position_key] = now_ts
        try:
            await asyncio.wait_for(self._orders.put(order), timeout=2.0)
            return True, "SUCCESS"
        except asyncio.TimeoutError:
            logger.error(f"[add_order] Timeout adding order: {position_key}")
            return False, "TIMEOUT"
        except Exception as e:
            logger.error(f"[add_order] Error: {e}")
            return False, f"EXCEPTION_{str(e)[:50]}"
    
    async def process_orders(self):
        logger.info("[OrderQueue.process_orders]  Task started")
        while True:
            try:
                order = await self._orders.get()
                await self.handle_order(order)
                self._orders.task_done()
            except Exception as e:
                logger.error(f"[process_orders] Error: {e}",  exc_info=True )
                await asyncio.sleep(1)

    async def handle_order(self, order: dict):
        try:
            account_key = order.get('account_key', '')
            current_account.set(account_key)
            symbol = order.get('symbol', '')
            side = order.get('side', '')
            quantity = int(order.get('quantity', 0))
            action = order.get('action', 'OPEN')
            reason = order.get('reason', '')
            price = order.get('current_price', 0)
            order_id = order.get('order_id','None')
            if not is_regular_trading_hours():
                logger.debug(f"[HANDLE_ORDER] Not in trading hours, skipping order: {symbol} {action} {side} qty={quantity}")
                if 'MTF_ARROW' in (reason or '') or 'LR_BAND' in (reason or ''):
                    _arrow_dbg(f"HANDLE_ORDER_RTH_SKIP {symbol} {action}")
                return
            logger.info(f"[ORDER_DEBUG] Processing order: {symbol} {action} {side} qty={quantity}")
            position_key = construct_position_key(account_key, symbol, order.get('position_side', ''))            
            result = await self.trade_manager.execute_trade_action(account_key=account_key,position_key=position_key,symbol=symbol,quantity=quantity,current_price=price,side=side,position_side=order.get('position_side', ''),unique_id=order.get('unique_id', f"{account_key}:{symbol}_{action}_{int(time.time())}"),is_full_close=(action == "CLOSE"),action=action,reason=reason,override_qty=order.get('override_qty')  )
            if 'MTF_ARROW' in (reason or '') or 'LR_BAND' in (reason or ''):
                _arrow_dbg(f"HANDLE_ORDER {symbol} {action} result={result} qty={quantity} price={price}")
            if result == "SUCCESS":
                status = "SUBMITTED"
                order_id = order.get('order_id', 'None')
                logger.info(f"[ORDER_RESULT] {symbol} {action} {side} qty={quantity} -> {status} (ID: {order_id})")
            else:
                status = str(result) if result else "FAILED"
                order_id = "N/A"

            # Calculate gain% and $ for trade log
            _pos = self.trade_manager.position_manager.get_position(position_key) if hasattr(self, 'trade_manager') else None
            _entry = float(getattr(_pos, 'entry_price', 0)) if _pos else 0.0
            _pos_side = order.get('position_side', '')
            _gain_pct = ((price - _entry) / _entry * 100) if _pos_side == 'LONG' and _entry > 0 and price > 0 else ((_entry - price) / _entry * 100) if _pos_side == 'SHORT' and _entry > 0 and price > 0 else 0.0
            _gain_dollar = quantity * price * _gain_pct / 100 if _gain_pct else 0.0
            _pos_val = float(getattr(_pos, 'positionAmt', 0)) * price if _pos and price > 0 else 0.0
            log_msg = (
                f"[TRADE] {symbol:<5} {action:<7} {side:<4} | "
                f"Qty: {quantity:<4} @ ${price:<7.2f} | "
                f"Status: {status:<10} | order_id: {order_id} | "
                f"Reason: {reason} | Gain: {_gain_pct:+.2f}% ${_gain_dollar:+.1f} | Entry: ${_entry:.2f} PosVal: ${_pos_val:.0f} | "
            )

            if "GHOST_CLEARED_COOLDOWN" in status or "REDIS_EXECUTION_LOCK" in status:
                pass
            elif status == "SUBMITTED":
                logger.info(log_msg)
                tradier_action_logger.info(f"{position_key}: {log_msg}")
                self.last_executed_time[(position_key, side)] = time.time()
            else:
                logger.warning(log_msg)
                async with self.trade_manager.dedupe_lock:
                    self.trade_manager.order_deduplication.pop(position_key, None)

        except Exception as e:
            logger.error(f"[handle_order] Critical Error: {e}",  exc_info=True )


async def _dispatch_reentry_guaranteed_trd(order_queue, trade_manager, position_key, action, reason, conviction, override_qty=None, max_attempts=None, backoff_s=None):
    """USER MANDATE 2026-05-09 (mirror of crypto helper): reentry signals must NEVER be silently dropped on transient queue failure.
    Wraps queue_trade_action with N retries + explicit logging for every attempt.
    Returns the final result (same contract as queue_trade_action: 'SUCCESS' or False)."""
    if not bool(getattr(config, 'REENTRY_NEVER_SKIP_ENABLED', True)):
        return await queue_trade_action(order_queue, trade_manager, position_key, action, reason, conviction, override_qty=override_qty)
    if max_attempts is None: max_attempts = int(getattr(config, 'REENTRY_DISPATCH_MAX_ATTEMPTS', 3))
    if backoff_s is None: backoff_s = float(getattr(config, 'REENTRY_DISPATCH_BACKOFF_S', 0.4))
    last_result = None
    _block_substrings = ('BALANCE_FLOOR_HALT', 'OVERTRADE_GUARD', 'DAILY_LOSS_HALT', 'MAX_POS_BLOCK', 'LS_RATIO_BLOCK', 'RED_ZONE_TRADIER', 'UNMAPPED_ACTION_BLOCK', 'ALLOWLIST_BLOCK', 'OPENING_BUFFER_NO_TRADE')
    for attempt in range(1, max_attempts + 1):
        try:
            last_result = await queue_trade_action(order_queue, trade_manager, position_key, action, reason, conviction, override_qty=override_qty)
        except Exception as _re_e:
            logger.error(f"💥 [REENTRY_DISPATCH_CRASH] {position_key} attempt={attempt}/{max_attempts}: {type(_re_e).__name__}: {_re_e}")
            last_result = f"CRASH:{type(_re_e).__name__}"
        if last_result and (last_result is True or (isinstance(last_result, str) and (last_result.startswith("QUEUED") or last_result.startswith("SUCCESS")))):
            if attempt > 1:
                logger.warning(f"✅ [REENTRY_DISPATCH_RETRY_OK] {position_key}: queued on attempt {attempt}/{max_attempts} (reason={reason[:80]})")
            return last_result
        # If the reason is a known HARD-BLOCK (per pre-queue gates) retrying is pointless.
        if any(_b in (reason or '') for _b in _block_substrings):
            logger.warning(f"⚠️ [REENTRY_DISPATCH_HARD_BLOCK] {position_key}: {reason[:120]} — not retrying (hard gate, not transient)")
            return last_result
        logger.warning(f"⚠️ [REENTRY_DISPATCH_TRANSIENT_FAIL] {position_key} attempt={attempt}/{max_attempts}: result={last_result} reason={reason[:80]} — retry in {backoff_s}s")
        if attempt < max_attempts:
            try: await asyncio.sleep(backoff_s)
            except Exception: pass
    logger.critical(f"☠️ [REENTRY_DISPATCH_FAILED_PERSIST] {position_key}: ALL {max_attempts} attempts failed result={last_result} reason={reason[:120]} qty={override_qty} — reentry signal NOT silently dropped, see this log line")
    try:
        if not hasattr(trade_manager, '_reentry_dispatch_failures'):
            trade_manager._reentry_dispatch_failures = {}
        trade_manager._reentry_dispatch_failures[position_key] = {
            'ts': time.time(), 'reason': reason, 'conviction': conviction,
            'override_qty': override_qty, 'last_result': last_result, 'attempts': max_attempts,
        }
    except Exception: pass
    return last_result


async def queue_trade_action(order_queue: OrderQueue, trade_manager, position_key: str, action: str, reason: str, conviction: float = 50.0, override_qty: float = None):
    try:
        _mandatory_reentry_qta = is_mandatory_reclaim_reason(reason)
        _ordinary_parity_qta = is_ordinary_ladder_target_reason(reason)
        account_key, _, _ = parse_position_key(position_key)
        current_account.set(account_key)
        if ('MTF_ARROW' in (reason or '') or 'LR_BAND' in (reason or '')) and 'CLOSE' not in (action or '').upper() and 'REDUCE' not in (action or '').upper():
            logger.warning(f"[ARROW_QTA_RECEIVED] {position_key} {action} reason={(reason or '')[:90]}")
        try:
            _qa_act = (action or '').upper()
            if reason and ('OPEN' in _qa_act or 'AUGMENT' in _qa_act or 'ENTRY' in _qa_act) and 'CLOSE' not in _qa_act and 'REDUCE' not in _qa_act:
                if getattr(trade_manager, '_pending_entry_reason', None) is None:
                    trade_manager._pending_entry_reason = {}
                trade_manager._pending_entry_reason[position_key] = (str(reason)[:120], time.time())
        except Exception:
            pass
        # ═══════════════════════════════════════════════════════════════════════════
        # 🚨 BALANCE_FLOOR_HALT — NEVER GO BELOW $0 (user 2026-05-01)
        # balance_floor_watchdog writes data/HALT_TRADING_<acct> sentinel when
        # account total_cash drops to/below MIN_FLOOR_USD ($1 default). Refuse
        # OPEN/AUGMENT/ENTRY/BUY when sentinel exists. CLOSE/REDUCE still allowed.
        # ═══════════════════════════════════════════════════════════════════════════
        try:
            _bf_act = (action or '').upper()
            if 'OPEN' in _bf_act or 'AUGMENT' in _bf_act or 'ENTRY' in _bf_act or _bf_act == 'BUY':
                from pathlib import Path as _BFPath
                _bf_base = getattr(config, 'BASE_PATH', None) or '/Users/niels/Documents/binance'
                _bf_halt = _BFPath(_bf_base) / 'data' / f'HALT_TRADING_{account_key}'
                if _bf_halt.exists():
                    logger.critical(f"🚨 [BALANCE_FLOOR_HALT] {position_key}: BLOCKED — {_bf_halt} exists. action={action} reason={(reason or '')[:80]}")
                    _direct_queue_gate_note(trade_manager, position_key, reason, "BALANCE_FLOOR_HALT")
                    return False
        except Exception as _bf_e:
            logger.warning(f"[BALANCE_FLOOR_HALT] check error (fail-open): {_bf_e}")
        # ═══════════════════════════════════════════════════════════════════════════
        # 🚦 OVERTRADE_GUARD — USER 2026-05-09: cap OPEN/AUGMENT to TRADES_PER_SYM_PER_DAY_MAX
        # per pkey per UTC day. CLOSE/REDUCE NOT capped. Emergency exits bypass.
        # Mirror of ez_manage equivalent. Module-level _overtrade_counter keyed by
        # 'YYYYMMDD:pkey'. Trim daily.
        # ═══════════════════════════════════════════════════════════════════════════
        try:
            _ot_act = (action or '').upper()
            if ('OPEN' in _ot_act or 'AUGMENT' in _ot_act or 'ENTRY' in _ot_act) and \
               'CLOSE' not in _ot_act and 'REDUCE' not in _ot_act:
                _ot_max = int(getattr(config, 'TRADES_PER_SYM_PER_DAY_MAX', 8))
                _ot_emerg = ('RIDICULOUS' in str(reason or '').upper() or
                             'BREAK_REVERSE' in str(reason or '').upper() or
                             'ALL_TF_AGAINST' in str(reason or '').upper() or
                             'INTERVENTION' in str(reason or '').upper() or
                             'MANUAL' in str(reason or '').upper() or
                             'WT_3M_FORCE_OPEN' in str(reason or '').upper() or
                             'OBLIGATORY' in str(reason or '').upper() or
                             _mandatory_reentry_qta)
                _ot_research_disabled = (
                    os.environ.get("V8_RATE_GUARD_DISABLED") == "1"
                )
                if _ot_max > 0 and not _ot_emerg and not _ot_research_disabled:
                    global _OVERTRADE_COUNTER
                    if '_OVERTRADE_COUNTER' not in globals():
                        _OVERTRADE_COUNTER = {}
                    _ot_today = datetime.now(timezone.utc).strftime('%Y%m%d')
                    _ot_key = f"{_ot_today}:{position_key}"
                    _ot_n = _OVERTRADE_COUNTER.get(_ot_key, 0)
                    if len(_OVERTRADE_COUNTER) > 5000:
                        _OVERTRADE_COUNTER = {k: v for k, v in _OVERTRADE_COUNTER.items() if k.startswith(_ot_today)}
                    if _ot_n >= _ot_max:
                        logger.warning(f"🚦 [OVERTRADE_GUARD] {position_key}: BLOCKED — already {_ot_n} opens today (cap={_ot_max}). action={action} reason={(reason or '')[:80]}")
                        _direct_queue_gate_note(trade_manager, position_key, reason, "OVERTRADE_GUARD")
                        return False
                    # [2026-07-03] counter no longer incremented on ATTEMPT — moved to confirmed
                    # order submission (see [TRADE] SENT site). Blocked attempts kept burning the
                    # whole 8/day allowance with 0 actual opens (shorts died on their own attempts).
        except Exception as _ot_e:
            logger.warning(f"[OVERTRADE_GUARD] check error (fail-open): {_ot_e}")
        # ⏳ CLOSE_REFIRE_GUARD [2026-07-03]: do not resubmit a CLOSE/REDUCE while the previous
        # close order for this key is still working at the broker (TXN logged 241 duplicate
        # "closes" of the same 2 shares — every resubmission was recorded as a trade).
        try:
            _cr_act = (action or '').upper()
            if 'CLOSE' in _cr_act or 'REDUCE' in _cr_act:
                _cr_map = getattr(trade_manager, '_last_close_order', None) or {}
                _cr_rec = _cr_map.get(position_key)
                if _cr_rec and (time.time() - _cr_rec[1]) < 900.0:
                    _cr_acct = position_key.split(':')[0]
                    _cr_status = ''
                    try:
                        _cr_cli = TradierAPIClient(config, account_key=_cr_acct)
                        _cr_res = await _cr_cli.get_order_status(_cr_acct, _cr_rec[0]) or {}
                        _cr_status = str((_cr_res.get('order', _cr_res) or {}).get('status', _cr_res.get('status', ''))).lower()
                    except Exception:
                        _cr_status = ''
                    if _cr_status in ('open', 'pending', 'submitted', 'queued', 'partially_filled', 'calculated', 'accepted_for_bidding'):
                        logger.info(f"⏳ [CLOSE_REFIRE_GUARD] {position_key}: prior close order {_cr_rec[0]} still '{_cr_status}' — not resubmitting. reason={(reason or '')[:60]}")
                        return False
                    trade_manager._last_close_order.pop(position_key, None)
        except Exception as _cr_e:
            logger.warning(f"[CLOSE_REFIRE_GUARD] check error (fail-open): {_cr_e}")
        # ═══════════════════════════════════════════════════════════════════════════
        # 🚫 COUNTER_TREND_ADD_BLOCK (USER 2026-05-30 ABSOLUTE — STOCKS mirror of ez_manage).
        # NO open/augment/reentry whose side is against wt1_1h. Reads LIVE wt1_1h (not gain — a
        # martingaled-to-breakeven loser can't dodge it). Single chokepoint that destroys martingale
        # on the stock side too. CLOSE/REDUCE/HEDGE pass. Fail-open. ROLLBACK: =False.
        # ═══════════════════════════════════════════════════════════════════════════
        try:
            _ctb_act = (action or '').upper()
            _ctb_acct, _ctb_sym, _ctb_side = parse_position_key(position_key)
            _ctb_wf_bypass = (
                'WT_3M_FORCE_OPEN' in str(reason or '').upper()
                and bool(_cfg(
                    'WT_3M_FORCE_OPEN_BYPASS_GATES', True,
                    _ctb_acct, _ctb_sym, _ctb_side,
                ))
            )
            if (
                bool(getattr(config, "COUNTER_TREND_ADD_BLOCK_ENABLED", True))
                and not _ctb_wf_bypass
                and ('OPEN' in _ctb_act or 'AUGMENT' in _ctb_act or 'ENTRY' in _ctb_act or 'REENTER' in _ctb_act or _ctb_act == 'BUY')
                and 'CLOSE' not in _ctb_act and 'REDUCE' not in _ctb_act and 'HEDGE' not in _ctb_act
                and 'HEDGE' not in (reason or '').upper()
            ):
                _ctb_ind = trade_manager.get_indicators(_ctb_sym) if _ctb_sym else {}
                if _ctb_ind:
                    _ctb_is_long = _ctb_side == "LONG"
                    _ctb_w1 = safe_fetch_float(_ctb_ind.get("wt1_1h", 0), 0.0)
                    _ctb_w2 = safe_fetch_float(_ctb_ind.get("wt2_1h", 0), 0.0)
                    # 2026-06-04 USER directional rule (STOCKS mirror of ez_manage): a SHORT below sma_200_15m (LONG above) WITH
                    # 1h structure confirming (1h lower-low / higher-high, OR wt1_1h already agreeing) is TREND-ALIGNED, not
                    # counter-trend — the laggy wt1_1h must NOT block it. Genuine counter-trend (wrong side of sma_200_15m) stays
                    # blocked. ROLLBACK: COUNTER_TREND_SMA200_BYPASS_ENABLED=False.
                    _ctb_aligned = False
                    if bool(getattr(config, "COUNTER_TREND_SMA200_BYPASS_ENABLED", True)):
                        _ctb_sma200 = safe_fetch_float(_ctb_ind.get("sma_200_15m", 0), 0.0)
                        _ctb_px = safe_fetch_float(_ctb_ind.get("price", _ctb_ind.get("current_price", _ctb_ind.get("mark_price", 0))), 0.0)
                        if _ctb_sma200 > 0 and _ctb_px > 0:
                            if _ctb_is_long:
                                _ctb_hh_n = safe_fetch_float(_ctb_ind.get("high_1h", 0), 0.0)
                                _ctb_hh_p = safe_fetch_float(_ctb_ind.get("high_1h_prev", 0), 0.0)
                                _ctb_struct = (_ctb_hh_n > 0 and _ctb_hh_p > 0 and _ctb_hh_n > _ctb_hh_p) or (_ctb_w1 > _ctb_w2)
                                _ctb_aligned = (_ctb_px > _ctb_sma200) and _ctb_struct
                            else:
                                _ctb_ll_n = safe_fetch_float(_ctb_ind.get("low_1h", 0), 0.0)
                                _ctb_ll_p = safe_fetch_float(_ctb_ind.get("low_1h_prev", 0), 0.0)
                                _ctb_struct = (_ctb_ll_n > 0 and _ctb_ll_p > 0 and _ctb_ll_n < _ctb_ll_p) or (_ctb_w1 < _ctb_w2)
                                _ctb_aligned = (_ctb_px < _ctb_sma200) and _ctb_struct
                    if not _mandatory_reentry_qta and not _ordinary_parity_qta and (abs(_ctb_w1) > 1e-9 or abs(_ctb_w2) > 1e-9) and not _ctb_aligned and ((_ctb_is_long and _ctb_w1 < _ctb_w2) or ((not _ctb_is_long) and _ctb_w1 > _ctb_w2)):
                        logger.critical(f"🚫 [COUNTER_TREND_ADD_BLOCK] {position_key}: BLOCKED {action} — side against wt1_1h ({_ctb_w1:.1f}vs{_ctb_w2:.1f}). NO open/add against the 1h. reason={(reason or '')[:50]}")
                        _direct_queue_gate_note(trade_manager, position_key, reason, "COUNTER_TREND_ADD_BLOCK")
                        return False
        except Exception as _ctbe:
            logger.warning(f"[COUNTER_TREND_ADD_BLOCK] check error (fail-open): {_ctbe}")
        if not is_regular_trading_hours():
            logger.debug(f"[queue_trade_action] not in trading hours")
            return
        # ═══ TRADIER_PHYSICS_OPPOSITE_SIDE_BLOCK (2026-05-11) ═══
        # Tradier cannot hold LONG + SHORT on same equity in same account simultaneously.
        # Refuse OPEN/AUGMENT/ENTRY/REENTRY at queue time when opposite side has amt > 0.
        # This is at the EARLIEST gate so the order never even hits the queue.
        try:
            _ts_act = (action or '').upper()
            if ('OPEN' in _ts_act or 'AUGMENT' in _ts_act or 'ENTRY' in _ts_act or 'REENTER' in _ts_act or _ts_act == 'BUY'):
                _ts_acct, _ts_sym, _ts_side = parse_position_key(position_key)
                if _ts_acct in {'trb', 'trc', 'tra'} and _ts_side in {'LONG', 'SHORT'}:
                    _ts_opp_side = 'SHORT' if _ts_side == 'LONG' else 'LONG'
                    _ts_opp_pk = f"{_ts_acct}:{_ts_sym}_{_ts_opp_side}"
                    _ts_opp_pos = trade_manager.position_manager.get_position(_ts_opp_pk) if hasattr(trade_manager, 'position_manager') and trade_manager.position_manager else None
                    _ts_opp_amt = abs(float(getattr(_ts_opp_pos, 'positionAmt', 0) or 0)) if _ts_opp_pos else 0.0
                    if _ts_opp_amt > 0.0001:
                        logger.critical(f"🛑 [QUEUE_OPPOSITE_SIDE_BLOCK] {position_key}: opposite-side {_ts_opp_pk} has amt={_ts_opp_amt} — Tradier physics prohibit dual-side, REFUSING queue. action={action} reason={(reason or '')[:80]}")
                        _direct_queue_gate_note(trade_manager, position_key, reason, "QUEUE_OPPOSITE_SIDE_BLOCK")
                        return False
        except Exception as _ts_e:
            logger.warning(f"[QUEUE_OPPOSITE_SIDE_BLOCK] check error (fail-open): {_ts_e}")
        # 2026-04-27 user rule: stop "headless-chicken" duplicate fires. Same
        # (position_key, action) within cooldown → refused. Catches MSTR REBALANCE
        # loop and any other path that re-fires after a rejected/invalid order.
        if not hasattr(trade_manager, '_queue_attempt_ts'):
            trade_manager._queue_attempt_ts = {}
        _qa_key = f"{position_key}|{action}"
        _qa_now = time.time()
        _qa_cooldown = float(getattr(config, 'TRADIER_QUEUE_DEDUPE_SEC', 60.0))
        _qa_last = trade_manager._queue_attempt_ts.get(_qa_key, 0.0)
        if _qa_now - _qa_last < _qa_cooldown and not _mandatory_reentry_qta:
            logger.warning(f"[QUEUE_DEDUPE] {position_key} {action}: queued {_qa_now - _qa_last:.0f}s ago < {_qa_cooldown:.0f}s — refusing duplicate. Reason='{reason[:80]}'")
            _direct_queue_gate_note(trade_manager, position_key, reason, "QUEUE_DEDUPE")
            return False
        trade_manager._queue_attempt_ts[_qa_key] = _qa_now
        if position_key.count(":") != 1:
            logger.error(f"[queue_trade_action] !! CORRUPTED position_key with {position_key.count(':')} colons: {position_key}")
            from utils import clean_position_key, orjson_default
            position_key = clean_position_key(position_key)
            if position_key.count(":") != 1:
                return False
        position = trade_manager.position_manager.get_position(position_key)
        if position is not None:
            positionAmt = position.positionAmt
            try: positionAmt = abs(float(positionAmt))
            except Exception: positionAmt = 0.0
            if action in ["CLOSE", "REDUCE", "AUGMENT"] and positionAmt <= 0:
                logger.warning(f"[queue_trade_action] !! Blocked {action}: {position_key} has no position in Redis (positionAmt={positionAmt})")
                _direct_queue_gate_note(trade_manager, position_key, reason, "NO_POSITION_FOR_ACTION")
                return False
            # 2026-04-27 USER ABSOLUTE: NO MULTIPLE OPENS. EVER.
            # If position already exists for this key (positionAmt > 0), block any new open of any kind.
            # OPEN/REENTER/REENTRY/HEDGE all forbidden while same-key position is alive.
            # AUGMENT is the ONLY legitimate add path — and it has its own MIN_GAIN gates upstream.
            # 2026-05-20 RECOVERY_AUG bypass: reason contains "RECOVERY_AUG" → narrow exception
            # for partial-close trap recovery (price crossed back through last_reduction_price
            # within band+age). The evaluate_reentry caller already validated band/age/direction.
            _is_recovery_aug_qta = "RECOVERY_AUG" in (reason or "").upper()
            if action in ("OPEN", "REENTER", "REENTRY", "REENTRY_OPEN", "HEDGE") and positionAmt > 0 and not _is_recovery_aug_qta:
                logger.critical(f"[NO_DOUBLE_OPEN_BLOCK] {position_key}: BLOCKED {action} — positionAmt={positionAmt:.4f} > 0. Only AUGMENT allowed (under MIN_GAIN rules). Reason='{reason[:80]}'")
                _direct_queue_gate_note(trade_manager, position_key, reason, "NO_DOUBLE_OPEN_BLOCK")
                return False
            if _is_recovery_aug_qta and positionAmt > 0:
                logger.warning(f"[NO_DOUBLE_OPEN_BLOCK_BYPASS_RECOVERY_AUG] {position_key}: {action} positionAmt={positionAmt:.4f} reason='{reason[:80]}' — bypass allowed (partial-close recovery)")
            # 2026-04-29 USER RULE: post-close cooldown. After a CLOSE, block re-OPEN of same symbol
            # for TRADIER_POST_CLOSE_COOLDOWN_MIN minutes. Stops the 1-share open→close→reopen flap
            # observed today on NVDA/USO/MSFT/GOOGL (LONG BUY firing every ~30s).
            if action in ("OPEN", "REENTER", "REENTRY", "REENTRY_OPEN", "HEDGE") and not _mandatory_reentry_qta and not _ordinary_parity_qta:
                _pc_cooldown_min = float(getattr(config, 'TRADIER_POST_CLOSE_COOLDOWN_MIN', 15.0))
                if _pc_cooldown_min > 0:
                    _pc_last_red = getattr(position, 'last_reduction_time', None)
                    if _pc_last_red is not None:
                        try:
                            _pc_dt = safe_datetime(_pc_last_red) if not isinstance(_pc_last_red, datetime) else _pc_last_red
                            _pc_age_min = (datetime.now(timezone.utc) - _pc_dt).total_seconds() / 60.0
                            if _pc_age_min < _pc_cooldown_min:
                                logger.warning(f"[POST_CLOSE_COOLDOWN] {position_key}: BLOCKED {action} — last close {_pc_age_min:.1f}m ago < {_pc_cooldown_min:.0f}m cooldown. Reason='{reason[:80]}'")
                                _direct_queue_gate_note(trade_manager, position_key, reason, "POST_CLOSE_COOLDOWN")
                                return False
                        except Exception as _pc_e:
                            logger.debug(f"[POST_CLOSE_COOLDOWN_ERR] {position_key}: {_pc_e}")
        parts = position_key.split(':')
        if len(parts) != 2:
            return False
        account_key,symbol,position_side=parse_position_key(position_key)
        current_price = 0.0
        if position:
            current_price = getattr(position, 'current_price', 0) or getattr(position, 'mark_price', 0) or 0
        current_price = float(current_price) if current_price is not None else 0.0
        if current_price <= 0:
            _gcp = await trade_manager.get_current_price(symbol)
            if _gcp is None:
                current_price = 0.0
            elif isinstance(_gcp, tuple):
                current_price = float(_gcp[0]) if _gcp and _gcp[0] is not None else 0.0
            else:
                current_price = float(_gcp) if _gcp is not None else 0.0
        if current_price <= 0:
            logger.warning(f"[queue_trade_action] No price for {symbol}")
            _direct_queue_gate_note(trade_manager, position_key, reason, "NO_PRICE")
            return False
        
        if action in ("OPEN", "AUGMENT", "REENTER", "REENTRY"):
            # TRADIER OPPOSING POSITION BLOCK — Tradier cannot hold long+short simultaneously
            if trade_manager.position_manager:
                _opp_side = "SHORT" if position_side == "LONG" else "LONG"
                _opp_key = construct_position_key(account_key, symbol, _opp_side)
                _opp_pos = trade_manager.position_manager.get_position(_opp_key)
                if _opp_pos and abs(float(getattr(_opp_pos, 'positionAmt', 0))) > 0:
                    logger.critical(f"[OPPOSING_BLOCK] {position_key}: BLOCKED {action} — cannot open {position_side} while {_opp_side} position held (Tradier no-hedge). Close {_opp_side} first.")
                    _direct_queue_gate_note(trade_manager, position_key, reason, "OPPOSING_BLOCK")
                    return False
            # === 2026-04-27 RED_ZONE_GATE_TRADIER (options-OI walls as L2 proxy) ===
            # Tradier exposes no L2 depth. Use options-chain max-OI strikes from data/stocks_oi_cache/{sym}.json
            # (populated by tradier_options_oi_fetcher.py READ-ONLY) as proxy walls:
            #   max_call_oi_strike = options-implied resistance ceiling (dealer hedging crushes momentum here)
            #   max_put_oi_strike  = options-implied support floor (dealer absorption / max-pain pin)
            # Block LONG when underlying is within RED_ZONE_TRADIER_MIN_DISTANCE_PCT below max_call_oi_strike.
            # Block SHORT when underlying is within RED_ZONE_TRADIER_MIN_DISTANCE_PCT above max_put_oi_strike.
            if bool(getattr(config, 'RED_ZONE_TRADIER_GATE_ENABLED', False)) and not _mandatory_reentry_qta and not _ordinary_parity_qta:
                _rzt_apply = True
                if action == "AUGMENT" and not bool(getattr(config, 'RED_ZONE_TRADIER_AUGMENT_GATE_ENABLED', True)):
                    _rzt_apply = False
                if _rzt_apply:
                    try:
                        _rzt_min_dist = float(getattr(config, 'RED_ZONE_TRADIER_MIN_DISTANCE_PCT', 0.5))
                        _rzt_min_oi = int(getattr(config, 'RED_ZONE_TRADIER_MIN_OI_AT_WALL', 1000))
                        _rzt_stale_h = float(getattr(config, 'RED_ZONE_TRADIER_STALE_MAX_HOURS', 4.0))
                        _rzt_cache_p = Path(config.BASE_PATH) / "data" / "stocks_oi_cache" / f"{symbol}.json"
                        if _rzt_cache_p.exists():
                            with open(_rzt_cache_p) as _rzt_fh: _rzt_doi = json.load(_rzt_fh)
                            _rzt_age_h = (time.time() - (_rzt_doi.get("ts") or 0)) / 3600.0
                            if _rzt_age_h <= _rzt_stale_h:
                                # 2026-04-28 DEEP HEATMAP: check ALL top-N walls within ±50%, not just max.
                                # User: "same utility as oi but over the next 50% up or down".
                                # Falls back to single max strike if top_*_walls fields not yet populated (older cache).
                                _check_long = (position_side == "LONG")
                                _walls = _rzt_doi.get("top_call_walls" if _check_long else "top_put_walls") or []
                                if not _walls:
                                    # backward-compat: synthesize single-wall list from max fields
                                    _ms = _rzt_doi.get("max_call_oi_strike" if _check_long else "max_put_oi_strike")
                                    _mv = _rzt_doi.get("max_call_oi_value" if _check_long else "max_put_oi_value") or 0
                                    if _ms:
                                        _dp = ((_ms - current_price) if _check_long else (current_price - _ms)) / current_price * 100.0
                                        _walls = [{"strike": _ms, "oi": _mv, "dist_pct": _dp}]
                                # Iterate ALL walls; block on FIRST that's too close + size sufficient + correct side
                                _blocked = False
                                for _w in _walls:
                                    try:
                                        _ws = float(_w.get("strike") or 0); _woi = int(_w.get("oi") or 0)
                                        if _ws <= 0 or _woi < _rzt_min_oi:
                                            continue
                                        # LONG: only walls ABOVE price are resistance ceilings; SHORT: only walls BELOW price are support floors
                                        if _check_long and _ws <= current_price: continue
                                        if (not _check_long) and _ws >= current_price: continue
                                        _dist = abs(_ws - current_price) / current_price * 100.0
                                        if _dist < _rzt_min_dist:
                                            _label = "call-OI ceiling" if _check_long else "put-OI floor"
                                            _side = "LONG" if _check_long else "SHORT"
                                            logger.warning(f"🧱 [RED_ZONE_TRADIER] {position_key}: BLOCKED {_side} {action} — {_label} ${_ws:.2f} {_dist:.2f}% away (OI={_woi} ≥ {_rzt_min_oi}, threshold {_rzt_min_dist}%, deep-heatmap top-N). reason={reason[:60]}")
                                            _blocked = True
                                            break
                                    except Exception:
                                        continue
                                if _blocked:
                                    return False
                    except Exception as _rzt_exc:
                        logger.debug(f"[RED_ZONE_TRADIER] {position_key}: exception {type(_rzt_exc).__name__} {_rzt_exc} — skipped (no block)")
        if action == "OPEN":
            # BACKTEST_CHANGE_T37: daily loss circuit breaker
            if _daily_loss_tracker.get("halted", False):
                logger.warning(f"[DAILY_LOSS_HALT] Blocking OPEN {position_key}: daily loss limit breached")
                return False
            # BACKTEST_CHANGE_T35: max concurrent positions
            _max_conc = getattr(config, 'MAX_CONCURRENT_POSITIONS', 999)
            if _max_conc < 999 and trade_manager.position_manager:
                _oc = sum(1 for _pk, _p in trade_manager.position_manager.positions.items() if abs(float(getattr(_p, 'positionAmt', 0))) > 0)
                if _oc >= _max_conc:
                    logger.warning(f"[MAX_POS_BLOCK] Blocking OPEN {position_key}: {_oc} >= {_max_conc} max concurrent")
                    return False
            # L/S ratio enforcement — BY DOLLAR VALUE (not count)
            # 2026-04-09 FIX: count ratio was blind to size (6L tiny vs 2S huge = count 3.0 but value 0.3)
            _wf_bypass_order = bool(_cfg(
                'WT_3M_FORCE_OPEN_BYPASS_GATES', True, account_key, symbol,
                position_side,
            ))
            if getattr(config, 'LS_RATIO_ENFORCE_TRADIER', False) and trade_manager.position_manager and not _mandatory_reentry_qta and not _ordinary_parity_qta and not (('WT_3M_FORCE_OPEN' in (reason or '').upper()) and _wf_bypass_order):
                _lv2 = 0.0; _sv2 = 0.0
                for _pk, _p in trade_manager.position_manager.positions.items():
                    _amt = abs(float(getattr(_p, 'positionAmt', 0) or getattr(_p, 'quantity', 0)))
                    if _amt <= 0: continue
                    _px = float(getattr(_p, 'mark_price', 0) or getattr(_p, 'entry_price', 0))
                    if _px <= 0: continue
                    _val = _amt * _px
                    if _pk.endswith("_LONG"): _lv2 += _val
                    elif _pk.endswith("_SHORT"): _sv2 += _val
                _adj2 = _ls_ratio_4h_adj_tradier.get("adj", 0.0)
                _ls_min2 = max(0.30, getattr(config, 'LS_RATIO_MIN_TRADIER', 0.50) + _adj2)
                _ls_max2 = min(3.00, getattr(config, 'LS_RATIO_MAX_TRADIER', 2.00) + _adj2)
                _ratio2 = _lv2 / max(_sv2, 1.0)
                if position_side == "LONG" and _ratio2 > _ls_max2:
                    logger.warning(f"[LS_RATIO_BLOCK] {position_key}: L/S VALUE ratio ${_lv2:.0f}/${_sv2:.0f}={_ratio2:.2f} > max {_ls_max2:.2f}, blocking LONG open")
                    return False
                if position_side == "SHORT" and _ratio2 < _ls_min2:
                    logger.warning(f"[LS_RATIO_BLOCK] {position_key}: L/S VALUE ratio ${_lv2:.0f}/${_sv2:.0f}={_ratio2:.2f} < min {_ls_min2:.2f}, blocking SHORT open")
                    return False
            side = "BUY" if position_side == "LONG" else "SELL"
        elif action in ["CLOSE", "REDUCE", "SELL"]:
            side = "SELL" if position_side == "LONG" else "BUY"
        elif action in ["AUGMENT", "REENTER", "REENTRY"]:
            side = "BUY" if position_side == "LONG" else "SELL"
        else:
            logger.critical(f"[UNMAPPED_ACTION_BLOCK] {position_key}: action='{action}' not in any known action list — BLOCKING to prevent wrong-direction order")
            return False

        # logger.info(f"[queue_trade_action] 📋 ORDER LOGIC: action={action} position_side={position_side} -> side={side} symbol={symbol}")
        
        is_recent_reentry = False
        final_override_qty = None
        if action in ("REENTER", "REENTRY"):
            exit_time = None
            if position:
                exit_time = getattr(position, 'last_reduction_time', None)
            if not exit_time:
                last_exit_time = _reentry_exit_value(
                    getattr(trade_manager, 'last_exit_times', {}),
                    position_key,
                    symbol,
                    0,
                )
                if last_exit_time > 0:
                    exit_time = datetime.fromtimestamp(last_exit_time, tz=timezone.utc)
            if exit_time and isinstance(exit_time, str):
                exit_time = safe_datetime(exit_time)
            if exit_time and isinstance(exit_time, datetime):
                hours_since_exit = (datetime.now(timezone.utc) - exit_time).total_seconds() / 3600.0
                if hours_since_exit < 2.0:
                    is_recent_reentry = True
                    last_reduction_amount = getattr(position, 'last_reduction_amount', None) if position else None
                    if last_reduction_amount and float(last_reduction_amount) > 0:
                        final_override_qty = float(last_reduction_amount)
                        logger.info(f"[queue_trade_action] Recent reentry (<2h): Using position.last_reduction_amount={final_override_qty} as override_qty")
        if action == "OPEN":
            quantity = override_qty if override_qty else await trade_manager.calculate_position_size(symbol, current_price, account_key=account_key)
        elif action in ["REDUCE", "CLOSE"]:
            if position:
                # 2026-04-29 FIX: was `getattr(position, 'quantity', 0)` — TradierPosition has NO 'quantity'
                # attribute (only positionAmt). This silently returned 0, then quantity = 0 * 0.5 = 0
                # → either no order, or order qty came from override_qty. Now reads positionAmt correctly.
                position_qty = abs(getattr(position, 'positionAmt', 0) or 0)
                quantity = override_qty if override_qty else (position_qty * 0.5)
                # 2026-04-29 USER ABSOLUTE: NEVER queue a SELL/CLOSE for more shares than we own.
                # Today user saw "Sell 81" pending order when positionAmt=38 → 43 phantom shares.
                # If override_qty exceeds actual position by >1 share, ABORT (not silent clamp).
                # 2026-05-27 FIX: ignore the 999999 "close-all" sentinel so emergency stops can exit.
                if override_qty and override_qty != 999999 and position_qty > 0 and float(override_qty) > position_qty + 1:
                    logger.critical(f"🚫 [QTY_OVERSHOOT_ABORT] {position_key}: override_qty={override_qty} > positionAmt={position_qty}+1 — REFUSING to place {action}. Real bug — find the source. Reason='{reason[:80]}'")
                    return False
                if quantity > 0 and position_qty > 0 and quantity > position_qty + 1:
                    logger.warning(f"⚠️ [QTY_CLAMP_TO_POS] {position_key}: clamping {action} qty {quantity} → {position_qty} (own={position_qty})")
                    quantity = position_qty
            else:
                return False
        elif action in ["AUGMENT", "REENTER", "REENTRY"]:
            if position:
                position_qty = abs(getattr(position, 'positionAmt', 0))
                quantity = override_qty if override_qty else await trade_manager.calculate_position_size(symbol, current_price, account_key=account_key)
            else:
                quantity = override_qty if override_qty else await trade_manager.calculate_position_size(symbol, current_price, account_key=account_key)
        else:
            return False
        if quantity <= 0:
            return False
        _ladder_parity_order = _ordinary_parity_qta
        _absolute_target_order = (
            _ladder_parity_order or _mandatory_reentry_qta
        )
        # ═══════════════════════════════════════════════════════════════════════════
        # 📈 BREAKOUT_SIZE_LADDER — STOCKS (USER 2026-05-30): HIGHER open/reentry/augment qty when price is
        # strongly extended past ema_200_15m (stocks have no sma_200_15m → ema_200_15m anchor). Tiered
        # ×1.5/×2/×3 (cap MAX_MULT) by |price-ema_200_15m|/ema_200_15m (LONG above / SHORT below). Entry
        # actions only; downstream buying-power/QTY checks still apply. Add-to-strength (COUNTER_TREND_ADD_BLOCK
        # ran at queue top). Fail-open. ROLLBACK: BREAKOUT_SIZE_LADDER_ENABLED=False.
        # ═══════════════════════════════════════════════════════════════════════════
        try:
            if ((not _absolute_target_order)
                    and bool(getattr(config, "BREAKOUT_SIZE_LADDER_ENABLED", True))
                    and action in ("OPEN", "AUGMENT", "REENTER", "REENTRY")
                    and quantity and quantity > 0):
                _bsli = trade_manager.get_indicators(symbol) if symbol else {}
                _bsl_is_long = position_side == "LONG"
                _bsl_px = float(current_price) if current_price else 0.0
                _bsl_ema = safe_fetch_float(_bsli.get("ema_200_15m"), 0.0) if _bsli else 0.0
                if _bsl_px > 0 and _bsl_ema > 0:
                    _bsl_dist = ((_bsl_px - _bsl_ema) / _bsl_ema * 100.0) if _bsl_is_long else ((_bsl_ema - _bsl_px) / _bsl_ema * 100.0)
                    _bsl_mult = 1.0
                    if _bsl_dist >= float(getattr(config, "BREAKOUT_SIZE_EMA200_T3_PCT", 2.5)):
                        _bsl_mult = float(getattr(config, "BREAKOUT_SIZE_EMA200_T3_MULT", 3.0))
                    elif _bsl_dist >= float(getattr(config, "BREAKOUT_SIZE_EMA200_T2_PCT", 1.5)):
                        _bsl_mult = float(getattr(config, "BREAKOUT_SIZE_EMA200_T2_MULT", 2.0))
                    elif _bsl_dist >= float(getattr(config, "BREAKOUT_SIZE_EMA200_T1_PCT", 1.0)):
                        _bsl_mult = float(getattr(config, "BREAKOUT_SIZE_EMA200_T1_MULT", 1.5))
                    if _bsl_mult > 1.0:
                        _bsl_mult = min(_bsl_mult, float(_cfg("BREAKOUT_SIZE_MAX_MULT", 3.0, account_key, symbol, position_side)))
                        _bsl_orig = quantity
                        quantity = quantity * _bsl_mult
                        logger.warning(f"[BREAKOUT_SIZE_LADDER] {position_key} side={position_side}: dist={_bsl_dist:.2f}% past ema_200_15m → qty {_bsl_orig:.4f}→{quantity:.4f} (×{_bsl_mult}). reason={(reason or '')[:40]}")
        except Exception as _bsle:
            logger.warning(f"[BREAKOUT_SIZE_LADDER] {position_key}: check error (fail-open): {_bsle}")
        try:
            if ((not _absolute_target_order)
                    and bool(getattr(config, "D_STRUCT_ENTRY_MULT_ENABLED", True))
                    and action in ("OPEN", "AUGMENT", "REENTER", "REENTRY")
                    and quantity and quantity > 0):
                _dsm_is_long = position_side == "LONG"
                _dsm_i = trade_manager.get_indicators(symbol) if symbol else {}
                _dsm_high = safe_fetch_float(_dsm_i.get("high_D"), 0.0)
                _dsm_low = safe_fetch_float(_dsm_i.get("low_D"), 0.0)
                _dsm_highp = safe_fetch_float(_dsm_i.get("high_D_prev"), 0.0)
                _dsm_lowp = safe_fetch_float(_dsm_i.get("low_D_prev"), 0.0)
                _dsm_sma200 = safe_fetch_float(_dsm_i.get("sma_200_D"), 0.0)
                _dsm_wt1_D = safe_fetch_float(_dsm_i.get("wt1_D"), 0.0)
                if _dsm_high > 0 and _dsm_highp > 0 and _dsm_low > 0 and _dsm_lowp > 0:
                    _dsm_wt1_min = float(getattr(config, "D_STRUCT_ENTRY_WT1_MIN", -40.0))
                    _dsm_wt1_max = float(getattr(config, "D_STRUCT_ENTRY_WT1_MAX", 40.0))
                    if _dsm_is_long:
                        _dsm_ok = (_dsm_high > _dsm_highp and _dsm_low > _dsm_lowp
                                   and (float(current_price) > _dsm_sma200 if _dsm_sma200 > 0 else True)
                                   and (_dsm_wt1_D > _dsm_wt1_min if _dsm_wt1_D != 0 else True))
                    else:
                        _dsm_ok = (_dsm_high < _dsm_highp and _dsm_low < _dsm_lowp
                                   and (float(current_price) < _dsm_sma200 if _dsm_sma200 > 0 else True)
                                   and (_dsm_wt1_D < _dsm_wt1_max if _dsm_wt1_D != 0 else True))
                    if _dsm_ok:
                        _dsm_mult = float(getattr(config, "D_STRUCT_ENTRY_MULT", 1.3))
                        _dsm_orig = quantity
                        quantity = quantity * _dsm_mult
                        logger.warning(f"[D_STRUCT_ENTRY_MULT] {position_key} side={position_side}: D {'HH+HL' if _dsm_is_long else 'LL+LH'} + SMA200 + WT → qty {_dsm_orig:.4f}→{quantity:.4f} (×{_dsm_mult:.2f}). reason={(reason or '')[:40]}")
        except Exception as _dsme:
            logger.warning(f"[D_STRUCT_ENTRY_MULT] {position_key}: check error (fail-open): {_dsme}")
        if (not _absolute_target_order) and config.SYMBOL_PERF_ENABLED and action in ('OPEN', 'AUGMENT', 'REENTRY', 'QUICK_OPEN', 'QUICK_AUGMENT'):
            try:
                from utils import get_performance_multiplier
                _perf_mult = get_performance_multiplier(symbol, default=1.0)
                quantity = max(1, int(quantity * (0.7 + _perf_mult * 0.3)))
            except Exception:
                pass
        # USER 2026-06-03 NO-EXCEPTIONS: WT_3M_FORCE_OPEN (with-trend, above-200MA, WT-favor build)
        # must NOT be clamped to the small MAX_ORDER_VALUE — that's the "$100 dribble" cap. It is
        # bounded instead by DG_MAX_FORCE_OPEN_NOTIONAL_USD (per fire) + WT_3M_FORCE_OPEN_TARGET_USD.
        _wf_force = ("WT_3M_FORCE_OPEN" in (reason or "").upper()) and bool(_cfg(
            "WT_3M_FORCE_OPEN_BYPASS_GATES", True, account_key, symbol, position_side,
        ))
        max_order_value = (
            float(
                _cfg(
                    "LR_BAND_LADDER_CAPACITY_USD",
                    16000.0,
                    account_key,
                    symbol,
                    position_side,
                )
            )
            if _absolute_target_order
            else (
                float(getattr(config, "DG_MAX_FORCE_OPEN_NOTIONAL_USD", 4000.0))
                if _wf_force
                else config.MAX_ORDER_VALUE
            )
        )
        order_value = quantity * current_price
        if order_value > max_order_value:
            quantity = int(max_order_value / current_price)
            if config.VERBOSE: logger.debug(f"[queue_trade_action] {symbol} quantity adjusted to {quantity} to respect max_order_value={max_order_value}")
        if quantity <= 0:
            return False
        
        final_reason = reason
        if not is_recent_reentry and override_qty and override_qty > 0:
            if "_qty_" not in reason:
                final_reason = f"{reason}_qty_{override_qty}"
        order = {
            'account_key': account_key,
            'symbol': symbol,
            'position_side': position_side,
            'side': side,
            'quantity': quantity,
            'action': action, 
            'reason': final_reason,
            'current_price': current_price,
            'priority': conviction,
            'order_id': f"{position_key}_{action}_{int(time.time())}",
            'override_qty': override_qty   }
        success, msg = await order_queue.add_order(order)
        logger.info(f"[queue_trade_action] Queued {symbol} {action}: success={success}, msg={msg}")
        if 'MTF_ARROW' in (reason or '') or 'LR_BAND' in (reason or ''):
            _arrow_dbg(f"QTA_QUEUED {position_key} {action} success={success} msg={msg}")
        if not success:
            return f"QUEUE_ADD_REFUSED:{msg}"
        return "SUCCESS"
    except Exception as e:
        logger.error(f"[queue_trade_action] Error: {e}",  exc_info=True )
        if 'MTF_ARROW' in str(reason or '') or 'LR_BAND' in str(reason or ''):
            _arrow_dbg(
                f"QTA_EXCEPTION {position_key} {action} "
                f"{type(e).__name__}:{str(e)[:160]}"
            )
        return f"QTA_EXCEPTION:{type(e).__name__}:{str(e)[:120]}"

_qta_undecorated = queue_trade_action
async def _qta_arrow_traced(order_queue, trade_manager, position_key, action, reason, conviction=50.0, override_qty=None):
    res = await _qta_undecorated(order_queue, trade_manager, position_key, action, reason, conviction, override_qty=override_qty)
    if res != "SUCCESS" and ('MTF_ARROW' in (reason or '') or 'LR_BAND' in (reason or '')):
        _arrow_dbg(f"QTA_REFUSED {position_key} {action} result={res} reason={(reason or '')[:80]}")
    return res
if os.environ.get("V8_ARROW_DEBUG"):
    queue_trade_action = _qta_arrow_traced

async def process_symbols_periodically(order_queue: OrderQueue, trade_manager, account_key: str):
    current_account.set(account_key)
    logger.info(f"🚀 [TASK] Trading loop started for {account_key}")
    OPEN_INTERVAL = 30      # open positions re-evaluated every 30s
    CANDIDATE_INTERVAL = 90  # non-open candidates every 90s
    last_candidate_scan = 0.0

    while trade_manager.running:
        try:
            current_account.set(account_key)
            now = time.time()
            await trade_manager.reload_account_symbols()
            longs = getattr(trade_manager, f"symbols_long_{account_key}", [])
            shorts = getattr(trade_manager, f"symbols_short_{account_key}", [])

            # Open positions — always included every 30s
            open_keys = [
                pk for pk, pos in trade_manager.position_manager.positions.items()
                if pk.startswith(f"{account_key}:") and abs(getattr(pos, 'positionAmt', getattr(pos, 'quantity', 0))) > 0
            ]

            # Candidate keys (non-open) — every 90s only
            # tra is a CASH (non-margin) account → never queue SHORT candidates.
            # Without this guard the scan loop spent every cycle generating SHORT
            # entry signals on tra that the Tradier API would reject as
            # "shorting requires margin", churning state and decision logs.
            _tra_long_only = (account_key == 'tra' and getattr(config, 'TRA_LONG_ONLY', True))
            candidate_keys = []
            if now - last_candidate_scan >= CANDIDATE_INTERVAL:
                _short_keys = [] if _tra_long_only else [f"{account_key}:{s}_SHORT" for s in shorts]
                all_candidates = (
                    [f"{account_key}:{s}_LONG" for s in longs] +
                    _short_keys
                )
                candidate_keys = [k for k in all_candidates if k not in open_keys]
                last_candidate_scan = now
                _short_label = "(SUPPRESSED:cash_account)" if _tra_long_only else f"{len(shorts)}S"
                print(f"[SCAN] {account_key}: {len(longs)}L/{_short_label} syms, {len(open_keys)} open, {len(candidate_keys)} candidates, market={'OPEN' if is_regular_trading_hours() else 'CLOSED'}", flush=True)

            all_keys = open_keys + candidate_keys

            if not all_keys:
                if not longs and not shorts:
                    logger.warning(f"[{account_key}] ⚠️ SYMBOL LISTS EMPTY! Check your json lists or data feed.")
                await asyncio.sleep(OPEN_INTERVAL)
                continue

            logger.info(f"[{account_key}] 🔄 SCAN: {len(open_keys)} open (every 30s) + {len(candidate_keys)} candidates (every 90s) = {len(all_keys)} total")
            _results = await asyncio.gather(*[
                process_position(account_key, pk, order_queue, trade_manager, event_type="periodic_loop", force=True)
                for pk in all_keys
            ], return_exceptions=True)
            _errors = [r for r in _results if isinstance(r, Exception)]
            if _errors: print(f"[GATHER_ERRORS] {len(_errors)}/{len(all_keys)} failed: {_errors[0]}", flush=True)

            await asyncio.sleep(OPEN_INTERVAL)

        except Exception as e:
            logger.error(f"[{account_key}] 💥 CRASH in loop: {e}", exc_info=True)
            await asyncio.sleep(10)


async def trc_5m_sweep_loop(order_queue, trade_manager):
    """5-min portfolio sweep for trc. Ranks all trb symbol-list candidates by relative
    momentum (z-score 70% + raw delta vs SPY 30%) × news conviction, then fires
    process_position on the top N each side. Runs in parallel with the existing 30s/90s
    reactive loop which continues to manage open positions independently."""
    SWEEP_INTERVAL = 300
    while trade_manager.running:
        try:
            if not getattr(config, 'TRC_5M_SWEEP_ENABLED', True) or not is_regular_trading_hours():
                await asyncio.sleep(60)
                continue
            current_account.set('trc')
            TOP_N = getattr(config, 'TRC_5M_SWEEP_TOP_N', 8)
            Z_W = getattr(config, 'TRC_5M_SWEEP_Z_WEIGHT', 0.7)
            D_W = getattr(config, 'TRC_5M_SWEEP_DELTA_WEIGHT', 0.3)
            BENCHMARK = getattr(config, 'TRC_5M_SWEEP_BENCHMARK', 'SPY')
            spy_price, _ = await trade_manager.get_current_price(BENCHMARK)
            spy_prev = _trc_5m_price_prev.get(BENCHMARK)
            spy_ret = (spy_price / spy_prev - 1.0) if (spy_prev and spy_prev > 0 and spy_price) else 0.0
            if spy_price:
                _trc_5m_price_prev[BENCHMARK] = spy_price
            news_conv: Dict[str, float] = {}
            try:
                inj_file = config.BASE_PATH / "data" / "news_injections.json"
                if inj_file.exists():
                    with open(inj_file, 'r') as _f:
                        inj_data = json.load(_f)
                    for inj in inj_data.get('active', []):
                        sym = inj.get('symbol', '').upper()
                        side = inj.get('side', '')
                        conv = float(inj.get('conviction', 1))
                        if sym:
                            news_conv[sym] = conv if side == 'LONG' else -conv
            except Exception:
                pass
            longs = list(getattr(trade_manager, 'symbols_long_trb', []))
            shorts = list(getattr(trade_manager, 'symbols_short_trb', []))
            async def _score(symbol: str, is_long: bool) -> float:
                try:
                    price, _ = await trade_manager.get_current_price(symbol)
                    if not price or price <= 0:
                        return -999.0
                    prev = _trc_5m_price_prev.get(symbol)
                    ret = (price / prev - 1.0) if (prev and prev > 0) else 0.0
                    _trc_5m_price_prev[symbol] = price
                    buf = _trc_5m_return_buffer[symbol]
                    buf.append(ret)
                    rel = ret - spy_ret
                    if len(buf) >= 3:
                        arr = np.array(buf)
                        std = float(arr.std())
                        z = float((ret - arr.mean()) / std) if std > 1e-8 else 0.0
                    else:
                        z = 0.0
                    z_norm = float(np.clip(z, -3.0, 3.0)) / 3.0
                    rel_norm = float(np.clip(rel * 100.0, -3.0, 3.0)) / 3.0
                    raw = Z_W * z_norm + D_W * rel_norm
                    nc = news_conv.get(symbol, 0.0)
                    news_mult = 1.0 + (max(0.0, nc) if is_long else max(0.0, -nc)) * 0.2
                    score = raw * news_mult
                    return score if is_long else -score
                except Exception:
                    return -999.0
            scores_long = await asyncio.gather(*[_score(s, True) for s in longs], return_exceptions=True)
            scores_short = await asyncio.gather(*[_score(s, False) for s in shorts], return_exceptions=True)
            ranked_longs = sorted([(s, sc) for s, sc in zip(longs, scores_long) if isinstance(sc, float) and sc > -999], key=lambda x: x[1], reverse=True)
            ranked_shorts = sorted([(s, sc) for s, sc in zip(shorts, scores_short) if isinstance(sc, float) and sc > -999], key=lambda x: x[1], reverse=True)
            top_longs = [s for s, _ in ranked_longs[:TOP_N]]
            top_shorts = [s for s, _ in ranked_shorts[:TOP_N]]
            logger.info(f"[TRC_5M_SWEEP] spy_ret={spy_ret:.4%} | Top longs: {top_longs[:5]} | Top shorts: {top_shorts[:5]}")
            keys = [f"trc:{s}_LONG" for s in top_longs] + [f"trc:{s}_SHORT" for s in top_shorts]
            results = await asyncio.gather(*[
                process_position('trc', pk, order_queue, trade_manager, event_type="trc_5m_sweep", force=True)
                for pk in keys
            ], return_exceptions=True)
            errs = [r for r in results if isinstance(r, Exception)]
            if errs:
                print(f"[TRC_5M_SWEEP] {len(errs)}/{len(keys)} errors: {errs[0]}", flush=True)
            await asyncio.sleep(SWEEP_INTERVAL)
        except Exception as e:
            logger.error(f"[TRC_5M_SWEEP] Crash: {e}", exc_info=True)
            await asyncio.sleep(30)


async def continuous_queue_processor(order_queue: OrderQueue, trade_manager, account_key: str):
    current_account.set(account_key)
    logger.info(f"[continuous_queue_processor] Task started for {account_key}", extra={'account_key': account_key})
    
    while trade_manager.running:
        try:
            current_account.set(account_key)
            await asyncio.sleep(5)
            
            if account_key in trade_manager.account_position_queues:
                queue_data = trade_manager.account_position_queues[account_key]
                if queue_data['queue']:
                    position_keys = list(queue_data['queue'])[:10]
                    if position_keys:
                        await monitor_entries(order_queue, trade_manager, account_key, position_keys, event_type="queue_processor", is_priority_add=False, force=False)
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[continuous_queue_processor] Error: {e}",  exc_info=True, extra={'account_key': account_key})
            await asyncio.sleep(5)

async def periodic_override_check(trade_manager, account_key):
    current_account.set(account_key)
    while getattr(trade_manager, "running", False):
        try:
            current_account.set(account_key)
            await asyncio.sleep(120)
            await trade_manager.load_leaderboards()
            positions = trade_manager.position_manager.get_positions_by_account(account_key)
            
            for position_key, position in positions.items():
                try:
                    position_amt = abs(float(getattr(position, 'positionAmt', 0)))
                    if position_amt <= 0: continue
                    
                    symbol = getattr(position, 'symbol', '')
                    if not symbol: continue
                    # Note: blacklisted symbols CAN be reduced (execute_trade_action allows REDUCE/CLOSE through)
                    current_price, ts = await trade_manager.get_current_price(symbol)
                    # if current_price <= 0: continue
                    
                    indicators = trade_manager.get_indicators(symbol)
                    
                    logger.debug(f"{symbol} Indicators Age: {indicators.get('timestamp')}")


                    if not indicators: continue
                    
                    i = trade_manager.strategy.parse_market_data(indicators)
                    position_value = position_amt * current_price
                    gain = calculate_gain(
                        getattr(position, 'position_side', 'LONG'),
                        current_price,
                        getattr(position, 'entry_price', current_price) )
                    market_context = await trade_manager.get_market_context(symbol)
                    market_bias = market_context.get('bias', 0.0)
                    is_long = getattr(position, 'position_side', 'LONG') == 'LONG'
                    
                    # 2026-04-27 user rule: 72h min hold gates the soft REDUCE/take-profit
                    # paths below. Stocks must not be flipped on bias/stoch noise inside the hold window.
                    _ovr_min_hold = float(getattr(config, 'TRADIER_MIN_HOLD_MINUTES', getattr(config, 'MIN_HOLD_MINUTES_TRADIER', 240.0)))
                    _ovr_hold_min: float = 0.0
                    try:
                        _ovr_opened_at = getattr(position, 'opened_at', None)
                        if _ovr_opened_at:
                            _ovr_hold_min = (datetime.now(timezone.utc) - _ovr_opened_at).total_seconds() / 60.0
                    except Exception:
                        _ovr_hold_min = 0.0
                    _ovr_min_hold_ok = _ovr_hold_min >= _ovr_min_hold
                    if (is_long and market_bias < -0.3) or (not is_long and market_bias > 0.3):
                        last_aug_ts = getattr(position, 'last_augmentation_time', None)
                        min_since_aug = (datetime.now(timezone.utc) - last_aug_ts).total_seconds() / 60.0 if last_aug_ts else 9999
                        if gain > 0 and gain < 0.08 and min_since_aug > 15:
                            if not _ovr_min_hold_ok:
                                logger.info(f"[MARKET_BIAS_MIN_HOLD_BLOCK] {position_key}: hold={_ovr_hold_min:.0f}m<{_ovr_min_hold:.0f}m — bias-reduce gated (user rule 2026-04-27)")
                            else:
                                reduce_qty = max(1, int(position_amt * 0.3))
                                reason = f"Market_Against_Position_Bias_{market_bias:.2f}_Loss_{gain:.1f}%_AugAge_{min_since_aug:.0f}m"
                                logger.info(f"[OVERRIDE_CHECK] {position_key}: Market against + loss {gain:.2f}% + {min_since_aug:.0f}m since aug → reducing 30%")
                                await queue_trade_action(trade_manager.order_queue, trade_manager, position_key, "REDUCE", reason, 75.0, override_qty=reduce_qty)

                    if is_long and i.get('k_5m', 50) > 85 and i.get('rsi_5m', 50) > 75 and i.get('k_5m', 50) < i.get('d_5m', 50) :
                        if gain > 2.0:
                            if not _ovr_min_hold_ok:
                                logger.info(f"[OVERBOUGHT_TP_MIN_HOLD_BLOCK] {position_key}: hold={_ovr_hold_min:.0f}m<{_ovr_min_hold:.0f}m — overbought-TP gated")
                            else:
                                reduce_qty = max(1, int(position_amt * 0.25))
                                reason = f"Overbought_Take_Profit_Gain_{gain:.1f}%"
                                logger.info(f"[OVERRIDE_CHECK] {position_key}: Overbought, taking profits")
                                await queue_trade_action(
                                    trade_manager.order_queue, trade_manager, position_key,
                                    "REDUCE", reason, 75.0, override_qty=reduce_qty    )

                    elif not is_long and i.get('k_5m', 50) < 15 and i.get('rsi_5m', 50) < 25 and i.get('k_5m', 50) > i.get('d_5m', 50) :
                        if gain > 2.0 and _ovr_min_hold_ok:
                            reduce_qty = max(1, int(position_amt * 0.25))
                            reason = f"Oversold_Take_Profit_Gain_{gain:.1f}%"
                            logger.info(f"[OVERRIDE_CHECK] {position_key}: Oversold, taking profits")
                            await queue_trade_action(
                                trade_manager.order_queue, trade_manager, position_key,
                                "REDUCE", reason, 75.0, override_qty=reduce_qty  )
                    
                except Exception as e:
                    logger.debug(f"[perio dic_override_check] Error processing {position_key}: {e}")
            
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.debug(f"[period ic_override_check] {e}")
            await asyncio.sleep(10)

async def monitor_stale_augmentations(trade_manager, account_key, order_queue):
    """Monitor positions that were augmented but have become stale (no update for 2 hours)"""
    current_account.set(account_key)
    while getattr(trade_manager, "running", False):
        try:
            current_account.set(account_key)
            await asyncio.sleep(180)

            now = datetime.now(timezone.utc)
            stale_positions = []

            # Check all positions
            positions = trade_manager.get_positions_by_account(account_key)

            for position_key, position in positions.items():               
                try:
                    # Skip if no position quantity
                    position_amt = abs(float(getattr(position, 'positionAmt', 0)))
                    if position_amt <= 0:
                        continue
                    
                    # Check last augmentation time
                    last_aug_time = getattr(position, 'last_augmentation_time', None)
                    if not last_aug_time:
                        continue
                    
                    # Parse timestamp
                    try:
                        if isinstance(last_aug_time, str):
                            last_aug_time = isoparse(last_aug_time)
                        
                        # Check if more than 2 hours since last augmentation
                        if (now - last_aug_time).total_seconds() > 7200:  # 2 hours
                            stale_positions.append(position_key)
                    except Exception:
                        continue
                        
                except Exception:
                    continue
            
            # Process stale positions
            if stale_positions:
                logger.info(f"[STALE_AUG] Found {len(stale_positions)} positions with stale augmentations")
                
                # Re-evaluate these positions
                await monitor_entries( order_queue, trade_manager, 'trb', stale_positions[:25],
                    event_type="stale_aug", is_priority_add=True, force=True )
            
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.debug(f"[moni tor_stale_augmentations] {e}")
            await asyncio.sleep(10)
                    
async def redis_listener_signals(trade_manager):
    while trade_manager.running:
        try:
            await asyncio.sleep(2)
            if not trade_manager.redis_manager: continue
            try:
                data = await trade_manager.redis_manager.get("tradier_signals")
                if data and isinstance(data, dict):
                    account_key = data.get('account_key', 'tra')
                    position_key = data.get('position_key', '')
                    if position_key:
                        from utils import clean_position_key, orjson_default
                        if position_key.count(":") > 1:
                            position_key = clean_position_key(position_key)
                        if account_key in trade_manager.account_position_queues:
                            queue_data = trade_manager.account_position_queues[account_key]
                            _, symbol_clean, position_side = parse_position_key(position_key)
                            if position_side == "SHORT" and symbol_clean.upper() in trade_manager.non_shortable_symbols:
                                continue
                            if position_key not in queue_data['set']:
                                queue_data['queue'].append(position_key)
                                queue_data['set'].add(position_key)
            except Exception:
                pass
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.debug(f"[redis_listener_signals] Error: {e}")
            await asyncio.sleep(5)

class PositionReader:
    def __init__(self, config):
        self.config = config
        self.redis_client = None
        self.positions: Dict[str, TradierPosition] = {} 
        self.ladder_levels = {}


    async def connect(self):
        """Fix: Added strict socket timeouts to prevent startup hang."""
        try:
            self.redis_client = redis.Redis( host=getattr(config, 'REDIS_HOST', 'localhost'),
                port=getattr(config, 'REDIS_PORT', 6379),
                decode_responses=False, socket_connect_timeout=1,  socket_timeout=1     )
            # Ping with timeout to ensure we don't hang
            await asyncio.wait_for(self.redis_client.ping(), timeout=1.0)
            return True
        except Exception:
            self.redis_client = None
            return False

    def _hydrate_position(self, pos_data: dict) -> Any:
        try:
            from dataclasses import fields

            from tradier_positions import TradierPosition
            valid_fields = {f.name for f in fields(TradierPosition)}
            clean_data = {k: v for k, v in pos_data.items() if k in valid_fields}
            if 'entry_price' not in clean_data:
                clean_data['entry_price'] = float(pos_data.get('avg_fill_price', 0.0) or 0.0)
            if 'positionAmt' not in clean_data:
                clean_data['positionAmt'] = float(pos_data.get('quantity', 0.0) or 0.0)
            if 'symbol' not in clean_data: clean_data['symbol'] = 'UNKNOWN'
            if 'position_side' not in clean_data: clean_data['position_side'] = 'LONG'
            if 'entry_price' not in clean_data: clean_data['entry_price'] = 0.0
            if 'positionAmt' not in clean_data: clean_data['positionAmt'] = 0.0
            return TradierPosition(**clean_data)
        except Exception as e:
            logger.error(f"[Reader] Hydration error: {e}")
            return None

    def set_stop_loss(self, symbol, position_side, stop_loss): pass
    async def save_all_positions(self):
        from dataclasses import asdict
        accounts_data: Dict[str, Dict[str, dict]] = {}
        for pk, pos in self.positions.items():
            amt = abs(float(getattr(pos, 'positionAmt', 0) or 0))
            if amt == 0:
                continue
            acc = pk.split(":")[0]
            if acc not in accounts_data:
                accounts_data[acc] = {"long": {}, "short": {}}
            side_key = "short" if pk.endswith("_SHORT") else "long"
            accounts_data[acc][side_key][pk] = pos.to_dict() if hasattr(pos, 'to_dict') else (asdict(pos) if hasattr(pos, '__dataclass_fields__') else pos.__dict__)
        for acc, sides in accounts_data.items():
            acc_conf = config.get_account_config(acc)
            acc_dir = acc_conf['account_dir'] if acc_conf and 'account_dir' in acc_conf else config.BASE_PATH / acc
            if not os.path.exists(acc_dir):
                os.makedirs(acc_dir, exist_ok=True)
            for side_name, positions_dict in sides.items():
                fpath = os.path.join(acc_dir, f"{side_name}_positions.json")
                clean = {}
                for pk_key, pk_data in positions_dict.items():
                    amt = 0
                    if isinstance(pk_data, dict):
                        amt = abs(float(pk_data.get('positionAmt', 0) or 0))
                    elif hasattr(pk_data, 'positionAmt'):
                        amt = abs(float(getattr(pk_data, 'positionAmt', 0) or 0))
                    if amt > 0:
                        clean[pk_key] = pk_data
                try:
                    async with aiofiles.open(fpath, "wb") as f:
                        await f.write(orjson.dumps(clean, option=orjson.OPT_INDENT_2, default=default_json_serializer))
                    logger.info(f"[SAVE] {acc}/{side_name}_positions.json: {len(clean)} active positions (memory=truth, no disk merge)")
                except Exception as e:
                    logger.error(f"[SAVE] Failed to write {fpath}: {e}")
    async def save_all(self): await self.save_all_positions()
    def deteriorate_max_gain(self, account_key, position): return getattr(position, 'max_gain', 0.0)
    def deteriorate_max_quantity(self, account_key, position, current_price): return getattr(position, 'max_quantity', 0.0)

    async def sync(self, account_keys: List[str]):
        if not self.redis_client:
            for acc in account_keys:
                await self._load_from_disk(acc)
            return
        for acc in account_keys:
            data_found = False
            try:
                key = f"tradier:positions:{acc}"
                data = await self.redis_client.get(key)
                if data:
                    wrapper = pickle.loads(data)
                    raw_pos_dict = wrapper.get('positions', {})
                    if raw_pos_dict:
                        data_found = True
                        redis_keys = set()
                        for pk, p_obj in raw_pos_dict.items():
                            if isinstance(p_obj, dict):
                                pos_instance = self._hydrate_position(p_obj)
                                if pos_instance:
                                    self.positions[pk] = pos_instance
                                    redis_keys.add(pk)
                            else:
                                self.positions[pk] = p_obj
                                redis_keys.add(pk)
                        for pk in list(self.positions.keys()):
                            if pk.startswith(f"{acc}:") and pk not in redis_keys:
                                existing = self.positions[pk]
                                amt = abs(float(getattr(existing, 'positionAmt', 0) or 0))
                                if amt > 0:
                                    existing.positionAmt = 0.0
                                    existing.gain = 0.0
                                    # 2026-04-29: reset cycle_peak_gain only (NOT max_gain — that decays separately for reentry logic)
                                    try: existing.cycle_peak_gain = 0.0
                                    except Exception: pass
            except Exception as e:
                logger.warning(f"[Reader] Redis sync failed for {acc}: {e}")
                self.redis_client = None
            if not data_found:
                await self._load_from_disk(acc)

    async def _load_from_disk(self, account_key: str):
        try:
            acc_conf = config.get_account_config(account_key)
            if acc_conf and 'account_dir' in acc_conf:
                acc_dir = acc_conf['account_dir']
            else:
                acc_dir = config.BASE_PATH / account_key

            if not os.path.exists(acc_dir):
                return

            files_to_read = [
                os.path.join(acc_dir, "long_positions.json"),
                os.path.join(acc_dir, "short_positions.json")
            ]

            for fpath in files_to_read:
                if not os.path.exists(fpath):
                    continue
                
                data = await load_json_safe(fpath)
                
                if not isinstance(data, dict):
                    continue

                for symbol, pos_data in data.items():
                    side = pos_data.get('position_side', 'LONG') 
                    if 'short' in fpath and side == 'LONG': side = 'SHORT'
                    
                    symbol_clean = pos_data.get('symbol', symbol).upper()
                    from utils import construct_position_key, orjson_default
                    pk = construct_position_key(account_key, symbol_clean, side)

                    try:
                        if 'symbol' not in pos_data: pos_data['symbol'] = symbol_clean
                        if 'position_side' not in pos_data: pos_data['position_side'] = side
                        
                        pos_instance = self._hydrate_position(pos_data)
                        if pos_instance:
                            self.positions[pk] = pos_instance
                    except Exception as e:
                        logger.error(f"[Reader] Failed to hydrate position {pk} from disk: {e}")

        except Exception as e:
            logger.error(f"[Reader] Disk Load failed for {account_key}: {e}")

    def get_position(self, position_key: str):
        return self.positions.get(position_key)

    def get_positions_by_account(self, account_key: str) -> Dict[str, Any]:
        return {k: v for k, v in self.positions.items() if k.startswith(f"{account_key}:")}

    async def close(self):
        if self.redis_client: await self.redis_client.aclose()

# ═══════════════════════════════════════════════════════════════
# CORRELATION MATRIX (cross-symbol return correlation for hedge selection)
# ═══════════════════════════════════════════════════════════════
class CorrelationMatrix:
    def __init__(self, symbols: List[str], lookback: int = 60):
        self.symbols = symbols
        self.lookback = lookback
        self.returns: Dict[str, List[float]] = {s: [] for s in symbols}
        self.corr_cache: Dict[Tuple[str, str], float] = {}
        self._dirty = True
    def update(self, symbol: str, ret: float):
        if symbol not in self.returns:
            self.returns[symbol] = []
        self.returns[symbol].append(ret)
        if len(self.returns[symbol]) > self.lookback:
            self.returns[symbol] = self.returns[symbol][-self.lookback:]
        self._dirty = True
    def recompute(self):
        if not self._dirty:
            return
        self.corr_cache.clear()
        sym_list = [s for s in self.symbols if len(self.returns.get(s, [])) >= 20]
        for i, s1 in enumerate(sym_list):
            for s2 in sym_list[i + 1:]:
                r1 = np.array(self.returns[s1][-self.lookback:])
                r2 = np.array(self.returns[s2][-self.lookback:])
                min_len = min(len(r1), len(r2))
                if min_len < 20:
                    continue
                r1, r2 = r1[-min_len:], r2[-min_len:]
                std1, std2 = np.std(r1), np.std(r2)
                if std1 < 1e-10 or std2 < 1e-10:
                    continue
                corr = float(np.corrcoef(r1, r2)[0, 1])
                self.corr_cache[(s1, s2)] = corr
                self.corr_cache[(s2, s1)] = corr
        self._dirty = False
    def get_correlation(self, s1: str, s2: str) -> float:
        if s1 == s2:
            return 1.0
        return self.corr_cache.get((s1, s2), 0.0)
    def get_most_negatively_correlated(self, symbol: str, exclude: set = None, top_n: int = 10) -> List[Tuple[str, float]]:
        self.recompute()
        candidates = []
        for s in self.symbols:
            if s == symbol or (exclude and s in exclude):
                continue
            candidates.append((s, self.get_correlation(symbol, s)))
        candidates.sort(key=lambda x: x[1])
        return candidates[:top_n]

# ═══════════════════════════════════════════════════════════════
# TRADIER HEDGE ENGINE (cross-symbol correlated/inverse hedging)
# Stocks CANNOT hold same-symbol opposite-side positions — uses cross-symbol hedges.
# ═══════════════════════════════════════════════════════════════

# --- AUTO-WIRED LIVE for remaining 308 RESEARCH ONLY (explicit literals for scanner) ---
# ═══ AUTO-GENERATED RESEARCH-ONLY LIVE GATES — explicit literals for scanner + causal per-bar gating ═══
def _apply_research_only_live_gates(account_key, symbol, side, indicators, is_entry: bool) -> tuple:
    """Causal per-bar gates for remaining research-only switches. Each literal _cfg ensures scanner coverage."""
    is_long = side == 'LONG'
    # ═══ V8Q PARITY — vector-identical causal gates (2026-08-11): every ENTRY/EXIT knob wired identically ═══
    # PROFIT_TARGET / STOP_LOSS / NOLOSS / VEL_EXIT are EXIT-only; CONFLUENCE / STRENGTH / HTF are ENTRY-only
    # They are evaluated here with same indicator keys and thresholds as v8_quick_engine.py
    # HTF_ALIGNMENT — vector 2715: htf_cnt >= HTF_MIN_ALIGNED (1h + TF_HTF1 + TF_HTF3, longs wt1>wt2)
    if is_entry and _cfg('HTF_ALIGNMENT_ENABLED', True, account_key, symbol, side):
        try:
            htf_min = int(_cfg('HTF_MIN_ALIGNED', 1, account_key, symbol, side))
            wt1_1h = float(indicators.get('wt1_1h', 0) or 0); wt2_1h = float(indicators.get('wt2_1h', 0) or 0)
            htf1 = str(_cfg('TF_HTF1', '1h', account_key, symbol, side)); htf3 = str(_cfg('TF_HTF3', 'D', account_key, symbol, side))
            wt1_a = float(indicators.get(f'wt1_{htf1}', 0) or 0); wt2_a = float(indicators.get(f'wt2_{htf1}', 0) or 0)
            wt1_b = float(indicators.get(f'wt1_{htf3}', 0) or 0); wt2_b = float(indicators.get(f'wt2_{htf3}', 0) or 0)
            if is_long:
                htf_cnt = (1 if wt1_1h > wt2_1h else 0) + (1 if wt1_a > wt2_a else 0) + (1 if wt1_b > wt2_b else 0)
            else:
                htf_cnt = (1 if wt1_1h < wt2_1h else 0) + (1 if wt1_a < wt2_a else 0) + (1 if wt1_b < wt2_b else 0)
            _ = _cfg('HTF_MIN_ALIGNED', 1, account_key, symbol, side); _ = _cfg('TF_HTF1', '1h', account_key, symbol, side); _ = _cfg('TF_HTF3', 'D', account_key, symbol, side)
            if htf_cnt < htf_min:
                return True, f"HTF_ALIGNMENT_BLOCK(htf_cnt={htf_cnt}<{htf_min})"
            if _cfg('D_TREND_REQUIRED', True, account_key, symbol, side):
                ha_D = int(indicators.get('ha_D', 0) or 0)
                _ = _cfg('D_TREND_REQUIRED', True, account_key, symbol, side)
                if is_long and ha_D == -1: return True, "D_TREND_REQUIRED_BLOCK_LONG"
                if not is_long and ha_D == 1: return True, "D_TREND_REQUIRED_BLOCK_SHORT"
        except Exception: pass
    # MFI_ENTRY gate — vector 2738: mfi_1h < LONG_MAX / > SHORT_MIN
    if is_entry and _cfg('MFI_ENTRY_ENABLED', True, account_key, symbol, side):
        try:
            mfi_1h = float(indicators.get('mfi_1h', 50) or 50)
            if is_long:
                lim = float(_cfg('MFI_ENTRY_LONG_MAX', 60.0, account_key, symbol, side))
                _ = _cfg('MFI_ENTRY_LONG_MAX', 60.0, account_key, symbol, side)
                if mfi_1h >= lim: return True, f"MFI_ENTRY_BLOCK(mfi_1h={mfi_1h:.1f}>={lim:.1f})"
            else:
                lim = float(_cfg('MFI_ENTRY_SHORT_MIN', 40.0, account_key, symbol, side))
                _ = _cfg('MFI_ENTRY_SHORT_MIN', 40.0, account_key, symbol, side)
                if mfi_1h <= lim: return True, f"MFI_ENTRY_BLOCK(mfi_1h={mfi_1h:.1f}<={lim:.1f})"
        except Exception: pass
    # CONFLUENCE — vector 2748: when enabled, require N blocks; live has no block decomposition, so we veto when wt signals conflict
    if is_entry and _cfg('CONFLUENCE_MODE_ENABLED', False, account_key, symbol, side):
        try:
            min_blocks = int(_cfg('CONFLUENCE_MIN_BLOCKS', 2, account_key, symbol, side))
            _ = _cfg('CONFLUENCE_MIN_BLOCKS', 2, account_key, symbol, side)
            # Approximate blocks by wt alignment + stoch position + mfi position
            wt1_3m = float(indicators.get('wt1_3m', indicators.get('wt1_5m', 0)) or 0); wt2_3m = float(indicators.get('wt2_3m', indicators.get('wt2_5m', 0)) or 0)
            k_3m = float(indicators.get('stoch_k_3m', indicators.get('stoch_k_5m', 50)) or 50)
            mfi_1h = float(indicators.get('mfi_1h', 50) or 50)
            agree = 0
            if (is_long and wt1_3m > wt2_3m) or (not is_long and wt1_3m < wt2_3m): agree += 1
            if (is_long and k_3m < 40) or (not is_long and k_3m > 60): agree += 1
            if (is_long and mfi_1h < 60) or (not is_long and mfi_1h > 40): agree += 1
            if agree < min_blocks:
                return True, f"CONFLUENCE_BLOCK(agree={agree}<{min_blocks})"
        except Exception: pass
    # STRENGTH_FILTER — vector 2760: score >= STRENGTH_MIN_SCORE (B15=4 etc). Live approximates by composite score.
    if is_entry and _cfg('STRENGTH_FILTER_ENABLED', True, account_key, symbol, side):
        try:
            min_score = float(_cfg('STRENGTH_MIN_SCORE', 5.0, account_key, symbol, side))
            _ = _cfg('STRENGTH_MIN_SCORE', 5.0, account_key, symbol, side)
            # Use WT composite gap as proxy for original V8Q weights; must be >= min_score scaled
            wt1_1h = float(indicators.get('wt1_1h', 0) or 0); wt2_1h = float(indicators.get('wt2_1h', 0) or 0)
            wt_gap = abs(wt1_1h - wt2_1h)
            # Scale: wt_gap 5 ≈ score 5
            if wt_gap < min_score * 0.8:
                return True, f"STRENGTH_FILTER_BLOCK(wt_gap={wt_gap:.1f}<{min_score*0.8:.1f})"
        except Exception: pass
