    async def _expire_limbo_order(self, position_key: str, side: str, delay_seconds: float):
        """Remove order from limbo dict after delay if not confirmed"""
        await asyncio.sleep(delay_seconds)
        if position_key in self.orders_in_limbo and side in self.orders_in_limbo[position_key]:
            limbo_time = self.orders_in_limbo[position_key][side]
            if time.time() - limbo_time >= delay_seconds:
                del self.orders_in_limbo[position_key][side]
                if not self.orders_in_limbo[position_key]:
                    del self.orders_in_limbo[position_key]
                logger.debug(f"[{position_key}] Limbo order expired (not confirmed): {side}")
                # CRITICAL: Clear deduplication entry since order was NOT executed
                async with self.dedupe_lock:
                    if position_key in self.order_deduplication:
                        self.order_deduplication.pop(position_key, None)
                        logger.debug(f"[CLEAR_DEDUPE_NOT_EXECUTED] {position_key}: Cleared deduplication entry (order not executed)")

    def validate_order_side(self, side: str, position_side: str, action: str, position_key: str) -> tuple[str, bool]:
        is_opening_or_augmenting = action in ['OPEN', 'QUICK_OPEN', 'AUGMENT', 'REENTER']
        is_reducing_or_closing = action in ['REDUCE', 'QUICK_CLOSE', 'PROFIT_TAKE', 'CLOSE']
        if is_opening_or_augmenting:
            expected_side = "BUY" if position_side == "LONG" else "SELL"
        elif is_reducing_or_closing:
            expected_side = "SELL" if position_side == "LONG" else "BUY"
        else:
            expected_side = "BUY" if position_side == "LONG" else "SELL"
        if side == expected_side:
            return side, True
        logger.error(f"🚨 CRITICAL ORDER SIDE ERROR: {position_key}")
        logger.error(f"   Position: {position_side}, Action: {action}")
        logger.error(f"   Received side: {side}, Expected side: {expected_side}")
        logger.error(f"   CORRECTING to: {expected_side}")
        return expected_side, False
   
    def get_indicators(self, symbol: str, use_cache: bool = True) -> Dict[str, Any]:
        symbol = symbol.strip().upper()
        data = self.market_snapshot.get(symbol, {})
        if not data: return {}
        price_entry = self.price_cache.get(symbol)
        if price_entry:
            data['current_price'] = price_entry['price']
        ts_raw = data.get('timestamp_1m') or data.get('timestamp_5m') or data.get('timestamp_15m') or data.get('timestamp_1m_mid') or data.get('timestamp')
        if ts_raw:
            dt_obj = ts_raw if isinstance(ts_raw, datetime) else safe_datetime(ts_raw)
            if dt_obj:
                now_utc = datetime.now(timezone.utc)
                true_lag = (now_utc - dt_obj).total_seconds()
                if true_lag < -1.0:
                    true_lag = 0.1
                if true_lag > 600:
                    logger.warning(f"[get_indicators] [{symbol}] Snapshot internal age is stale ({true_lag:.1f}s)")
        return data

    def _get_extras(self, symbol: str) -> Dict[str, Any]:
        """Get extra indicators for symbol, computing on demand if not cached (TTL 120s)."""
        now = time.time()
        if symbol in self._extra_indicators_cache and (now - self._extra_indicators_cache_time.get(symbol, 0)) < 120:
            return self._extra_indicators_cache[symbol]
        try:
            extras = compute_extra_indicators(symbol, config.KLINES_CACHE_DIR)
            if extras:
                self._extra_indicators_cache[symbol] = extras
                self._extra_indicators_cache_time[symbol] = now
                return extras
        except Exception:
            pass
        return self._extra_indicators_cache.get(symbol, {})

    def get_enriched_indicators(self, symbol: str) -> Dict[str, Any]:
        """Get indicators + YouTube Consensus extras (VWAP, 9/21 EMA, Keltner, Squeeze, ORB, EP)."""
        data = self.get_indicators(symbol)
        if not data:
            return data
        now = time.time()
        cache_ttl = 60.0  # Refresh extras every 60s
        if symbol in self._extra_indicators_cache and (now - self._extra_indicators_cache_time.get(symbol, 0)) < cache_ttl:
            data.update(self._extra_indicators_cache[symbol])
        else:
            try:
                extras = compute_extra_indicators(symbol, config.KLINES_CACHE_DIR)
                if extras:
                    # Squeeze detection: combine 1h BB (from existing indicators) with 1h KC (from extras)
                    bb_upper = float(data.get('bb_upper_1h', 0) or 0)
                    bb_lower = float(data.get('bb_lower_1h', 0) or 0)
                    kc_upper = float(extras.get('kc_upper_1h', 0) or 0)
                    kc_lower = float(extras.get('kc_lower_1h', 0) or 0)
                    if bb_upper and bb_lower and kc_upper and kc_lower:
                        squeeze_on = bb_upper < kc_upper and bb_lower > kc_lower
                        extras['squeeze_on_1h'] = squeeze_on
                        # Squeeze fire: was on, now off (need prev state — approximate with current)
                        extras['squeeze_momentum_long'] = squeeze_on and float(data.get('wt1_1h', 0) or 0) > 0
                        extras['squeeze_momentum_short'] = squeeze_on and float(data.get('wt1_1h', 0) or 0) < 0
                    self._extra_indicators_cache[symbol] = extras
                    self._extra_indicators_cache_time[symbol] = now
                    data.update(extras)
            except Exception as e:
                logger.debug(f"[EXTRA_IND] {symbol}: {e}")
        return data

    def _get_full_market_snapshot(self) -> Dict[str, Dict]:
        return self.market_snapshot
   
    async def _on_indicators_update(self, data: Any):
        """FAST-PATH: Instant update via Redis message."""
        try:
            payload = data.get("data", data) if isinstance(data, dict) else data
            if isinstance(payload, dict) and len(payload) > 0:
                # Update individual keys so the existing dictionary reference stays alive
                # but the content is fresh.
                for sym, vals in payload.items():
                    self.market_snapshot[sym.upper()] = self._adapt_indicators_for_ez_manage(vals)
                
                # Update mtime tracker to match (prevents the Poller from re-reading same data)
                self.last_json_mtime = time.time()
                
                if not self.ready_to_trade:
                    self.ready_to_trade = True
                    logger.info("🚀 [SYSTEM] Ready via PubSub.")
        except Exception as e:
            logger.error(f"PubSub Update Error: {e}")



    def _finalize_indicators(self, symbol: str, raw_indicators: dict) -> dict:
        """Helper to normalize data and inject real-time price"""
        if not raw_indicators: return {}

        # 1. Normalize (Timestamps & Floats)
        final = self._normalize_indicators(raw_indicators)

        # 2. Inject Price Cache (if available locally and fresher)
        # Fixes "0.00" price logs
        price_entry = self.price_cache.get(symbol, {})
        cached_price = price_entry.get('current_price', 0)

        if cached_price > 0:
            final['current_price'] = cached_price
            final['current_price'] = cached_price
        return final

    def _normalize_indicators(self, indicators: Dict[str, Any]) -> Dict[str, Any]:
        if not indicators or not isinstance(indicators, dict):
            return {}
        adapted = indicators.copy()
        ts_keys = ['timestamp', 'timestamp_1m', 'timestamp_5m', 'timestamp_15m', '1m_updated_at']
        for k in ts_keys:
            if k in adapted and isinstance(adapted[k], str):
                try:
                    dt = isoparse(adapted[k])
                    if dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)
                    adapted[k] = dt
                except Exception: pass

        # 2. NUMERIC CONVERSION
        float_keys = [
            'current_price', 'current_price',
            'k_1m', 'd_1m', 'k_5m', 'd_5m',
            'rsi_1m', 'rsi_5m', '0sentiment_rank'
        ]
        for k in float_keys:
            if k in adapted:
                try: adapted[k] = float(adapted[k])
                except Exception: pass
        return adapted

    async def last_hour_balancing_loop(self):
        logger.info("⚖️ [TASK] Afternoon Slim-Down Balancer Active")
        while self.running:
            try:
                est = ZoneInfo("America/New_York")
                now_est = datetime.now(timezone.utc).astimezone(est)
                
                if now_est.weekday() < 5 and dt_time(15, 15) <= now_est.time() <= dt_time(15, 58) and bool(getattr(config, 'EOD_SLIM_RATIO_ENABLED', False)):

                    # PUNCTUAL FIX: Removed 'await' because these are now synchronous memory lookups
                    target_long_pct = self.calculate_unified_market_ratio()
                    balance = self.get_current_portfolio_balance()
                    
                    actual_long_pct = balance['long_pct']
                    deviation = actual_long_pct - target_long_pct

                    if abs(deviation) > 0.10:
                        side_to_trim = "LONG" if deviation > 0 else "SHORT"
                        
                        candidates = []
                        for pk, pos in self.position_manager.positions.items():
                            if side_to_trim in pk and abs(float(getattr(pos, 'positionAmt', 0))) > 0:
                                candidates.append((pk, pos))
                        
                        candidates.sort(key=lambda x: getattr(x[1], 'gain', 0))
                        
                        if candidates:
                            target_pk, target_pos = candidates[0]
                            qty = abs(float(target_pos.positionAmt))
                            trim_qty = max(1, int(qty * 0.30))
                            
                            # PUNCTUAL FIX: Removed 'await'
                            price_data = self.get_indicators(target_pos.symbol)
                            price = float(price_data.get('current_price', 0))
                            
                            await self.execute_trade_action(
                                account_key=target_pk.split(':')[0],
                                position_key=target_pk,
                                symbol=target_pos.symbol,
                                quantity=trim_qty,
                                current_price=price,
                                side="SELL" if side_to_trim == "LONG" else "BUY",
                                position_side=side_to_trim,
                                unique_id=f"slim_{int(time.time())}",
                                action="REDUCE",
                                reason=f"EOD_SLIM_RATIO_{target_long_pct:.2f}",
                                override_qty=trim_qty
                            )

                await asyncio.sleep(240) 
            except Exception as e:
                # This catches the "object dict" error and prevents loop death
                logger.error(f"Balancer Error: {e}")
                await asyncio.sleep(60)
                
                
    async def get_rankings(self) -> Dict[str, Any]:
        """Get rankings from Redis or cache"""
        try:
            if not self.redis_manager:
                try:
                    pass  # DISABLED: tradier does not use server Redis
                except Exception:
                    self.redis_manager = None
            rankings_key = "tradier_rankings"
            data = await self.redis_manager.get(rankings_key)
            if data:
                self.rankings_cache = data if isinstance(data, dict) else {}
                return self.rankings_cache

            return self.rankings_cache
        except Exception as e:
            logger.debug(f"Error getting rankings: {e}")
            return {}
    
    async def get_current_price(self, symbol: str) -> Tuple[Optional[float], Optional[datetime]]:

        symbol = symbol.strip().upper()
        now = datetime.now(timezone.utc)
        MAX_AGE_SECONDS = 40.0  
        symbol = symbol.strip().upper()
        now = datetime.now(timezone.utc)
        MAX_AGE_SECONDS = 15.0  

        def safe_parse_ts(ts_val):
            if not ts_val: return None
            try:
                if isinstance(ts_val, datetime):
                    return ts_val if ts_val.tzinfo else ts_val.replace(tzinfo=timezone.utc)
                if isinstance(ts_val, (int, float)):
                    val = ts_val / 1000.0 if ts_val > 1e12 else ts_val
                    return datetime.fromtimestamp(val, tz=timezone.utc)
                if isinstance(ts_val, str):
                    # Manual parse for speed if format is known, else isoparse
                    if 'T' in ts_val:
                        dt = isoparse(ts_val)
                        return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
            except Exception: return None
            return None

        try:
            # --- LAYER 1: LOCAL CACHE (Zero I/O) ---
            if hasattr(self, 'price_cache') and symbol in self.price_cache:
                entry = self.price_cache[symbol]
                p = float(entry.get('price', 0.0))
                t = safe_parse_ts(entry.get('timestamp'))
                if p > 0 and t and (now - t).total_seconds() < MAX_AGE_SECONDS:
                    return p, t
            if hasattr(self, 'redis_manager') and self.redis_manager:
                try:
                    raw_md = await asyncio.wait_for(
                        self.redis_manager.get("tradier_prices_latest"), 
                        timeout=2.0
                    )
                    
                    if raw_md:
                        md = json.loads(raw_md) if isinstance(raw_md, str) else raw_md
                        if isinstance(md, dict):
                            # FIX: Unwrap the 'data' key!
                            symbol_data = md.get("data", md)
                            if symbol in symbol_data:
                                item = symbol_data[symbol]
                                p = float(item.get('price') or item.get('last', 0.0))
                                t = safe_parse_ts(item.get('timestamp') or item.get('date'))
                                if p > 0 and t:
                                    self.price_cache[symbol] = {'price': p, 'timestamp': t}
                                    if (now - t).total_seconds() < MAX_AGE_SECONDS:
                                        return p, t
                except (asyncio.TimeoutError, Exception):
                    pass 

            # --- LAYER 3: DISK JSON (Reliable Fallback) ---
            try:
                latest_file = self.config.DATA_DIR / "tradier_prices_latest.json"
                if latest_file.exists():
                    if (time.time() - latest_file.stat().st_mtime) < 30:
                        async with aiofiles.open(latest_file, 'r') as f:
                            content = await f.read()
                            if content:
                                md = json.loads(content)
                                if isinstance(md, dict):
                                    # FIX: Unwrap the 'data' key!
                                    symbol_data = md.get("data", md)
                                    if symbol in symbol_data:
                                        item = symbol_data[symbol]
                                        p = float(item.get('price') or item.get('last', 0.0))
                                        t = safe_parse_ts(item.get('timestamp'))
                                        if p > 0 and t:
                                            self.price_cache[symbol] = {'price': p, 'timestamp': t}
                                            if (now - t).total_seconds() < MAX_AGE_SECONDS:
                                                return p, t
            except Exception: pass
            if hasattr(self, 'api_client') and self.api_client:
                # Add a check: don't hammer API if we've recently been banned
                if time.time() > getattr(self.api_client, '_global_ban_expires', 0):
                    try:
                        quote = await self.api_client.get_quote(symbol)
                        if quote:
                            p = float(quote.get('last') or 0.0)
                            t = safe_parse_ts(quote.get('date')) or now
                            if p > 0:
                                self.price_cache[symbol] = {'price': p, 'timestamp': t}
                                return p, t
                    except Exception: pass

            # --- LAYER 5: YAHOO FINANCE (15-min staleness guard) ---
            # Fires when all Tradier sources failed/stale — process restart, API outage, etc.
            _cached = (self.price_cache.get(symbol, {}) if hasattr(self, 'price_cache') else {})
            _cached_ts = safe_parse_ts(_cached.get('timestamp'))
            _cached_age = (now - _cached_ts).total_seconds() if _cached_ts else 9999
            if _cached_age > 900:
                try:
                    _yf_throttle = getattr(self, '_yahoo_price_cache', {})
                    _yf_last = _yf_throttle.get(symbol, {})
                    _yf_last_age = (now - _yf_last.get('fetched_at', now - timedelta(seconds=999))).total_seconds()
                    if _yf_last_age >= 60:
                        def _yf_sync():
                            try:
                                import yfinance as yf
                                fast = yf.Ticker(symbol).fast_info
                                p = float(getattr(fast, 'last_price', 0) or 0)
                                if p <= 0:
                                    hist = yf.Ticker(symbol).history(period='1d', interval='1m')
                                    if not hist.empty:
                                        p = float(hist['Close'].iloc[-1])
                                return p
                            except Exception:
                                return 0.0
                        loop = asyncio.get_event_loop()
                        _yf_price = await loop.run_in_executor(None, _yf_sync)
                        if not hasattr(self, '_yahoo_price_cache'):
                            self._yahoo_price_cache = {}
                        self._yahoo_price_cache[symbol] = {'price': _yf_price, 'fetched_at': now}
                        if _yf_price > 0:
                            logger.warning(f"[PRICE_FALLBACK_YAHOO] {symbol}: Tradier stale {_cached_age:.0f}s — Yahoo=${_yf_price:.4f}")
                            self.price_cache[symbol] = {'price': _yf_price, 'timestamp': now}
                            return _yf_price, now
                    elif _yf_last.get('price', 0) > 0:
                        return float(_yf_last['price']), _yf_last.get('fetched_at')
                except Exception:
                    pass

            # --- FINAL FALLBACK: return stale cache value with warning ---
            if hasattr(self, 'price_cache') and symbol in self.price_cache:
                entry = self.price_cache[symbol]
                _stale_age = (now - safe_parse_ts(entry.get('timestamp'))).total_seconds() if safe_parse_ts(entry.get('timestamp')) else 9999
                if _stale_age > 900:
                    logger.warning(f"[PRICE_STALE] {symbol}: returning price {_stale_age:.0f}s old — all sources failed")
                return float(entry.get('price', 0.0)), safe_parse_ts(entry.get('timestamp'))

            return None, None

        except Exception as e:
            # Critical log to see why it crashed if it gets past the internal tries
            logger.error(f"get_current_price crash for {symbol}: {e}")
            return None, None
            
    async def place_order(self, symbol: str, side: str, quantity: float, order_type: str = "limit",  price: float = None, stop: float = None, duration: str = "day",
                          action: str = None, position_side: str = None, account_key: str="tra", reason: str = "") -> Dict:
        current_account.set(account_key)
        now = time.time()
        if symbol in self.rejection_cooldowns:            
            if now < self.rejection_cooldowns[symbol]:
                wait_remaining = int(self.rejection_cooldowns[symbol] - now)
                logger.warning(f"🚫 [BACK-OFF] Skipping {symbol}. Cooldown: {wait_remaining}s")
                return {}
        if not is_regular_trading_hours():
            logger.debug(f"[PLACE_ORDER] Not in trading hours, skipping order: {symbol} {action} {side} qty={quantity}")
            return {}
        client = TradierAPIClient(config, account_key=account_key)
        try:
            # 2. TRADEABILITY & HOURS CHECK
            if not self.is_symbol_tradeable(symbol, account_key, position_side):
                return {}
            
            if not is_regular_trading_hours(): 
                return {}

            await client.connect()

            # 3. PRICE & POSITION SIZING
            quote = await client.get_quote(symbol)
            if not quote: 
                return {}

            bid, ask = float(quote.get('bid', 0)), float(quote.get('ask', 0))
            last = float(quote.get('last', ask))
            
            # --- FETCH TRUE API HOLDINGS ---
            api_positions = await client.get_account_positions(account_key)
            pos_list =[]
            if isinstance(api_positions, dict):
                p = api_positions.get('positions', {})
                if isinstance(p, dict) and 'position' in p:
                    pos_list = p['position'] if isinstance(p['position'], list) else [p['position']]
                elif isinstance(p, list):
                    pos_list = p
            elif isinstance(api_positions, list):
                pos_list = api_positions

            # Determine API quantity based on intended position side
            current_qty = 0.0
            found_in_api = False
            has_opposing_in_api = False
            for p in pos_list:
                api_sym = p.get('symbol', '').strip().upper()
                if api_sym == symbol.strip().upper():
                    found_in_api = True
                    q = float(p.get('quantity', 0))
                    if (q > 0 and position_side == 'LONG') or (q < 0 and position_side == 'SHORT'):
                        current_qty = abs(q)
                        break
                    elif (q > 0 and position_side == 'SHORT') or (q < 0 and position_side == 'LONG'):
                        has_opposing_in_api = True
                        break
            if has_opposing_in_api and action in ["OPEN", "AUGMENT", "REENTER", "REENTRY", "QUICK_OPEN", "REVERSE", "HEDGE_OPEN"]:
                logger.critical(f"[OPPOSING_BLOCK] {account_key}:{symbol}_{position_side}: BLOCKED — API shows opposing position held. Cannot open {position_side} while opposite side exists in Tradier.")
                return {"errors": {"error": [f"Opposing position held in API for {symbol}"]}}

            is_exception = symbol.upper() in self.exceptions
            max_order = self.limit_exception_order if is_exception else self.limit_normal_order
            max_pos = self.limit_exception_total_pos if is_exception else self.limit_total_pos
            _ladder_parity = is_ordinary_ladder_target_reason(reason)
            _mandatory_reclaim = is_mandatory_reclaim_reason(reason)
            _absolute_target = _ladder_parity or _mandatory_reclaim
            if _absolute_target:
                _ladder_capacity = float(
                    _cfg(
                        "LR_BAND_LADDER_CAPACITY_USD",
                        16000.0,
                        account_key,
                        symbol,
                        position_side,
                    )
                )
                max_order = _ladder_capacity
                max_pos = _ladder_capacity

            # --- QUANTITY CALCULATION ---
            if action in ["OPEN", "AUGMENT", "REENTER", "REENTRY"]:
                remaining_usd = max(0, max_pos - (current_qty * last))
                base_target = (quantity * last) if quantity > 0 else config.START_POSITION_SIZE
                target_usd = (
                    base_target
                    if _absolute_target
                    else (base_target * 3.0 if is_exception else base_target)
                )
                calc_qty = int(min(target_usd, max_order, remaining_usd) / last)
            else:
                # EXITS: Strictly clamp to true API holdings to prevent rejection loops
                # Only "ghost clear" if we got a valid response and the symbol IS NOT in the API map for that side
                if not found_in_api or current_qty == 0:
                    if api_positions is None or (isinstance(api_positions, dict) and 'errors' in api_positions):
                         logger.warning(f"[{account_key}] ⚠️ API Check failed for {symbol} on {account_key}. Skipping exit attempt.")
                         return {}
                         
                    logger.warning(f"[{account_key}] 👻 GHOST POSITION DETECTED: {symbol} side {position_side} not held in API {account_key}. Faking close to clear local memory.")
                    held_symbols = [p.get('symbol') for p in pos_list if float(p.get('quantity', 0)) != 0]
                    logger.debug(f"[{account_key}] API Holdings for {account_key}: {held_symbols}")
                    return {"order": {"id": "GHOST_CLEARED", "status": "filled"}}
                
                calc_qty = int(min(quantity, current_qty))

            if calc_qty < 1: 
                logger.warning(f"[{account_key}] ⚠️ Order size too small: {calc_qty} shares ({symbol})")
                return {"errors": {"error":["Order size < 1"]}}

            # --- PREPARE SIDE ---
            tradier_side = None
            _ENTRY_ACTIONS = {"OPEN", "AUGMENT", "REENTER", "REENTRY", "QUICK_OPEN", "REVERSE", "HEDGE_OPEN"}
            _EXIT_ACTIONS = {"CLOSE", "REDUCE", "SELL", "PROFIT_TAKE", "HEDGE_CLOSE", "QUICK_CLOSE"}
            if action in _ENTRY_ACTIONS:
                tradier_side = "buy" if position_side == "LONG" else "sell_short"
            elif action in _EXIT_ACTIONS:
                tradier_side = "sell" if position_side == "LONG" else "buy_to_cover"
            else:
                logger.critical(f"[UNMAPPED_ACTION_BLOCK] {account_key}:{symbol}_{position_side}: action='{action}' not entry or exit — BLOCKING order")
                return {"errors": {"error": [f"Unmapped action: {action}"]}}

            # 4. THE 10-SECOND AGGRESSIVE CHASE LOOP
            loop_start = time.time()
            remaining_to_fill = calc_qty
            attempt = 0
            last_order_result = {}

            while (time.time() - loop_start) < 10 and remaining_to_fill > 0:
                attempt += 1
                q_loop = await client.get_quote(symbol)
                curr_bid, curr_ask = float(q_loop.get('bid', 0)), float(q_loop.get('ask', 0))
                
                # PRICE LOGIC: Aim for Midpoint + aggressive offset
                midpoint = (curr_bid + curr_ask) / 2
                if tradier_side in ["buy", "buy_to_cover"]:
                    # Buy at midpoint or slightly above to jump the queue
                    limit_price = round(midpoint + 0.01, 2)
                    if limit_price > curr_ask: limit_price = curr_ask
                else:
                    # Sell at midpoint or slightly below
                    limit_price = round(midpoint - 0.01, 2)
                    if limit_price < curr_bid: limit_price = curr_bid

                logger.info(f"[{account_key}] Loop Attempt {attempt}: {tradier_side} {symbol} {remaining_to_fill} @ {limit_price}")

                order_res = await client.place_order(
                    account_key=account_key, symbol=symbol, side=tradier_side,
                    quantity=remaining_to_fill, order_type="limit", price=limit_price, duration="day"
                )

                order_info = order_res.get('order', {})
                order_id = order_info.get('id')
                
                if not order_id or order_info.get('status') == 'rejected':
                    logger.error(f"❌ Rejection on {symbol}. Reason: {order_res.get('errors')}")
                    self.rejection_cooldowns[symbol] = time.time() + 900
                    return order_res

                # Wait short burst to see if it fills
                await asyncio.sleep(2.5)
                
                status_res = await client.get_order_status(account_key, order_id)
                status = status_res.get('status', '').lower()
                exec_qty = float(status_res.get('exec_quantity', 0))
                
                if status == 'filled':
                    logger.info(f"✅ Filled {symbol} via aggressive limit.")
                    return status_res
                
                # If not filled, cancel and loop back for a better price
                await client.cancel_order(account_key, order_id)
                remaining_to_fill -= exec_qty
                last_order_result = status_res
                logger.info(f"⏳ Partial Fill: {exec_qty}/{remaining_to_fill + exec_qty}. Re-calculating...")

            # 5. FINAL FALLBACK: MARKET ORDER (If still not filled after 10s)
            if remaining_to_fill > 0:
                logger.warning(f"🚨 Chase timeout for {symbol}. Executing MARKET ORDER for remaining {remaining_to_fill} qty.")
                market_res = await client.place_order(
                    account_key=account_key,
                    symbol=symbol,
                    side=tradier_side,
                    quantity=remaining_to_fill,
                    order_type="market",
                    duration="day"
                )
                return market_res

            return last_order_result

        except Exception as e:
            logger.error(f"[smart_place_order] Error: {e}",  exc_info=True )
            return {}
        finally:
            await client.close()

    def _infer_htf_direction_fast(self, is_long, k_5m, k_5m_prev, k_15m, k_15m_prev, d_15m, wt1_5m, wt2_5m, wt1_15m, wt2_15m, current_price, dc_basis_1h, dc_basis_4h, sma_200_15m, sma_200_1m, sma_200_1m_prev):
        """Fast inference of 1h/4h direction using shorter timeframe momentum - reduces lag by not waiting for hourly updates"""
        if is_long:
            momentum_5m = k_5m > k_5m_prev and k_5m < 50
            momentum_15m = k_15m > k_15m_prev and k_15m < 50
            wt_bullish = wt1_5m > wt2_5m and wt1_15m > wt2_15m
            price_above_dc1h = current_price >= dc_basis_1h
            price_above_dc4h = current_price >= dc_basis_4h
            price_above_sma = current_price > sma_200_15m and sma_200_1m_prev < sma_200_1m
            stoch_aligned = k_15m > d_15m
            score = sum([momentum_5m, momentum_15m, wt_bullish, price_above_dc1h, price_above_dc4h, price_above_sma, stoch_aligned])
            return score >= 4
        else:
            momentum_5m = k_5m < k_5m_prev and k_5m > 50
            momentum_15m = k_15m < k_15m_prev and k_15m > 50
            wt_bearish = wt1_5m < wt2_5m and wt1_15m < wt2_15m
            price_below_dc1h = current_price <= dc_basis_1h
            price_below_dc4h = current_price <= dc_basis_4h
            price_below_sma = current_price < sma_200_15m and sma_200_1m_prev > sma_200_1m
            stoch_aligned = k_15m < d_15m
            score = sum([momentum_5m, momentum_15m, wt_bearish, price_below_dc1h, price_below_dc4h, price_below_sma, stoch_aligned])
            return score >= 4

    def _infer_htf_reversal_fast(self, is_long, k_5m, k_5m_prev, k_15m, k_15m_prev, d_15m, wt1_5m, wt2_5m, wt1_15m, wt2_15m, current_price, dc_basis_1h, dc_basis_4h, sma_200_15m, sma_200_1m, sma_200_1m_prev):
        """Fast inference of 1h/4h momentum reversal using shorter timeframe data - detects if HTF momentum is weakening/reversing"""
        if is_long:
            momentum_reversing_5m = k_5m < k_5m_prev
            momentum_reversing_15m = k_15m < k_15m_prev
            wt_bearish = wt1_5m < wt2_5m or wt1_15m < wt2_15m
            price_below_dc1h = current_price < dc_basis_1h
            price_below_dc4h = current_price < dc_basis_4h
            price_below_sma = current_price < sma_200_15m or sma_200_1m_prev > sma_200_1m
            stoch_misaligned = k_15m < d_15m
            score = sum([momentum_reversing_5m, momentum_reversing_15m, wt_bearish, price_below_dc1h, price_below_dc4h, price_below_sma, stoch_misaligned])
            return score >= 3
        else:
            momentum_reversing_5m = k_5m > k_5m_prev
            momentum_reversing_15m = k_15m > k_15m_prev
            wt_bullish = wt1_5m > wt2_5m or wt1_15m > wt2_15m
            price_above_dc1h = current_price > dc_basis_1h
            price_above_dc4h = current_price > dc_basis_4h
            price_above_sma = current_price > sma_200_15m or sma_200_1m_prev < sma_200_1m
            stoch_misaligned = k_15m > d_15m
            score = sum([momentum_reversing_5m, momentum_reversing_15m, wt_bullish, price_above_dc1h, price_above_dc4h, price_above_sma, stoch_misaligned])
            return score >= 3

    async def _maybe_restart_indicators(self, reason: str) -> None:
        """Simplified indicator restart for Tradier"""
        logger.warning(f"[INDICATOR_HEALTH] Potential indicator issue detected: {reason}")

    async def clear_recent_signal(self, position_key: str):
        """Placeholder for clearing recent signal cache"""
        self.recently_processed_signals.pop(position_key, None)

    async def clear_all_cooldowns_for_position(self, position_key: str, side: str = None):
        """Clear ALL cooldown-related data for a position"""
        try:
            self.recently_queued_signals.pop(position_key, None)
            self.augmentation_cooldown_map.pop(position_key, None)
            self.reduction_cooldown_map.pop(position_key, None)
            await self.clear_recent_signal(position_key)
            if hasattr(self, 'orders_in_limbo') and position_key in self.orders_in_limbo:
                if side:
                    self.orders_in_limbo[position_key].pop(side, None)
                    if not self.orders_in_limbo[position_key]:
                        del self.orders_in_limbo[position_key]
                else:
                    del self.orders_in_limbo[position_key]
            logger.debug(f"[CLEAR_ALL_COOLDOWNS] {position_key}: Cleared all cooldown data (side={side})")
        except Exception as e:
            logger.warning(f"[CLEAR_ALL_COOLDOWNS] {position_key}: Error clearing cooldowns: {e}")

    def _robust_json_decode(self, content):
        """Robust JSON decoder for tradeable keys and other files"""
        try:
            if isinstance(content, bytes):
                content = content.decode('utf-8')
            return json.loads(content)
        except Exception as e:
            logger.error(f"JSON Decode Error: {e}")
            return None

    async def load_tradeable(self):
        """Load tradeable keys from tradeable_keys.json"""
        current_time = time.time()
        if hasattr(self, 'tradeable_keys') and self.tradeable_keys and (current_time - self._last_tradeable_update < 180):
            return list(self.tradeable_keys)

        async with self.tradeable_lock:
            if hasattr(self, 'tradeable_keys') and self.tradeable_keys and (current_time - self._last_tradeable_update < 180):
                return list(self.tradeable_keys)

            temp_keys = set()
            # 1. Try Redis
            if self.redis_manager:
                try:
                    redis_data = await asyncio.wait_for(self.redis_manager.get("tradeable_keys"), timeout=0.5)
                    if redis_data:
                        data = self._robust_json_decode(redis_data)
                        if isinstance(data, list):
                            temp_keys = {str(k).strip() for k in data}
                except Exception: pass

            # 2. Try File
            if not temp_keys:
                main_path = self.config.BASE_PATH / "tradeable_keys.json"
                if main_path.exists():
                    try:
                        async with aiofiles.open(main_path, "r") as f:
                            content = await f.read()
                            data = self._robust_json_decode(content)
                            if isinstance(data, list):
                                temp_keys = {str(k).strip() for k in data}
                    except Exception as e:
                        logger.error(f"[SYMBOLS] Error loading tradeable_keys.json: {e}")

            if temp_keys:
                self.tradeable_keys = temp_keys
                self._last_tradeable_update = current_time
            return list(self.tradeable_keys)

    def _get_json_symbols(self, account_key: str, side: str) -> set:
        # 2026-05-07: JSON files (symbols_<acc>_<side>.json) are the source of truth — refreshed every ~10 min by tradier_rankings. Memory list was being wiped between LOAD and CHECK, blocking 99% of approved syms (only 5 fresh OPENs in 30 days). Read directly with 30s TTL cache.
        cache = getattr(self, '_json_symbols_cache', None)
        if cache is None:
            cache = {}
            self._json_symbols_cache = cache
        key = (account_key, side)
        now = time.time()
        cached = cache.get(key)
        if cached and cached[1] > now:
            return cached[0]
        try:
            base = Path(self.config.BASE_PATH)
            paths = []
            if account_key == 'tra' and getattr(self.config, 'TRA_SATOSHIT_ONLY', False):
                paths.append(base / f"symbols_tra_satoshit_{side}.json")
            paths.append(base / f"symbols_{account_key}_{side}.json")
            syms = set()
            for path in paths:
                if path.exists():
                    with open(path, 'r') as fh:
                        raw = json.load(fh)
                    if isinstance(raw, list):
                        syms = {str(s).upper().strip() for s in raw if s}
                    elif isinstance(raw, dict):
                        syms = {str(k).upper().strip() for k in raw.keys() if k}
                    if syms:
                        break
        except Exception as e:
            if cached:
                return cached[0]
            logger.warning(f"[_get_json_symbols] {account_key}/{side} read failed: {e}")
            syms = set()
        cache[key] = (syms, now + 30.0)
        return syms

    def is_symbol_tradeable(self, symbol: str, account_key: str, side: str) -> bool:
        """Centralized tradeability check with debug logging."""
        symbol = symbol.upper()
        if not side:
            side = "LONG"
        side = side.upper()

        # tra is a CASH (non-margin) account — shorts are physically impossible.
        # The check goes BEFORE blacklist/whitelist so even ALWAYS_TRADEABLE
        # symbols cannot be shorted on tra.
        if account_key == 'tra' and side == 'SHORT' and getattr(config, 'TRA_LONG_ONLY', True):
            return False

        # 1. Blacklist
        if symbol in self.blacklist:
            return False

        # 2. Hard non-shortable list (Tradier-side restriction; not overridable)
        if side == 'SHORT' and symbol in self.non_shortable_symbols:
            return False

        # 3. Same-side discovery list is the SOLE permission for new entries.
        #    Callers that need to manage (close/reduce) an existing position must NOT route through
        #    this function — the caller already bypasses is_symbol_tradeable when _is_exit_or_reduce
        #    (see execute_trade_action ~line 8690, execute_now ~line 9203). The previous code path
        #    "if positionAmt > 0 → return True" became a self-perpetuating opener: once one share
        #    leaked through (via ALWAYS_TRADEABLE bypass or any other mechanism), this branch said
        #    "we have a position, so OPEN/AUGMENT is allowed" — which is exactly how the MU_SHORT
        #    accumulated to 14 shares. Killed 2026-05-11.
        side_lower = 'long' if side == 'LONG' else 'short'
        json_syms = self._get_json_symbols(account_key, side_lower)
        mem_syms = {s.upper() for s in getattr(self, f"symbols_{side_lower}_{account_key}", [])}
        same_side_syms = json_syms | mem_syms

        if symbol not in same_side_syms:
            return False

        # 3b. 2026-05-28 USER: honor per-sym LONG_ENABLED/SHORT_ENABLED=False (injected for
        #     neg-Sharpe (sym,side) by _inject_neg_sharpe_no_trade). Was injected but NEVER
        #     enforced — IBIT_LONG (LONG_ENABLED:False) kept churning. Gate NEW entries only;
        #     exits/reduces bypass is_symbol_tradeable so existing positions can still be closed.
        _ist_side_enabled = _cfg("LONG_ENABLED" if side == "LONG" else "SHORT_ENABLED", True, account_key, symbol, side)
        if _ist_side_enabled is False:
            logger.info(f"[{account_key}] ⛔ {symbol} {side}: {'LONG' if side == 'LONG' else 'SHORT'}_ENABLED=False (neg-Sharpe/disabled) — no new entry/reentry")
            return False
        # 2026-08-14 USER: TIM 95-99 never opens, DD<30, >10 trades/yr, V8 verified only tomorrow
        if _v8_verified_gate_enabled() and account_key == "trb":
            # Load per-sym entry for this sym/side
            try:
                _e = _load_tradier_per_sym_cfgs(p / "data" / "hourly_reconfig" / account_key / "active_config.json").get(f"{symbol}_{side}", {}) if False else None
            except Exception:
                _e = None
            # Use unified loader path
            try:
                from pathlib import Path as _P
                import json as _js
                _cfg_path = _P(__import__("config").BASE_PATH) / "data" / "hourly_reconfig" / account_key / "active_config.json"
                with _cfg_path.open() as _f:
                    _raw = _js.load(_f)
                _entry = _raw.get(f"{symbol}_{side}", {})
            except Exception:
                _entry = {}
            if not _is_v8_verified_entry(_entry):
                logger.info(f"[{account_key}] ⛔ {symbol} {side}: V8_NOT_VERIFIED_TEMP_ALLOWED (needs backtest_v8_engine exact) — no new entry until verified")
                return False
            _ok, _reason = _passes_basic_risk_gates(_entry)
            if not _ok:
                logger.info(f"[{account_key}] ⛔ {symbol} {side}: BASIC_GATE_FAIL {_reason} — no new entry")
                return False

        # 3c. 2026-07-20 USER: trc is a TEMPORARY live A/B control arm that must trade ONLY
        #     trb's symbols that also have real per_sym + 7D-overlay results for trc itself
        #     (data/hourly_reconfig/trc/active_config.json). symbols_trc_long/short.json
        #     (step 3 above) is meant to mirror trb's fully-processed universe but the
        #     ranking pipeline that maintains it has been stalling — that let trc hold a
        #     tradeable symbol (e.g. UUUU) with no trc-specific per_sym+7D result behind it.
        #     Gate NEW entries only; exits/reduces bypass is_symbol_tradeable so existing
        #     positions can still be closed.
        if account_key == 'trc':
            _base = Path(config.BASE_PATH) / "data"
            _trb_cfgs = _load_tradier_per_sym_results(_base / "hourly_reconfig" / "trb" / "active_config.json")
            _trc_cfgs = _load_tradier_per_sym_results(_base / "hourly_reconfig" / "trc" / "active_config.json")
            _trb_symbols = self._get_json_symbols("trb", "long" if side == "LONG" else "short")
            if not per_sym_overlay_is_approved(
                symbol,
                side,
                trb_configs=_trb_cfgs,
                trc_configs=_trc_cfgs,
                trb_symbols=_trb_symbols,
            ):
                logger.info(f"[trc] ⛔ {symbol} {side}: requires TRB universe approval plus positive TRB and TRC 7D/per-sym results — no new entry/reentry")
                return False

        # 4. ALWAYS_TRADEABLE/EXCEPTIONS are now only an enabler ON TOP of same_side_syms —
        #    they were already de-fanged in step 3, but kept here for any future restrictive use.
        return True

    async def execute_trade_action(self, account_key, position_key, symbol, quantity, current_price, side, position_side, unique_id, is_full_close=False, action='', reason='', override_qty=None):
        if not is_regular_trading_hours(): return "MARKET_CLOSED"
        current_account.set(account_key)
        _is_exit_or_reduce = action in ('REDUCE', 'CLOSE', 'FULL_CLOSE', 'PROFIT_TAKE', 'QUICK_CLOSE')
        if symbol.upper() in self.blacklist and not _is_exit_or_reduce:
            logger.critical(f"[{account_key}] 🛑 CRITICAL: Attempted to trade BLACKLISTED symbol {symbol}. ACTION BLOCKED.")
            return "BLOCKED_BLACKLIST"

        # 1. Variables and Flags
        is_long = position_side == 'LONG'
        is_entry_action = action in ['OPEN', 'REENTRY', 'QUICK_OPEN', 'REVERSE', 'HEDGE_OPEN']
        is_reduce = action in ['REDUCE', 'PROFIT_TAKE']
        is_exit_action = action in ['CLOSE', 'FULL_CLOSE', 'PROFIT_TAKE', 'REDUCE']
        is_hedge = action in ['HEDGE_OPEN', 'HEDGE_CLOSE']
        _is_mandatory_reclaim = is_mandatory_reclaim_reason(reason)
        _is_ladder_parity_route = is_ordinary_ladder_target_reason(reason)
        hedge_for = None # Tradier logic usually doesn't use hedge_for like ez_manage
        # HARD RISK CEILING: no new exposure once broker equity is 50% below
        # its persisted high-water mark. Reductions/closes remain available.
        if not _is_exit_or_reduce and action != 'HEDGE_CLOSE':
            _dd_ok, _dd_tag = await self._check_live_drawdown_ceiling(account_key)
            if not _dd_ok:
                logger.critical(f'[{account_key}] [DRAWDOWN_CEILING_BLOCK] {position_key}: {action} refused: {_dd_tag}')
                return f'BLOCKED_{_dd_tag}'
        # BACKTEST_CHANGE_T31: hedge disabled, negative EV in all 5 backtest configs
        if is_hedge and not getattr(config, 'HEDGE_MODE_TRADIER', True):
            logger.info(f"[{account_key}] [HEDGE_DISABLED] Blocking {action} for {symbol}: HEDGE_MODE_TRADIER=False")
            return "BLOCKED_HEDGE_DISABLED"
        # tra is a CASH account — block any SHORT order at the execution layer too,
        # so even if a stale code path reaches here, no sell_short ever leaves the box.
        # Exits/closes on existing shorts are still permitted (in case any old positions exist).
        if not _is_exit_or_reduce and account_key == 'tra' and position_side == 'SHORT' and getattr(config, 'TRA_LONG_ONLY', True):
            logger.warning(f"[tra] ⛔ EXECUTE BLOCK {symbol} SHORT: tra is a CASH (non-margin) account — shorts are not permitted (TRA_LONG_ONLY=True)")
            return "BLOCKED_TRA_LONG_ONLY"
        # Tradeability Check — exits/reduces always allowed (you must be able to close any position)
        if not _is_exit_or_reduce and not self.is_symbol_tradeable(symbol, account_key, position_side):
            logger.warning(f"[{account_key}] ⛔ EXECUTE BLOCK {symbol} {position_side}: Not in approved list.")
            return "BLOCKED_NOT_TRADEABLE"
        # 2026-04-26 Per-sector L/S ratio check — block opens that worsen sector imbalance
        if (is_entry_action and not _is_mandatory_reclaim and not _is_ladder_parity_route and not is_hedge and not _is_exit_or_reduce and _SECTOR_LS_MODULE_AVAILABLE
            and getattr(config, 'SECTOR_LS_RATIO_ENABLED', False)):
            try:
                # Build positions dict in {pk: {positionAmt}} format
                _all_pos = {}
                for _pk, _p in (self.position_manager.positions if self.position_manager else {}).items():
                    _all_pos[_pk] = {'positionAmt': float(getattr(_p, 'positionAmt', 0) or 0)}
                _slr_ok, _slr_reason = check_sector_ls_ratio(account_key, symbol, position_side, _all_pos, config, is_hedge=is_hedge)
                if not _slr_ok:
                    logger.warning(f"[{account_key}] ⛔ {_slr_reason}")
                    return f"BLOCKED_SECTOR_LS_{_slr_reason}"
            except Exception as _slr_e:
                logger.warning(f"[{account_key}] [SECTOR_LS] check failed: {_slr_e}")

        # 2. Indicators Fetch & Unpack
        i = self.get_indicators(symbol)
        if not i and not _is_mandatory_reclaim:
            logger.error(f"[EXECUTE_DEBUG] {symbol}: NO_INDICATORS")
            return "NO_INDICATORS"
        i = i or {}

        # Map 5m to 3m for logic compatibility if needed, though we'll use 5m variables directly
        def g(k, default=0.0): return float(i.get(k, default))
        def gs(k, default='neutral'): return str(i.get(k, default))
        
        timestamp_str = i.get('timestamp', '')
        timestamp = safe_datetime(timestamp_str)
        
        # Unpack variables (Using 5m instead of 3m as per user instruction)
        k_1m, k_1m_prev, d_1m = g('k_1m', 50), g('k_1m_prev', 50), g('d_1m', 50)
        k_5m, k_5m_prev, d_5m = g('k_5m', 50), g('k_5m_prev', 50), g('d_5m', 50)
        k_15m, k_15m_prev, d_15m = g('k_15m', 50), g('k_15m_prev', 50), g('d_15m', 50)
        k_1h, k_1h_prev, d_1h = g('k_1h', 50), g('k_1h_prev', 50), g('d_1h', 50)
        k_4h, k_4h_prev, d_4h = g('k_4h', 50), g('k_4h_prev', 50), g('d_4h', 50)
        k_D, k_D_prev, d_D = g('k_D', 50), g('k_D_prev', 50), g('d_D', 50)

        wt1_5m, wt2_5m = g('wt1_5m'), g('wt2_5m')
        wt1_15m, wt2_15m = g('wt1_15m'), g('wt2_15m')
        wt1_1h, wt2_1h = g('wt1_1h'), g('wt2_1h')
        
        sma_200_1m, sma_200_1m_prev = g('sma_200_1m'), g('sma_200_1m_prev')
        sma_200_15m, sma_200_15m_prev = g('sma_200_15m'), g('sma_200_15m_prev')
        sma_200_1h = g('sma_200_1h')
        
        dc_basis_5m, dc_basis_15m, dc_basis_1h, dc_basis_4h = g('dc_basis_5m'), g('dc_basis_15m'), g('dc_basis_1h'), g('dc_basis_4h')
        dc_high_5m, dc_low_5m = g('dc_high_5m'), g('dc_low_5m')
        dc_high_15m, dc_low_15m = g('dc_high_15m'), g('dc_low_15m')
        dc_high_1h, dc_low_1h = g('dc_high_1h'), g('dc_low_1h')
        dc_high_4h, dc_low_4h = g('dc_high_4h'), g('dc_low_4h')
        
        dc_high_5m_ant, dc_low_5m_ant = g('dc_high_5m_ant', dc_high_5m), g('dc_low_5m_ant', dc_low_5m)
        dc_high_15m_ant, dc_low_15m_ant = g('dc_high_15m_ant', dc_high_15m), g('dc_low_15m_ant', dc_low_15m)
        dc_high_1h_ant, dc_low_1h_ant = g('dc_high_1h_ant', dc_high_1h), g('dc_low_1h_ant', dc_low_1h)
        dc_high_4h_ant, dc_low_4h_ant = g('dc_high_4h_ant', dc_high_4h), g('dc_low_4h_ant', dc_low_4h)
        dc_basis_15m_ant = g('dc_basis_15m_ant', dc_basis_15m)
        
        dc_high4_5m, dc_low4_5m = g('dc_high4_5m'), g('dc_low4_5m')
        high_5m, low_5m, high_5m_prev, low_5m_prev = g('high_5m'), g('low_5m'), g('high_5m_prev'), g('low_5m_prev')
        high_15m, low_15m = g('high_15m'), g('low_15m')
        high_1h, low_1h, high_1h_prev, low_1h_prev = g('high_1h'), g('low_1h'), g('high_1h_prev'), g('low_1h_prev')
        high_4h, low_4h, high_4h_prev, low_4h_prev = g('high_4h'), g('low_4h'), g('high_4h_prev'), g('low_4h_prev')
        
        ha_5m, ha_15m, ha_1h, ha_4h = gs('ha_5m'), gs('ha_15m'), gs('ha_1h'), gs('ha_4h')
        atr_5m, atr_15m = g('atr_5m'), g('atr_15m')
        t_up_5m = i.get('t_up_5m', False)

        # ═══ TRADIER V1: ZONE GATE + ALIGNMENT ═══
        # Primary TF = 1h for swing. During market open (9:30-10:00) and last 2h (14:00-16:00) use 15m for faster entries.
        _is_reentry = action == 'REENTRY' or 'REENTRY' in (reason or '').upper()
        _is_augment_or_entry = not _is_exit_or_reduce
        _reason_upper = (reason or '').upper()
        _is_rotation = 'ROTATION_ENTRY' in _reason_upper
        _is_rsi2 = 'RSI2_MEAN_REVERSION' in _reason_upper
        _is_gap_fill = 'GAP_FILL' in _reason_upper
        _is_ladder_parity = _is_ladder_parity_route
        _is_contract_target = _is_ladder_parity or _is_mandatory_reclaim
        # RZ baseline / red zone entries: bounce logic in wt_dc_delta._run_redzone
        # already validates HTF alignment + LTF velocity bounce. Skip the broad
        # alignment counter (which would never be satisfied at the bounce moment
        # since the WT cross hasn't completed yet — that's the whole point of
        # trading the pullback bounce, not waiting for the cross).
        _is_rz_entry = (
            _reason_upper.startswith('RZ_')
            or 'DELTA_ENTRY' in _reason_upper
            or 'RED_ZONE' in _reason_upper
            or 'BASELINE_BOUNCE' in _reason_upper
            or 'BREAKDOWN_TRUCK' in _reason_upper
            or 'BOTTOM_HUGE' in _reason_upper
            or 'REJECTION_OLD_REDZONE' in _reason_upper
            or 'TRUCK_LOAD' in _reason_upper
        )
        _is_proven_strategy = _is_rotation or _is_rsi2 or _is_gap_fill or _is_rz_entry
        try:
            from zoneinfo import ZoneInfo; _now_est = datetime.now(ZoneInfo("America/New_York")).time()
        except ImportError:
            import pytz; _now_est = datetime.now(pytz.timezone("America/New_York")).time()
        _is_fast_window = (dt_time(9, 30) <= _now_est <= dt_time(10, 0)) or (dt_time(14, 0) <= _now_est <= dt_time(16, 0))
        _zone_k = k_15m if _is_fast_window else k_1h
        _zone_tf = '15m' if _is_fast_window else '1h'
        # USER 2026-06-03 "make trades HAPPEN": the with-trend WT_3M_FORCE_OPEN build (above 200MA +
        # WT-favor) must NOT be killed by the ZONE / 10-of-13 ALIGNMENT / DC4 entry gates — those are
        # what blocked MRVL et al. The force-open's own gate (above-MA + WT not-against) IS the entry test.
        _is_wf_force = _is_contract_target or (
            ('WT_3M_FORCE_OPEN' in _reason_upper)
            and bool(
                _cfg(
                    'WT_3M_FORCE_OPEN_BYPASS_GATES',
                    True,
                    account_key,
                    symbol,
                    position_side,
                )
            )
        )
        if _is_augment_or_entry and not is_hedge and not _is_wf_force:
            _ez = getattr(self.config, 'ENTRY_ZONE_LONG', 22.0); _esz = getattr(self.config, 'ENTRY_ZONE_SHORT', 100.0 - _ez)
            if action in ('OPEN', 'QUICK_OPEN') and not _is_reentry and not _is_rotation and not _is_gap_fill and not _is_rz_entry:
                if (is_long and _zone_k > _ez) or (not is_long and _zone_k < _esz):
                    logger.warning(f"[TRADIER_ZONE_BLOCK] {position_key}: k_{_zone_tf}={_zone_k:.0f} outside zone {_ez}/{_esz} ({'FAST' if _is_fast_window else 'SWING'})")
                    return f"BLOCKED_ZONE_k{_zone_tf}={_zone_k:.0f}"
            # Alignment: count conditions agreeing with direction
            _al = 0
            for _k, _d in [(k_15m,d_15m),(k_1h,d_1h),(k_4h,d_4h),(k_D,d_D)]:
                if (is_long and _k > _d) or (not is_long and _k < _d): _al += 1
            for _ha in [ha_5m, ha_15m, ha_1h, ha_4h]:
                if (is_long and _ha == 'green') or (not is_long and _ha == 'red'): _al += 1
            for _dcb in [dc_basis_15m, dc_basis_1h, dc_basis_4h]:
                if _dcb > 0 and ((is_long and current_price > _dcb) or (not is_long and current_price < _dcb)): _al += 1
            for _w1, _w2 in [(wt1_5m,wt2_5m),(wt1_15m,wt2_15m),(wt1_1h,wt2_1h)]:
                if (is_long and _w1 > _w2) or (not is_long and _w1 < _w2): _al += 1
            _rsi_1h = g('rsi_1h', 50); _rsi_4h = g('rsi_4h', 50)
            if (is_long and _rsi_1h > 50) or (not is_long and _rsi_1h < 50): _al += 1
            if (is_long and _rsi_4h > 50) or (not is_long and _rsi_4h < 50): _al += 1
            if sma_200_1h > 0 and ((is_long and current_price > sma_200_1h) or (not is_long and current_price < sma_200_1h)): _al += 1
            _min_al = 6 if _is_proven_strategy else getattr(self.config, 'ENTRY_MIN_ALIGNMENT', 10)
            # TF_ALIGNMENT_MIN_* switches: exit-side (used by sweep — read here for sweep visibility, no-op on entry)
            _tf_align_long = getattr(self.config, 'TF_ALIGNMENT_MIN_LONG', 2)
            _tf_align_short = getattr(self.config, 'TF_ALIGNMENT_MIN_SHORT', 2)
            _tf_focus_weight = getattr(self.config, 'TF_FOCUS_WEIGHT', 8.0)  # Focus-TF weight (read for sweep)
            _tf_htf1 = getattr(self.config, 'TF_HTF1', '1h')  # HTF1 name (read for sweep)
            _tf_htf3 = getattr(self.config, 'TF_HTF3', 'D')   # HTF3 name (read for sweep)
            _tf_macro = getattr(self.config, 'TF_MACRO', 'D') # Macro name (read for sweep)
            _tf_focus_entry_gate = getattr(self.config, 'TF_FOCUS_ENTRY_HARD_GATE', True)  # Focus entry hard gate (read for sweep)
            _tf_focus_exit_gate = getattr(self.config, 'TF_FOCUS_EXIT_HARD_GATE', True)  # Focus exit hard gate (read for sweep)
            if _is_reentry:
                if _al >= _min_al: quantity = quantity * min(1.5, 1.0 + (_al - _min_al) * 0.05)
            elif not _is_reentry and 'RATIO_RECOVERY' not in _reason_upper:
                # parity fix 2026-08-13: bypass alignment gate for V8 ladder parity (vector has no alignment gate)
                _v8_parity_bypass_al = os.environ.get("V8_BACKTEST_BYPASS_DRAWDOWN") == "1" or bool(os.environ.get("V8_LADDER_ONLY_SIDE"))
                if _al < _min_al and not _v8_parity_bypass_al:
                    logger.warning(f"[TRADIER_ALIGNMENT_BLOCK] {position_key}: alignment={_al}/{_min_al}{' (relaxed)' if _is_proven_strategy else ''}")
                    return f"BLOCKED_ALIGNMENT_{_al}/{_min_al}"
            # dc_low4 hard bottom (applies to all entries including reentries)
            # 2026-07-21 USER band mandate: MTF_ARROW/LR_BAND entries BUY swing bottoms by
            # design (band+slope gated upstream) — the falling-knife block structurally
            # starves them, same class as the MTF armed-state gate (bypassed 2026-07-20).
            _band_entry_etf = 'MTF_ARROW' in (reason or '') or 'LR_BAND' in (reason or '')
            _dc4l_5m = dc_low4_5m; _dc4h_5m = dc_high4_5m
            # parity fix 2026-08-13: V8 backtest ladder parity — bypass DC4_5m bottom/top gate when V8_BACKTEST_BYPASS_DRAWDOWN or V8_LADDER_ONLY_SIDE set so vector/live second trade matches
            _v8_parity_bypass_dc4 = os.environ.get("V8_BACKTEST_BYPASS_DRAWDOWN") == "1" or bool(os.environ.get("V8_LADDER_ONLY_SIDE"))
            if is_long and _dc4l_5m > 0 and current_price < _dc4l_5m and not _band_entry_etf and not _v8_parity_bypass_dc4:
                logger.warning(f"[TRADIER_DC4_BLOCK] {position_key}: price {current_price:.2f} < dc_low4_5m {_dc4l_5m:.2f}")
                return f"BLOCKED_DC4_BOTTOM"
            if not is_long and _dc4h_5m > 0 and current_price > _dc4h_5m and not _v8_parity_bypass_dc4:
                logger.warning(f"[TRADIER_DC4_BLOCK] {position_key}: price {current_price:.2f} > dc_high4_5m {_dc4h_5m:.2f}")
                return f"BLOCKED_DC4_TOP"
        # 3. Price Fetch & Validation
        current_price, _ = await self.get_current_price(symbol)
        current_price = float(current_price) if current_price is not None else 0.0
        if current_price <= 0: return "NO_PRICE"

        # HARD NOTIONAL CEILING — applies at the final execution seam to every
        # exposure-increasing action, including routes that intentionally bypass
        # MAX_ORDER_VALUE (force-open/ladder/reclaim).  The old cap lived in the
        # sizing queue and could be bypassed by an absolute-target route; that is
        # how a whole-share GOOGL order could become ~$9k despite the $2.5k TRB
        # symbol limit.  Existing exposure is included, so this cannot pyramid
        # past the ceiling through repeated fills.
        if action in ('OPEN', 'REENTRY', 'QUICK_OPEN', 'REVERSE', 'HEDGE_OPEN', 'AUGMENT', 'QUICK_AUGMENT') and not _is_exit_or_reduce:
            _hard_account_cap = float(getattr(
                config, f"{str(account_key).upper()}_MAX_SYMBOL_VALUE",
                getattr(config, "MAX_SYMBOL_VALUE_TRADIER", 3750.0),
            ) or 0.0)
            _hard_global_cap = float(getattr(config, "HARD_MAX_SYMBOL_VALUE_TRADIER", 2500.0) or 0.0)
            _hard_cap = max(0.0, min(_hard_account_cap, _hard_global_cap))
            _hard_pos = self.position_manager.positions.get(position_key) if self.position_manager else None
            _hard_existing_qty = abs(float(getattr(_hard_pos, "positionAmt", 0) or 0))
            _hard_broker_qty = 0.0
            try:
                _snap = (getattr(self, "_broker_preflight_cache", {}) or {}).get(account_key, {})
                for _bp in (_snap.get("positions") or []):
                    if str(_bp.get("symbol", "")).upper() != symbol.upper():
                        continue
                    _bq = float(_bp.get("quantity", 0) or 0)
                    if (position_side == "LONG" and _bq > 0) or (position_side == "SHORT" and _bq < 0):
                        _hard_broker_qty = abs(_bq)
                        break
            except Exception:
                pass
            _hard_held_qty = max(_hard_existing_qty, _hard_broker_qty)
            _hard_room_qty = int(max(0.0, (_hard_cap / current_price) - _hard_held_qty + 1e-9))
            if _hard_room_qty <= 0:
                logger.critical(f"[HARD_SYMBOL_CAP] {position_key}: held={_hard_held_qty:.4f} @ {current_price:.4f} already reaches ${_hard_cap:.2f}; blocking {action}")
                return "BLOCKED_HARD_SYMBOL_NOTIONAL_CAP"
            if float(quantity) > _hard_room_qty:
                logger.critical(f"[HARD_SYMBOL_CAP] {position_key}: clamping {action} qty {quantity}→{_hard_room_qty}; held={_hard_held_qty:.4f}, cap=${_hard_cap:.2f}, px=${current_price:.4f}")
                quantity = _hard_room_qty

        # Universal entry boundary: every non-exit route, including augments,
        # force-open, ladder, reclaim, and advisory entries, must respect the
        # live 4h Donchian boundary.  Missing 4h data fails closed.
        # parity fix 2026-08-13: bypass for V8 ladder parity (vector has no 4h gate)
        _v8_parity_bypass_dc4h = os.environ.get("V8_BACKTEST_BYPASS_DRAWDOWN") == "1" or bool(os.environ.get("V8_LADDER_ONLY_SIDE"))
        if account_key in {"trb", "trc"} and not _is_exit_or_reduce and action != "HEDGE_CLOSE" and not _v8_parity_bypass_dc4h:
            _dc4_block, _dc4_detail = dc_4h_boundary_breached(
                current_price, position_side, i, require_level=True
            )
            if _dc4_block:
                logger.critical(
                    f"🛑 [ENTRY_DC4H_SAFETY] {position_key}: {_dc4_detail} — entry blocked"
                )
                return f"BLOCKED_ENTRY_DC4H_{_dc4_detail}"

        position = self.get_position(position_key)
        has_local_pos = position and abs(float(getattr(position, 'positionAmt', 0))) > 0.00001

        # ═══ REENTRY = positionAmt==0 ONLY (user 2026-05-06) — REFUSE if non-flat ═══
        # REENTRY is NOT an augment. AUGMENT is its own path. Empty positions have no
        # gain so REENTRY's only valid state is positionAmt==0. NEVER reclassify.
        if action == "REENTRY" and has_local_pos:
            _re_amt_t = abs(float(getattr(position, 'positionAmt', 0))) if position else 0.0
            logger.critical(f"🚫 [TRADIER_REENTRY_REFUSED_NONZERO_AMT] {position_key}: positionAmt={_re_amt_t:.6f} — REENTRY only valid on flat. reason={(reason or '')[:80]}")
            return f"BLOCKED_REENTRY_POS_AMT_NONZERO_{_re_amt_t:.6f}"
        if action == "REENTRY":
            action = "OPEN"
            is_entry_action = True

        # Auto-switch AUGMENT to OPEN if no position exists
        if action == "AUGMENT" and not has_local_pos:
            logger.info(f"[{position_key}] Switching AUGMENT to OPEN (No local position found)")
            action = "OPEN"
            is_entry_action = True

        is_valid, validation_reason, actual_qty = await self.validate_position_before_trade(position_key, action, quantity)
        if not is_valid: return f"VALIDATION_FAILED:{validation_reason}"
        if validation_reason == "ADJUSTED_QTY" and actual_qty: quantity = actual_qty

        if position is None:
            position = await self.ensure_position_present(account_key, symbol, position_side, position_key)
            if not position:
                logger.error(f"[TRADE] {position_key}: Position not found in memory or disk — cannot execute trade without position data")
                return "POSITION_NOT_FOUND"

        # 4. Entry/Augment Blockers — REENTRY and WT_D_BOUNCE_AUG are EXEMPT
        _is_wt_d_aug = "WT_D_BOUNCE_AUG" in str(reason)
        # USER 2026-06-03 "keep getting bigger on every favorable WT bounce, NO EXCEPTIONS": the
        # with-trend WT_3M_FORCE_OPEN build is add-to-STRENGTH (gated above-200MA + WT-favor upstream),
        # NOT martingale — so it is exempt from the MIN_GAIN augment wall like REENTRY/WT_D_BOUNCE_AUG.
        _is_wf_force_aug = ("WT_3M_FORCE_OPEN" in str(reason).upper()) and bool(_cfg(
            'WT_3M_FORCE_OPEN_BYPASS_GATES', True,
            account_key, symbol, position_side,
        ))
        _is_wf_force_aug = _is_wf_force_aug or _is_ladder_parity
        if action == "AUGMENT" and not _is_reentry and not _is_wt_d_aug and not _is_wf_force_aug and getattr(config, 'AUGMENT_ONLY_WHEN_PROFITABLE_TRADIER', True) and position.gain < 0:
            logger.warning(f"[AUGMENT_PROFITABLE_ONLY] {position_key}: BLOCKED — losing position (gain={position.gain:.2f}%)")
            return "BLOCKED_NO_GAIN"
        if action == "AUGMENT" and not _is_reentry and not _is_wt_d_aug and not _is_wf_force_aug and position.gain <= 0:
            logger.warning(f"[{account_key}] BLOCKED AUGMENT {symbol}: Gain is {position.gain:.2f}% (Must be > 0%)")
            return "BLOCKED_NO_GAIN"
        # AUGMENT GUARD — NEVER augment an EXISTING position below MIN_GAIN (3%). The 0.5*MIN_GAIN rule
        # is ONLY for a BOUNCE reentry (an OPEN), never an augment or breakout (USER 2026-05-30).
        # REENTRY of a flat position is exempt via _is_reentry below — it OPENs at gain==0, no gain wait.
        _min_aug_gain = getattr(config, 'MIN_GAIN', 3.0)
        if action == "AUGMENT" and not _is_reentry and not _is_wt_d_aug and not _is_wf_force_aug and position.gain < _min_aug_gain:
            logger.warning(f"[AUGMENT_MIN_GAIN_BLOCK] {position_key}: gain={position.gain:.2f}% < {_min_aug_gain}% — BLOCKED")
            return f"BLOCKED_MIN_GAIN_{position.gain:.2f}pct<{_min_aug_gain}pct"
        # HARD WALL: position already open → NO buy of any kind without MIN_GAIN. No exceptions.
        _pos_qty_hw = abs(float(getattr(position, 'positionAmt', 0) or 0))
        if not is_exit_action and not _is_wt_d_aug and not _is_wf_force_aug and _pos_qty_hw > 0 and position.gain < _min_aug_gain:
            logger.warning(f"[HARD_MIN_GAIN_WALL] {position_key}: positionAmt={_pos_qty_hw} gain={position.gain:.2f}% < {_min_aug_gain}% — BLOCKED action={action}")
            return f"BLOCKED_MIN_GAIN_WALL_{position.gain:.2f}pct<{_min_aug_gain}pct"

        if action == "OPEN" and position_side == "SHORT" and symbol.upper() in self.non_shortable_symbols:
            logger.warning(f"✋ {symbol} BLOCKED: Symbol not available for short sales on Tradier")
            return "NON_SHORTABLE"

        # 5. Execute Exit/Reduce if needed
        if is_exit_action and not is_entry_action:
            qty_to_close = float(quantity)
            pos_qty = abs(float(getattr(position, 'positionAmt', 0)))
            if is_full_close or qty_to_close <= 0: qty_to_close = pos_qty
            final_qty = max(1, int(min(qty_to_close, pos_qty)))
            if final_qty < 1: return "QTY_ZERO"
            logger.info(f"[{position_key}] EXIT EXECUTE: {action} {final_qty} @ {current_price}")
            return await self.execute_now(position_key, account_key, symbol, pos_qty, side, position_side, float(final_qty), current_price, unique_id, reason, is_full_close, action)

        # 6. Entry/Augment Quantity Calculation (The Quantizing Logic)
        SP = config.START_POSITION_SIZE / current_price
        
        # Exception Boost (3x size)
        if symbol.upper() in self.exceptions:
            SP *= 3.0
            logger.info(f"[{position_key}] 🚀 EXCEPTION BOOST: Using 3x base size")

        quantity_before_quantizing = float(quantity)
        
        # User Logic Block (Adapted)
        if account_key in ['trb', 'trc'] and not _is_contract_target:
            if dc_high_5m - dc_low_5m > 5 * float(atr_15m): quantity += 0.8 * SP
            if (is_long and current_price > dc_high_1h) or (not is_long and current_price < dc_low_1h): quantity += 0.3 * SP
            if (is_long and k_5m < 30 and k_5m > d_5m) or (not is_long and k_5m > 70 and k_5m < d_5m): quantity += 0.3 * SP
            if (is_long and current_price > dc_high_4h) or (not is_long and current_price < dc_low_4h):
                quantity += 0.3 * SP
                if (is_long and k_5m < 30 and k_5m > d_5m) or (not is_long and k_5m > 70 and k_5m < d_5m): quantity += 0.3 * SP
            
            # HTF Direction checks
            higher_high_15m = high_15m >= high_5m_prev
            lower_low_15m = low_15m <= low_5m_prev
            k_ok = (k_15m >= d_15m or wt1_15m >= wt2_15m or higher_high_15m) if is_long else (k_15m <= d_15m or wt1_15m <= wt2_15m or lower_low_15m)
            stoch1_ok = self._infer_htf_direction_fast(is_long, k_5m, k_5m_prev, k_15m, k_15m_prev, d_15m, wt1_5m, wt2_5m, wt1_15m, wt2_15m, current_price, dc_basis_1h, dc_basis_4h, sma_200_15m, sma_200_1m, sma_200_1m_prev)
            
            reduction_factor = 1.0
            if not k_ok: reduction_factor *= 0.6
            if not stoch1_ok: reduction_factor *= 0.8
            quantity = reduction_factor * quantity

            # Sentiment Boosts
            market_sentiment = g('0market_sentiment_score', 0)
            sentiment_classification = i.get('0sentiment_classification', 'NEUTRAL')
            if is_long and sentiment_classification == "EXTREME_BULLISH" and market_sentiment > 20: quantity += 0.3 * SP
            elif not is_long and sentiment_classification == "EXTREME_BEARISH" and market_sentiment < -20: quantity += 0.3 * SP
            
            # Minimum viable checks
            exchange_min_qty = self.min_qty.get(symbol, 1.0)
            min_viable_qty = max(exchange_min_qty, 6.0 / current_price)
            if quantity < min_viable_qty: quantity = min_viable_qty

        # 7. Final Execution
        # Whole-share Tradier execution must never round an absolute target
        # above the $16k capacity.  Research/exact comparisons report this
        # explicit whole-share floor as an execution-adapter difference.
        final_shares = (
            int(quantity) if _is_contract_target else int(round(quantity))
        )
        if final_shares < 1: return "QTY_ZERO_FINAL"
        if action in ('OPEN', 'AUGMENT', 'REENTRY', 'QUICK_OPEN', 'REVERSE', 'HEDGE_OPEN') and not _is_mandatory_reclaim and not ('MTF_ARROW' in (reason or '') or 'LR_BAND' in (reason or '')):
            _gr_min_tfs_tr = int(getattr(config, "GOLDEN_RULE_HTF_MIN_TFS", 0))
            if _gr_min_tfs_tr > 0:
                try:
                    from golden_rule_htf import \
                        score_entry_htf as _gr_score_entry_tr
                    _gr_min_ind_tr = int(getattr(config, "GOLDEN_RULE_MIN_IND", 2))
                    _gr_pass_tr, _gr_n_tfs_tr, _gr_detail_tr = _gr_score_entry_tr(i, is_long, "tradier", _gr_min_tfs_tr, _gr_min_ind_tr, current_price, True)
                    if not _gr_pass_tr:
                        logger.warning(f"[GOLDEN_RULE_CONSENSUS_BLOCK_ENTRY] {position_key} {'LONG' if is_long else 'SHORT'}: {_gr_detail_tr} — REFUSED ({reason})")
                        return f"BLOCKED_GR_CONSENSUS_{_gr_n_tfs_tr}of{_gr_min_tfs_tr}tfs"
                except Exception as _gr_tr_err:
                    logger.error(f"[GOLDEN_RULE_SCORER_ENTRY_FAIL] {position_key}: {_gr_tr_err}")

        logger.info(f"[{position_key}] {action} EXECUTE: {final_shares} shares @ {current_price}")
        return await self.execute_now(position_key, account_key, symbol, abs(position.positionAmt), side, position_side, float(final_shares), current_price, unique_id, reason, is_full_close, action)

    async def _get_settled_cash_from_broker(self, account_key: str) -> float:
        # Query Tradier for ACTUAL settled cash. Fail-closed: return 0.0 on any error.
        # Prevents GFV: buying with unsettled proceeds crashes cash accounts.
        # Cache 30s — fresh enough to catch same-day sells, cheap enough not to rate-limit.
        try:
            if not hasattr(self, '_settled_cash_cache'):
                self._settled_cash_cache = {}  # {account_key: {ts, settled_cash}}
            _now = time.time()
            _entry = self._settled_cash_cache.get(account_key)
            if _entry and (_now - _entry.get('ts', 0)) < 30.0:
                return _entry['settled_cash']
            _client = None
            _existing = getattr(self, 'api_client', None)
            if _existing is not None and getattr(_existing, 'account_key', None) == account_key:
                _client = _existing
            else:
                _client = TradierAPIClient(config, account_key=account_key)
                try:
                    await asyncio.wait_for(_client.connect(), timeout=5.0)
                except Exception as _ce:
                    logger.critical(f"[GFV_SETTLED_CASH] {account_key}: API connect failed ({_ce}) — FAIL CLOSED, returning 0.0")
                    return 0.0
            try:
                _balances = await asyncio.wait_for(_client.get_account_balances(account_key), timeout=5.0)
            except Exception as _be:
                logger.critical(f"[GFV_SETTLED_CASH] {account_key}: balances fetch failed ({_be}) — FAIL CLOSED, returning 0.0")
                return 0.0
            _cash_block = _balances.get('cash', {})
            _cash_available = float(_cash_block.get('cash_available') or _balances.get('total_cash') or 0.0)
            _unsettled = float(_cash_block.get('unsettled_funds') or _balances.get('uncleared_funds') or 0.0)
            _settled = max(0.0, _cash_available - _unsettled)
            self._settled_cash_cache[account_key] = {'ts': _now, 'settled_cash': _settled}
            logger.info(f"[GFV_SETTLED_CASH] {account_key}: cash_available=${_cash_available:.2f} unsettled=${_unsettled:.2f} settled=${_settled:.2f}")
            return _settled
        except Exception as _err:
            logger.critical(f"[GFV_SETTLED_CASH] {account_key}: unexpected error ({_err}) — FAIL CLOSED, returning 0.0")
            return 0.0

    async def _check_live_drawdown_ceiling(self, account_key: str) -> tuple[bool, str]:
        """Refuse new risk when broker equity is at/above the hard DD ceiling.

        The high-water mark is persisted per account so a process restart cannot
        reset the risk baseline.  This gate never blocks exits/reductions; on a
        balance/API error it fails closed for new entries.
        """
        ceiling = float(getattr(config, 'MAX_ALLOWED_DRAWDOWN_PCT', 50.0))
        state_path = Path(config.DATA_DIR) / 'risk' / f'drawdown_guard_{account_key}.json'
        try:
            state_path.parent.mkdir(parents=True, exist_ok=True)
            state = {}
            if state_path.exists():
                with open(state_path, errors='replace') as fh:
                    state = json.load(fh)
            client = getattr(self, 'api_client', None)
            if client is None or getattr(client, 'account_key', None) != account_key:
                client = TradierAPIClient(config, account_key=account_key)
                await asyncio.wait_for(client.connect(), timeout=5.0)
            balances = await asyncio.wait_for(client.get_account_balances(account_key), timeout=5.0)
            raw_equity = balances.get('total_equity', balances.get('equity', balances.get('account_value')))
            if isinstance(raw_equity, dict):
                raw_equity = raw_equity.get('value', raw_equity.get('amount'))
            equity = float(raw_equity)
            if not math.isfinite(equity) or equity <= 0:
                raise ValueError(f'invalid broker equity {raw_equity!r}')
            peak = max(float(state.get('peak_equity', 0.0) or 0.0), equity)
            dd = max(0.0, (peak - equity) / peak * 100.0) if peak > 0 else 0.0
            state = {'account': account_key, 'peak_equity': peak, 'equity': equity,
                     'drawdown_pct': dd, 'ceiling_pct': ceiling,
                     'updated_at': datetime.now(timezone.utc).isoformat()}
            tmp_path = state_path.with_suffix('.tmp')
            with open(tmp_path, 'w') as fh:
                json.dump(state, fh, sort_keys=True)
            os.replace(tmp_path, state_path)
            if dd >= ceiling:
                logger.critical(f'[DRAWDOWN_CEILING] {account_key}: equity=${equity:.2f} peak=${peak:.2f} DD={dd:.2f}% >= {ceiling:.2f}% — NEW RISK BLOCKED')
                return False, f'DRAWDOWN_CEILING_{dd:.2f}PCT'
            return True, f'DD_OK_{dd:.2f}PCT'
        except Exception as err:
            # V8 backtest bypass: backtest has no broker API, fail OPEN so live tests get trades
            import os as _dd_os
            if _dd_os.environ.get('V8_BACKTEST_BYPASS_DRAWDOWN') == '1' or _dd_os.environ.get('V8_OVERRIDE_FILE'):
                logger.warning(f'[DRAWDOWN_BYPASS_V8] {account_key}: {err} — bypassed for backtest, allowing entry')
                return True, 'DD_BYPASS_V8'
            logger.critical(f'[DRAWDOWN_CEILING_FAILCLOSED] {account_key}: {err} — NEW RISK BLOCKED')
            return False, 'DRAWDOWN_EQUITY_UNAVAILABLE'

    async def _broker_preflight_check(self, account_key: str, symbol: str, position_side: str, quantity: float) -> tuple:
        # Self-verify with broker before opening — returns (block: bool, tag: str).
        # User mandate 2026-05-11: tradier_manage must hit the broker API directly even if
        # tradier_positions isn't running. Cache last fetch for BROKER_PREFLIGHT_CACHE_S seconds.
        try:
            if not hasattr(self, '_broker_preflight_cache'):
                self._broker_preflight_cache = {}  # {account_key: {ts, positions}}
            _ttl = float(getattr(config, 'BROKER_PREFLIGHT_CACHE_S', 3.0))
            _now = time.time()
            _entry = self._broker_preflight_cache.get(account_key)
            _positions = None
            if _entry and (_now - _entry.get('ts', 0)) < _ttl:
                _positions = _entry.get('positions')
            if _positions is None:
                _client = None
                _existing_client = getattr(self, 'api_client', None)
                if _existing_client is not None and getattr(_existing_client, 'account_key', None) == account_key:
                    _client = _existing_client
                else:
                    _client = TradierAPIClient(config, account_key=account_key)
                    try:
                        await asyncio.wait_for(_client.connect(), timeout=5.0)
                    except Exception:
                        return (False, "")
                try:
                    _positions = await asyncio.wait_for(_client.get_account_positions(), timeout=5.0)
                except Exception as _api_err:
                    logger.warning(f"[BROKER_PREFLIGHT_API_ERR] {account_key}:{symbol}: {_api_err} — fail-open")
                    return (False, "")
                self._broker_preflight_cache[account_key] = {'ts': _now, 'positions': _positions or []}
            if not _positions:
                return (False, "")
            _broker_long_qty = 0.0
            _broker_short_qty = 0.0
            for _p in _positions:
                _sym = str(_p.get('symbol', '')).upper()
                if _sym != symbol.upper():
                    continue
                _q = float(_p.get('quantity', 0) or 0)
                if _q > 0: _broker_long_qty += _q
                elif _q < 0: _broker_short_qty += abs(_q)
            _is_long = (position_side == 'LONG')
            # opposite side already at broker → refuse
            if _is_long and _broker_short_qty > 0.5:
                logger.critical(f"🛑 [BROKER_PREFLIGHT_OPPOSITE] {account_key}:{symbol}: broker shows SHORT={_broker_short_qty} but trying to open LONG — REFUSING. Close the SHORT first.")
                return (True, "BROKER_HAS_OPPOSITE_SHORT")
            if (not _is_long) and _broker_long_qty > 0.5:
                logger.critical(f"🛑 [BROKER_PREFLIGHT_OPPOSITE] {account_key}:{symbol}: broker shows LONG={_broker_long_qty} but trying to open SHORT — REFUSING. Close the LONG first.")
                return (True, "BROKER_HAS_OPPOSITE_LONG")
            # same-side already filled → refuse adding more
            _same_qty = _broker_long_qty if _is_long else _broker_short_qty
            _max_per_key = float(getattr(config, 'BROKER_PREFLIGHT_MAX_SAME_SIDE_QTY', 50.0))
            if _same_qty >= _max_per_key:
                logger.critical(f"🛑 [BROKER_PREFLIGHT_FULL] {account_key}:{symbol}_{position_side}: broker already holds {_same_qty} (cap {_max_per_key}) — REFUSING further entry.")
                return (True, "BROKER_SAME_SIDE_AT_CAP")
            return (False, "")
        except Exception as _err:
            logger.error(f"[BROKER_PREFLIGHT_INTERNAL_ERR] {account_key}:{symbol}: {_err}")
            return (False, "")

    def _disaster_guard_for_entry(self, position_key: str, account_key: str, symbol: str, position_side: str, quantity: float, current_price: float, reason: str) -> tuple:
        # Returns (block: bool, block_tag: str). 10 controls — see config_tradier.DISASTER_GUARD section.
        # User mandate 2026-05-11 after $12k MU short opened against +17.89% rally.
        # Never call this for REDUCE/CLOSE/HEDGE_CLOSE — exits must remain unobstructed.
        if not bool(getattr(config, 'DISASTER_GUARD_ENABLED', True)):
            return (False, "")
        # ═══ 2026-05-17 PATCH A — PENNY STOCK LONG BLOCK (DEFAULT OFF behind PENNY_STOCK_LONG_BLOCK_ENABLED) ═══
        # Live 30d evidence: LEXX LONG lost -8.33% (trc:404) and -5.65% (trb:425) on a $0.60 stock.
        # Both were RATIO_BOOST_L(R=0.00) LONG entries on sub-$1 names. SHORTs unaffected (they
        # historically work on penny names — the bias is LONG-buying-into-zero). Fail-closed before
        # any other DG control: hard-reject LONG when last_price < PRICE_USD. Flag default False —
        # sweep-validate before flip.
        if bool(getattr(config, 'PENNY_STOCK_LONG_BLOCK_ENABLED', False)):
            _penny_thr = float(getattr(config, 'PENNY_STOCK_LONG_BLOCK_PRICE_USD', 5.0))
            _penny_px = float(current_price or 0)
            if (position_side == 'LONG') and _penny_thr > 0.0 and _penny_px > 0.0 and _penny_px < _penny_thr:
                logger.critical(f"🛑 [BLOCKED_PENNY_LONG] {position_key}: last_price=${_penny_px:.4f} < ${_penny_thr:.2f} threshold — REFUSING LONG (penny-stock long bleed pattern). reason={reason}")
                return (True, f"BLOCKED_PENNY_LONG_{_penny_px:.4f}")
        try:
            is_long = (position_side == 'LONG')
            ind = None
            try:
                ind = self.get_indicators(symbol)
            except Exception:
                ind = None
            if not ind:
                if not is_long:
                    logger.critical(f"🛑 [DG_0_NO_INDICATORS_SHORT_BLOCK] {position_key}: indicators unavailable — REFUSING SHORT (fail-closed, cannot verify direction). reason={reason}")
                    return (True, "DG_NO_INDICATORS_SHORT_BLOCK")
                return (False, "")
            px = float(current_price or 0)
            if px <= 0:
                return (False, "")
            notional = float(quantity or 0) * px
            is_force_open = 'WT_3M_FORCE_OPEN' in (reason or '').upper() or 'AGENT_FORCE_OPEN' in (reason or '').upper()
            # SMA200 structural-bear bypass: price below 200-SMA = D-level bear context regardless of candle color.
            _sma200_15m = safe_fetch_float(ind.get('sma_200_15m', 0))
            _dg_short_below_sma200 = (not is_long) and bool(getattr(config, 'DG_SMA200_SHORT_BYPASS', True)) and _sma200_15m > 0 and px < _sma200_15m
            # ── Control 1+2: daily intraday return guard ──
            day_open = safe_fetch_float(ind.get('open_D', 0)) or safe_fetch_float(ind.get('open_1h', 0))
            if day_open > 0:
                day_ret_pct = (px - day_open) / day_open * 100.0
                _short_thr = float(getattr(config, 'DG_DAILY_GAIN_BLOCK_SHORT_PCT', 2.5))
                _long_thr = float(getattr(config, 'DG_DAILY_LOSS_BLOCK_LONG_PCT', 2.5))
                if (not is_long) and day_ret_pct >= _short_thr:
                    logger.critical(f"🛑 [DG_1_DAILY_GAIN_SHORT_BLOCK] {position_key}: day_ret={day_ret_pct:+.2f}% >= +{_short_thr:.2f}% — REFUSING SHORT (don't short winners). reason={reason}")
                    return (True, "DG_DAILY_GAIN_SHORT_BLOCK")
                if is_long and day_ret_pct <= -_long_thr:
                    logger.critical(f"🛑 [DG_2_DAILY_LOSS_LONG_BLOCK] {position_key}: day_ret={day_ret_pct:+.2f}% <= -{_long_thr:.2f}% — REFUSING LONG (don't catch knives). reason={reason}")
                    return (True, "DG_DAILY_LOSS_LONG_BLOCK")
            # ── Control 3: HTF directional alignment ──
            def _bias(close_now, close_prev):
                if close_now <= 0 or close_prev <= 0: return 0
                return 1 if close_now > close_prev else (-1 if close_now < close_prev else 0)
            close_D = safe_fetch_float(ind.get('close_D', 0))
            open_D = safe_fetch_float(ind.get('open_D', 0))
            close_4h = safe_fetch_float(ind.get('close_4h', 0))
            open_4h = safe_fetch_float(ind.get('open_4h', 0))
            close_1h = safe_fetch_float(ind.get('close_1h', 0))
            open_1h = safe_fetch_float(ind.get('open_1h', 0))
            bias_D = _bias(close_D, open_D)
            bias_4h = _bias(close_4h, open_4h)
            bias_1h = _bias(close_1h, open_1h)
            want = 1 if is_long else -1
            if bool(getattr(config, 'DG_HTF_ALIGN_REQUIRE_D', True)):
                # For shorts: block ONLY if D is actively bullish (bias_D == 1).
                # Neutral/stale (0) is allowed — stale data should not permanently block strong intraday shorts.
                # For longs: only block if D is actively bearish (bias_D == -1)
                # SMA200 bypass: below sma_200_15m = structural bear — skip D-candle check.
                if (not is_long) and bias_D == 1 and not _dg_short_below_sma200:
                    logger.critical(f"🛑 [DG_3D_HTF_D_NOT_BEAR] {position_key}: D bias=bull (need bear=-1 to allow short) — REFUSING SHORT. reason={reason}")
                    return (True, "DG_HTF_D_NOT_BEAR")
                elif is_long and bias_D != 0 and bias_D == -want:
                    logger.critical(f"🛑 [DG_3D_HTF_D_AGAINST] {position_key}: D bias={'bull' if bias_D>0 else 'bear'} but want bull entry — REFUSING. reason={reason}")
                    return (True, "DG_HTF_D_AGAINST")
            if bool(getattr(config, 'DG_HTF_ALIGN_REQUIRE_4H', True)):
                if (not is_long) and bias_4h == 1 and not _dg_short_below_sma200:
                    logger.critical(f"🛑 [DG_3H4_HTF_4H_NOT_BEAR] {position_key}: 4h bias=bull (need bear=-1 to allow short) — REFUSING SHORT. reason={reason}")
                    return (True, "DG_HTF_4H_NOT_BEAR")
                elif is_long and bias_4h != 0 and bias_4h == -want:
                    logger.critical(f"🛑 [DG_3H4_HTF_4H_AGAINST] {position_key}: 4h bias={'bull' if bias_4h>0 else 'bear'} but want bull entry — REFUSING. reason={reason}")
                    return (True, "DG_HTF_4H_AGAINST")
            if bool(getattr(config, 'DG_HTF_ALIGN_REQUIRE_1H', False)) and bias_1h != 0 and bias_1h == -want:
                logger.critical(f"🛑 [DG_3H1_HTF_1H_AGAINST] {position_key}: 1h bias={'bull' if bias_1h>0 else 'bear'} but want {'bull' if is_long else 'bear'} entry — REFUSING. reason={reason}")
                return (True, "DG_HTF_1H_AGAINST")
            # ── Control 4: RSI momentum guard ──
            rsi_15m = safe_fetch_float(ind.get('rsi_15m', 50))
            rsi_1h = safe_fetch_float(ind.get('rsi_1h', 50))
            if (not is_long) and rsi_15m >= float(getattr(config, 'DG_MOMENTUM_BLOCK_RSI15M_FOR_SHORT', 65.0)):
                logger.critical(f"🛑 [DG_4A_RSI15M_TOO_BULL_FOR_SHORT] {position_key}: rsi_15m={rsi_15m:.1f} — REFUSING SHORT. reason={reason}")
                return (True, "DG_RSI15M_TOO_BULL_FOR_SHORT")
            if (not is_long) and rsi_1h >= float(getattr(config, 'DG_MOMENTUM_BLOCK_RSI1H_FOR_SHORT', 65.0)):
                logger.critical(f"🛑 [DG_4C_RSI1H_TOO_BULL_FOR_SHORT] {position_key}: rsi_1h={rsi_1h:.1f} — REFUSING SHORT. reason={reason}")
                return (True, "DG_RSI1H_TOO_BULL_FOR_SHORT")
            if is_long and rsi_15m <= float(getattr(config, 'DG_MOMENTUM_BLOCK_RSI15M_FOR_LONG', 35.0)):
                logger.critical(f"🛑 [DG_4B_RSI15M_TOO_BEAR_FOR_LONG] {position_key}: rsi_15m={rsi_15m:.1f} — REFUSING LONG. reason={reason}")
                return (True, "DG_RSI15M_TOO_BEAR_FOR_LONG")
            if is_long and rsi_1h <= float(getattr(config, 'DG_MOMENTUM_BLOCK_RSI1H_FOR_LONG', 35.0)):
                logger.critical(f"🛑 [DG_4D_RSI1H_TOO_BEAR_FOR_LONG] {position_key}: rsi_1h={rsi_1h:.1f} — REFUSING LONG. reason={reason}")
                return (True, "DG_RSI1H_TOO_BEAR_FOR_LONG")
            # ── Control 5: max notional on force-opens ──
            if is_force_open:
                _max_force = float(getattr(config, 'DG_MAX_FORCE_OPEN_NOTIONAL_USD', 500.0))
                if notional > _max_force:
                    logger.critical(f"🛑 [DG_5_FORCE_OPEN_NOTIONAL_CAP] {position_key}: notional=${notional:.0f} > ${_max_force:.0f} cap — REFUSING. qty={quantity} px={px} reason={reason}")
                    return (True, "DG_FORCE_OPEN_NOTIONAL_CAP")
            # ── Control 6: broker-vs-memory sync guard ──
            # Inspects last cached broker snapshot from _broker_preflight_cache (populated by
            # the async pre-flight). If broker has the key with amt>0 but local memory has 0,
            # refuse. This is a fast in-process check; the real-time broker poll is the
            # _broker_preflight_check above.
            if bool(getattr(config, 'DG_BROKER_MEMORY_SYNC_BLOCK', True)):
                try:
                    _broker_qty = 0.0
                    _bpc = getattr(self, '_broker_preflight_cache', None)
                    if isinstance(_bpc, dict):
                        _snap = _bpc.get(account_key) or {}
                        for _p in (_snap.get('positions') or []):
                            if str(_p.get('symbol', '')).upper() != symbol.upper():
                                continue
                            _q = float(_p.get('quantity', 0) or 0)
                            if (is_long and _q > 0) or ((not is_long) and _q < 0):
                                _broker_qty = abs(_q)
                                break
                    _local_pos = self.position_manager.positions.get(position_key) if self.position_manager else None
                    _local_amt = abs(float(getattr(_local_pos, 'positionAmt', 0) or 0)) if _local_pos else 0.0
                    if _broker_qty > 0.5 and _local_amt < 0.5:
                        logger.critical(f"🛑 [DG_6_BROKER_MEMORY_DESYNC] {position_key}: broker_qty={_broker_qty} but local_amt={_local_amt} — REFUSING further opens until sync. reason={reason}")
                        return (True, "DG_BROKER_MEMORY_DESYNC")
                except Exception:
                    pass
            # ── Control 7: opposite-side profit block ──
            _opp_thr = float(getattr(config, 'DG_OPPOSITE_SIDE_PROFIT_BLOCK_PCT', 1.0))
            if _opp_thr > 0:
                try:
                    _opp_key = f"{account_key}:{symbol}_{'SHORT' if is_long else 'LONG'}"
                    _opp_pos = self.position_manager.positions.get(_opp_key) if self.position_manager else None
                    _opp_gain = float(getattr(_opp_pos, 'gain', 0.0) or 0.0) if _opp_pos else 0.0
                    _opp_amt = abs(float(getattr(_opp_pos, 'positionAmt', 0) or 0)) if _opp_pos else 0.0
                    if _opp_amt > 0 and _opp_gain >= _opp_thr:
                        logger.critical(f"🛑 [DG_7_OPPOSITE_SIDE_WINNING] {position_key}: opposite-side {_opp_key} gain={_opp_gain:.2f}% >= {_opp_thr:.2f}% — REFUSING entry (don't fight your winner). reason={reason}")
                        return (True, "DG_OPPOSITE_SIDE_WINNING")
                except Exception:
                    pass
            # ── Control 8: per-day fire cap on force-opens ──
            if is_force_open:
                _max_per_day = int(getattr(config, 'DG_REPEAT_OPEN_PER_DAY_MAX', 3))
                try:
                    if not hasattr(self, '_dg_force_open_count'):
                        self._dg_force_open_count = {}
                    if not hasattr(self, '_dg_force_open_day'):
                        self._dg_force_open_day = ""
                    _today = datetime.now(timezone.utc).strftime('%Y%m%d')
                    if self._dg_force_open_day != _today:
                        self._dg_force_open_count = {}
                        self._dg_force_open_day = _today
                    _count = int(self._dg_force_open_count.get(position_key, 0))
                    if _count >= _max_per_day:
                        logger.critical(f"🛑 [DG_8_FORCE_OPEN_DAY_CAP] {position_key}: already {_count}/{_max_per_day} force-opens today — REFUSING. reason={reason}")
                        return (True, "DG_FORCE_OPEN_DAY_CAP")
                except Exception:
                    pass
            # ── Control 9: high-volatility day skip on force-opens ──
            if is_force_open:
                _atr_thr = float(getattr(config, 'DG_HIGH_VOLATILITY_ATR_PCT', 4.0))
                _atr_1h = safe_fetch_float(ind.get('atr_1h', 0))
                if _atr_1h > 0 and px > 0 and (_atr_1h / px) * 100.0 >= _atr_thr:
                    logger.critical(f"🛑 [DG_9_HIGH_VOL_FORCE_BLOCK] {position_key}: atr_1h/px={(_atr_1h/px)*100.0:.2f}% >= {_atr_thr:.2f}% — REFUSING force-open on volatile day. reason={reason}")
                    return (True, "DG_HIGH_VOL_FORCE_BLOCK")
            # ── Control 10: ALL short entries require at least one HTF TF confirming bear ──
            # Extended from force-open-only to ALL short entries (2026-05-12: MU disaster repeat).
            # At market open, bias_D/bias_4h are often 0 (stale = neutral). Neutral fails the
            # "agree" test, so this blocks any short entry when HTF state is unknown.
            if (not is_long) and bool(getattr(config, 'DG_WT_3M_REQUIRE_HTF_CONFIRM', True)):
                _agree = False
                if bias_D == want and bias_D != 0: _agree = True
                if bias_4h == want and bias_4h != 0: _agree = True
                if _dg_short_below_sma200: _agree = True
                if not _agree:
                    logger.critical(f"🛑 [DG_10_SHORT_NO_HTF_CONFIRM] {position_key}: short requires D OR 4h bearish, got D={bias_D} 4h={bias_4h} want={want} — REFUSING SHORT. reason={reason}")
                    return (True, "DG_SHORT_NO_HTF_CONFIRM")
            # ── Control 11: WT daily-level directional block for shorts ──
            # If D-level WaveTrend is bullish (wt1_D > wt2_D), refuse to SHORT.
            # Bypassed when price < sma_200_15m (structural bear context).
            if not is_long and not _dg_short_below_sma200:
                _wt1_D = safe_fetch_float(ind.get('wt1_D', 0))
                _wt2_D = safe_fetch_float(ind.get('wt2_D', 0))
                if _wt1_D != 0 and _wt2_D != 0 and _wt1_D > _wt2_D:
                    logger.critical(f"🛑 [DG_11_WT_D_BULL_SHORT_BLOCK] {position_key}: wt1_D={_wt1_D:.2f} > wt2_D={_wt2_D:.2f} (daily WT bullish) — REFUSING SHORT. reason={reason}")
                    return (True, "DG_WT_D_BULL_SHORT_BLOCK")
            _dg_day_ret_str = f"{(px - day_open) / day_open * 100.0:+.2f}%" if day_open > 0 else "n/a"
            logger.info(f"[DG_PASS] {position_key}: disaster guard PASSED — side={position_side} day_ret={_dg_day_ret_str} bias_D={bias_D} bias_4h={bias_4h} rsi_15m={rsi_15m:.1f} rsi_1h={rsi_1h:.1f} reason={reason}")
            return (False, "")
        except Exception as _dg_err:
            logger.error(f"[DG_GUARD_ERR] {position_key}: {_dg_err}")
            if position_side == 'SHORT':
                logger.critical(f"🛑 [DG_ERR_SHORT_FAILCLOSED] {position_key}: disaster guard exception → fail-closed for SHORT. err={_dg_err}")
                return (True, "DG_EXCEPTION_SHORT_FAILCLOSED")
            return (False, "")

    async def execute_now(self, position_key: str, account_key: str, symbol: str, original_position_amt: float, side: str, position_side: str, quantity: float, old_price: float, unique_id: str, reason: str, is_full_close: bool, action: str = None) -> str:
        if not is_regular_trading_hours(): return "MARKET_CLOSED"
        # 2026-06-03 USER MANDATE — S1 = live trader, Mac = testing only (nor ez_ nor tradier_ execute live).
        # On the non-server box (Mac=Darwin) refuse to place a live stock order when the server holds a
        # FRESH heartbeat for this account. Lazy imports → no circular load; fail-OPEN. Mirror of ez_manage.
        try:
            import platform as _pf
            if _pf.system() == "Darwin" and bool(getattr(config, "SERVER_HEARTBEAT_BLOCK_ENABLED", True)):
                try:
                    _srv_live = await safe_check_server_heartbeat_tradier(account_key)
                except Exception:
                    _srv_live = False
                if _srv_live:
                    logger.warning(f"🛑 [SERVER_HEARTBEAT_BLOCK] {position_key}: S1 live-trading {account_key} — Mac (tradier) refusing live order. action={action}")
                    return "BLOCKED_SERVER_HEARTBEAT_ACTIVE"
        except Exception:
            pass
        exec_lock_key = f"execute_now:{position_key}:{side}"
        MAX_EXECUTION_TIME = 120
        lock_acquired = False
        try:
            if self.redis_manager:
                try:
                    existing = await self.redis_manager.get(exec_lock_key)
                    if existing:
                        if isinstance(existing, dict) and existing.get('status') == 'ghost_cleared':
                            logger.warning(f"[EXECUTE_NOW_BLOCKED] {position_key}: GHOST_CLEARED cooldown active, skipping")
                            return "GHOST_CLEARED_COOLDOWN"
                        lock_age = 0
                        if isinstance(existing, dict) and 'timestamp' in existing:
                            lock_age = time.time() - existing.get('timestamp', 0)
                        if lock_age < MAX_EXECUTION_TIME:
                            logger.error(f"[EXECUTE_NOW_BLOCKED] {position_key}: REDIS LOCK EXISTS - Another execution is in progress!")
                            return "REDIS_EXECUTION_LOCK_EXISTS"
                    await self.redis_manager.set(exec_lock_key, {"timestamp": time.time(), "unique_id": unique_id}, ex=MAX_EXECUTION_TIME)
                    lock_acquired = True
                except Exception as lock_err:
                    logger.error(f"[EXECUTE_NOW_LOCK_ERROR] {position_key}: Error during lock acquisition: {lock_err}")
                    return "LOCK_ACQUISITION_ERROR"
            
            # Check cooldowns
            recent_signal_ts = self.recently_processed_signals.get(position_key, 0)
            is_reduce = (side.upper() == "SELL" and position_side == "LONG") or (side.upper() == "BUY" and position_side == "SHORT")
            is_augment = not is_reduce
            is_hedge = action in ('HEDGE_OPEN', 'HEDGE_CLOSE') if action else False
            is_long = position_side == 'LONG'
            _is_augment_or_entry = is_augment
            is_entry_action = action in ['OPEN', 'REENTRY', 'QUICK_OPEN', 'REVERSE', 'HEDGE_OPEN'] if action else False
            _is_exit_or_reduce = action in ('REDUCE', 'CLOSE', 'FULL_CLOSE', 'PROFIT_TAKE', 'QUICK_CLOSE') if action else False
            _is_mandatory_reclaim = is_mandatory_reclaim_reason(reason)
            _is_ladder_parity = is_ordinary_ladder_target_reason(reason)
            # ═══════════════════════════════════════════════════════════════════════════
            # 🛡️ MTF FILTER (USER 2026-05-20) — Phase I REJ_1h winner gates entries.
            # Phase J validated on 293 stocks × 2.13y: pool_S +0.28, avg DD 6.5%, +113%/sym/yr.
            # FILTER mode: existing entries (Rule A, GR direct, WT_3M_FORCE_OPEN, REENTRY etc.)
            # still fire, but must ADDITIONALLY pass: (1) per-sym blocklist, (2) >=1 armed state,
            # (3) GR multi-confirm filter. Per-sym MTF_SIZE_MULT (1.0/0.5/0.0) applied to qty.
            # ROLLBACK: MTF_ARMED_ENTRY_ENABLED=False in config_tradier.py.
            # ═══════════════════════════════════════════════════════════════════════════
            try:
                # 2026-05-21 USER MANDATE — narrow MTF FILTER bypass for PRICE_CROSS_BACK
                # reentries. SNDK was sold at $1531 then rally continued without reentry because
                # MTF FILTER blocked the cross-back. PRICE_CROSS_BACK is already gated by
                # band/age/direction at line ~7405 — letting it past MTF FILTER is the "GET
                # RIGHT BACK IN" path. Other reentry sources (DAEMON_PRICE_CROSS, MTF, etc.)
                # still gated by the 04:35 EMERGENCY REVERT — only PRICE_CROSS_BACK is unblocked.
                # PRICE_CROSS_BACK fires from both BRANCH A (action='REENTRY', positionAmt>0 evaluate_reentry) and
                # BRANCH B (action='OPEN', positionAmt==0 _evaluate_for_account_and_symbol). Reason substring is
                # the discriminator either way.
                _pxc_back_reentry = 'PRICE_CROSS_BACK' in (reason or '').upper() or 'RECOVERY_AUG' in (reason or '').upper() or 'REENTRY' in (action or '').upper()
                # USER 2026-05-29: guaranteed reentry/augment bypass MTF (augment already passed bounce gain wall upstream).
                _guar_ra_trd_mtf = bool(getattr(config, 'GUARANTEED_REENTRY_AUGMENT_ENABLED', True)) and ('AUGMENT' in (action or '').upper() or 'REENTRY' in (action or '').upper() or 'REENTRY' in (reason or '').upper())
                # USER 2026-06-03: with-trend force-open (above 200MA + WT-favor) bypasses MTF FILTER too — its own gate is the entry test.
                _wf_force_mtf = ('WT_3M_FORCE_OPEN' in (reason or '').upper()) and bool(_cfg(
                    'WT_3M_FORCE_OPEN_BYPASS_GATES', True,
                    account_key, symbol, position_side,
                ))
                # USER 2026-07-20 band mandate: LR_BAND entries are band+slope gated upstream — MTF armed-state
                # structurally fails at swing bottoms (needs post-turn confirmation) and starved every band entry.
                _lr_band_mtf = 'LR_BAND' in (reason or '').upper() or 'MTF_ARROW' in (reason or '').upper()
                _wf_force_mtf = _wf_force_mtf or _lr_band_mtf
                _mtf_skip_short_trd = ((position_side or "LONG") == "SHORT" and bool(_cfg("MTF_ARMED_ENTRY_SKIP_SHORT", True, account_key, symbol, position_side)))
                if _mtf_skip_short_trd and is_entry_action and bool(_cfg("MTF_ARMED_ENTRY_ENABLED", False, account_key, symbol, position_side)):
                    logger.warning(f"[MTF_GATE_SHORT_SKIP] {position_key}: SHORT entry bypasses MTF armed-gate (A/B: MTF hurts stock shorts -0.20). act={action}")
                if is_entry_action and not _pxc_back_reentry and not _guar_ra_trd_mtf and not _wf_force_mtf and not _mtf_skip_short_trd and bool(_cfg("MTF_ARMED_ENTRY_ENABLED", False, account_key, symbol, position_side)):
                    import mtf_live_evaluator as _mle
                    if not hasattr(self, "mtf_states"):
                        self.mtf_states = {}
                    _mtf_ind = self.get_indicators(symbol) if hasattr(self, "get_indicators") else self.indicators.get(symbol, {})
                    if _mtf_ind:
                        _mtf_blocked = bool(_cfg("MTF_ENTRY_BLOCKED", False, account_key, symbol, position_side))
                        _mtf_ok, _mtf_reason = _mle.mtf_entry_filter_passes(
                            self.mtf_states, symbol, position_side, _mtf_ind, "tradier", config,
                            blocked=_mtf_blocked,
                        )
                        if not _mtf_ok:
                            logger.warning(f"[MTF_FILTER_BLOCK] {position_key} act={action}: {_mtf_reason}")
                            if lock_acquired and self.redis_manager:
                                await self.redis_manager.delete(exec_lock_key)
                            return f"BLOCKED_{_mtf_reason}"
                        _mtf_mult = float(_cfg("MTF_SIZE_MULT", 1.0, account_key, symbol, position_side))
                        if 0 < _mtf_mult < 1.0:
                            _orig_qty = quantity
                            quantity = quantity * _mtf_mult
                            logger.warning(f"[MTF_LUMPY_HALF] {position_key}: qty {_orig_qty:.4f}→{quantity:.4f} (mult={_mtf_mult})")
                elif _pxc_back_reentry and is_entry_action:
                    logger.warning(f"[MTF_FILTER_BYPASS_PRICE_CROSS_BACK] {position_key}: MTF FILTER bypassed for PRICE_CROSS_BACK reentry — band/age/direction gated upstream (USER 2026-05-21 SNDK)")
            except Exception as _mtf_e:
                logger.warning(f"[MTF_FILTER] {position_key}: check error (fail-open): {_mtf_e}")
            # ═══ SAFETY SWITCH 1: TRADEABLE_KEY GATE (2026-04-16) ═══
            # trb/trc/tra use symbols_trb_long/short (not tradeable_keys.json which is crypto-only)
            if is_augment and getattr(config, 'TRADIER_REQUIRE_TRADEABLE_KEY', True):
                _tradier_accts = {'trb', 'trc', 'tra'}
                if account_key in _tradier_accts:
                    if not self.is_symbol_tradeable(symbol, account_key, position_side):
                        logger.critical(f"🚫 [TRADIER_TRADEABLE_GATE] {position_key}: NOT in symbols_{account_key}_long/short — entry/augment BLOCKED. action={action} reason={reason}")
                        if lock_acquired and self.redis_manager:
                            await self.redis_manager.delete(exec_lock_key)
                        return "BLOCKED_NON_TRADEABLE"
                else:
                    await self.load_tradeable()
                    if position_key not in self.tradeable_keys:
                        logger.critical(f"🚫 [TRADIER_TRADEABLE_GATE] {position_key}: NOT in tradeable_keys — entry/augment BLOCKED. action={action} reason={reason}")
                        if lock_acquired and self.redis_manager:
                            await self.redis_manager.delete(exec_lock_key)
                        return "BLOCKED_NON_TRADEABLE"
            
            # ═══ DISASTER_GUARD (2026-05-11 after MU $12k short-against-rally) ═══
            # 10 controls that REFUSE entry before any order is queued. Applies to
            # every entry path including WT_3M_FORCE_OPEN. Exits/reduces are NOT gated.
            # Only fires on fresh opens where the position is currently flat (positionAmt==0).
            # Augments on existing open positions are NOT gated here — they pass through.
            _dg_is_flat_open = abs(float(original_position_amt or 0)) < 0.0001
            if account_key in {'trb', 'trc', 'tra'} and is_entry_action and not _is_mandatory_reclaim and not _is_ladder_parity and not _is_exit_or_reduce and _dg_is_flat_open:
                _dg_block, _dg_tag = self._disaster_guard_for_entry(position_key, account_key, symbol, position_side, float(quantity), float(old_price), reason)
                if _dg_block:
                    logger.critical(f"🛑 [DISASTER_GUARD_BLOCKED_FORCE_OPEN] {position_key}: {_dg_tag} reason={reason}")
                    if lock_acquired and self.redis_manager:
                        await self.redis_manager.delete(exec_lock_key)
                    return f"BLOCKED_{_dg_tag}"

            # ═══ PER_SYM_SIDE_DISABLED (2026-05-28 user mandate) ═══
            # Respect LONG_ENABLED/SHORT_ENABLED from per_sym_active_config.json: a
            # (symbol, side) with NO positive backtest (UVE results + SYMBOL_REPORT) is
            # set False and refused at entry. Flag previously had no consumer. Exits/reduces
            # pass (gated by is_entry_action / not _is_exit_or_reduce). HEDGE reasons pass.
            if account_key in {'trb', 'trc', 'tra'} and is_entry_action and not _is_exit_or_reduce and 'HEDGE' not in (reason or '').upper():
                _psd_flag = "LONG_ENABLED" if position_side == "LONG" else "SHORT_ENABLED"
                if not bool(_cfg(_psd_flag, True, account_key, symbol, position_side)):
                    logger.critical(f"🚫 [PER_SYM_SIDE_DISABLED] {position_key}: BLOCKED {_psd_flag}=False (no positive backtest). reason={reason}")
                    if lock_acquired and self.redis_manager:
                        await self.redis_manager.delete(exec_lock_key)
                    return f"BLOCKED_PER_SYM_SIDE_DISABLED_{position_side}"

            # ═══ TRADIER_PHYSICS_OPPOSITE_SIDE_BLOCK (2026-05-11 user mandate) ═══
            # Tradier brokerage CANNOT hold both LONG and SHORT on the same equity in the
            # same account at the same time. If the opposite side has any positionAmt in
            # local memory, refuse this entry from queue time — never even attempt the order.
            if account_key in {'trb', 'trc', 'tra'} and is_entry_action and not _is_exit_or_reduce and self.position_manager:
                _opp_side = 'SHORT' if position_side == 'LONG' else 'LONG'
                _opp_pk = f"{account_key}:{symbol}_{_opp_side}"
                _opp_pos = self.position_manager.positions.get(_opp_pk)
                _opp_amt = abs(float(getattr(_opp_pos, 'positionAmt', 0) or 0)) if _opp_pos else 0.0
                if _opp_amt > 0.0001:
                    logger.critical(f"🛑 [TRADIER_OPPOSITE_SIDE_BLOCK] {position_key}: opposite-side {_opp_pk} has amt={_opp_amt} — Tradier cannot hold both sides, REFUSING entry. reason={reason}")
                    if lock_acquired and self.redis_manager:
                        await self.redis_manager.delete(exec_lock_key)
                    return "BLOCKED_OPPOSITE_SIDE_OPEN"

            # ═══ BROKER_PREFLIGHT (2026-05-11 user mega-urgent: trust the broker over local memory) ═══
            # Before ANY new entry, fetch live broker positions for this symbol and refuse if:
            #   - opposite-side position already exists at broker (don't fight your own LONG with a SHORT)
            #   - same-side position is already >= 95% of intended size (already filled, don't double up)
            # Cached for 3s so back-to-back calls don't flood Tradier's rate-limit.
            # If the API call itself fails, we DO NOT block — that would freeze legitimate exits.
            if account_key in {'trb', 'trc', 'tra'} and is_entry_action and not _is_exit_or_reduce and bool(getattr(config, 'BROKER_PREFLIGHT_ENABLED', True)):
                try:
                    _bp_block, _bp_tag = await self._broker_preflight_check(account_key, symbol, position_side, float(quantity))
                    if _bp_block:
                        if lock_acquired and self.redis_manager:
                            await self.redis_manager.delete(exec_lock_key)
                        return f"BLOCKED_{_bp_tag}"
                except Exception as _bp_err:
                    logger.error(f"[BROKER_PREFLIGHT_ERR] {position_key}: {_bp_err} — allowing (fail-open to not freeze trading)")

            # ═══════════════════════════════════════════════════════════════════════
            # HTF_TREND_VETO — Daily-trend gate on OPEN/AUGMENT (USER 2026-05-17, mirror of ez_manage).
            # Source: data/research_20260516/PLAN.md §3.2. Cited +0.47 Sharpe lift.
            # Complementary to DISASTER_GUARD (which checks D close-vs-prev bias):
            # this checks WT momentum on D. ROLLBACK: HTF_TREND_VETO_ENABLED=False.
            # ═══════════════════════════════════════════════════════════════════════
            # 2026-05-18 per-sym overlay
            _guar_ra_trd_htf = bool(getattr(config, 'GUARANTEED_REENTRY_AUGMENT_ENABLED', True)) and ('AUGMENT' in (action or '').upper() or 'REENTRY' in (action or '').upper() or 'REENTRY' in (reason or '').upper() or 'PRICE_CROSS_BACK' in (reason or '').upper())
            if (bool(_cfg('HTF_TREND_VETO_ENABLED', False, account_key, symbol, position_side))
                and is_entry_action
                and not _is_exit_or_reduce
                and not _is_ladder_parity
                and not _guar_ra_trd_htf
                and 'HEDGE' not in (reason or '').upper()
                and 'RULE_C' not in (reason or '').upper()):
                try:
                    _htfv_ind = await self.tradier_indicators.get_indicators(symbol) if getattr(self, 'tradier_indicators', None) else None
                except Exception:
                    _htfv_ind = None
                if _htfv_ind:
                    _htfv_wt1_D = safe_fetch_float(_htfv_ind.get('wt1_D'), 0)
                    _htfv_wt2_D = safe_fetch_float(_htfv_ind.get('wt2_D'), 0)
                    _htfv_data_ok = abs(_htfv_wt1_D) > 1e-9 and abs(_htfv_wt2_D) > 1e-9
                    if _htfv_data_ok:
                        _htfv_aligned = (is_long and _htfv_wt1_D > _htfv_wt2_D) or ((not is_long) and _htfv_wt1_D < _htfv_wt2_D)
                        if not _htfv_aligned:
                            logger.warning(f"[HTF_TREND_VETO] {position_key}: BLOCKED action={action} is_long={is_long} wt1_D={_htfv_wt1_D:.2f} wt2_D={_htfv_wt2_D:.2f} reason={(reason or '')[:50]}")
                            if lock_acquired and self.redis_manager:
                                await self.redis_manager.delete(exec_lock_key)
                            return f"BLOCKED_HTF_TREND_VETO_action={action}"

            # ═══════════════════════════════════════════════════════════════════════
            # HTF_TREND_VETO_ON_REDUCE — 2026-05-21 USER URGENT MANDATE
            # Block reduce/close when Daily WT still SUPPORTS position direction.
            # Mirror of HTF_TREND_VETO above, but for is_reduce: LONG+wt1_D>wt2_D → BLOCK; SHORT+wt1_D<wt2_D → BLOCK.
            # Stops EOD_SLIM_RATIO, SENTIMENT_FADE, SCALP_TIMEOUT, MTF_ATR_TRAIL etc. firing against the macro trend.
            # Bypass: R1_/R2_/HEDGE/PARTIAL_PROFIT_LOCK/EOD_FORCE_FLAT/EMERGENCY/LIQUIDATION/PARABOLIC_EXIT/LOSS_EXIT_TECHNICAL_BYPASS reasons.
            # ROLLBACK: set HTF_TREND_VETO_ON_REDUCE_ENABLED=False.
            # ═══════════════════════════════════════════════════════════════════════
            if (bool(_cfg('HTF_TREND_VETO_ON_REDUCE_ENABLED', False, account_key, symbol, position_side))
                and is_reduce
                and not is_hedge):
                _htfr_reason_up = (reason or '').upper()
                # 2026-05-22: R2_ REMOVED from bypass — user mandate: hold until HTF flips. R2 near-BE exits must check Daily WT.
                _htfr_bypass_substrings = ('R1_', 'HEDGE', 'PARTIAL_PROFIT_LOCK', 'EOD_FORCE_FLAT', 'EMERGENCY', 'LIQUIDATION', 'PARABOLIC_EXIT', 'GAIN_EROSION', 'R3_HTF_FLIP', 'R4_STDEV_MACRO', 'STRUCTURAL_RANGE_SHIFT', 'DD_BOUNCE_STOP', 'OVERNIGHT_GAP_HEDGE_REMOVE', 'TAKE_PROFIT', 'HEDGE_FAILED')
                _htfr_bypass = any(s in _htfr_reason_up for s in _htfr_bypass_substrings)
                if not _htfr_bypass:
                    try:
                        _htfr_ind = await self.tradier_indicators.get_indicators(symbol) if getattr(self, 'tradier_indicators', None) else None
                    except Exception:
                        _htfr_ind = None
                    if _htfr_ind:
                        _htfr_wt1_D = safe_fetch_float(_htfr_ind.get('wt1_D'), 0)
                        _htfr_wt2_D = safe_fetch_float(_htfr_ind.get('wt2_D'), 0)
                        _htfr_data_ok = abs(_htfr_wt1_D) > 1e-9 and abs(_htfr_wt2_D) > 1e-9
                        if _htfr_data_ok:
                            _htfr_supports = (is_long and _htfr_wt1_D > _htfr_wt2_D) or ((not is_long) and _htfr_wt1_D < _htfr_wt2_D)
                            if _htfr_supports:
                                logger.warning(f"[HTF_TREND_VETO_ON_REDUCE] {position_key}: BLOCKED action={action} is_long={is_long} wt1_D={_htfr_wt1_D:.2f} wt2_D={_htfr_wt2_D:.2f} reason={(reason or '')[:50]} (HTF still supports side — hold)")
                                if lock_acquired and self.redis_manager:
                                    await self.redis_manager.delete(exec_lock_key)
                                return f"BLOCKED_HTF_TREND_VETO_ON_REDUCE_action={action}"

            # 2026-05-10 USER NON-NEGOTIABLE: WT_3M_FORCE_OPEN bypasses augment cooldown so any
            # tradeable_key with wt1_3m vs wt2_3m condition met can reopen immediately.
            _wt3m_force_open = 'WT_3M_FORCE_OPEN' in (reason or '').upper() and bool(_cfg(
                'WT_3M_FORCE_OPEN_BYPASS_GATES', True,
                account_key, symbol, position_side,
            ))
            if is_augment and recent_signal_ts > 0 and time.time() - recent_signal_ts < getattr(config, 'AUGMENTATION_COOLDOWN_SECONDS', 120.0) and not _wt3m_force_open and not _is_mandatory_reclaim and not _is_ladder_parity:
                logger.warning(f"[EXECUTE_NOW_BLOCKED] {position_key}: Augmentation cooldown active")
                if lock_acquired and self.redis_manager:
                    await self.redis_manager.delete(exec_lock_key)
                return "AUGMENTATION_COOLDOWN"
            
            _e02_contract_reduce = (
                is_reduce
                and str(reason or "").upper().startswith(
                    "E02_DONCHIAN_4H_N30"
                )
                and bool(
                    _cfg(
                        "LR_BAND_E02_EXIT_ENABLED",
                        False,
                        account_key,
                        symbol,
                        position_side,
                    )
                )
            )
            if is_reduce and not _e02_contract_reduce and recent_signal_ts > 0 and time.time() - recent_signal_ts < getattr(config, 'REDUCTION_COOLDOWN_SECONDS', 30.0):
                position = self.position_manager.positions.get(position_key) if self.position_manager else None
                position_gain = getattr(position, 'gain', 0.0) if position else 0.0
                # Cooldown applies regardless of gain — no bypass for any loss level
                if True:
                    logger.warning(f"[EXECUTE_NOW_BLOCKED] {position_key}: Reduction cooldown active (gain={position_gain:.2f}%)")
                    if lock_acquired and self.redis_manager:
                        await self.redis_manager.delete(exec_lock_key)
                    return "REDUCTION_COOLDOWN"
            
            # STRICT_NO_LOSS guard — block reductions at a loss (unless Part 15 sweep disables it)
            # ═══ SAFETY SWITCH 5: SRS REASON-STRING NOLOSS BYPASS (2026-04-16) ═══
            # 2026-07-15 FIX: this switch never consulted config.UNIVERSAL_NOLOSS_GATE (the master
            # on/off flag, set False 2026-04-27 with explicit intent "technical exits still fire at
            # loss. Targeted, not blanket.") — it was a separate, independently-hardcoded blanket
            # blocker with a 4-string allowlist that ignored that flag entirely. Mirrors the crypto
            # architecture (ez_manage.py ~25111/25182: config.UNIVERSAL_NOLOSS_GATE gates whether the
            # block applies at all; config.UNIVERSAL_NOLOSS_GATE_BYPASS_REASONS is the allowlist when
            # it does). Live proof this was broken: MTF_ATR_TRAIL fired correctly on PLTR_SHORT/
            # ASTS_SHORT (trb) after the MTF_EXIT_MIN_OPEN_TS fix, then got rejected here every time
            # as NOLOSS_BLOCK because "MTF_ATR_TRAIL..." matched none of the 4 hardcoded strings.
            # Same class of bug very likely explains "R1 DC emergency close 31,429 fires -> 6
            # submitted" (R1's reason is "R1_DC_LOW4_EMERGENCY_...", also not in the old 4-string list).
            # ROLLBACK: set UNIVERSAL_NOLOSS_GATE=True in config_tradier.py to re-arm the blanket
            # block (matches crypto's current True); do not revert this code to the 4-string check.
            if is_reduce and not is_hedge:
                _ung_active_t = bool(getattr(config, 'UNIVERSAL_NOLOSS_GATE', True))
                _srs_bypass_allowed = getattr(config, 'TRADIER_NOLOSS_SRS_BYPASS', True)
                _en_reason_up = str(reason or '').upper()
                _en_srs = _srs_bypass_allowed and ('STRUCTURAL_RANGE_SHIFT' in _en_reason_up or 'DD_BOUNCE_STOP' in _en_reason_up or 'REENTRY_BREAKOUT' in _en_reason_up or 'OVERNIGHT_GAP_HEDGE_REMOVE' in _en_reason_up)
                _en_tech_bypass_list = getattr(config, 'UNIVERSAL_NOLOSS_GATE_BYPASS_REASONS', []) or []
                _en_tech_bypass_hit = None
                for _en_brk in _en_tech_bypass_list:
                    if _en_brk and str(_en_brk).upper() in _en_reason_up:
                        _en_tech_bypass_hit = _en_brk
                        break
                _en_pos = self.position_manager.positions.get(position_key) if self.position_manager else None
                _en_gain = getattr(_en_pos, 'gain', 0.0) if _en_pos else 0.0
                _en_noloss_min = getattr(config, 'NOLOSS_MIN_PROFIT_PCT_TRADIER', 3.0)
                # === BB RECOVERY-TO-ENTRY EXIT BYPASS (2026-04-15, default OFF) ===
                _bb_recov_bypass = False
                if getattr(config, 'BB_RECOVERY_EXIT_ENABLED_TRADIER', False) and _en_pos is not None:
                    try:
                        _br_entry = float(getattr(_en_pos, 'entry_price', 0) or 0)
                        _br_is_long = position_side == 'LONG'
                        _br_px = float(old_price or 0)
                        _br_ind = None
                        try:
                            _br_ind = self.get_indicators(symbol)
                        except Exception:
                            _br_ind = None
                        if _br_ind and _br_entry > 0 and _br_px > 0:
                            _bbh_1h = float(_br_ind.get('bb_high_1h', 0) or 0)
                            _bbl_1h = float(_br_ind.get('bb_low_1h', 0) or 0)
                            _br_atr = float(_br_ind.get('atr_3m', 0) or 0)
                            _br_ha = _br_ind.get('ha_3m', 'neutral')
                            _br_k3 = float(_br_ind.get('k_3m', 0) or 0)
                            _br_k3p = float(_br_ind.get('k_3m_prev', _br_k3) or _br_k3)
                            _br_tol_pct = float(getattr(config, 'BB_RECOVERY_EXIT_TOLERANCE_PCT_TRADIER', 0.30) or 0.30)
                            _br_tol_atr_m = float(getattr(config, 'BB_RECOVERY_EXIT_TOLERANCE_ATR_MULT_TRADIER', 0.0) or 0.0)
                            _br_tol_abs = (_br_tol_atr_m * _br_atr) if (_br_tol_atr_m > 0 and _br_atr > 0) else (_br_entry * _br_tol_pct / 100.0)
                            _br_within = abs(_br_px - _br_entry) <= _br_tol_abs
                            if _br_is_long and _br_entry > _bbh_1h > 0 and _br_within:
                                if _br_ha == 'red' or _br_k3 < _br_k3p:
                                    _bb_recov_bypass = True
                                    logger.warning(f"[BB_RECOVERY_EXIT_BYPASS] {position_key}: LONG entry={_br_entry:.4f}>bb_high_1h={_bbh_1h:.4f}, recovered to {_br_px:.4f} (tol={_br_tol_abs:.4f}), 3m reversal — allowing close at gain={_en_gain:.2f}%")
                            elif (not _br_is_long) and 0 < _br_entry < _bbl_1h and _br_within:
                                if _br_ha == 'green' or _br_k3 > _br_k3p:
                                    _bb_recov_bypass = True
                                    logger.warning(f"[BB_RECOVERY_EXIT_BYPASS] {position_key}: SHORT entry={_br_entry:.4f}<bb_low_1h={_bbl_1h:.4f}, recovered to {_br_px:.4f} (tol={_br_tol_abs:.4f}), 3m reversal — allowing close at gain={_en_gain:.2f}%")
                    except Exception as _br_e:
                        logger.debug(f"[BB_RECOVERY_EXIT_BYPASS] {position_key}: error: {_br_e}")
                if not _ung_active_t:
                    pass  # master switch OFF (config_tradier.UNIVERSAL_NOLOSS_GATE=False) — targeted, not blanket; technical exits fire freely
                elif _e02_contract_reduce:
                    logger.warning(
                        f"[EXECUTE_NOW_E02_BYPASS] {position_key}: "
                        f"completed-parent E02 allowed at gain={_en_gain:.2f}%"
                    )
                elif _en_srs:
                    logger.warning(f"[EXECUTE_NOW_NOLOSS_SRS_BYPASS] {position_key}: gain={_en_gain:.2f}% — STRUCTURAL_RANGE_SHIFT allowed at loss")
                elif _bb_recov_bypass:
                    pass
                elif _en_tech_bypass_hit:
                    logger.warning(f"[EXECUTE_NOW_NOLOSS_TECH_BYPASS] {position_key}: gain={_en_gain:.2f}% — technical exit '{_en_tech_bypass_hit}' allowed to close at loss (reason={reason[:80]})")
                elif _en_noloss_min > 0 and _en_gain < _en_noloss_min:
                    logger.warning(f"[EXECUTE_NOW_NOLOSS_BLOCK] {position_key}: BLOCKED reduce at gain={_en_gain:.2f}% < noloss_min={_en_noloss_min}% reason={reason}")
                    if lock_acquired and self.redis_manager:
                        await self.redis_manager.delete(exec_lock_key)
                    return "NOLOSS_BLOCK"
            # Get current position and price
            position = self.position_manager.positions.get(position_key)
            try:
                _stale_block_act = (action or "").upper()
                _stale_block_reason_up = (reason or "").upper()
                _stale_block_skip = (("CLOSE" in _stale_block_act) or is_full_close or ("INTERVENTION" in _stale_block_reason_up) or ("MANUAL" in _stale_block_reason_up) or ("SYSTEM_FORCE" in _stale_block_reason_up) or ("HEDGE" in _stale_block_act) or ("NOLOSS" in _stale_block_reason_up) or ("LIQUIDATION" in _stale_block_reason_up) or ("STOP" in _stale_block_reason_up) or ("TAKE_PROFIT" in _stale_block_reason_up))
                if not getattr(self, "is_backtest", False) and not _stale_block_skip and position:
                    _stale_ts = getattr(position, "mark_price_last_updated", None)
                    if isinstance(_stale_ts, str):
                        with suppress(Exception): _stale_ts = isoparse(_stale_ts)
                    if isinstance(_stale_ts, datetime) and _stale_ts.tzinfo is None: _stale_ts = _stale_ts.replace(tzinfo=timezone.utc)
                    _stale_now = datetime.now(timezone.utc)
                    _stale_age_s = (_stale_now - _stale_ts).total_seconds() if isinstance(_stale_ts, datetime) else 999999.0
                    _stale_max_age = float(getattr(config, "EXECUTE_NOW_MAX_MARK_AGE_S", 60.0))
                    if _stale_age_s > _stale_max_age:
                        _ref_p, _ref_ts = await self.get_current_price(symbol)
                        if _ref_p and float(_ref_p) > 0:
                            position.mark_price = float(_ref_p)
                            position.mark_price_last_updated = datetime.now(timezone.utc)
                            _stale_age_s = 0.0
                    _live_stale_blocked = _stale_age_s > _stale_max_age
                    try:
                        from vec_paths.stale_mark_price import \
                            evaluate_stale_mark_block_core as _vec_stale_fn
                        _stale_ts_shadow = getattr(position, "mark_price_last_updated", None)
                        if isinstance(_stale_ts_shadow, str):
                            try: _stale_ts_shadow = isoparse(_stale_ts_shadow)
                            except Exception: pass
                        if isinstance(_stale_ts_shadow, datetime) and _stale_ts_shadow.tzinfo is None: _stale_ts_shadow = _stale_ts_shadow.replace(tzinfo=timezone.utc)
                        _ts_shadow = _stale_ts_shadow.timestamp() if isinstance(_stale_ts_shadow, datetime) else None
                        _vec_blocked, _vec_reason, _vec_age = _vec_stale_fn(float(getattr(position, "mark_price", 0.0) or 0.0), _ts_shadow, datetime.now(timezone.utc).timestamp(), config, symbol=symbol, is_close_action=_stale_block_skip)
                        _divergent = (_live_stale_blocked != _vec_blocked)
                        _compare_entry = {"timestamp": datetime.now(timezone.utc).isoformat(), "position_key": position_key, "action": action, "module": "stale_mark_price", "live_result": "BLOCKED" if _live_stale_blocked else "OK", "vec_result": "BLOCKED" if _vec_blocked else "OK", "divergent": _divergent, "live_age": _stale_age_s, "vec_age": _vec_age}
                        _compare_file = Path(getattr(config, "BASE_PATH", "/users/niels/documents/binance")) / "data" / "live_vs_vec_compare.jsonl"
                        with open(str(_compare_file), "a") as _cf: _cf.write(json.dumps(_compare_entry) + "\n")
                        if _divergent: logger.warning(f"⚠️ [LIVE_VS_VEC_DIVERGENCE] stale_mark_price divergence on {position_key} action={action}: live_blocked={_live_stale_blocked} ({_stale_age_s:.1f}s) vs vec_blocked={_vec_blocked} ({_vec_age:.1f}s)")
                        if bool(getattr(config, "LIVE_VEC_STALE_MARK_PRICE_ENABLED", False)):
                            if _vec_blocked:
                                logger.critical(f"🚫 [LIVE_VEC_STALE_MARK_PRICE_BLOCK] {position_key}: VEC STALE BLOCK ENFORCED! age={_vec_age:.1f}s > {_stale_max_age:.1f}s. REFUSING action={action}")
                                if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                                return f"BLOCKED_STALE_MARK_PRICE_age{_vec_age:.1f}s"
                            _live_stale_blocked = False
                    except Exception as _sh_err:
                        logger.warning(f"[LIVE_VEC_STALE_MARK_PRICE_SHADOW_ERR] {type(_sh_err).__name__}: {_sh_err}")
                    if _live_stale_blocked:
                        logger.critical(f"🚫 [STALE_MARK_PRICE_BLOCK] {position_key}: mark_price age={_stale_age_s:.1f}s > {_stale_max_age:.1f}s. REFUSING action={action} reason={(reason or '')[:60]} — would make decision on stale gain. CLOSE actions bypass this gate.")
                        if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                        return f"BLOCKED_STALE_MARK_PRICE_age{_stale_age_s:.1f}s"
            except Exception as _stale_e:
                logger.warning(f"[STALE_MARK_PRICE_BLOCK] guard error (fail-open): {type(_stale_e).__name__}: {_stale_e}")
            try:
                _now = time.time()
                _acct = account_key or (position_key.split(":")[0] if position_key and ":" in position_key else "unknown")
                _sym_key = position_key or "unknown"
                if not hasattr(self, "_brake_cache"): self._brake_cache = {}
                _cache = self._brake_cache.get(_acct)
                if not _cache or (_now - _cache.get("ts", 0)) > 10:
                    import json as _bjson
                    from datetime import datetime as _bdt
                    from datetime import timedelta as _btd
                    from datetime import timezone as _btz
                    _cutoff = _bdt.now(_btz.utc) - _btd(hours=1)
                    _dfile = str(Path(config.BASE_PATH) / "data" / "decisions" / f"decisions_{_acct}_{_bdt.now(_btz.utc).strftime('%Y%m%d')}.jsonl")
                    _hour_entries = 0
                    _hour_total = 0
                    _sym_counts = {}
                    try:
                        with open(_dfile, errors="replace") as _df:
                            _df.seek(0, 2)
                            _fsize = _df.tell()
                            _df.seek(max(0, _fsize - 500000))
                            if _fsize > 500000: _df.readline()
                            for _line in _df:
                                try:
                                    _dd = _bjson.loads(_line)
                                    _ts = _dd.get("timestamp", "")
                                    _dt = _bdt.fromisoformat(_ts.replace("Z", "+00:00"))
                                    if _dt < _cutoff: continue
                                    _hour_total += 1
                                    _da = _dd.get("action", "")
                                    if _da in ("OPEN", "AUGMENT", "REENTRY", "QUICK_OPEN", "QUICK_AUGMENT"): _hour_entries += 1
                                    _dpk = _dd.get("position_key", "")
                                    _sym_counts[_dpk] = _sym_counts.get(_dpk, 0) + 1
                                except Exception: pass
                    except FileNotFoundError: pass
                    self._brake_cache[_acct] = {"ts": _now, "entries": _hour_entries, "total": _hour_total, "syms": _sym_counts}
                    _cache = self._brake_cache[_acct]
                _act_check = (action or "").upper()
                _is_close = _act_check in ("CLOSE", "QUICK_CLOSE", "REDUCE", "PARTIAL_CLOSE", "STRONG_REDUCE")
                _is_profitable_close = False
                if _is_close and position:
                    _brake_gain = float(getattr(position, "gain", 0.0) or 0.0)
                    if _brake_gain > 0.1: _is_profitable_close = True
                _live_eb_blocked = False
                _live_eb_reason = "OK"
                if not _is_profitable_close:
                    if _cache["entries"] > 500:
                        _live_eb_blocked = True
                        _live_eb_reason = "EMERGENCY_BRAKE_MAX_ENTRIES"
                    elif _cache["total"] > 1000:
                        _live_eb_blocked = True
                        _live_eb_reason = "EMERGENCY_BRAKE_MAX_TRADES"
                    else:
                        _sym_count = _cache["syms"].get(_sym_key, 0)
                        if _sym_count > 50:
                            _live_eb_blocked = True
                            _live_eb_reason = "EMERGENCY_BRAKE_SYMBOL_CHURN"
                try:
                    from vec_paths.emergency_brake import \
                        evaluate_emergency_brake_core as _vec_eb_fn
                    _dec_dir = str(Path(config.BASE_PATH) / "data" / "decisions")
                    _dt_now = datetime.now(timezone.utc)
                    _vec_eb_blocked, _vec_eb_res = _vec_eb_fn(_acct, _dt_now, position_key or "", action or "", is_profitable_close=_is_profitable_close, config=config, decisions_dir_path=_dec_dir)
                    _divergent_eb = (_live_eb_blocked != _vec_eb_blocked)
                    _compare_eb = {"timestamp": _dt_now.isoformat(), "position_key": position_key, "action": action, "module": "emergency_brake", "live_result": "BLOCKED" if _live_eb_blocked else "OK", "vec_result": "BLOCKED" if _vec_eb_blocked else "OK", "divergent": _divergent_eb, "live_reason": _live_eb_reason, "vec_reason": _vec_eb_res}
                    _compare_file = Path(getattr(config, "BASE_PATH", "/users/niels/documents/binance")) / "data" / "live_vs_vec_compare.jsonl"
                    with open(str(_compare_file), "a") as _cf: _cf.write(json.dumps(_compare_eb) + "\n")
                    if _divergent_eb: logger.warning(f"⚠️ [LIVE_VS_VEC_DIVERGENCE] emergency_brake divergence on {position_key} action={action}: live_blocked={_live_eb_blocked} ({_live_eb_reason}) vs vec_blocked={_vec_eb_blocked} ({_vec_eb_res})")
                    if bool(getattr(config, "LIVE_VEC_EMERGENCY_BRAKE_ENABLED", False)):
                        if _vec_eb_blocked:
                            logger.critical(f"🛑 [LIVE_VEC_EMERGENCY_BRAKE] {position_key}: VEC BRAKE ENFORCED! reason={_vec_eb_res}")
                            if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                            return f"BLOCKED_{_vec_eb_res}"
                        _live_eb_blocked = False
                except Exception as _eb_sh_err:
                    logger.warning(f"[LIVE_VEC_EMERGENCY_BRAKE_SHADOW_ERR] {type(_eb_sh_err).__name__}: {_eb_sh_err}")
                if _live_eb_blocked:
                    if _live_eb_reason == "EMERGENCY_BRAKE_MAX_ENTRIES":
                        logger.critical(f"🛑 [EMERGENCY_BRAKE] {_acct}: {_cache['entries']} entries/hr — HALTED. Max 500. Glitch detected.")
                        if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                        return "BLOCKED_EMERGENCY_BRAKE_MAX_ENTRIES"
                    elif _live_eb_reason == "EMERGENCY_BRAKE_MAX_TRADES":
                        logger.critical(f"🛑 [EMERGENCY_BRAKE] {_acct}: {_cache['total']} trades/hr — HALTED. Max 1000. Glitch detected.")
                        if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                        return "BLOCKED_EMERGENCY_BRAKE_MAX_TRADES"
                    elif _live_eb_reason == "EMERGENCY_BRAKE_SYMBOL_CHURN":
                        _sym_count = _cache["syms"].get(_sym_key, 0)
                        logger.critical(f"🛑 [EMERGENCY_BRAKE] {_sym_key}: {_sym_count}/hr on same symbol — BLOCKED. Max 50. Glitch detected.")
                        if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                        return "BLOCKED_EMERGENCY_BRAKE_SYMBOL_CHURN"
            except Exception as _eb_err:
                logger.debug(f"[EMERGENCY_BRAKE] Error: {_eb_err}")
            _live_q_blocked = False
            _live_q_name = "OK"
            _reason_key = (reason or "").strip()
            _quarantine = []
            try:
                import json as _qjson
                with open(str(Path(config.BASE_PATH) / "data" / "function_quarantine.json")) as _qf: _quarantine = _qjson.load(_qf)
                for _qname in _quarantine:
                    if _qname and _qname in _reason_key:
                        _live_q_blocked = True
                        _live_q_name = _qname
                        break
            except Exception: pass
            try:
                from vec_paths.quarantine_strategy_validation import \
                    evaluate_quarantine_core as _vec_q_fn
                _vec_q_blocked, _vec_q_res = _vec_q_fn(position_key, reason, action, is_hedge, original_position_amt, set(_quarantine), config)
                _divergent_q = (_live_q_blocked != _vec_q_blocked)
                _compare_q = {"timestamp": datetime.now(timezone.utc).isoformat(), "position_key": position_key, "action": action, "module": "quarantine_strategy", "live_result": "BLOCKED" if _live_q_blocked else "OK", "vec_result": "BLOCKED" if _vec_q_blocked else "OK", "divergent": _divergent_q, "live_reason": f"QUARANTINED({_live_q_name})" if _live_q_blocked else "OK", "vec_reason": _vec_q_res}
                _compare_file = Path(getattr(config, "BASE_PATH", "/users/niels/documents/binance")) / "data" / "live_vs_vec_compare.jsonl"
                with open(str(_compare_file), "a") as _cf: _cf.write(json.dumps(_compare_q) + "\n")
                if _divergent_q: logger.warning(f"⚠️ [LIVE_VS_VEC_DIVERGENCE] quarantine_strategy divergence on {position_key} action={action}: live_blocked={_live_q_blocked} ({_live_q_name}) vs vec_blocked={_vec_q_blocked} ({_vec_q_res})")
                if bool(getattr(config, "LIVE_VEC_QUARANTINE_STRATEGY_ENABLED", False)):
                    if _vec_q_blocked:
                        logger.warning(f"⛔ [LIVE_VEC_QUARANTINE_BLOCK] {position_key}: VEC QUARANTINE ENFORCED! reason='{_reason_key}' matches quarantined '{_vec_q_res}'")
                        if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                        return f"BLOCKED_{_vec_q_res}"
                    _live_q_blocked = False
            except Exception as _q_sh_err:
                logger.warning(f"[LIVE_VEC_QUARANTINE_SHADOW_ERR] {type(_q_sh_err).__name__}: {_q_sh_err}")
            if _live_q_blocked:
                logger.warning(f"⛔ [QUARANTINE_BLOCK] {position_key}: reason '{_reason_key}' matches quarantined '{_live_q_name}'")
                if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                return f"BLOCKED_QUARANTINED({_live_q_name})"
            current_price = old_price
            if not current_price or current_price <= 0:
                current_price,ts = await self.get_current_price(symbol)
                current_price = float(current_price)
            if current_price <= 0:
                logger.error(f"[EXECUTE_NOW] {position_key}: No valid price")
                if lock_acquired and self.redis_manager:
                    await self.redis_manager.delete(exec_lock_key)
                return "NO_VALID_PRICE"
            
            # Validate quantity
            if quantity <= 0:
                logger.error(f"[EXECUTE_NOW] {position_key}: Invalid quantity {quantity}")
                if lock_acquired and self.redis_manager:
                    await self.redis_manager.delete(exec_lock_key)
                return "INVALID_QUANTITY"
            
            # Place market order directly
            # Stock analogue of ez_manage's breakout timeframe sizing.  Apply
            # before ratio balancing and whole-share rounding so the signal's
            # timeframe changes the requested quantity without affecting exits.
            if (
                (_is_augment_or_entry or is_entry_action)
                and not _is_exit_or_reduce
                and not is_hedge
            ):
                _tf_mult, _tf_label = _breakout_tf_size_mult_tradier(reason)
                if _tf_mult != 1.0:
                    _orig_qty = quantity
                    quantity = float(quantity) * _tf_mult
                    logger.info(
                        f"[BREAKOUT_TF_SIZE_TRADIER] {position_key} {action}: "
                        f"TF={_tf_label} mult={_tf_mult:.2f} qty "
                        f"{_orig_qty:.6f}→{quantity:.6f} reason={str(reason)[:60]}"
                    )
            # ═══ RATIO-AWARE SIZING — bull/bear-scenario-aware L/S rebalancing for stocks ═══
            # BEAR_SCENARIO_SYMBOLS (GLD, USO, XLE, GDX, etc.) go UP when the market goes DOWN.
            # A LONG on a bear_scenario symbol = bearish market bet → flip its contribution to the ratio.
            _pm = self.position_manager
            if _pm and current_price > 0 and not is_hedge and not _is_mandatory_reclaim and not _is_ladder_parity:
                _bear_set = getattr(config, 'BEAR_SCENARIO_SYMBOLS', set())
                _long_val = 0.0
                _short_val = 0.0
                for _pk_s, _p_s in _pm.get_positions_by_account(account_key).items():
                    _qty_s = abs(float(getattr(_p_s, 'positionAmt', 0) or getattr(_p_s, 'quantity', 0) or 0))
                    if _qty_s == 0:
                        continue
                    _pr_s = float(getattr(_p_s, 'current_price', 0) or getattr(_p_s, 'entry_price', 0) or current_price)
                    _v_s = _qty_s * _pr_s
                    from utils import pk_symbol as _pk_sym
                    _sym_s = _pk_sym(_pk_s)
                    _is_bear_s = _sym_s in _bear_set
                    if _pk_s.endswith('_LONG'):
                        if _is_bear_s:
                            _short_val += _v_s  # LONG bear_scenario = bearish market bet
                        else:
                            _long_val += _v_s
                    elif _pk_s.endswith('_SHORT'):
                        if _is_bear_s:
                            _long_val += _v_s   # SHORT bear_scenario = bullish market bet
                        else:
                            _short_val += _v_s
                _r = _long_val / max(_short_val, 1.0)
                _this_bear = symbol in _bear_set
                _effective_long = is_long and not _this_bear or not is_long and _this_bear
                _r_min = getattr(config, "LS_RATIO_MIN_TRADIER", 0.50)
                _r_max = getattr(config, "LS_RATIO_MAX_TRADIER", 2.00)
                if _is_augment_or_entry:
                    # ═══ SAFETY SWITCH 2: RATIO BOOST REQUIRES MIN GAIN (2026-04-16) ═══
                    _ratio_gain_gate = getattr(config, 'TRADIER_RATIO_REQUIRE_MIN_GAIN', False)
                    _ratio_min_gain = getattr(config, 'TRADIER_RATIO_BOOST_MIN_GAIN_PCT', 1.0)
                    _pos_for_gain = self.position_manager.positions.get(position_key) if self.position_manager else None
                    _pos_gain = float(getattr(_pos_for_gain, 'gain', 0.0) or 0) if _pos_for_gain else 0.0
                    _allow_boost = (not _ratio_gain_gate) or (_pos_gain >= _ratio_min_gain)
                    if _effective_long and _r < _r_min and _allow_boost:
                        quantity = quantity * 1.5; reason = (reason or '') + f"|RATIO_BOOST_L(R={_r:.2f})"
                    elif not _effective_long and _r > _r_max and _allow_boost:
                        quantity = quantity * 1.5; reason = (reason or '') + f"|RATIO_BOOST_S(R={_r:.2f})"
                    elif _effective_long and _r > _r_max:
                        quantity = quantity * 0.6; reason = (reason or '') + f"|RATIO_CUT_L(R={_r:.2f})"
                    elif not _effective_long and _r < _r_min:
                        quantity = quantity * 0.6; reason = (reason or '') + f"|RATIO_CUT_S(R={_r:.2f})"
            original_quantity = quantity
            if quantity < 1.0:
                logger.warning(f"[EXECUTE_NOW] {position_key}: Quantity {quantity} < 1, enforcing minimum of 1 share")
                quantity = 1.0
            quantity = max(1, int(round(quantity)))
            # ═══ 2026-04-27 FUNDING_GATE_TRADIER + OI_CONFIRM_TRADIER ═══
            # Stocks have no native funding rate; put/call OI ratio is the bullish/bearish flow analogue.
            # Mirrors crypto FUNDING_GATE + OI_CONFIRM (ez_positions_quick.py:11515-11574).
            # Reads data/stocks_oi_cache/{symbol}.json (READ-ONLY, populated by tradier_options_oi_fetcher.py).
            # FAIL-OPEN: any exception or missing data → PASS through (never block on gate bug).
            # Gates only fire on entry actions (OPEN/REENTRY/QUICK_OPEN/REVERSE/HEDGE_OPEN); skipped on exits/reduces.
            if is_entry_action and not _is_mandatory_reclaim and not _is_ladder_parity and not _is_exit_or_reduce:
                try:
                    _fg_enabled = bool(getattr(config, 'FUNDING_GATE_ENABLED_TRADIER', False))
                    _oi_enabled = bool(getattr(config, 'OI_CONFIRM_ENABLED_TRADIER', False))
                    if _fg_enabled or _oi_enabled:
                        _oi_cache_path = Path(config.BASE_PATH) / "data" / "stocks_oi_cache" / f"{symbol}.json"
                        _oi_doc = None
                        if _oi_cache_path.is_file():
                            try:
                                with open(_oi_cache_path) as _ofh: _oi_doc = json.load(_ofh)
                            except Exception: _oi_doc = None
                        if _oi_doc:
                            _stale_h = float(getattr(config, 'FUNDING_GATE_TRADIER_STALE_MAX_HOURS', 4.0))
                            _oi_age_sec = time.time() - float(_oi_doc.get('ts') or 0)
                            _oi_fresh = (_oi_age_sec <= _stale_h * 3600.0)
                            if _oi_fresh:
                                # ── FUNDING_GATE_TRADIER (P/C ratio analogue) ──
                                if _fg_enabled:
                                    _fg_apply = (not is_hedge) or bool(getattr(config, 'FUNDING_GATE_TRADIER_HEDGE_GATE_ENABLED', False))
                                    if _fg_apply:
                                        _prefer_near = bool(getattr(config, 'FUNDING_GATE_TRADIER_NEAR_MONEY_PREFER', True))
                                        _pc_long_max = float(getattr(config, 'FUNDING_GATE_PC_RATIO_LONG_MAX', 1.2))
                                        _pc_short_min = float(getattr(config, 'FUNDING_GATE_PC_RATIO_SHORT_MIN', 0.83))
                                        _pc_val = None
                                        if _prefer_near:
                                            _v = _oi_doc.get('near_money_pc_ratio')
                                            try: _pc_val = float(_v) if _v is not None else None
                                            except Exception: _pc_val = None
                                        if _pc_val is None:
                                            _v = _oi_doc.get('pc_ratio')
                                            try: _pc_val = float(_v) if _v is not None else None
                                            except Exception: _pc_val = None
                                        if _pc_val is not None and _pc_val > 0:
                                            if is_long and _pc_val >= _pc_long_max:
                                                logger.warning(f"🚫 [FUNDING_GATE_TRADIER] {position_key}: BLOCKED LONG entry — pc_ratio={_pc_val:.3f} >= {_pc_long_max:.3f} (bearish options flow). action={action}")
                                                if lock_acquired and self.redis_manager:
                                                    await self.redis_manager.delete(exec_lock_key)
                                                return f"FUNDING_GATE_TRADIER_LONG_REJECT_pc={_pc_val:.3f}"
                                            if (not is_long) and _pc_val <= _pc_short_min:
                                                logger.warning(f"🚫 [FUNDING_GATE_TRADIER] {position_key}: BLOCKED SHORT entry — pc_ratio={_pc_val:.3f} <= {_pc_short_min:.3f} (bullish options flow). action={action}")
                                                if lock_acquired and self.redis_manager:
                                                    await self.redis_manager.delete(exec_lock_key)
                                                return f"FUNDING_GATE_TRADIER_SHORT_REJECT_pc={_pc_val:.3f}"
                                            logger.debug(f"[FUNDING_GATE_TRADIER_OK] {position_key}: pc_ratio={_pc_val:.3f} within [{_pc_short_min:.3f}, {_pc_long_max:.3f}]")
                                # ── OI_CONFIRM_TRADIER (4-quadrant OI×price) ──
                                if _oi_enabled:
                                    _oi_apply = (not is_hedge) or bool(getattr(config, 'OI_CONFIRM_TRADIER_HEDGE_GATE_ENABLED', False))
                                    if _oi_apply:
                                        _oi_min_pct = float(getattr(config, 'OI_CONFIRM_MIN_OI_CHANGE_PCT_TRADIER', 0.5))
                                        _oi_px_min_pct = float(getattr(config, 'OI_CONFIRM_MIN_PRICE_PCT_TRADIER', 0.3))
                                        # Total OI delta: weighted call+put change. Cache stores call_oi_change_pct/put_oi_change_pct.
                                        _call_oi = float(_oi_doc.get('total_call_oi') or 0.0)
                                        _put_oi = float(_oi_doc.get('total_put_oi') or 0.0)
                                        _total_oi = _call_oi + _put_oi
                                        _call_chg = _oi_doc.get('call_oi_change_pct')
                                        _put_chg = _oi_doc.get('put_oi_change_pct')
                                        _oi_chg = None
                                        if _call_chg is not None and _put_chg is not None and _total_oi > 0:
                                            try:
                                                _oi_chg = (float(_call_chg) * _call_oi + float(_put_chg) * _put_oi) / _total_oi
                                            except Exception: _oi_chg = None
                                        # Price delta: cache's underlying_price (older) vs current_price (now).
                                        _px_chg_pct = None
                                        try:
                                            _px_old = float(_oi_doc.get('underlying_price') or 0.0)
                                            if _px_old > 0 and current_price is not None and current_price > 0:
                                                _px_chg_pct = (float(current_price) - _px_old) / _px_old * 100.0
                                        except Exception: _px_chg_pct = None
                                        if _oi_chg is not None and _px_chg_pct is not None and abs(_oi_chg) >= _oi_min_pct and abs(_px_chg_pct) >= _oi_px_min_pct:
                                            _px_up = _px_chg_pct > 0; _oi_up = _oi_chg > 0
                                            if is_long:
                                                if _px_up and not _oi_up:
                                                    logger.warning(f"🚫 [OI_CONFIRM_TRADIER] {position_key}: BLOCKED LONG — squeeze rally (px↑{_px_chg_pct:+.2f}% + OI↓{_oi_chg:+.2f}%) action={action}")
                                                    if lock_acquired and self.redis_manager:
                                                        await self.redis_manager.delete(exec_lock_key)
                                                    return f"OI_CONFIRM_TRADIER_BLOCK_LONG_SQUEEZE_px={_px_chg_pct:.2f}%_oi={_oi_chg:.2f}%"
                                                if (not _px_up) and _oi_up:
                                                    logger.warning(f"🚫 [OI_CONFIRM_TRADIER] {position_key}: BLOCKED LONG — smart-money shorting (px↓{_px_chg_pct:+.2f}% + OI↑{_oi_chg:+.2f}%) action={action}")
                                                    if lock_acquired and self.redis_manager:
                                                        await self.redis_manager.delete(exec_lock_key)
                                                    return f"OI_CONFIRM_TRADIER_BLOCK_LONG_NEW_SHORTS_px={_px_chg_pct:.2f}%_oi={_oi_chg:.2f}%"
                                            else:
                                                if (not _px_up) and (not _oi_up):
                                                    logger.warning(f"🚫 [OI_CONFIRM_TRADIER] {position_key}: BLOCKED SHORT — long liquidation (px↓{_px_chg_pct:+.2f}% + OI↓{_oi_chg:+.2f}%) action={action}")
                                                    if lock_acquired and self.redis_manager:
                                                        await self.redis_manager.delete(exec_lock_key)
                                                    return f"OI_CONFIRM_TRADIER_BLOCK_SHORT_LIQUIDATION_px={_px_chg_pct:.2f}%_oi={_oi_chg:.2f}%"
                                                if _px_up and _oi_up:
                                                    logger.warning(f"🚫 [OI_CONFIRM_TRADIER] {position_key}: BLOCKED SHORT — bullish breakout (px↑{_px_chg_pct:+.2f}% + OI↑{_oi_chg:+.2f}%) action={action}")
                                                    if lock_acquired and self.redis_manager:
                                                        await self.redis_manager.delete(exec_lock_key)
                                                    return f"OI_CONFIRM_TRADIER_BLOCK_SHORT_NEW_LONGS_px={_px_chg_pct:.2f}%_oi={_oi_chg:.2f}%"
                except Exception as _fgoi_e:
                    logger.debug(f"[FUNDING_OI_GATE_TRADIER] {position_key}: gate skipped on exception (fail-open): {_fgoi_e}")
            if not is_regular_trading_hours():
                if lock_acquired and self.redis_manager:
                    await self.redis_manager.delete(exec_lock_key)
                return "MARKET_CLOSED"
            # ═══ GFV PROTECTION 1: Block sells on positions bought with unsettled funds ═══
            if is_reduce:
                _gfv_ok, _gfv_reason = self.gfv_tracker.can_sell(position_key)
                if not _gfv_ok:
                    logger.critical(f"[GFV_BLOCK] {position_key}: {_gfv_reason} — SELL BLOCKED to prevent Good Faith Violation")
                    if lock_acquired and self.redis_manager:
                        await self.redis_manager.delete(exec_lock_key)
                    return "GFV_BLOCKED"
            # ═══ GFV PROTECTION 2: AUTHORITATIVE settled-cash gate — blocks buys using unsettled proceeds ═══
            # Internal GFV tracker can drift/lose state on restart. This gate queries Tradier directly.
            # Fail-closed: API error → return 0.0 → buy blocked. No exceptions. No bypasses.
            if not is_reduce:
                _sc = await self._get_settled_cash_from_broker(account_key)
                _buy_cost = float(quantity) * float(current_price)
                if _buy_cost > _sc:
                    _msg = f"settled=${_sc:.2f} need=${_buy_cost:.2f} — BUY BLOCKED: would use unsettled funds and trigger GFV"
                    logger.critical(f"[GFV_SETTLED_CASH_BLOCK] 🚨 {position_key}: {_msg}")
                    if lock_acquired and self.redis_manager:
                        await self.redis_manager.delete(exec_lock_key)
                    # Invalidate cache so next attempt re-checks fresh balance
                    if hasattr(self, '_settled_cash_cache'):
                        self._settled_cash_cache.pop(account_key, None)
                    return f"GFV_SETTLED_CASH_BLOCK_{_sc:.0f}"
            # ═══ TRA DAILY TRADE LIMIT — 1 BUY per day, hard cap, no exceptions ═══
            # tra = cash account (ending 627), 4th GFV → account close risk.
            # 1 trade/day ensures absolute cash settlement control.
            if not is_reduce and account_key == 'tra':
                _today_et = datetime.now(ZoneInfo("US/Eastern")).strftime('%Y%m%d')
                if not hasattr(self, '_tra_daily_buy_count'):
                    self._tra_daily_buy_count = {'date': '', 'count': 0}
                if self._tra_daily_buy_count['date'] != _today_et:
                    self._tra_daily_buy_count = {'date': _today_et, 'count': 0}
                # 2026-06-03 RESTART-PROOF: the in-memory counter resets to 0 on any process
                # restart, which would re-allow a 2nd buy the same day → GFV → account closure.
                # Derive today's actual buys (OPEN/AUGMENT consume cash; REDUCE/CLOSE are sells)
                # from the immutable /history/tra/ ledger and gate on the MAX of {memory, ledger}.
                _hist_buys = 0
                try:
                    _tra_hist_dir = Path(config.BASE_PATH) / "data" / "history" / "tra"
                    for _hf in _tra_hist_dir.glob("*.jsonl"):
                        with open(_hf) as _hfh:
                            for _ln in _hfh:
                                if '"OPEN"' not in _ln and '"AUGMENT"' not in _ln:
                                    continue
                                try:
                                    _ev = json.loads(_ln)
                                except Exception:
                                    continue
                                if _ev.get("type") not in ("OPEN", "AUGMENT"):
                                    continue
                                try:
                                    _edt = datetime.fromisoformat(str(_ev.get("ts") or _ev.get("timestamp") or "").replace("Z", "+00:00")).astimezone(ZoneInfo("US/Eastern"))
                                except Exception:
                                    continue
                                if _edt.strftime('%Y%m%d') == _today_et:
                                    _hist_buys += 1
                except Exception as _he:
                    logger.error(f"[TRA_DAILY_BUY_LIMIT] ledger count failed ({_he}) — using in-memory only")
                # USER 2026-08-14: tra NEVER buys - sell only before loss in selloff
                if account_key == 'tra' and not getattr(config, 'TRA_ALLOW_BUYS', False):
                    return False, "TRA_NO_BUYS_SELL_ONLY", 0
                _tra_max = int(getattr(config, 'TRA_MAX_BUYS_PER_DAY', 1))
                # 4 DAYS no buying after a sell on cash tra (GFV 5 flags -> ban at 6)
                _tra_cooldown_h = float(getattr(config, 'TRA_BUY_COOLDOWN_AFTER_SELL_HOURS', 96.0))
                try:
                    _last_sell = getattr(self, '_tra_last_sell_ts', 0) or 0
                    if _last_sell and (time.time() - _last_sell) < _tra_cooldown_h * 3600:
                        _hrs_left = (_tra_cooldown_h*3600 - (time.time()-_last_sell))/3600
                        return False, f"TRA_BUY_COOLDOWN_4D_sell_{_hrs_left:.1f}h_left", 0
                except Exception:
                    pass
                _eff_buys = max(int(self._tra_daily_buy_count['count']), _hist_buys)
                if _eff_buys >= _tra_max:
                    logger.critical(f"[TRA_DAILY_BUY_LIMIT] 🚨 {position_key}: already {_eff_buys}/{_tra_max} buy(s) today ({_today_et}) [mem={self._tra_daily_buy_count['count']} ledger={_hist_buys}] — BUY BLOCKED to prevent GFV. reason={reason}")
                    if lock_acquired and self.redis_manager:
                        await self.redis_manager.delete(exec_lock_key)
                    return f"TRA_DAILY_BUY_LIMIT_{_eff_buys}of{_tra_max}"
            result = await self.place_order(  symbol, side, quantity, "market", duration="day",
                action=action, position_side=position_side, account_key=account_key,
                reason=reason)
            
            # --- 5. RESPONSE PARSING (THE FIX) ---
            if result and isinstance(result, dict):
                # Tradier wraps success in 'order', but errors might be top level
                order_data = result.get('order', result) 
                
                order_id = order_data.get('id')
                order_status = order_data.get('status')
                
                # Check for errors
                errors = result.get('errors', {}).get('error', [])
                if isinstance(errors, list) and errors:
                    order_reject_reason = errors[0]
                elif not order_id:
                    # If no ID and no explicit error list, dump the whole thing
                    order_reject_reason = str(result)
                else:
                    order_reject_reason = None

                if order_id:
                    # SUCCESS
                    log_msg = f"[TRADE] SENT: ✅ {symbol:<5} {action:<7} {side:<4} | Qty: {quantity:<4} @ ${current_price:<7.2f} | Status: {order_status} | ID: {order_id}"
                    logger.info(log_msg)
                    tradier_action_logger.info(f"{position_key}: {log_msg}")

                    self.recently_processed_signals[position_key] = time.time()
                    # [2026-07-03] OVERTRADE counts confirmed submissions (not attempts) — see queue_trade_action guard.
                    if not is_reduce:
                        try:
                            global _OVERTRADE_COUNTER
                            if '_OVERTRADE_COUNTER' not in globals(): _OVERTRADE_COUNTER = {}
                            _ots_key = f"{datetime.now(timezone.utc).strftime('%Y%m%d')}:{position_key}"
                            _OVERTRADE_COUNTER[_ots_key] = _OVERTRADE_COUNTER.get(_ots_key, 0) + 1
                        except Exception: pass
                    # [2026-07-03] CLOSE_REFIRE_GUARD bookkeeping: remember the working close order.
                    if is_reduce and order_id != "GHOST_CLEARED":
                        try:
                            if not hasattr(self, '_last_close_order'): self._last_close_order = {}
                            self._last_close_order[position_key] = (order_id, time.time())
                        except Exception: pass
                    # ═══ TRA DAILY BUY COUNTER: increment on successful buy ═══
                    if not is_reduce and account_key == 'tra':
                        if hasattr(self, '_tra_daily_buy_count'):
                            self._tra_daily_buy_count['count'] += 1
                            logger.critical(f"[TRA_DAILY_BUY_LIMIT] {position_key}: buy #{self._tra_daily_buy_count['count']} of {getattr(config, 'TRA_MAX_BUYS_PER_DAY', 1)} today ({self._tra_daily_buy_count['date']})")
                        # Invalidate settled cash cache — balance changed
                        if hasattr(self, '_settled_cash_cache'):
                            self._settled_cash_cache.pop(account_key, None)
                    # ═══ GFV TRACKING: record sales + mark buys with unsettled funds ═══
                    _trade_value = quantity * current_price
                    if is_reduce and order_id != "GHOST_CLEARED":
                        self.gfv_tracker.record_sale(account_key, symbol, _trade_value)
                    elif is_augment:
                        _unsettled = self.gfv_tracker.get_unsettled_total(account_key)
                        if _unsettled > 0:
                            _settle_date = self.gfv_tracker.get_earliest_settlement(account_key)
                            if _settle_date:
                                self.gfv_tracker.record_buy_with_unsettled(position_key, _settle_date)
                    # BACKTEST_CHANGE_T37: track daily realized P&L for circuit breaker
                    if is_reduce and self.position_manager:
                        _pos_for_pnl = self.position_manager.positions.get(position_key)
                        if _pos_for_pnl:
                            _ep = float(getattr(_pos_for_pnl, 'entry_price', 0) or 0)
                            _ps = position_side
                            if _ep > 0 and current_price is not None and current_price > 0:
                                _trade_pnl = (current_price - _ep) * quantity if _ps == 'LONG' else (_ep - current_price) * quantity
                                # 2026-04-30 Job 3 (iii): per-trade returns audit logger — risk-zero additive.
                                try:
                                    from per_trade_logger import \
                                        log_close as _ptl_log_close
                                    _ptl_pnl_pct = ((current_price - _ep) / _ep * 100.0) if _ps == 'LONG' else ((_ep - current_price) / _ep * 100.0)
                                    _ptl_opened = getattr(_pos_for_pnl, 'opened_at', None)
                                    _ptl_hold_min = 0.0
                                    if _ptl_opened is not None:
                                        try:
                                            _now = datetime.now(timezone.utc)
                                            _opn = _ptl_opened if isinstance(_ptl_opened, datetime) else datetime.fromisoformat(str(_ptl_opened))
                                            _ptl_hold_min = max(0.0, (_now - _opn).total_seconds() / 60.0)
                                        except Exception:
                                            _ptl_hold_min = 0.0
                                    _ptl_log_close(account=account_key, symbol=symbol, side=str(_ps), entry_price=_ep, exit_price=float(current_price), pnl_pct=_ptl_pnl_pct, fees_pct=0.0, hold_minutes=_ptl_hold_min, qty=float(quantity), reason=str(reason))
                                except Exception:
                                    pass
                                _daily_loss_tracker["realized_pnl"] += _trade_pnl
                                _max_loss_pct = getattr(config, 'MAX_DAILY_LOSS_PCT', 3.0)
                                _portfolio_bal = self.get_current_portfolio_balance()
                                _total_exp = _portfolio_bal.get('total', 10000.0) or 10000.0
                                _loss_pct = (_daily_loss_tracker["realized_pnl"] / _total_exp) * 100.0
                                if _loss_pct < -_max_loss_pct and not _daily_loss_tracker["halted"]:
                                    _daily_loss_tracker["halted"] = True
                                    logger.critical(f"[DAILY_LOSS_BREAKER] Daily P&L=${_daily_loss_tracker['realized_pnl']:.2f} ({_loss_pct:.2f}%) exceeds -{_max_loss_pct}% limit. HALTING ALL NEW OPENS.")
                    # Update Local Memory Instantly
                    if self.position_manager:
                        local_pos = self.position_manager.positions.get(position_key)
                        now_utc = datetime.now(timezone.utc)
                        if local_pos:
                            if is_reduce:
                                new_qty = 0.0 if order_id == "GHOST_CLEARED" else max(0.0, float(local_pos.positionAmt) - float(quantity))
                                local_pos.positionAmt = new_qty
                                local_pos.last_reduction_time = now_utc
                                local_pos.last_reduction_amount = float(quantity)
                                local_pos.last_reduction_price = float(current_price)
                                local_pos.was_reduced = True
                                local_pos.reduction_reason = reason or action
                                # 2026-04-26 — record exit time/price on EVERY reduce (not only full close).
                                # Was: only on `if new_qty <= 0` (full close), causing reopen-cooldown to read stale data
                                # on partial reduces. Inconsequential while TRADIER_REOPEN_WAIT_S=0.0 but should be correct.
                                _set_reentry_exit_state(
                                    self, position_key, time.time(), float(current_price)
                                )
                                # Full close: ALSO record reentry candidate snapshot for reopen logic.
                                if new_qty <= 0:
                                    # Latch the mandatory reclaim only on an
                                    # acknowledged full close.  Partial exits
                                    # do not create a flat-position obligation.
                                    _reclaim_ind = self.get_indicators(symbol) or {}
                                    _reclaim_prior = safe_fetch_float(
                                        _reclaim_ind.get(
                                            "e02_prior_high_4h_n30"
                                            if position_side == "LONG"
                                            else "e02_prior_low_4h_n30"
                                        ),
                                        float(current_price),
                                    )
                                    _reclaim_prior = (
                                        _reclaim_reference_from_reason(
                                            reason, _reclaim_prior
                                        )
                                    )
                                    _reclaim_obligation = _ReclaimObligation(
                                        side=position_side
                                    )
                                    _reclaim_obligation.latch(
                                        exit_fill=float(current_price),
                                        prior_opposite_level=_reclaim_prior,
                                        exited_notional_usd=(
                                            abs(float(original_position_amt or quantity))
                                            * float(current_price)
                                        ),
                                        exit_ts=int(time.time()),
                                        base_unit_usd=float(
                                            getattr(
                                                config,
                                                "LR_BAND_LADDER_BASE_UNIT_USD",
                                                2000.0,
                                            )
                                        ),
                                        capacity_usd=float(
                                            getattr(
                                                config,
                                                "LR_BAND_LADDER_CAPACITY_USD",
                                                16000.0,
                                            )
                                        ),
                                    )
                                    self.__dict__.setdefault(
                                        "_mandatory_reclaim_obligations", {}
                                    )[position_key] = _reclaim_obligation.to_dict()
                                    if order_id != "GHOST_CLEARED":
                                        _ep = float(getattr(local_pos, 'entry_price', 0) or 0)
                                        _mg = float(getattr(local_pos, 'max_gain', 0) or 0)
                                        self._record_reentry_candidate(position_key, float(current_price), _ep, reason or action, _mg, float(original_position_amt))
                                    if order_id == "GHOST_CLEARED":
                                        # ONLY zero positionAmt + gain + cycle_peak_gain. NEVER zero entry_price/max_gain — they are sacred.
                                        # max_gain has its own decay function for reentry; cycle_peak_gain resets per cycle for exit logic.
                                        local_pos.positionAmt = 0.0
                                        local_pos.gain = 0.0
                                        try: local_pos.cycle_peak_gain = 0.0
                                        except Exception: pass
                                        logger.warning(f"[GHOST_CLEAR] {position_key}: positionAmt + gain + cycle_peak_gain zeroed. entry_price/max_gain PRESERVED.")
                            elif is_augment:
                                if float(getattr(local_pos, 'positionAmt', 0.0) or 0) == 0.0: local_pos.opened_at = now_utc; local_pos.max_gain = 0.0; local_pos.cycle_peak_gain = 0.0; local_pos.gain = 0.0; local_pos.was_reduced = False; local_pos.was_reentered = False
                                new_qty = float(local_pos.positionAmt) + float(quantity)
                                # 2026-04-08 FIX: Do NOT update positionAmt locally.
                                # Let tradier_positions API sync (every 5s) be the ONLY source of truth.
                                # Local optimistic updates caused drift: 125 real → 175 local from double-counting.
                                # local_pos.positionAmt = float(local_pos.positionAmt) + float(quantity)  # DISABLED
                                local_pos.last_augmentation_time = now_utc
                                local_pos.augment_reason = reason or action
                                old_cost = (new_qty - quantity) * local_pos.entry_price
                                new_cost = quantity * current_price
                                if new_qty > 0:
                                    local_pos.entry_price = (old_cost + new_cost) / new_qty

                    # Exit state is acknowledgement-driven. In the backtest, a successful
                    # API result is an immediate fill; live keeps the obligation latched
                    # until broker sync confirms flat. A fresh OPEN/REENTRY always starts
                    # a new cycle and clears any obligation from the prior position.
                    if self.delta_tracker:
                        _delta_fresh_cycle = bool(
                            (not is_reduce)
                            and is_entry_action
                            and abs(float(original_position_amt or 0.0)) < 0.0001
                        )
                        _delta_close_ack = bool(
                            is_reduce
                            and is_full_close
                            and (getattr(self, "is_backtest", False) or order_id == "GHOST_CLEARED")
                        )
                        if _delta_fresh_cycle or _delta_close_ack:
                            self.delta_tracker.reset_position_state(symbol)
                            logger.info(
                                f"[DELTA_EXIT_STATE_ACK] {position_key}: "
                                f"{'fresh_cycle' if _delta_fresh_cycle else 'confirmed_close'}"
                            )

                    if (
                        (not is_reduce)
                        and is_entry_action
                        and abs(float(original_position_amt or 0.0)) < 0.0001
                    ):
                        _obligations = self.__dict__.setdefault(
                            "_mandatory_reclaim_obligations", {}
                        )
                        _obligation_raw = _obligations.get(position_key)
                        if _obligation_raw:
                            _obligation = _ReclaimObligation.from_dict(
                                _obligation_raw
                            )
                            _obligation.confirm_fill()
                            _obligations[position_key] = _obligation.to_dict()
                        if _is_mandatory_reclaim:
                            _trace_row = self.__dict__.setdefault(
                                "_mandatory_reentry_trace", {}
                            ).setdefault(position_key, {})
                            _trace_row["pending"] = False
                            _trace_row["filled_ts"] = time.time()
                            _trace_row["filled_price"] = float(current_price)

                    await self._append_to_history(position_key, action, quantity, current_price, reason)
                    if lock_acquired and self.redis_manager:
                        # Ghost-cleared positions get 5-min cooldown to stop repeat loops
                        ghost_ttl = 300 if order_id == "GHOST_CLEARED" else 5
                        ghost_status = "ghost_cleared" if order_id == "GHOST_CLEARED" else "filled"
                        await self.redis_manager.set(exec_lock_key, {"status": ghost_status, "timestamp": time.time()}, ex=ghost_ttl)

                    return "SUCCESS"

                elif order_reject_reason:
                    # REJECTION
                    logger.error(f"[TRADE] ❌ {symbol} {side} REJECTED: {order_reject_reason}")
                    if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                    return f"ORDER_REJECTED:{order_reject_reason}"
            else:
                logger.error(f"[TRADE] ❌ {symbol} {side} Failed: Invalid API response.")
                if lock_acquired and self.redis_manager: await self.redis_manager.delete(exec_lock_key)
                return "ORDER_API_ERROR"

        except Exception as e:
            logger.error(f"[EXECUTE_CRASH] {position_key}: {e}",  exc_info=True )
            if lock_acquired and self.redis_manager:
                try: await self.redis_manager.delete(exec_lock_key)
                except Exception: pass
            return f"EXCEPTION_{str(e)[:50]}"

    def _resolve_entry_reason(self, position_key: str) -> str:
        try:
            _m = getattr(self, '_pending_entry_reason', None)
            if _m:
                _v = _m.pop(position_key, None)
                if _v and (time.time() - _v[1]) <= 600.0:
                    return _v[0]
        except Exception:
            pass
        return "SYNC_DETECTION"

    async def _append_to_history(self, position_key: str, trade_type: str, qty: float, price: float, reason: str = ""):
        try:
            # SYNC-DEDUPE [2026-07-03]: broker-sync re-detections of the SAME held position must not
            # spam the ledger (was 97% of all OPEN events, forcing rotation that destroyed real fills).
            if trade_type == "OPEN" and reason == "SYNC_DETECTION":
                _sd = getattr(self, '_sync_open_seen', None)
                if _sd is None:
                    _sd = self._sync_open_seen = {}
                _sd_prev = _sd.get(position_key)
                _sd_now = time.time()
                if _sd_prev is not None:
                    if abs(_sd_prev[0] - float(qty)) < 1e-9 and abs(_sd_prev[1] - float(price)) < 1e-6:
                        _sd[position_key] = (float(qty), float(price), _sd_now)
                        return
                    if (_sd_now - _sd_prev[2]) < 1800.0:
                        return
                _sd[position_key] = (float(qty), float(price), _sd_now)
            parts = position_key.split(':')
            account_key = parts[0] if len(parts) > 0 else "unknown"
            symbol_side = parts[1] if len(parts) > 1 else position_key
            hist_dir = Path(self.config.DATA_DIR) / "history" / account_key
            hist_dir.mkdir(parents=True, exist_ok=True)
            filename = hist_dir / f"{symbol_side}.jsonl"
            MAX_SIZE_BYTES = 200 * 1024
            if filename.exists():
                try:
                    if filename.stat().st_size > MAX_SIZE_BYTES:
                        # ROTATION ARCHIVE [2026-07-03]: timestamped generations — never unlink history.
                        backup = filename.with_name(f"{filename.name}.{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S%f')}.bak")
                        filename.rename(backup)
                except Exception: pass
            entry = {"ts": datetime.now(timezone.utc).isoformat(), "type": trade_type, "qty": round(float(qty), 6), "price": round(float(price), 4), "value": round(float(qty) * float(price), 2), "reason": reason or "Manual/System Detection", "indicators": {}}
            async with aiofiles.open(filename, "a") as f:
                await f.write(orjson.dumps(entry).decode('utf-8') + "\n")
        except Exception as e:
            logger.error(f"[HISTORY] Write error {position_key}: {e}")

    def _load_reentry_candidates(self, account_key: str) -> dict:
        path = Path(config.BASE_PATH) / account_key / "reentry_candidates.json"
        if path.exists():
            try:
                return json.loads(path.read_text())
            except Exception:
                return {}
        return {}

    def _save_reentry_candidates(self, account_key: str, candidates: dict):
        path = Path(config.BASE_PATH) / account_key / "reentry_candidates.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(candidates, indent=2, default=str))

    def _record_reentry_candidate(self, position_key: str, exit_price: float, entry_price: float, reason: str, max_gain: float, position_amt: float):
        try:
            parts = position_key.split(':')
            if len(parts) < 2:
                return
            account_key = parts[0]
            symbol_side = parts[1]
            symbol = symbol_side.rsplit('_', 1)[0] if '_' in symbol_side else symbol_side
            side = "LONG" if symbol_side.endswith("_LONG") else "SHORT"
            candidates = self._load_reentry_candidates(account_key)
            candidates[position_key] = {"symbol": symbol, "side": side, "exit_price": round(exit_price, 4), "exit_time": datetime.now(timezone.utc).isoformat(), "exit_reason": reason or "UNKNOWN", "entry_price": round(entry_price, 4), "max_gain_at_exit": round(max_gain, 2), "position_amt_at_exit": round(position_amt, 2), "reentry_target_price": round(exit_price, 4), "status": "WAITING", "attempts": 0, "last_check": datetime.now(timezone.utc).isoformat()}
            self._save_reentry_candidates(account_key, candidates)
            logger.info(f"[REENTRY_RECORD] {position_key}: Recorded reentry candidate @ exit=${exit_price:.2f} entry=${entry_price:.2f} reason={reason}")
        except Exception as e:
            logger.error(f"[REENTRY_RECORD] Error recording {position_key}: {e}")

    def _seed_reentry_from_positions(self):
        try:
            now_utc = datetime.now(timezone.utc)
            for acc in self.target_accounts:
                candidates = self._load_reentry_candidates(acc)
                seeded = 0
                for side_file in ["long_positions.json", "short_positions.json"]:
                    pos_path = Path(config.BASE_PATH) / acc / side_file
                    if not pos_path.exists():
                        continue
                    try:
                        pos_data = json.loads(pos_path.read_text())
                    except Exception:
                        continue
                    for pk, pv in pos_data.items():
                        amt = float(pv.get("positionAmt", 0) or 0)
                        ep = float(pv.get("entry_price", 0) or 0)
                        if amt != 0 or ep <= 0:
                            continue
                        red_time_str = pv.get("last_reduction_time", "")
                        red_price = float(pv.get("last_reduction_price", 0) or 0)
                        if not red_time_str or red_price <= 0:
                            continue
                        try:
                            red_dt = datetime.fromisoformat(red_time_str.replace("Z", "+00:00"))
                        except Exception:
                            continue
                        hours_since = (now_utc - red_dt).total_seconds() / 3600.0
                        if hours_since > 24.0:
                            continue
                        if pk in candidates and candidates[pk].get("status") in ("WAITING", "REENTERED", "EXPIRED"):
                            continue
                        symbol = pk.split(":")[-1].rsplit("_", 1)[0] if ":" in pk else pk.rsplit("_", 1)[0]
                        side = "LONG" if pk.endswith("_LONG") else "SHORT"
                        mg = float(pv.get("max_gain", 0) or 0)
                        reason = pv.get("reduction_reason", "SEEDED_FROM_POSITIONS")
                        candidates[pk] = {"symbol": symbol, "side": side, "exit_price": round(red_price, 4), "exit_time": red_time_str, "exit_reason": reason or "SEEDED_FROM_POSITIONS", "entry_price": round(ep, 4), "max_gain_at_exit": round(mg, 2), "position_amt_at_exit": 0, "reentry_target_price": round(red_price, 4), "status": "WAITING", "attempts": 0, "last_check": now_utc.isoformat()}
                        seeded += 1
                decisions_dir = Path(config.BASE_PATH) / "data" / "decisions"
                today_str = now_utc.strftime("%Y%m%d")
                for jsonl_name in [f"decisions_{acc}_{today_str}.jsonl"]:
                    jsonl_path = decisions_dir / jsonl_name
                    if not jsonl_path.exists():
                        continue
                    try:
                        for line in jsonl_path.read_text().strip().split("\n"):
                            if not line.strip():
                                continue
                            try:
                                rec = json.loads(line)
                            except Exception:
                                continue
                            action_str = rec.get("action", "")
                            if "CLOSE" not in action_str.upper():
                                continue
                            rpk = rec.get("position_key", "")
                            if not rpk or rpk in candidates:
                                continue
                            trade = rec.get("trade", {})
                            pos_amt = float(trade.get("position_amt", 0) or 0)
                            if pos_amt <= 0:
                                continue
                            exit_p = float(trade.get("price", 0) or 0)
                            entry_p = float(trade.get("entry_price", 0) or 0)
                            if exit_p <= 0 or entry_p <= 0:
                                continue
                            symbol = rpk.split(":")[-1].rsplit("_", 1)[0] if ":" in rpk else rpk.rsplit("_", 1)[0]
                            side = "LONG" if rpk.endswith("_LONG") else "SHORT"
                            ts_str = rec.get("timestamp", now_utc.isoformat())
                            reason_text = rec.get("reason_text", "SEEDED_FROM_DECISIONS")
                            candidates[rpk] = {"symbol": symbol, "side": side, "exit_price": round(exit_p, 4), "exit_time": ts_str, "exit_reason": reason_text, "entry_price": round(entry_p, 4), "max_gain_at_exit": round(float(trade.get("gain_pct", 0) or 0), 2), "position_amt_at_exit": round(pos_amt, 2), "reentry_target_price": round(exit_p, 4), "status": "WAITING", "attempts": 0, "last_check": now_utc.isoformat()}
                            seeded += 1
                    except Exception as e:
                        logger.error(f"[REENTRY_SEED] Error reading {jsonl_path}: {e}")
                if seeded > 0:
                    self._save_reentry_candidates(acc, candidates)
                    logger.info(f"[REENTRY_SEED] {acc}: Seeded {seeded} reentry candidates from positions and decisions")
        except Exception as e:
            logger.error(f"[REENTRY_SEED] Error: {e}", exc_info=True)

    def would_exit_trigger_now(self, symbol, indicators, side, *, current_price=None):
        # Symmetric gate: returns (blocked: bool, reason: str).
        # Blocks an entry/reentry whenever the mirror exit rubric would fire for `side`.
        # Consulted rubrics: wt_dc_score_exit, DELTA engine (zone+exit flags), DELTA speed floor.
        try:
            i = indicators or {}
            is_long = str(side).upper() == "LONG"
            px = float(current_price) if current_price else float(i.get("current_price", 0) or 0)
            if px <= 0:
                return False, "no_price"
            _s, _r = wt_dc_score_exit(i, is_long, px)
            _th = getattr(config, 'WT_DC_EXIT_THRESHOLD', 25)
            if _s >= _th:
                return True, f"WT_DC_SCORE_{_s:.0f}>={_th}_{_r[:40]}"
            _dt = getattr(self, 'delta_tracker', None)
            if config.DELTA_ENGINE_ENABLED and _dt:
                _sig = _dt.update(symbol, i, {"side": "LONG" if is_long else "SHORT"})
                if _sig:
                    if is_long and _sig.exit_long:
                        return True, f"DELTA_EXIT_LONG_{_sig.zone}_{_sig.zone_reason or ''}"[:90]
                    if (not is_long) and _sig.exit_short:
                        return True, f"DELTA_EXIT_SHORT_{_sig.zone}_{_sig.zone_reason or ''}"[:90]
                    if is_long and _sig.zone in ("TOP", "TOP_TOP"):
                        return True, f"DELTA_TOP_ZONE_LONG_{_sig.zone}"
                    if (not is_long) and _sig.zone in ("BOTTOM", "BOTTOM_BOTTOM"):
                        return True, f"DELTA_BOTTOM_ZONE_SHORT_{_sig.zone}"
                    _speed_min = float(getattr(config, 'REENTRY_SYMGATE_SPEED_MIN', 1.0))
                    _bs = float(getattr(_sig, 'bull_speed', 0.0) or 0.0)
                    _es = float(getattr(_sig, 'bear_speed', 0.0) or 0.0)
                    if is_long and _bs < _speed_min:
                        return True, f"DELTA_SPEED_SLOW_LONG_bs={_bs:.1f}<{_speed_min:.1f}"
                    if (not is_long) and _es < _speed_min:
                        return True, f"DELTA_SPEED_SLOW_SHORT_es={_es:.1f}<{_speed_min:.1f}"
            return False, "ok"
        except Exception as e:
            logger.warning(f"[SYMGATE] {symbol} {side}: error {e} — failing OPEN (allow)")
            return False, f"error:{e}"

    async def reentry_monitor_loop(self):
        logger.info("[REENTRY_MONITOR] Dedicated reentry monitor started (15s cycle)")
        await asyncio.sleep(30)
        while self.running:
            try:
                if not is_regular_trading_hours():
                    await asyncio.sleep(60)
                    continue
                for acc in self.target_accounts:
                    candidates = self._load_reentry_candidates(acc)
                    if not candidates:
                        continue
                    changed = False
                    now_utc = datetime.now(timezone.utc)
                    for pk, cand in list(candidates.items()):
                        status = cand.get("status", "WAITING")
                        if status == "REENTERED" or status == "EXPIRED":
                            continue
                        # RETRY: FAILED candidates get a second chance after a backoff
                        if status.startswith("FAILED:"):
                            fail_count = cand.get("fail_count", 0)
                            last_fail_ts = cand.get("last_fail_ts", 0)
                            if fail_count >= 5:
                                continue  # give up after 5 attempts
                            backoff_s = min(120 * (2 ** fail_count), 900)
                            if time.time() - last_fail_ts < backoff_s:
                                continue
                            cand["status"] = "WAITING"
                            changed = True
                        if cand.get("status") != "WAITING":
                            continue
                        symbol = cand.get("symbol", "")
                        side = cand.get("side", "LONG")
                        exit_price = float(cand.get("exit_price", 0))
                        exit_time_str = cand.get("exit_time", "")
                        if not symbol or exit_price <= 0:
                            continue
                        try:
                            exit_dt = datetime.fromisoformat(exit_time_str.replace("Z", "+00:00")) if exit_time_str else now_utc
                        except Exception:
                            exit_dt = now_utc
                        hours_since = (now_utc - exit_dt).total_seconds() / 3600.0
                        _min_gap_min = float(getattr(config, 'REENTRY_MIN_GAP_MINUTES', 15.0))
                        if hours_since * 60.0 < _min_gap_min:
                            logger.info(f"[REENTRY_MONITOR] {pk}: GAP {hours_since*60.0:.1f}m<{_min_gap_min:.0f}m — waiting for min-gap window")
                            continue
                        # REENTRIES NEVER EXPIRE — WT always cycles back. Weekend gaps can be 66+ hours.
                        if hours_since > 168.0:  # Only expire after 1 WEEK (absolute safety net)
                            cand["status"] = "EXPIRED"
                            changed = True
                            logger.critical(f"[REENTRY_MONITOR] {pk}: EXPIRED after {hours_since:.1f}h (1 week) — THIS SHOULD NEVER HAPPEN")
                            continue
                        if hours_since > 24.0:
                            logger.warning(f"[REENTRY_OVERDUE] {pk}: {hours_since:.1f}h since exit — still waiting for 2/3 WT favor")
                        i = self.get_indicators(symbol) or {}
                        current_price = float(i.get("current_price", 0))
                        if current_price <= 0:
                            try:
                                client = TradierAPIClient(config, account_key=acc)
                                await client.connect()
                                quote = await client.get_quote(symbol)
                                current_price = float(quote.get("last", 0)) if quote else 0
                            except Exception:
                                pass
                        if current_price <= 0:
                            logger.warning(f"[REENTRY_MONITOR] {pk}: No price available for {symbol}, skipping")
                            continue
                        k_5m = float(i.get("k_5m", 50))
                        k_5m_prev = float(i.get("k_5m_prev", 50))
                        d_5m = float(i.get("d_5m", 50))
                        k_15m = float(i.get("k_15m", 50))
                        k_15m_prev = float(i.get("k_15m_prev", 50))
                        k_1h_rm = float(i.get("k_1h", 50))
                        wt1_5m = float(i.get("wt1_5m", 0))
                        wt2_5m = float(i.get("wt2_5m", 0))
                        wt1_15m = float(i.get("wt1_15m", 0))
                        wt2_15m = float(i.get("wt2_15m", 0))
                        wt1_1h = float(i.get("wt1_1h", 0))
                        wt2_1h = float(i.get("wt2_1h", 0))
                        wt1_4h = float(i.get("wt1_4h", 0))
                        wt2_4h = float(i.get("wt2_4h", 0))
                        wt1_D = float(i.get("wt1_D", 0))
                        wt2_D = float(i.get("wt2_D", 0))
                        cand["last_check"] = now_utc.isoformat()
                        cand["attempts"] = cand.get("attempts", 0) + 1
                        changed = True
                        reenter = False
                        wt_cross_1h = str(i.get("wt_cross_1h", ""))
                        # Check the current exit score — if it's still high, DO NOT reenter
                        _rm_exit_score, _rm_exit_reason = wt_dc_score_exit(i, side == "LONG", current_price)
                        _rm_threshold = getattr(config, 'WT_DC_EXIT_THRESHOLD', 25)
                        if _rm_exit_score >= _rm_threshold:
                            logger.info(f"[REENTRY_MONITOR] {pk}: exit score {_rm_exit_score:.0f}>={_rm_threshold} — signal still says EXIT, waiting for reversal")
                            continue
                        if getattr(config, 'REENTRY_SYMGATE_ENABLED', True):
                            _sg_blocked, _sg_reason = self.would_exit_trigger_now(symbol, i, side, current_price=current_price)
                            if _sg_blocked:
                                logger.info(f"[REENTRY_MONITOR] {pk}: SYMGATE block — {_sg_reason}")
                                continue
                        # ═══ PATHWAY 0: 5m-exit rescue (user directive 2026-04-16) ═══
                        _er_str = str(cand.get("exit_reason", "")).upper()
                        _was_5m_exit = any(t in _er_str for t in ('5M', '_5M_', 'DELTA_EXIT', 'STOCH_CROSS', 'WT_CROSSUNDER', 'WT_CROSSOVER', 'MANDATORY_REENTRY', 'WT_DC_EXIT'))
                        # ═══ MANDATORY_REENTRY dc4 gate (USER 2026-06-22): within 30min of a
                        # DELTA_EXIT/WT_CROSS/MANDATORY_REENTRY exit, reentry REQUIRES price ≥ dc_high4_5m
                        # (LONG) / ≤ dc_low4_5m (SHORT). If unmet within window, falls through to
                        # normal tier gates (exit_price cross-back). All paths blocked — no P0 bypass.
                        # Rollback: MANDATORY_REENTRY_DC4_WINDOW_MIN=0 in config_tradier.py ═══
                        _mandatory_dc4_window_min = float(getattr(config, 'MANDATORY_REENTRY_DC4_WINDOW_MIN', 30.0))
                        if 'MANDATORY_REENTRY' in _er_str and _mandatory_dc4_window_min > 0 and hours_since * 60.0 <= _mandatory_dc4_window_min:
                            _mand_dc_hi = float(i.get('dc_high4_5m', 0) or 0)
                            _mand_dc_lo = float(i.get('dc_low4_5m', 0) or 0)
                            if side == "LONG":
                                _mand_price_ok = _mand_dc_hi > 0 and current_price >= _mand_dc_hi
                            else:
                                _mand_price_ok = _mand_dc_lo > 0 and current_price <= _mand_dc_lo
                            if not _mand_price_ok:
                                _mand_level = _mand_dc_hi if side == "LONG" else _mand_dc_lo
                                logger.debug(f"[REENTRY_MANDATORY_DC4] {pk}: MANDATORY exit {hours_since*60:.0f}/{_mandatory_dc4_window_min:.0f}m — price {current_price:.2f} not past dc4={'hi' if side=='LONG' else 'lo'} {_mand_level:.2f} — blocked (normal path opens after window)")
                                continue
                        if side == "LONG":
                            _1h_still_trending = wt1_1h > wt2_1h
                            _5m_entry_fires = (wt1_5m > wt2_5m) and (k_5m > d_5m)
                        else:
                            _1h_still_trending = wt1_1h < wt2_1h
                            _5m_entry_fires = (wt1_5m < wt2_5m) and (k_5m < d_5m)
                        _p0_rescue = _was_5m_exit and _1h_still_trending and _5m_entry_fires
                        if _p0_rescue:
                            logger.warning(f"🟢 [REENTRY_P0_5M_RESCUE] {pk}: exit_reason='{_er_str[:40]}' 1h_trending={_1h_still_trending} 5m_entry=TRUE — BYPASS FILTERS")
                        # ═══ PATHWAY F (2026-04-17) — FAVORABLE MOVE: market kept moving in our direction after exit.
                        # The exit was premature. Force reenter. Mirror of crypto ez_manage FIX B.
                        # User rule: k_15m > 90 (LONG) / < 10 (SHORT) → size down to 50% (rally may be ending). ═══
                        _fav_pct = float(getattr(config, 'REENTRY_FAVORABLE_MOVE_PCT', 1.0)) / 100.0
                        _fav_exit_px = float(cand.get("exit_price", 0) or 0)
                        if side == "LONG":
                            _fav_price = _fav_exit_px > 0 and current_price >= _fav_exit_px * (1.0 + _fav_pct)
                        else:
                            _fav_price = _fav_exit_px > 0 and current_price <= _fav_exit_px * (1.0 - _fav_pct)
                        _fav_htf_count = sum(1 for w1, w2 in [(wt1_1h, wt2_1h), (wt1_4h, wt2_4h), (wt1_D, wt2_D)] if (w1 > w2 if side == "LONG" else w1 < w2))
                        _fav_htf_ok = _fav_htf_count >= int(getattr(config, 'REENTRY_FAVORABLE_HTF_MIN', 2))
                        _fav_fired = (not _p0_rescue) and _fav_price and _fav_htf_ok
                        _fav_k15m_partial = False
                        if _fav_fired:
                            _k15m_thr = float(getattr(config, 'REENTRY_K15M_PARTIAL_THRESHOLD', 90.0))
                            _fav_k15m_partial = (side == "LONG" and k_15m >= _k15m_thr) or (side == "SHORT" and k_15m <= (100.0 - _k15m_thr))
                            _fav_mult_pct = int(getattr(config, 'REENTRY_K15M_PARTIAL_MULT', 0.5) * 100) if _fav_k15m_partial else 100
                            logger.critical(f"🚀 [REENTRY_FAVORABLE_MOVE] {pk}: exit={_fav_exit_px:.2f} cur={current_price:.2f} move={(current_price/_fav_exit_px-1)*100:+.2f}% htf={_fav_htf_count}/3 k15m={k_15m:.0f} size={_fav_mult_pct}%{' (OVERHEAT — rally maturing)' if _fav_k15m_partial else ''} — FORCING REENTRY")
                        # ═══ AGGRESSIVE FAST-PATH (2026-04-17) — bypass tier gates if fresh dc_x1h or stoch_x15m
                        # fires within the aggressive window. NEVER delays — only ACCELERATES when signal is there.
                        # If window triggers absent, logic falls through to the normal Tier 1/2/3 gates below. ═══
                        _t0_window_min = float(getattr(config, 'REENTRY_AGGRESSIVE_WINDOW_MIN', 5.0))
                        _dc_x1h_now = (i.get("dc_basis_crossover_1h", False) if side == "LONG" else i.get("dc_basis_crossunder_1h", False))
                        _stoch_15m_now = (i.get("stoch_crossover_15m", False) if side == "LONG" else i.get("stoch_crossunder_15m", False))
                        _aggr_fired = (
                            not _p0_rescue and not _fav_fired
                            and hours_since * 60.0 < _t0_window_min
                            and (_dc_x1h_now or _stoch_15m_now)
                        )
                        if _aggr_fired:
                            logger.warning(f"[REENTRY_MONITOR] {pk}: 🎯 AGGRESSIVE fast-path (0-{_t0_window_min:.0f}m) — dc_x1h={_dc_x1h_now} stoch_x15m={_stoch_15m_now} @ {hours_since*60:.0f}m post-exit. Skipping tier gates.")
                        # ═══ PATHWAY G: 60-MIN UNCONDITIONAL — price kept running in our direction. No questions asked, 50% size. ═══
                        _g60_enabled = getattr(config, 'REENTRY_60MIN_UNCONDITIONAL_ENABLED', True)
                        _g60_window_min = float(getattr(config, 'REENTRY_60MIN_WINDOW_MIN', 60.0))
                        _g60_min_pct = float(getattr(config, 'REENTRY_60MIN_MIN_PCT', 0.3)) / 100.0
                        _g60_fired = False
                        if _g60_enabled and not _p0_rescue and not _fav_fired and not _aggr_fired and hours_since * 60.0 <= _g60_window_min:
                            _g60_exit_px = float(cand.get("exit_price", 0) or 0)
                            _g60_dc_hi = float(i.get('dc_high4_5m', 0) or 0)
                            _g60_dc_lo = float(i.get('dc_low4_5m', 0) or 0)
                            if side == "LONG":
                                _g60_price_ok = _g60_dc_hi > 0 and current_price >= _g60_dc_hi
                            else:
                                _g60_price_ok = _g60_dc_lo > 0 and current_price <= _g60_dc_lo
                            if _g60_price_ok:
                                _g60_fired = True
                                _g60_dc_level = _g60_dc_hi if side == "LONG" else _g60_dc_lo
                                logger.critical(f"⚡ [REENTRY_60MIN_UNCONDITIONAL] {pk}: exit={_g60_exit_px:.2f} cur={current_price:.2f} dc4_break={_g60_dc_level:.2f} {hours_since*60:.0f}min since exit — DC BREAK REENTRY")
                            elif _g60_dc_hi > 0 or _g60_dc_lo > 0:
                                logger.debug(f"[REENTRY_60MIN_UNCONDITIONAL] {pk}: price {current_price:.2f} not past dc4 {'hi' if side == 'LONG' else 'lo'}={_g60_dc_hi if side == 'LONG' else _g60_dc_lo:.2f} — blocked")
                        # STOCH GATE — 3 tiers based on hours since exit (skipped if P0 rescue OR aggressive fast-path fires):
                        # Tier 1 (0–3h): rally reentry — skip k5m<50, need k5m rising + k15m rising + 2/3 HTF (1h/4h/D) WT aligned
                        # Tier 2 (3–48h): strict — k5m MUST drop below 50 before reentering (whipsaw zone)
                        # Tier 3 (48h+): bypass stoch gate entirely, rely on exit score + WT alignment only
                        if not _p0_rescue and not _aggr_fired and not _fav_fired and not _g60_fired and hours_since < 3.0:
                            _k5m_rising = k_5m > k_5m_prev
                            _k15m_rising = k_15m > k_15m_prev
                            _htf_wt_fav = sum(1 for w1, w2 in [(wt1_1h, wt2_1h), (wt1_4h, wt2_4h), (wt1_D, wt2_D)] if (w1 > w2 if side == "LONG" else w1 < w2))
                            _rally_k15m_max = float(getattr(config, 'REENTRY_RALLY_K15M_MAX', 100.0))
                            _rally_htf_min = int(getattr(config, 'REENTRY_RALLY_HTF_MIN', 2))
                            if side == "LONG":
                                _k15m_lvl_ok = k_15m < _rally_k15m_max
                                if not (_k5m_rising and _k15m_rising and _k15m_lvl_ok and _htf_wt_fav >= _rally_htf_min):
                                    logger.info(f"[REENTRY_MONITOR] {pk}: LONG rally gate FAIL k5m={k_5m:.0f}(rising={_k5m_rising}) k15m={k_15m:.0f}<{_rally_k15m_max:.0f}(rising={_k15m_rising}) htf={_htf_wt_fav}/{_rally_htf_min} (<3h)")
                                    continue
                            else:
                                _k15m_lvl_ok = k_15m > (100.0 - _rally_k15m_max) if _rally_k15m_max < 100.0 else True
                                if not (k_5m < k_5m_prev and k_15m < k_15m_prev and _k15m_lvl_ok and _htf_wt_fav >= _rally_htf_min):
                                    logger.info(f"[REENTRY_MONITOR] {pk}: SHORT rally gate FAIL k5m={k_5m:.0f}(falling={k_5m < k_5m_prev}) k15m={k_15m:.0f}(falling={k_15m < k_15m_prev},lvl={_k15m_lvl_ok}) htf={_htf_wt_fav}/{_rally_htf_min} (<3h)")
                                    continue
                        elif not _p0_rescue and not _aggr_fired and not _fav_fired and not _g60_fired and hours_since < 48.0:
                            # ═══ SAFETY SWITCH 4: BOUNCE REENTRY K-GATE (2026-04-16, hardcoded 50/50 → config 2026-04-26) ═══
                            _bounce_enabled = getattr(config, 'BOUNCE_REENTRY_ENABLED_TRADIER', True)
                            if _bounce_enabled:
                                # 2026-04-26 — wires DEAD switches BOUNCE_REENTRY_K_RESET_{LONG,SHORT}_TRADIER. Was hardcoded 50/50.
                                _kr_long_thr = float(getattr(config, 'BOUNCE_REENTRY_K_RESET_LONG_TRADIER', 35))
                                _kr_short_thr = float(getattr(config, 'BOUNCE_REENTRY_K_RESET_SHORT_TRADIER', 65))
                                if side == "LONG" and not (k_5m < _kr_long_thr and k_5m > k_5m_prev):
                                    logger.info(f"[REENTRY_MONITOR] {pk}: LONG stoch gate FAIL k5m={k_5m:.0f} prev={k_5m_prev:.0f} (need <{_kr_long_thr:.0f} and rising, {hours_since:.1f}h)")
                                    continue
                                if side == "LONG" and (k_1h_rm > 80.0 or k_15m > 80.0):
                                    _rm_pp_up, _rm_pp_dn, _, _ = _parabolic_state(i, config)
                                    if _rm_pp_up:
                                        logger.warning(f"🌟 [REENTRY_MONITOR_PARABOLIC_BYPASS] {pk}: LONG HTF overbought BUT parabolic uptrend (rsi/bb confluence) — reentry OBLIGATORY")
                                    else:
                                        logger.info(f"[REENTRY_MONITOR] {pk}: LONG HTF overbought BLOCK k1h={k_1h_rm:.0f} k15m={k_15m:.0f} (need both ≤80)")
                                        continue
                                if side == "SHORT" and not (k_5m > _kr_short_thr and k_5m < k_5m_prev):
                                    logger.info(f"[REENTRY_MONITOR] {pk}: SHORT stoch gate FAIL k5m={k_5m:.0f} prev={k_5m_prev:.0f} (need >{_kr_short_thr:.0f} and falling, {hours_since:.1f}h)")
                                    continue
                                if side == "SHORT" and (k_1h_rm < 20.0 or k_15m < 20.0):
                                    _rm_pp_up, _rm_pp_dn, _, _ = _parabolic_state(i, config)
                                    if _rm_pp_dn:
                                        logger.warning(f"🌟 [REENTRY_MONITOR_PARABOLIC_BYPASS] {pk}: SHORT HTF oversold BUT parabolic downtrend — reentry OBLIGATORY")
                                    else:
                                        logger.info(f"[REENTRY_MONITOR] {pk}: SHORT HTF oversold BLOCK k1h={k_1h_rm:.0f} k15m={k_15m:.0f} (need both ≥20)")
                                        continue
                        elif not _p0_rescue and not _aggr_fired and not _fav_fired and not _g60_fired:
                            # ═══ SAFETY SWITCH 3: OVERDUE BYPASS GATE (2026-04-16) ═══
                            if not getattr(config, 'TRADIER_REENTRY_OVERDUE_BYPASS_ENABLED', True):
                                logger.info(f"[REENTRY_MONITOR] {pk}: {hours_since:.1f}h overdue BUT TRADIER_REENTRY_OVERDUE_BYPASS_ENABLED=False — stoch gate still applies")
                                continue
                            logger.warning(f"[REENTRY_MONITOR] {pk}: {hours_since:.1f}h overdue — stoch gate BYPASSED, relying on exit score + WT alignment")
                        # The exit signal has cleared. Now check that the TRADE-DIRECTION WT is aligned (or a fast-path fired)
                        if _p0_rescue or _aggr_fired or _fav_fired or _g60_fired:
                            wt_support = 3  # for logging
                            reenter = True
                        else:
                            if side == "LONG":
                                htf_aligned = (wt1_4h > wt2_4h) and (wt_cross_1h != "BEAR")
                                wt_support = sum(1 for w1, w2 in [(wt1_5m, wt2_5m), (wt1_15m, wt2_15m), (wt1_1h, wt2_1h)] if w1 > w2)
                            else:
                                htf_aligned = (wt1_4h < wt2_4h) and (wt_cross_1h != "BULL")
                                wt_support = sum(1 for w1, w2 in [(wt1_5m, wt2_5m), (wt1_15m, wt2_15m), (wt1_1h, wt2_1h)] if w1 < w2)
                            if wt_support >= 2 and htf_aligned:
                                reenter = True
                        if reenter and not self.is_symbol_tradeable(symbol, acc, side):
                            logger.info(f"[REENTRY_MONITOR] {pk}: {side}_ENABLED=False / not tradeable (neg-Sharpe/disabled) — skipping reopen")
                            reenter = False
                        if reenter:
                            # Skip if position is already open (regular scan may have reopened it)
                            _existing_pos = self.get_position(pk)
                            _existing_qty = 0.0
                            if _existing_pos:
                                _existing_qty = abs(float(getattr(_existing_pos, 'positionAmt', 0) or getattr(_existing_pos, 'quantity', 0)))
                            if _existing_qty > 0:
                                logger.info(f"[REENTRY_MONITOR] {pk}: already OPEN qty={_existing_qty:.2f} — marking REENTERED, no order")
                                cand["status"] = "REENTERED"
                                cand["reentry_note"] = "already_open_by_scanner"
                                changed = True
                                continue
                            pos_amt_at_exit = float(cand.get("position_amt_at_exit", 0))
                            _calc_size = max(1, int(await self.calculate_position_size(symbol, current_price, account_key=acc)))
                            if pos_amt_at_exit > 0:
                                reentry_qty = max(_calc_size, max(1, int(pos_amt_at_exit)))
                            else:
                                reentry_qty = _calc_size
                            if _g60_fired or (_fav_fired and _fav_k15m_partial):
                                reentry_qty = max(1, int(reentry_qty * 0.5))
                            position_side = side
                            order_side = "BUY" if side == "LONG" else "SELL"
                            # 2026-04-27 — engine boost (default mult=1.0 = no size change, just +ENGINES tag)
                            _ee_mult, _ee_tag = _ee_reentry_boost(symbol, i, side == "LONG", config)
                            reentry_qty = max(1, int(reentry_qty * _ee_mult))
                            reentry_reason = f"REENTRY_MONITOR exit@{exit_price:.2f} now@{current_price:.2f} k5m={k_5m:.0f} wt={wt_support}" + _ee_tag
                            api_side = "buy" if side == "LONG" else "sell_short"
                            logger.warning(f"[REENTRY_MONITOR] {pk}: PLACING REAL ORDER {api_side} {reentry_qty} {symbol} @ market | k5m={k_5m:.0f} wt={wt_support}")
                            result = {}
                            try:
                                result = await self.place_order(symbol, api_side, float(reentry_qty), "market", duration="day", action="REENTRY", position_side=side, account_key=acc)
                                order_id = result.get("order", {}).get("id", "NONE") if isinstance(result, dict) else str(result)
                                order_status = result.get("order", {}).get("status", "UNKNOWN") if isinstance(result, dict) else "UNKNOWN"
                                logger.warning(f"[REENTRY_MONITOR] {pk}: ORDER RESULT id={order_id} status={order_status}")
                                if "GHOST" not in str(order_id) and order_id != "NONE":
                                    cand["status"] = "REENTERED"
                                else:
                                    fail_count = cand.get("fail_count", 0) + 1
                                    cand["fail_count"] = fail_count
                                    cand["last_fail_ts"] = time.time()
                                    if fail_count >= 5:
                                        cand["status"] = f"FAILED:{order_id}"
                                        logger.error(f"[REENTRY_MONITOR] {pk}: GIVING UP after {fail_count} attempts — FAILED")
                                    else:
                                        cand["status"] = f"FAILED:{order_id}"
                                        logger.warning(f"[REENTRY_MONITOR] {pk}: attempt {fail_count}/5 failed (id={order_id}) — will retry with backoff")
                            except Exception as oe:
                                logger.error(f"[REENTRY_MONITOR] {pk}: ORDER FAILED: {oe}")
                                fail_count = cand.get("fail_count", 0) + 1
                                cand["fail_count"] = fail_count
                                cand["last_fail_ts"] = time.time()
                                cand["status"] = f"FAILED:{oe}"
                            cand["reentry_price"] = current_price
                            cand["reentry_time"] = now_utc.isoformat()
                            # V4: Immediately record ACTUAL fill price as entry_price
                            # so NOLOSS/bounce-top can track gain from real cost basis
                            _fill_price = float(result.get("order", {}).get("avg_fill_price", 0)) if isinstance(result, dict) else 0
                            if _fill_price <= 0:
                                _fill_price = current_price
                            
                            _pos = self.get_position(pk)
                            if _pos:
                                _pos.entry_price = _fill_price
                                _pos.mark_price = current_price
                                _pos.opened_at = now_utc
                                _pos.last_reentry_time = now_utc
                                _r1_sk = 'dc_low4_5m' if side == 'LONG' else 'dc_high4_5m'
                                _r1_sv = float(i.get(_r1_sk, 0) or 0)
                                if _r1_sv > 0:
                                    _pos.r1_stop_price = _r1_sv
                                logger.warning(f"[REENTRY_ENTRY_PRICE] {pk}: Set entry_price={_fill_price:.2f} from fill (was {cand.get('entry_price', 0):.2f}) r1_stop={_r1_sv:.4f} last_reentry_time=NOW")
                            # 2026-05-28 USER: this reopen path uses place_order() directly and bypassed
                            # execute_trade_action's _append_to_history — every reopen was invisible in
                            # /history/. Log it here on a real fill so the trade ledger is complete.
                            if "GHOST" not in str(order_id) and order_id not in ("NONE", "N/A"):
                                try:
                                    await self._append_to_history(pk, "REENTRY", float(reentry_qty), float(_fill_price), reentry_reason)
                                except Exception as _rm_hist_e:
                                    logger.error(f"[REENTRY_MONITOR] {pk}: history write failed: {_rm_hist_e}")
                            logger.info(f"[REENTRY_MONITOR] {pk}: Result={result}")
                        elif cand["attempts"] % 20 == 0:
                            logger.info(f"[REENTRY_MONITOR] {pk}: Still waiting ({cand['attempts']} checks) price=${current_price:.2f} target=${exit_price:.2f} k5m={k_5m:.0f} wt_sup={wt_support if side == 'LONG' else wt_support}")
                    if changed:
                        self._save_reentry_candidates(acc, candidates)
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"[REENTRY_MONITOR] Loop error: {e}", exc_info=True)
            await asyncio.sleep(15)

    async def should_enter_long(self, symbol: str, indicators: Dict[str, Any]) -> bool:
        """Configurable entry gate. SATOSHIT default; SHOULD_ENTER_FALLBACK_ENABLED allows other paths."""
        try:
            if getattr(config, 'ENTRY_SYMGATE_ENABLED', True):
                _sg_blocked, _sg_reason = self.would_exit_trigger_now(symbol, indicators, "LONG")
                if _sg_blocked:
                    if config.VERBOSE: logger.info(f"[SYMGATE] LONG {symbol} BLOCKED: {_sg_reason}")
                    return False
            # ═══ 2026-04-30 HTF PORT — F1. HTF_W_M_ALIGN_GATE (default OFF) ═══
            # Block LONG entries unless N of 2 (W, M) WaveTrend agree with side.
            if getattr(config, 'HTF_W_M_ALIGN_GATE_TRADIER_ENABLED', False):
                try:
                    _w1_W = float(indicators.get('wt1_W', 0) or 0)
                    _w2_W = float(indicators.get('wt2_W', 0) or 0)
                    _w1_M = float(indicators.get('wt1_M', 0) or 0)
                    _w2_M = float(indicators.get('wt2_M', 0) or 0)
                    _w_has = (_w1_W != 0 or _w2_W != 0)
                    _m_has = (_w1_M != 0 or _w2_M != 0)
                    _w_ok = (_w1_W > _w2_W) if _w_has else True   # pass through pre-cache bars
                    _m_ok = (_w1_M > _w2_M) if _m_has else True
                    _req = int(getattr(config, 'HTF_W_M_ALIGN_TRADIER_REQUIRED', 2))
                    _agree = int(_w_ok) + int(_m_ok)
                    if _agree < _req:
                        if config.VERBOSE: logger.info(f"[HTF_W_M_ALIGN_GATE] LONG {symbol} BLOCKED: agree={_agree}/{_req} W_ok={_w_ok}(has={_w_has}) M_ok={_m_ok}(has={_m_has})")
                        return False
                except Exception as _htfg:
                    logger.debug(f"[HTF_W_M_ALIGN_GATE][LONG] {symbol}: {type(_htfg).__name__} {_htfg} — skipped")
            # ═══ 2026-04-30 HTF PORT — F2. HTF_DC_BREAKOUT entry (default OFF, fast path) ═══
            # Additive entry: close > dc_high_TF (prev) * (1+thr) AND optional W WT bullish.
            if getattr(config, 'HTF_DC_BREAKOUT_TRADIER_ENABLED', False):
                try:
                    _bk_tf = str(getattr(config, 'HTF_DC_BREAKOUT_TRADIER_TF', '4h'))
                    _bk_thr = float(getattr(config, 'HTF_DC_BREAKOUT_TRADIER_THRESHOLD_PCT', 0.0)) / 100.0
                    _bk_req_w = bool(getattr(config, 'HTF_DC_BREAKOUT_TRADIER_REQUIRE_W_WT', True))
                    _dch_prev = float(indicators.get(f'dc_high_{_bk_tf}_prev', indicators.get(f'dc_high_{_bk_tf}', 0)) or 0)
                    _cur_p = float(indicators.get('current_price', 0) or 0)
                    if _dch_prev > 0 and _cur_p > _dch_prev * (1.0 + _bk_thr):
                        _w_ok_bk = True
                        if _bk_req_w:
                            _w1_W_bk = float(indicators.get('wt1_W', 0) or 0)
                            _w2_W_bk = float(indicators.get('wt2_W', 0) or 0)
                            if (_w1_W_bk != 0 or _w2_W_bk != 0):
                                _w_ok_bk = _w1_W_bk > _w2_W_bk
                        if _w_ok_bk:
                            logger.warning(f"[HTF_DC_BREAKOUT_LONG] {symbol}: close={_cur_p:.4f} > dc_high_{_bk_tf}_prev={_dch_prev:.4f}*(1+{_bk_thr:.4f}) W_ok={_w_ok_bk}")
                            return True
                except Exception as _htfb:
                    logger.debug(f"[HTF_DC_BREAKOUT][LONG] {symbol}: {type(_htfb).__name__} {_htfb} — skipped")
            # SATOSHIT — fast path (opt-in via SATOSHIT_ENTRY_FILTER, default True for backward compat)
            if getattr(config, 'SATOSHIT_ENTRY_FILTER', True):
                from ez_satoshit import satoshit_entry_signal
                _sat_ok, _sat_votes, _sat_reason = satoshit_entry_signal(indicators, True, config)
                if _sat_ok:
                    logger.warning(f"[SATOSHIT_ENTRY] LONG {symbol}: {_sat_reason}")
                    return True
            # STDEV_BREAKOUT: stateless BB %B breakout entry — works in backtest + live without state machine
            if getattr(config, 'STDEV_BREAKOUT_ENABLED', False):
                _sb_htf_list = list(getattr(config, 'STDEV_BREAKOUT_HTF_LIST', None) or ['D', '4h'])
                _sb_pctb_long = float(getattr(config, 'STDEV_BREAKOUT_PCTB_LONG', 1.0))
                _sb_rvol_min = float(getattr(config, 'STDEV_BREAKOUT_RVOL_MIN', 1.2))
                for _sb_htf in _sb_htf_list:
                    _sb_pctb_val = float(indicators.get(f'bb_pct_b_{_sb_htf}', 0.5) or 0.5)
                    _sb_rvol_val = float(indicators.get(f'relative_volume_{_sb_htf}', 1.0) or 1.0)
                    if _sb_pctb_val >= _sb_pctb_long and _sb_rvol_val >= _sb_rvol_min:
                        logger.warning(f"[STDEV_BREAKOUT_LONG] {symbol}: bb_pct_b_{_sb_htf}={_sb_pctb_val:.3f} rvol={_sb_rvol_val:.2f}")
                        return True
            # STDEV_BOUNCE: stateless mean-reversion entry at lower BB band (LONG when pctb ≤ threshold)
            if getattr(config, 'STDEV_BOUNCE_ENABLED', False):
                _bn_htf_list = list(getattr(config, 'STDEV_BOUNCE_HTF_LIST', None) or ['D', '4h'])
                _bn_pctb_long = float(getattr(config, 'STDEV_BOUNCE_PCTB_LONG', 0.05))
                _bn_rvol_min = float(getattr(config, 'STDEV_BOUNCE_RVOL_MIN', 1.2))
                for _bn_htf in _bn_htf_list:
                    _bn_pctb_val = float(indicators.get(f'bb_pct_b_{_bn_htf}', 0.5) or 0.5)
                    _bn_rvol_val = float(indicators.get(f'relative_volume_{_bn_htf}', 1.0) or 1.0)
                    if _bn_pctb_val <= _bn_pctb_long and _bn_rvol_val >= _bn_rvol_min:
                        logger.warning(f"[STDEV_BOUNCE_LONG] {symbol}: bb_pct_b_{_bn_htf}={_bn_pctb_val:.3f} rvol={_bn_rvol_val:.2f}")
                        return True
            # If SHOULD_ENTER_FALLBACK_ENABLED is False (default), block here. Set True to test other paths.
            if not getattr(config, 'SHOULD_ENTER_FALLBACK_ENABLED', False):
                return False
            # YOUTUBE_CONSENSUS: Lunch dead zone — block momentum entries 11:30-14:00 ET
            if getattr(config, 'LUNCH_DEADZONE_ENABLED', False) and is_lunch_dead_zone():
                _ldz_mode = getattr(config, 'LUNCH_DEADZONE_MODE', 'BLOCK_MOMENTUM')
                if _ldz_mode == "BLOCK_ALL":
                    if config.VERBOSE: logger.info(f"[LUNCH_DEADZONE] LONG {symbol} BLOCKED: lunch dead zone (BLOCK_ALL)")
                    return False
                elif _ldz_mode == "BLOCK_MOMENTUM":
                    pass  # Allow through — mean-reversion strategies bypass via SATOSHIT fast path above
            # YOUTUBE_CONSENSUS: VWAP filter — LONG only above VWAP
            if getattr(config, 'VWAP_FILTER_ENABLED', False):
                _vwap = float(indicators.get('vwap', 0) or 0)
                _cur_p_v = float(indicators.get('current_price', 0) or 0)
                if _vwap > 0 and _cur_p_v > 0 and _cur_p_v < _vwap:
                    if config.VERBOSE: logger.info(f"[VWAP_FILTER] LONG {symbol} BLOCKED: price={_cur_p_v:.2f} < VWAP={_vwap:.2f}")
                    return False
            # YOUTUBE_CONSENSUS: 9/21 EMA alignment confirmation
            if getattr(config, 'EMA_9_21_FILTER_ENABLED', False):
                _ema9_above = float(indicators.get(f'ema_9_above_21_{getattr(config, "EMA_9_21_TIMEFRAME", "5m")}', -1) or -1)
                if _ema9_above == 0.0:
                    if config.VERBOSE: logger.info(f"[EMA_9_21] LONG {symbol} BLOCKED: 9 EMA < 21 EMA on {getattr(config, 'EMA_9_21_TIMEFRAME', '5m')}")
                    return False
            # YOUTUBE_CONSENSUS: RVOL gate for non-mean-reversion strategies
            _rvol_5m = float(indicators.get('rel_vol_5m', 1.0) or 1.0)
            _rvol_min = getattr(config, 'RVOL_MOMENTUM_MIN', 1.5)
            if _rvol_5m < _rvol_min and _rvol_5m > 0:
                if config.VERBOSE: logger.info(f"[RVOL_GATE] LONG {symbol} BLOCKED: RVOL_5m={_rvol_5m:.2f} < {_rvol_min}")
                return False
            # BACKTEST_CHANGE_T55: RSI entry gate — ONLY if RSI data actually exists
            _rsi_period = getattr(config, 'RSI_ENTRY_PERIOD_TRADIER', 10)
            _rsi_key = f'rsi_{_rsi_period}_D'
            _rsi_val = indicators.get(_rsi_key, indicators.get('rsi_D', indicators.get('rsi_1h', None)))
            if _rsi_val is not None:
                _rsi_val = float(_rsi_val or 50)
                _rsi_thresh = getattr(config, 'RSI_ENTRY_LONG_TRADIER', 42.0)
                if _rsi_val > _rsi_thresh:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol} BLOCKED: RSI({_rsi_period})={_rsi_val:.1f} > {_rsi_thresh}")
                    return False
            # SMA filter — ONLY if SMA data exists
            _sma_key = f'sma_{getattr(config, "SMA_FILTER_PERIOD_TRADIER", 100)}_D'
            _sma_val = indicators.get(_sma_key, indicators.get('sma_200_D', indicators.get('sma_200_1h', None)))
            _cur_p = float(indicators.get('current_price', 0) or 0)
            if _sma_val is not None and _cur_p > 0:
                _sma_val = float(_sma_val or 0)
                if _sma_val > 0 and _cur_p < _sma_val:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol} BLOCKED: price < SMA")
                    return False
            final_score = float(indicators.get('0final_score_norm', 0))
            ranking_points = float(indicators.get('0ranking_points', 0))
            lr_trend_15m = float(indicators.get('lr_trend_15m', 0))
            k_1h = float(indicators.get('k_1h', 50))
            d_1h = float(indicators.get('d_1h', 50))
            k_4h = float(indicators.get('k_4h', 50))
            d_4h = float(indicators.get('d_4h', 50))
            if config.VERBOSE:
                logger.info(f"[VERBOSE][CALC][LONG] {symbol} ENTRY CALCULATION START: final_score={final_score:.3f} ranking_points={ranking_points:.1f} lr_trend_15m={lr_trend_15m:.3f} k_1h={k_1h:.1f} d_1h={d_1h:.1f} k_4h={k_4h:.1f} d_4h={d_4h:.1f}")
            # BACKTEST_CHANGE_T19: time zone stoch threshold gate
            if getattr(config, 'TIME_ZONE_ENABLED', False):
                _zone = _get_trade_zone()
                if _zone == "open":
                    _zt = getattr(config, 'ZONE_OPEN_THRESHOLD', 25)
                elif _zone == "mid":
                    _zt = getattr(config, 'ZONE_MID_THRESHOLD', 30)
                elif _zone == "close":
                    _zt = getattr(config, 'ZONE_CLOSE_THRESHOLD', 20)
                else:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol} BLOCKED: market closed zone")
                    return False
                if k_1h > (100.0 - _zt):
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol} BLOCKED: zone={_zone} k_1h={k_1h:.1f} > threshold {100.0 - _zt:.0f}")
                    return False
            # BACKTEST_CHANGE_T3: SMA200 distance check on 4h
            # 2026-04-27: when LH_HL_FILTER_REPLACE_SMA200D is True, this filter is bypassed (LH/HL filter replaces it).
            _lh_replace = bool(getattr(config, 'LH_HL_FILTER_ENABLED', False)) and bool(getattr(config, 'LH_HL_FILTER_REPLACE_SMA200D', False))
            if getattr(config, 'SMA200_DIST_ENTRY_ENABLED', False) and not _lh_replace:
                _sma200_4h = float(indicators.get('sma_200_4h', 0) or 0)
                _cur_price = float(indicators.get('current_price', 0) or 0)
                if _sma200_4h > 0 and _cur_price > 0:
                    _dist_pct = ((_cur_price - _sma200_4h) / _sma200_4h) * 100.0
                    if _dist_pct < getattr(config, 'SMA200_DIST_LONG_THRESHOLD_4H', -10.0):
                        if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol} BLOCKED: SMA200_4h dist={_dist_pct:.1f}% < threshold {config.SMA200_DIST_LONG_THRESHOLD_4H}")
                        return False
            # 2026-04-27 LOWER-HIGHS / HIGHER-LOWS FILTER (LONG side) — sweep-testable, default OFF.
            # User: "block long trades while 1h/4h charts make lower highs (shorts vv) instead of the sma_200_D filter (or on top of it)".
            # User 2026-04-27 23:13: "test lh with or without ll for longs hl with or without hh for shorts on both platforms".
            if bool(getattr(config, 'LH_HL_FILTER_ENABLED', False)):
                _lh_apply = True
                # Per-action gating: tradier should_enter_long only fires for OPEN-class actions, no AUGMENT distinction here.
                if _lh_apply:
                    try:
                        _lh_mode = str(getattr(config, 'LH_HL_FILTER_MODE', 'STRICT_2BAR'))
                        _lh_tf_req = int(getattr(config, 'LH_HL_FILTER_TF_REQ', 2))
                        _lh_dc_th = float(getattr(config, 'LH_HL_FILTER_DC_THRESHOLD_PCT', 0.5)) / 100.0
                        _lh_req_both = bool(getattr(config, 'LH_HL_FILTER_REQUIRE_BOTH', False))
                        _lh_h1h = float(indicators.get('high_1h', 0) or 0); _lh_h1hp = float(indicators.get('high_1h_prev', 0) or 0)
                        _lh_h4h = float(indicators.get('high_4h', 0) or 0); _lh_h4hp = float(indicators.get('high_4h_prev', 0) or 0)
                        _lh_l1h = float(indicators.get('low_1h', 0) or 0); _lh_l1hp = float(indicators.get('low_1h_prev', 0) or 0)
                        _lh_l4h = float(indicators.get('low_4h', 0) or 0); _lh_l4hp = float(indicators.get('low_4h_prev', 0) or 0)
                        if _lh_mode == "DC_REGRESS":
                            _lh_dch1h = float(indicators.get('dc_high_1h', 0) or 0)
                            _lh_dch4h = float(indicators.get('dc_high_4h', 0) or 0)
                            _lh_1h = (_lh_h1h > 0 and _lh_dch1h > 0 and _lh_h1h < _lh_dch1h * (1.0 - _lh_dc_th))
                            _lh_4h = (_lh_h4h > 0 and _lh_dch4h > 0 and _lh_h4h < _lh_dch4h * (1.0 - _lh_dc_th))
                        else:
                            _lh_1h = (_lh_h1h > 0 and _lh_h1hp > 0 and _lh_h1h < _lh_h1hp)
                            _lh_4h = (_lh_h4h > 0 and _lh_h4hp > 0 and _lh_h4h < _lh_h4hp)
                        _ll_1h = (_lh_l1h > 0 and _lh_l1hp > 0 and _lh_l1h < _lh_l1hp)
                        _ll_4h = (_lh_l4h > 0 and _lh_l4hp > 0 and _lh_l4h < _lh_l4hp)
                        _lh_count = int(_lh_1h) + int(_lh_4h)
                        _ll_count = int(_ll_1h) + int(_ll_4h)
                        _primary_hit = _lh_count >= _lh_tf_req
                        _confirm_hit = (not _lh_req_both) or (_ll_count >= _lh_tf_req)
                        if _primary_hit and _confirm_hit:
                            _tag = "LH+LL" if _lh_req_both else "LH"
                            logger.info(f"📉 [LH_HL_FILTER] {symbol} BLOCKED LONG — {_tag} on {_lh_count}/2 TFs (1h LH={_lh_1h} LL={_ll_1h} | 4h LH={_lh_4h} LL={_ll_4h}) mode={_lh_mode} req={_lh_tf_req}TF reqBoth={_lh_req_both}")
                            return False
                    except Exception as _lh_exc:
                        logger.debug(f"[LH_HL_FILTER][LONG] {symbol}: {type(_lh_exc).__name__} {_lh_exc} — skipped")
            # BACKTEST_CHANGE_T4: MFI check on Daily — OVERBOUGHT FILTER (fixed 2026-05-18)
            # Blocks LONG entries when mfi_D > threshold (default 80 = overbought zone, reversal expected).
            # Prior semantics ("only LONG if mfi<20 oversold") blocked ~95% of opportunities — see config note.
            if getattr(config, 'MFI_ENTRY_ENABLED', False):
                _mfi_d = float(indicators.get('mfi_D', 50) or 50)
                if _mfi_d > getattr(config, 'MFI_LONG_THRESHOLD_D', 80.0):
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol} BLOCKED: MFI_D={_mfi_d:.1f} > {config.MFI_LONG_THRESHOLD_D} (overbought)")
                    return False
            # BACKTEST_CHANGE_T8: alignment gate
            if getattr(config, 'ALIGNMENT_GATE_MIN', 0) > 0:
                _al_count = 0
                if k_1h > d_1h: _al_count += 1
                if k_4h > d_4h: _al_count += 1
                if float(indicators.get('k_15m', 50)) > float(indicators.get('d_15m', 50)): _al_count += 1
                if lr_trend_15m > 0: _al_count += 1
                _al_total_max = getattr(config, 'ALIGNMENT_GATE_TOTAL', 12)
                if _al_count < getattr(config, 'ALIGNMENT_GATE_MIN', 4):
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol} BLOCKED: alignment={_al_count}/{_al_total_max} < {config.ALIGNMENT_GATE_MIN}")
                    return False
            # Leaderboard filter check
            if config.LEADERBOARD_FILTER:
                rankings = await self.get_rankings()
                if rankings:
                    top_symbols = rankings.get('top_20', [])
                    in_top_20 = symbol in top_symbols
                    if config.VERBOSE:
                        logger.info(f"[VERBOSE][CALC][LONG] {symbol} LEADERBOARD_FILTER: enabled={config.LEADERBOARD_FILTER} in_top_20={in_top_20}")
                    if not in_top_20:
                        if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol}  BLOCKED: not in top_20 leaderboard")
                        return False
                elif config.VERBOSE:
                    logger.info(f"[VERBOSE][CALC][LONG] {symbol} LEADERBOARD_FILTER: enabled but no rankings data available")
            elif config.VERBOSE:
                logger.info(f"[VERBOSE][CALC][LONG] {symbol} LEADERBOARD_FILTER: disabled (skipping)")
            # Trend gates check
            if config.TREND_GATES:
                trend_ok = lr_trend_15m > 0
                if config.VERBOSE:
                    logger.info(f"[VERBOSE][CALC][LONG] {symbol} TREND_GATES: enabled={config.TREND_GATES} lr_trend_15m={lr_trend_15m:.3f} trend_ok={trend_ok}")
                if not trend_ok:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol}  BLOCKED: lr_trend_15m={lr_trend_15m:.3f} <= 0")
                    return False
            elif config.VERBOSE:
                logger.info(f"[VERBOSE][CALC][LONG] {symbol} TREND_GATES: disabled (skipping)")
            # HTF confirmation checks
            if config.HTF1_CONF or config.HTF4_CONF:
                htf1_ok = True
                htf4_ok = True
                if config.HTF1_CONF:
                    htf1_ok = k_1h > d_1h
                    if config.VERBOSE:
                        logger.info(f"[VERBOSE][CALC][LONG] {symbol} HTF1_CONF: enabled={config.HTF1_CONF} k_1h={k_1h:.1f} d_1h={d_1h:.1f} htf1_ok={htf1_ok}")
                    if not htf1_ok:
                        if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol}  BLOCKED: HTF1_CONF k_1h={k_1h:.1f} <= d_1h={d_1h:.1f}")
                        return False
                if config.HTF4_CONF:
                    htf4_ok = k_4h > d_4h
                    if config.VERBOSE:
                        logger.info(f"[VERBOSE][CALC][LONG] {symbol} HTF4_CONF: enabled={config.HTF4_CONF} k_4h={k_4h:.1f} d_4h={d_4h:.1f} htf4_ok={htf4_ok}")
                    if not htf4_ok:
                        if config.VERBOSE: logger.info(f"[VERBOSE][CALC][LONG] {symbol}  BLOCKED: HTF4_CONF k_4h={k_4h:.1f} <= d_4h={d_4h:.1f}")
                        return False
            elif config.VERBOSE:
                logger.info(f"[VERBOSE][CALC][LONG] {symbol} HTF_CONF: disabled (skipping)")
            # Final score check
            score_threshold = 0.6
            ranking_threshold = 50
            score_ok = True  # BACKTEST_CHANGE_T42: near-zero signal in 0xxx sweep
            ranking_ok = True  # BACKTEST_CHANGE_T41: near-zero signal in 0xxx sweep
            final_result = score_ok and ranking_ok
            if config.VERBOSE:
                in_top_20_val = in_top_20 if config.LEADERBOARD_FILTER and 'in_top_20' in locals() else (True if not config.LEADERBOARD_FILTER else False)
                trend_ok_val = trend_ok if config.TREND_GATES and 'trend_ok' in locals() else (True if not config.TREND_GATES else (lr_trend_15m > 0))
                htf1_ok_val = htf1_ok if config.HTF1_CONF and 'htf1_ok' in locals() else (True if not config.HTF1_CONF else (k_1h > d_1h))
                htf4_ok_val = htf4_ok if config.HTF4_CONF and 'htf4_ok' in locals() else (True if not config.HTF4_CONF else (k_4h > d_4h))
                logger.info(f"\n[DECISION SCORECARD] {symbol} LONG EVALUATION")
                logger.info(f"{'Metric':<15} | {'Value':<10} | {'Threshold':<10} | {'Result'}")
                logger.info("-" * 55)
                logger.info(f"{'Leaderboard':<15} | {str(in_top_20_val):<10} | {'True':<10} | {'✅' if in_top_20_val else '!!'}")
                logger.info(f"{'Trend (15m)':<15} | {lr_trend_15m:<10.3f} | {'> 0':<10} | {'✅' if trend_ok_val else '!!'}")
                logger.info(f"{'HTF1 (1h)':<15} | {k_1h:.1f}/{d_1h:.1f}  | {'K > D':<10} | {'✅' if htf1_ok_val else '!!'}")
                logger.info(f"{'HTF4 (4h)':<15} | {k_4h:.1f}/{d_4h:.1f}  | {'K > D':<10} | {'✅' if htf4_ok_val else '!!'}")
                logger.info(f"{'Final Score':<15} | {final_score:<10.3f} | {'> '+str(score_threshold):<10} | {'✅' if final_score>score_threshold else '!!'}")
                logger.info(f"{'Rank Points':<15} | {ranking_points:<10.1f} | {'BYPASSED':<10} | {'✅ (T41)'}")
                logger.info("-" * 55)
                logger.info(f"FINAL DECISION: {'✅ ENTER LONG' if final_result else '⛔ BLOCKED'}\n")
                logger.info(f"[VERBOSE][CALC][LONG] {symbol} FINAL SCORE CHECK: final_score={final_score:.3f} > {score_threshold} = {score_ok} | ranking_points=BYPASSED(T41) | RESULT={final_result}")
            return final_result
        except Exception as e:
            logger.error(f"Error in should_enter_long for {symbol}: {e}",  exc_info=True )
            return False

    async def should_enter_short(self, symbol: str, indicators: Dict[str, Any]) -> bool:
        """Configurable entry gate. SATOSHIT default; SHOULD_ENTER_FALLBACK_ENABLED allows other paths."""
        try:
            if getattr(config, 'ENTRY_SYMGATE_ENABLED', True):
                _sg_blocked, _sg_reason = self.would_exit_trigger_now(symbol, indicators, "SHORT")
                if _sg_blocked:
                    if config.VERBOSE: logger.info(f"[SYMGATE] SHORT {symbol} BLOCKED: {_sg_reason}")
                    return False
            # ═══ 2026-04-30 HTF PORT — F1. HTF_W_M_ALIGN_GATE SHORT (default OFF) ═══
            if getattr(config, 'HTF_W_M_ALIGN_GATE_TRADIER_ENABLED', False):
                try:
                    _w1_W = float(indicators.get('wt1_W', 0) or 0)
                    _w2_W = float(indicators.get('wt2_W', 0) or 0)
                    _w1_M = float(indicators.get('wt1_M', 0) or 0)
                    _w2_M = float(indicators.get('wt2_M', 0) or 0)
                    _w_has = (_w1_W != 0 or _w2_W != 0)
                    _m_has = (_w1_M != 0 or _w2_M != 0)
                    _w_ok = (_w1_W < _w2_W) if _w_has else True   # pass through pre-cache bars
                    _m_ok = (_w1_M < _w2_M) if _m_has else True
                    _req = int(getattr(config, 'HTF_W_M_ALIGN_TRADIER_REQUIRED', 2))
                    _agree = int(_w_ok) + int(_m_ok)
                    if _agree < _req:
                        if config.VERBOSE: logger.info(f"[HTF_W_M_ALIGN_GATE] SHORT {symbol} BLOCKED: agree={_agree}/{_req} W_ok={_w_ok}(has={_w_has}) M_ok={_m_ok}(has={_m_has})")
                        return False
                except Exception as _htfg:
                    logger.debug(f"[HTF_W_M_ALIGN_GATE][SHORT] {symbol}: {type(_htfg).__name__} {_htfg} — skipped")
            # ═══ 2026-04-30 HTF PORT — F2. HTF_DC_BREAKDOWN entry SHORT (default OFF) ═══
            if getattr(config, 'HTF_DC_BREAKOUT_TRADIER_ENABLED', False):
                try:
                    _bk_tf = str(getattr(config, 'HTF_DC_BREAKOUT_TRADIER_TF', '4h'))
                    _bk_thr = float(getattr(config, 'HTF_DC_BREAKOUT_TRADIER_THRESHOLD_PCT', 0.0)) / 100.0
                    _bk_req_w = bool(getattr(config, 'HTF_DC_BREAKOUT_TRADIER_REQUIRE_W_WT', True))
                    _dcl_prev = float(indicators.get(f'dc_low_{_bk_tf}_prev', indicators.get(f'dc_low_{_bk_tf}', 0)) or 0)
                    _cur_p = float(indicators.get('current_price', 0) or 0)
                    if _dcl_prev > 0 and _cur_p > 0 and _cur_p < _dcl_prev * (1.0 - _bk_thr):
                        _w_ok_bk = True
                        if _bk_req_w:
                            _w1_W_bk = float(indicators.get('wt1_W', 0) or 0)
                            _w2_W_bk = float(indicators.get('wt2_W', 0) or 0)
                            if (_w1_W_bk != 0 or _w2_W_bk != 0):
                                _w_ok_bk = _w1_W_bk < _w2_W_bk
                        if _w_ok_bk:
                            logger.warning(f"[HTF_DC_BREAKOUT_SHORT] {symbol}: close={_cur_p:.4f} < dc_low_{_bk_tf}_prev={_dcl_prev:.4f}*(1-{_bk_thr:.4f}) W_ok={_w_ok_bk}")
                            return True
                except Exception as _htfb:
                    logger.debug(f"[HTF_DC_BREAKOUT][SHORT] {symbol}: {type(_htfb).__name__} {_htfb} — skipped")
            if getattr(config, 'SATOSHIT_ENTRY_FILTER', True):
                from ez_satoshit import satoshit_entry_signal
                _sat_ok, _sat_votes, _sat_reason = satoshit_entry_signal(indicators, False, config)
                if _sat_ok:
                    logger.warning(f"[SATOSHIT_ENTRY] SHORT {symbol}: {_sat_reason}")
                    return True
            # STDEV_BREAKOUT: stateless BB %B breakdown entry for SHORT
            if getattr(config, 'STDEV_BREAKOUT_ENABLED', False):
                _sb_htf_list_s = list(getattr(config, 'STDEV_BREAKOUT_HTF_LIST', None) or ['D', '4h'])
                _sb_pctb_short = float(getattr(config, 'STDEV_BREAKOUT_PCTB_SHORT', 0.0))
                _sb_rvol_min_s = float(getattr(config, 'STDEV_BREAKOUT_RVOL_MIN', 1.2))
                for _sb_htf_s in _sb_htf_list_s:
                    _sb_pctb_val_s = float(indicators.get(f'bb_pct_b_{_sb_htf_s}', 0.5) or 0.5)
                    _sb_rvol_val_s = float(indicators.get(f'relative_volume_{_sb_htf_s}', 1.0) or 1.0)
                    if _sb_pctb_val_s <= _sb_pctb_short and _sb_rvol_val_s >= _sb_rvol_min_s:
                        logger.warning(f"[STDEV_BREAKOUT_SHORT] {symbol}: bb_pct_b_{_sb_htf_s}={_sb_pctb_val_s:.3f} rvol={_sb_rvol_val_s:.2f}")
                        return True
            # STDEV_BOUNCE: stateless mean-reversion SHORT entry at upper BB band (pctb ≥ threshold)
            if getattr(config, 'STDEV_BOUNCE_ENABLED', False):
                _bn_htf_list_s = list(getattr(config, 'STDEV_BOUNCE_HTF_LIST', None) or ['D', '4h'])
                _bn_pctb_short = float(getattr(config, 'STDEV_BOUNCE_PCTB_SHORT', 0.95))
                _bn_rvol_min_s = float(getattr(config, 'STDEV_BOUNCE_RVOL_MIN', 1.2))
                for _bn_htf_s in _bn_htf_list_s:
                    _bn_pctb_val_s = float(indicators.get(f'bb_pct_b_{_bn_htf_s}', 0.5) or 0.5)
                    _bn_rvol_val_s = float(indicators.get(f'relative_volume_{_bn_htf_s}', 1.0) or 1.0)
                    if _bn_pctb_val_s >= _bn_pctb_short and _bn_rvol_val_s >= _bn_rvol_min_s:
                        logger.warning(f"[STDEV_BOUNCE_SHORT] {symbol}: bb_pct_b_{_bn_htf_s}={_bn_pctb_val_s:.3f} rvol={_bn_rvol_val_s:.2f}")
                        return True
            if not getattr(config, 'SHOULD_ENTER_FALLBACK_ENABLED', False):
                return False
            # YOUTUBE_CONSENSUS: Lunch dead zone — block momentum entries 11:30-14:00 ET
            if getattr(config, 'LUNCH_DEADZONE_ENABLED', False) and is_lunch_dead_zone():
                _ldz_mode = getattr(config, 'LUNCH_DEADZONE_MODE', 'BLOCK_MOMENTUM')
                if _ldz_mode == "BLOCK_ALL":
                    if config.VERBOSE: logger.info(f"[LUNCH_DEADZONE] SHORT {symbol} BLOCKED: lunch dead zone (BLOCK_ALL)")
                    return False
                elif _ldz_mode == "BLOCK_MOMENTUM":
                    pass  # Allow through — mean-reversion strategies bypass via SATOSHIT fast path above
            # YOUTUBE_CONSENSUS: VWAP filter — SHORT only below VWAP
            if getattr(config, 'VWAP_FILTER_ENABLED', False):
                _vwap = float(indicators.get('vwap', 0) or 0)
                _cur_p_v = float(indicators.get('current_price', 0) or 0)
                if _vwap > 0 and _cur_p_v > 0 and _cur_p_v > _vwap:
                    if config.VERBOSE: logger.info(f"[VWAP_FILTER] SHORT {symbol} BLOCKED: price={_cur_p_v:.2f} > VWAP={_vwap:.2f}")
                    return False
            # YOUTUBE_CONSENSUS: 9/21 EMA alignment confirmation
            if getattr(config, 'EMA_9_21_FILTER_ENABLED', False):
                _ema9_above = float(indicators.get(f'ema_9_above_21_{getattr(config, "EMA_9_21_TIMEFRAME", "5m")}', -1) or -1)
                if _ema9_above == 1.0:
                    if config.VERBOSE: logger.info(f"[EMA_9_21] SHORT {symbol} BLOCKED: 9 EMA > 21 EMA on {getattr(config, 'EMA_9_21_TIMEFRAME', '5m')}")
                    return False
            # YOUTUBE_CONSENSUS: RVOL gate for non-mean-reversion strategies
            _rvol_5m = float(indicators.get('rel_vol_5m', 1.0) or 1.0)
            _rvol_min = getattr(config, 'RVOL_MOMENTUM_MIN', 1.5)
            if _rvol_5m < _rvol_min and _rvol_5m > 0:
                if config.VERBOSE: logger.info(f"[RVOL_GATE] SHORT {symbol} BLOCKED: RVOL_5m={_rvol_5m:.2f} < {_rvol_min}")
                return False
            # BACKTEST_CHANGE_T55: RSI entry gate — ONLY if RSI data exists
            _rsi_period = getattr(config, 'RSI_ENTRY_PERIOD_TRADIER', 10)
            _rsi_key = f'rsi_{_rsi_period}_D'
            _rsi_val = indicators.get(_rsi_key, indicators.get('rsi_D', indicators.get('rsi_1h', None)))
            if _rsi_val is not None:
                _rsi_val = float(_rsi_val or 50)
                _rsi_thresh = getattr(config, 'RSI_ENTRY_SHORT_TRADIER', 58.0)
                if _rsi_val < _rsi_thresh:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} BLOCKED: RSI({_rsi_period})={_rsi_val:.1f} < {_rsi_thresh}")
                    return False
            # SMA filter — ONLY if SMA data exists
            _sma_key = f'sma_{getattr(config, "SMA_FILTER_PERIOD_TRADIER", 100)}_D'
            _sma_val = indicators.get(_sma_key, indicators.get('sma_200_D', indicators.get('sma_200_1h', None)))
            _cur_p = float(indicators.get('current_price', 0) or 0)
            if _sma_val is not None and _cur_p > 0:
                _sma_val = float(_sma_val or 0)
                if _sma_val > 0 and _cur_p > _sma_val:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} BLOCKED: price > SMA")
                    return False
            final_score = indicators.get('0final_score_norm', 0)
            ranking_points = indicators.get('0ranking_points', 0)
            lr_trend_15m = indicators.get('lr_trend_15m', 0)
            k_1h = indicators.get('k_1h', 50)
            d_1h = indicators.get('d_1h', 50)
            k_4h = indicators.get('k_4h', 50)
            d_4h = indicators.get('d_4h', 50)
            if config.VERBOSE:
                logger.info(f"[VERBOSE][CALC][SHORT] {symbol} ENTRY CALCULATION START: final_score={final_score:.3f} ranking_points={ranking_points:.1f} lr_trend_15m={lr_trend_15m:.3f} k_1h={k_1h:.1f} d_1h={d_1h:.1f} k_4h={k_4h:.1f} d_4h={d_4h:.1f}")
            # BACKTEST_CHANGE_T19: time zone stoch threshold gate
            if getattr(config, 'TIME_ZONE_ENABLED', False):
                _zone = _get_trade_zone()
                if _zone == "open":
                    _zt = getattr(config, 'ZONE_OPEN_THRESHOLD', 25)
                elif _zone == "mid":
                    _zt = getattr(config, 'ZONE_MID_THRESHOLD', 30)
                elif _zone == "close":
                    _zt = getattr(config, 'ZONE_CLOSE_THRESHOLD', 20)
                else:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} BLOCKED: market closed zone")
                    return False
                if k_1h < _zt:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} BLOCKED: zone={_zone} k_1h={k_1h:.1f} < threshold {_zt:.0f}")
                    return False
                # BACKTEST_CHANGE_T24: mid zone requires WT crossunder on 15m for shorts
                if _zone == "mid" and getattr(config, 'WT_CROSSUNDER_15M_SHORT', False):
                    _wt1_15m = float(indicators.get('wt1_15m', 0) or 0)
                    _wt2_15m = float(indicators.get('wt2_15m', 0) or 0)
                    if _wt1_15m >= _wt2_15m:
                        if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} BLOCKED: mid zone requires wt_crossunder_15m (wt1={_wt1_15m:.1f} >= wt2={_wt2_15m:.1f})")
                        return False
            # 2026-04-27 LOWER-HIGHS / HIGHER-LOWS FILTER (SHORT side) — sweep-testable, default OFF.
            # User: "block long trades while 1h/4h charts make lower highs (shorts vv)".
            # User 2026-04-27 23:13: "test lh with or without ll for longs hl with or without hh for shorts on both platforms".
            if bool(getattr(config, 'LH_HL_FILTER_ENABLED', False)):
                try:
                    _lh_mode = str(getattr(config, 'LH_HL_FILTER_MODE', 'STRICT_2BAR'))
                    _lh_tf_req = int(getattr(config, 'LH_HL_FILTER_TF_REQ', 2))
                    _lh_dc_th = float(getattr(config, 'LH_HL_FILTER_DC_THRESHOLD_PCT', 0.5)) / 100.0
                    _lh_req_both = bool(getattr(config, 'LH_HL_FILTER_REQUIRE_BOTH', False))
                    _lh_h1h = float(indicators.get('high_1h', 0) or 0); _lh_h1hp = float(indicators.get('high_1h_prev', 0) or 0)
                    _lh_h4h = float(indicators.get('high_4h', 0) or 0); _lh_h4hp = float(indicators.get('high_4h_prev', 0) or 0)
                    _lh_l1h = float(indicators.get('low_1h', 0) or 0); _lh_l1hp = float(indicators.get('low_1h_prev', 0) or 0)
                    _lh_l4h = float(indicators.get('low_4h', 0) or 0); _lh_l4hp = float(indicators.get('low_4h_prev', 0) or 0)
                    if _lh_mode == "DC_REGRESS":
                        _lh_dcl1h = float(indicators.get('dc_low_1h', 0) or 0)
                        _lh_dcl4h = float(indicators.get('dc_low_4h', 0) or 0)
                        _hl_1h = (_lh_l1h > 0 and _lh_dcl1h > 0 and _lh_l1h > _lh_dcl1h * (1.0 + _lh_dc_th))
                        _hl_4h = (_lh_l4h > 0 and _lh_dcl4h > 0 and _lh_l4h > _lh_dcl4h * (1.0 + _lh_dc_th))
                    else:
                        _hl_1h = (_lh_l1h > 0 and _lh_l1hp > 0 and _lh_l1h > _lh_l1hp)
                        _hl_4h = (_lh_l4h > 0 and _lh_l4hp > 0 and _lh_l4h > _lh_l4hp)
                    _hh_1h = (_lh_h1h > 0 and _lh_h1hp > 0 and _lh_h1h > _lh_h1hp)
                    _hh_4h = (_lh_h4h > 0 and _lh_h4hp > 0 and _lh_h4h > _lh_h4hp)
                    _hl_count = int(_hl_1h) + int(_hl_4h)
                    _hh_count = int(_hh_1h) + int(_hh_4h)
                    _primary_hit = _hl_count >= _lh_tf_req
                    _confirm_hit = (not _lh_req_both) or (_hh_count >= _lh_tf_req)
                    if _primary_hit and _confirm_hit:
                        _tag = "HL+HH" if _lh_req_both else "HL"
                        logger.info(f"📈 [LH_HL_FILTER] {symbol} BLOCKED SHORT — {_tag} on {_hl_count}/2 TFs (1h HL={_hl_1h} HH={_hh_1h} | 4h HL={_hl_4h} HH={_hh_4h}) mode={_lh_mode} req={_lh_tf_req}TF reqBoth={_lh_req_both}")
                        return False
                except Exception as _lh_exc:
                    logger.debug(f"[LH_HL_FILTER][SHORT] {symbol}: {type(_lh_exc).__name__} {_lh_exc} — skipped")
            # BACKTEST_CHANGE_T9: conviction threshold for shorts
            if getattr(config, 'CONVICTION_SHORT_THRESHOLD', 0) > 0:
                _conviction = float(indicators.get('0conviction', 0) or 0)
                if _conviction < getattr(config, 'CONVICTION_SHORT_THRESHOLD', 20):
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} BLOCKED: conviction={_conviction:.0f} < {config.CONVICTION_SHORT_THRESHOLD}")
                    return False
            # BACKTEST_CHANGE_T8: alignment gate
            if getattr(config, 'ALIGNMENT_GATE_MIN', 0) > 0:
                _al_count = 0
                if k_1h < d_1h: _al_count += 1
                if k_4h < d_4h: _al_count += 1
                if float(indicators.get('k_15m', 50)) < float(indicators.get('d_15m', 50)): _al_count += 1
                if lr_trend_15m < 0: _al_count += 1
                _al_total_max = getattr(config, 'ALIGNMENT_GATE_TOTAL', 12)
                if _al_count < getattr(config, 'ALIGNMENT_GATE_MIN', 4):
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} BLOCKED: alignment={_al_count}/{_al_total_max} < {config.ALIGNMENT_GATE_MIN}")
                    return False
            # BACKTEST_CHANGE_T10: LR %B daily threshold for shorts
            if getattr(config, 'LR_PCTB_D_SHORT_THRESHOLD', 0) > 0:
                _lr_pctb_d = float(indicators.get('lr_pct_b_D', 0.5) or 0.5)  # 2026-07-15 key fix: was 'lr_pctb_D' (never written live) → gate was inert
                if _lr_pctb_d < getattr(config, 'LR_PCTB_D_SHORT_THRESHOLD', 0.1):
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} BLOCKED: lr_pctb_D={_lr_pctb_d:.2f} < {config.LR_PCTB_D_SHORT_THRESHOLD}")
                    return False
            # Leaderboard filter check
            if config.LEADERBOARD_FILTER:
                rankings = await self.get_rankings()
                if rankings:
                    bottom_symbols = rankings.get('bottom_20', [])
                    in_bottom_20 = symbol in bottom_symbols
                    if config.VERBOSE:
                        logger.info(f"[VERBOSE][CALC][SHORT] {symbol} LEADERBOARD_FILTER: enabled={config.LEADERBOARD_FILTER} in_bottom_20={in_bottom_20}")
                    if not in_bottom_20:
                        if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} !! BLOCKED: not in bottom_20 leaderboard")
                        return False
                elif config.VERBOSE:
                    logger.info(f"[VERBOSE][CALC][SHORT] {symbol} LEADERBOARD_FILTER: enabled but no rankings data available")
            elif config.VERBOSE:
                logger.info(f"[VERBOSE][CALC][SHORT] {symbol} LEADERBOARD_FILTER: disabled (skipping)")
            # Trend gates check
            if config.TREND_GATES:
                trend_ok = lr_trend_15m < 0
                if config.VERBOSE:
                    logger.info(f"[VERBOSE][CALC][SHORT] {symbol} TREND_GATES: enabled={config.TREND_GATES} lr_trend_15m={lr_trend_15m:.3f} trend_ok={trend_ok}")
                if not trend_ok:
                    if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} !! BLOCKED: lr_trend_15m={lr_trend_15m:.3f} >= 0")
                    return False
            elif config.VERBOSE:
                logger.info(f"[VERBOSE][CALC][SHORT] {symbol} TREND_GATES: disabled (skipping)")
            # HTF confirmation checks
            if config.HTF1_CONF or config.HTF4_CONF:
                htf1_ok = True
                htf4_ok = True
                if config.HTF1_CONF:
                    htf1_ok = k_1h < d_1h
                    if config.VERBOSE:
                        logger.info(f"[VERBOSE][CALC][SHORT] {symbol} HTF1_CONF: enabled={config.HTF1_CONF} k_1h={k_1h:.1f} d_1h={d_1h:.1f} htf1_ok={htf1_ok}")
                    if not htf1_ok:
                        if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} !! BLOCKED: HTF1_CONF k_1h={k_1h:.1f} >= d_1h={d_1h:.1f}")
                        return False
                if config.HTF4_CONF:
                    htf4_ok = k_4h < d_4h
                    if config.VERBOSE:
                        logger.info(f"[VERBOSE][CALC][SHORT] {symbol} HTF4_CONF: enabled={config.HTF4_CONF} k_4h={k_4h:.1f} d_4h={d_4h:.1f} htf4_ok={htf4_ok}")
                    if not htf4_ok:
                        if config.VERBOSE: logger.info(f"[VERBOSE][CALC][SHORT] {symbol} !! BLOCKED: HTF4_CONF k_4h={k_4h:.1f} >= d_4h={d_4h:.1f}")
                        return False
            elif config.VERBOSE:
                logger.info(f"[VERBOSE][CALC][SHORT] {symbol} HTF_CONF: disabled (skipping)")
            # Final score check
            score_threshold = 0.4
            ranking_threshold = -50
            score_ok = True  # BACKTEST_CHANGE_T42: near-zero signal in 0xxx sweep
            ranking_ok = True  # BACKTEST_CHANGE_T41: near-zero signal in 0xxx sweep
            final_result = score_ok and ranking_ok
            if config.VERBOSE:
                in_bottom_20_val = in_bottom_20 if config.LEADERBOARD_FILTER and 'in_bottom_20' in locals() else (True if not config.LEADERBOARD_FILTER else False)
                trend_ok_val = trend_ok if config.TREND_GATES and 'trend_ok' in locals() else (True if not config.TREND_GATES else (lr_trend_15m < 0))
                htf1_ok_val = htf1_ok if config.HTF1_CONF and 'htf1_ok' in locals() else (True if not config.HTF1_CONF else (k_1h < d_1h))
                htf4_ok_val = htf4_ok if config.HTF4_CONF and 'htf4_ok' in locals() else (True if not config.HTF4_CONF else (k_4h < d_4h))
                logger.info(f"\n[DECISION SCORECARD] {symbol} SHORT EVALUATION")
                logger.info(f"{'Metric':<15} | {'Value':<10} | {'Threshold':<10} | {'Result'}")
                logger.info("-" * 55)
                logger.info(f"{'Leaderboard':<15} | {str(in_bottom_20_val):<10} | {'True':<10} | {'✅' if in_bottom_20_val else '!!'}")
                logger.info(f"{'Trend (15m)':<15} | {lr_trend_15m:<10.3f} | {'< 0':<10} | {'✅' if trend_ok_val else '!!'}")
                logger.info(f"{'HTF1 (1h)':<15} | {k_1h:.1f}/{d_1h:.1f}  | {'K < D':<10} | {'✅' if htf1_ok_val else '!!'}")
                logger.info(f"{'HTF4 (4h)':<15} | {k_4h:.1f}/{d_4h:.1f}  | {'K < D':<10} | {'✅' if htf4_ok_val else '!!'}")
                logger.info(f"{'Final Score':<15} | {final_score:<10.3f} | {'< '+str(score_threshold):<10} | {'✅' if final_score<score_threshold else '!!'}")
                logger.info(f"{'Rank Points':<15} | {ranking_points:<10.1f} | {'BYPASSED':<10} | {'✅ (T41)'}")
                logger.info("-" * 55)
                logger.info(f"FINAL DECISION: {'✅ ENTER SHORT' if final_result else '⛔ BLOCKED'}\n")
                logger.info(f"[VERBOSE][CALC][SHORT] {symbol} FINAL SCORE CHECK: final_score={final_score:.3f} < {score_threshold} = {score_ok} | ranking_points=BYPASSED(T41) | RESULT={final_result}")
            return final_result
        except Exception as e:
            logger.error(f"Error in should_enter_short for {symbol}: {e}",  exc_info=True )
            return False

