    async def calculate_position_size(self, symbol: str, price: float, account_key: str = "tra", side: str = "LONG") -> float:
        """Calculate position size based on config — per-symbol overrides via rolling_config_optimizer."""
        try:
            if price <= 0:
                logger.error(f"Error calculating position size for {symbol}: Price is {price}")
                return 0.0
            target_value = _cfg('START_POSITION_SIZE', 600, account_key, symbol, side)
            # 2026-06-02 USER: per-sym CONVICTION sizing (mirror of crypto _psym_sps) — proven winners
            # (MU/SNDK) open BIG via size_mult from the FINAL book, capped. No-op unless CONVICTION_SIZING_ENABLED.
            if bool(getattr(config, 'CONVICTION_SIZING_ENABLED', False)):
                try:
                    _tradier_final_book_get(f"{symbol}_{side}", 'LONG_ENABLED')  # ensures _tradier_final_book is loaded (mtime-cached)
                    _cv_sm = (_tradier_final_book.get('tradeable', {}).get(f"{symbol}_{side}", {}) or {}).get('size_mult')
                    if _cv_sm is not None:
                        target_value = float(target_value) * max(1.0, min(float(_cv_sm), float(getattr(config, 'CONVICTION_SIZING_MAX', 8.0))))
                except Exception:
                    pass
            # BACKTEST_CHANGE_T23: close zone size multiplier
            if getattr(config, 'TIME_ZONE_ENABLED', False):
                _zone = _get_trade_zone()
                if _zone == "close":
                    target_value *= getattr(config, 'CLOSE_ZONE_SIZE_MULT', 1.5)
            max_value = min(target_value, _cfg('MAX_ORDER_VALUE', 2000, account_key, symbol, side))
            # Congress conviction sizing boost (stock_trader_scanner multi-source agreement)
            congress_boost = _get_congress_conviction_boost(symbol)
            if congress_boost > 1.0:
                max_value *= congress_boost
                max_value = min(max_value, config.MAX_ORDER_VALUE * 1.5)
            # 2026-04-26 VIX volatility regime size multiplier (VIX vs VIX-200dMA)
            if _VIX_MODULE_AVAILABLE and getattr(config, 'VIX_VOLATILITY_REGIME_ENABLED', False):
                try:
                    _vix_mult = get_vix_regime_size_mult(config)
                    if _vix_mult <= 0.0:
                        logger.warning(f"[{account_key}] [VIX_REGIME] {get_vix_regime_label(config)} — entry blocked for {symbol}")
                        return 0.0
                    if _vix_mult < 1.0:
                        max_value *= _vix_mult
                        logger.info(f"[{account_key}] [VIX_REGIME] {get_vix_regime_label(config)} size_mult={_vix_mult:.2f} → max_value=${max_value:.0f}")
                except Exception as _vix_e:
                    logger.warning(f"[{account_key}] [VIX_REGIME] check failed: {_vix_e}")
            if getattr(config, 'BAND_SLOPE_SIZING_V2_ENABLED', False):
                try:
                    _bs_ind = (self.market_snapshot or {}).get(symbol.upper(), {}) or {}
                    _bs_tf = getattr(config, 'BAND_SLOPE_SIZING_V2_TF', 'D')
                    _bs_pb = _bs_ind.get(f'lrL_pct_b_{_bs_tf}')
                    _bs_sl = _bs_ind.get(f'lrL_slope_{_bs_tf}')
                    if _bs_pb is not None and _bs_sl is not None:
                        _bs_pb = float(_bs_pb)
                        _bs_slope_day = float(_bs_sl) * {'1h': 6.5, '4h': 1.625, 'D': 1.0}.get(_bs_tf, 1.0)
                        _bs_long = (side == 'LONG')
                        _bs_edge = (1.0 - _bs_pb) if _bs_long else _bs_pb
                        _bs_m = 1.0 + float(getattr(config, 'BAND_SLOPE_SIZING_V2_DEPTH_GAIN', 1.0)) * (_bs_edge - 0.5) * 2.0
                        _bs_sn = min(abs(_bs_slope_day) / float(getattr(config, 'BAND_SLOPE_SIZING_V2_SLOPE_NORM_PCT_DAY', 1.0)), 1.0)
                        _bs_fav = _bs_slope_day > 0 if _bs_long else _bs_slope_day < 0
                        _bs_m *= (1.0 + 0.5 * _bs_sn) if _bs_fav else max(0.5, 1.0 - 0.5 * _bs_sn)
                        _bs_m = max(float(getattr(config, 'BAND_SLOPE_SIZING_V2_MIN', 0.5)), min(float(getattr(config, 'BAND_SLOPE_SIZING_V2_MAX', 2.5)), _bs_m))
                        max_value *= _bs_m
                        logger.info(f"[BAND_SLOPE_SIZING_V2] {symbol} {side}: lrL_pct_b_{_bs_tf}={_bs_pb:.3f} slope_day={_bs_slope_day:+.3f}%/d mult={_bs_m:.2f} → ${max_value:.0f}")
                except Exception as _bs_e:
                    logger.warning(f"[BAND_SLOPE_SIZING_V2] {symbol} sizing check failed: {_bs_e}")
            shares = max_value / price
            shares_int = max(1, int(round(shares)))
            return float(shares_int)
        except Exception as e:
            logger.error(f"Error calculating position size for {symbol}: {e}")
            return 0.0

    async def calculate_stop_loss(self, symbol: str, entry_price: float, side: str, indicators: Dict[str, Any]) -> float:
        """
        Calculate stop loss.
        Rule 1: Respect Daily DC levels (Macro structure).
        Rule 2: MUST be outside 15m DC levels (Micro structure) - never stop inside the noise.
        Rule 3: Max risk cap of 6% to prevent "infinite" structural stops.
        """
        try:
            d = self.strategy.parse_market_data(indicators)
            
            # Daily Levels (Macro)
            dc_low_d = d.get('dc_low_D', 0) or d.get('dc_low_D', 0)
            dc_high_d = d.get('dc_high_D', 0) or d.get('dc_high_D', 0)
            
            # 15m Levels (Micro)
            dc_low_15m = d.get('dc_low_15m', 0)
            dc_high_15m = d.get('dc_high_15m', 0)
            
            atr = d.get('atr_15m', 0)
            stop_price = 0.0

            if side == "LONG":
                # 1. Base Stop: 2% below Daily Low, or 2x ATR if Daily missing
                if dc_low_d > 0:
                    base_stop = dc_low_d * 0.98
                else:
                    base_stop = entry_price - (atr * 2.0 if atr > 0 else entry_price * 0.03)  # Marathon winner: stop_atr=2.0

                # 2. Structural Constraint: Stop MUST be below 15m Low
                # If base_stop is higher than 15m Low (inside the noise), push it down.
                if dc_low_15m > 0:
                    structural_limit = dc_low_15m * 0.995  # 0.5% buffer below 15m low
                    stop_price = min(base_stop, structural_limit)
                else:
                    stop_price = base_stop

                # 3. Sanity Cap: Don't risk more than 6% on entry
                max_risk_price = entry_price * 0.94
                if stop_price < max_risk_price:
                    stop_price = max_risk_price
                    logger.info(f"[{symbol}] Structural stop too wide. Capping at -6%: {stop_price:.2f}")

                logger.info(f"[{symbol}] Stop Loss: {stop_price:.2f} (Entry: {entry_price:.2f}, 15mLow: {dc_low_15m:.2f})")

            else: # SHORT
                # 1. Base Stop: 2% above Daily High
                if dc_high_d > 0:
                    base_stop = dc_high_d * 1.02
                else:
                    base_stop = entry_price + (atr * 2.0 if atr > 0 else entry_price * 0.03)

                # 2. Structural Constraint: Stop MUST be above 15m High
                if dc_high_15m > 0:
                    structural_limit = dc_high_15m * 1.005 # 0.5% buffer above 15m high
                    stop_price = max(base_stop, structural_limit)
                else:
                    stop_price = base_stop

                # 3. Sanity Cap: 6% max risk
                max_risk_price = entry_price * 1.06
                if stop_price > max_risk_price:
                    stop_price = max_risk_price
                    logger.info(f"[{symbol}] Structural stop too wide. Capping at -6%: {stop_price:.2f}")

                logger.info(f"[{symbol}] Stop Loss: {stop_price:.2f} (Entry: {entry_price:.2f}, 15mHigh: {dc_high_15m:.2f})")

            return float(stop_price)

        except Exception as e:
            logger.error(f"Error calculating stop loss for {symbol}: {e}")
            # Emergency Fallback: 4% fixed
            return entry_price * 0.96 if side == "LONG" else entry_price * 1.04
            
