    async def symbol_watchdog_loop(self):
        logger.info("[symbol_watchdog]  Task started")
        while self.running:
            try:
                await asyncio.sleep(30)
                now = time.time()
                stale_positions = [pk for pk, ts in self.last_monitored_positions.items() if now - ts > 60]
                for pk in stale_positions[:100]:
                    account_key = pk.split(':', 1)[0]
                    queue = self.account_position_queues[account_key]
                    if pk not in queue['set']:
                        queue['queue'].append(pk)
                        queue['set'].add(pk)
                        logger.warning(f"[symbol_watchdog] Re-queued stale position {pk}")
                stale_symbols = [sym for sym, ts in self.last_symbol_monitored.items() if now - ts > 90]
                for symbol in stale_symbols[:50]:
                    indicators = self.get_indicators(symbol)
                    if indicators:
                        self.indicators_cache[symbol.upper()] = indicators
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.debug(f"[symbol_watchdog] Error: {e}")
    
    async def market_data_sync_loop(self):
        """Safe-Path: Read NEWEST timestamped tradier_indicators file. NEVER use latest (gets stuck in OS cache)."""
        logger.info("🔍 [SAFE-PATH] File Poller Active — reading newest timestamped tradier_indicators every 1s")
        while self.running:
            try:
                # Find newest timestamped file (NOT latest)
                ts_files = sorted(config.DATA_DIR.glob("tradier_indicators_[0-9]*.json"), key=lambda f: f.stat().st_mtime, reverse=True)
                # S1 FALLBACK: if newest timestamped is stale >60s, try S1 file (S1 runs tradier_indicators, gateway only klines/prices)
                s1_path = config.DATA_DIR / "s1_indicators_latest.json"
                import time as _tm
                newest_age = (time.time() - ts_files[0].stat().st_mtime) if ts_files else 9999
                if newest_age > 60 and s1_path.exists() and (time.time() - s1_path.stat().st_mtime) < 60:
                    json_path = s1_path
                else:
                    json_path = ts_files[0] if ts_files else (config.DATA_DIR / "tradier_indicators_latest.json")
                if json_path.exists():
                    mtime = os.path.getmtime(json_path)
                    if mtime > self.last_json_mtime:
                        try:
                            with open(json_path, 'r') as f:
                                raw_data = json.loads(f.read())
                            if isinstance(raw_data, dict) and len(raw_data) > 0:
                                new_snapshot = {}
                                for sym, vals in raw_data.items():
                                    if isinstance(vals, dict):
                                        new_snapshot[sym.upper()] = self._adapt_indicators_for_ez_manage(vals)
                                self.market_snapshot = new_snapshot
                                self.last_json_mtime = mtime
                                logger.info(f"💾 [SAFE-PATH] Snapshot loaded: {len(new_snapshot)} symbols from {json_path.name}")
                        except Exception as je:
                            logger.warning(f"[SAFE-PATH] JSON read error (will retry): {je}")
                await asyncio.sleep(1.0)
            except Exception as e:
                logger.error(f"Sync Loop Error: {e}")
                await asyncio.sleep(5)
    
